-- 0228 Monumentos PDF (inventario_monumentos_pdf) parte 2
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19178','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Edificio del siglo XVI de estilo renacentista rural del Señorío de Molina, construido con fábrica rústica de mampostería de piedra arenisca roja, con una espadaña castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19179','iglesia','Iglesia Parroquial de Santiago el Mayor','Gran edificio del siglo XVI de líneas renacentistas reconstruido en el barroco con muros de mampostería encintada y contrafuertes de cantería caliza calavera que alberga una espaciosa nave única.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19179','ermita','Ermita de la Virgen del Espino','Santuario barroco del siglo XVIII levantado en el cerro local con aparejo de mampostería basta que cuenta con un crucero rematado en cúpula de media naranja decorada con yeserías molduradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19181','iglesia','Iglesia de la Natividad','Templo de filiación románica tardía del siglo XIII profundamente remodelado en el siglo XVI con cantería caliza, del que sobrevive su portada meridional de arquivoltas apuntadas y capiteles con motivos vegetales esquemáticos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19181','monumento','Yacimiento Arqueológico de Los Casares','Asentamiento con niveles de ocupación de la Edad del Bronce y de época romana, donde se documentan estructuras de cimentación en piedra y restos de material cerámico sigillata diseminado por la meseta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19184','iglesia','Iglesia Parroquial de Santo Domingo de Silos','Monumental templo del siglo XVI que conserva de forma espectacular su Portada Románica del siglo XIII','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19184','ermita','Ermita de la Virgen de la Fuensanta','Gran santuario barroco del siglo XVII de planta de cruz latina y cúpula sobre pechinas ricamente decorada con yeserías ornamentales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19183','iglesia','Iglesia Parroquial de San Juan Bautista','Monumental e histórico templo del siglo XVI de estilo renacentista clasicista herreriano; de proporciones catedralicias, posee una espectacular sillería de piedra caliza, tres naves de gran altura y un espectacular retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19183','monumento','Casas Palaciegas de Milmarcos (Arquitectura Civil)','Conjunto monumental de grandes viviendas nobiliarias y casonas de cantería de los siglos XVI al XVIII con portadas de medio punto y blasones heráldicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19185','monumento','Núcleos de población de La Miñosa','El término municipal incluye los siguientes núcleos de población: Tordelloso y Naharros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19185','iglesia','Iglesia de San Pedro (Miñosa)','Obra rural del siglo XVI levantada en sillarejo de pizarra rústica y arenisca, con','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19185','ermita','Ermita de San Roque (Tordelloso)','Pequeño oratorio de planta rectangular en mampostería vista y sillares de refuerzo angulares, rematado por tejado a dos aguas con artesonado interior de madera de pino sin decorar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19186','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica de mampostería caliza alcarreña, con una robusta espadaña de líneas sencillas y un interior muy austero adaptado al entorno.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19187','iglesia','Iglesia Parroquial de San Jorge','Edificio del siglo XVI de estilo renacentista rural castellano, construido con fábrica de ladrillo visto y cajones de mampostería caliza, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19188','monumento','Torre-Fortaleza de Mochales','Espectacular torre defensiva bajomedieval del siglo XIV erigida en sillería de piedra caliza viva sobre un espolón estratégico, vestigio de la antigua fortificación que controlaba el valle del río Mesa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19188','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo gótico del siglo XV que conserva muros de sillería caliza calavera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19189','iglesia','Iglesia de Nuestra Señora de la Luz','Destacada obra del siglo XVI construida en sillería y sillarejo, cuyo interior alberga el sepulcro plateresco de don Erasmo de Eraso erigido en alabastro finamente esculpido con motivos heráldicos y figuras yacentes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19189','monumento','Picota-Rollo de Justicia','Monumento exento de estilo plateresco del siglo XVI labrado en piedra caliza, compuesto por una basa moldurada, fuste cilíndrico liso y un remate decorado con cuatro cabezas de león o canes flanqueando el capitel.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19190','monumento','Castillo-Alcázar de Molina de Aragón','Obra maestra absoluta de la arquitectura militar medieval (siglos XIIXIV) declarada Monumento Nacional; colosal fortaleza señorial que corona el cerro de la ciudad alta, edificada en sillería de piedra arenisca roja y caliza, destacando su espectacular Torre de Aragón (torre del homenaje exenta exenta de planta pentagonal única), un cinturón defensivo massivo jalonado por torres cuadradas almenadas enteras, adarves transitables y un patio de armas inmenso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19190','iglesia','Monasterio de San Francisco','Monumental complejo de la orden de los franciscanos (siglos XIV-XVI) edificado en sillería caliza calavera; destaca su iglesia barroca con una espectacular torre campanario rematada por una linterna calada que domina el casco histórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19190','iglesia','Iglesia de San Gil','Monumental basílica del gótico tardío y renacimiento; posee una portada plateresca de piedra arenisca, tres naves de gran altura y alberga capillas con yeserías de gran valor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19190','monumento','Puente Viejo sobre el río Gallo','Espectacular infraestructura civil románica y medieval (siglo XIII) esculpida íntegramente combinando grandes bloques de arenisca roja de cantería impecable, caracterizado por sus tres grandes arcos de medio punto y tajamares angulares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19190','monumento','Barrio Judío y Morería','Trazado urbano medieval de la villa que conserva calles empedradas tradicionales, pasadizos de piedra y casonas señoriales de cantería de piedra con portadas de medio punto y blasones heráldicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19191','iglesia','Iglesia Parroquial de San Pedro Apóstol','Templo mudéjar del siglo XVI edificado en mampostería encalada con portadas de cantería granítica que destaca por sus bóvedas de crucería góticas en el presbiterio y un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19192','iglesia','Iglesia de Santa María de la Asunción','Obra cumbre de la transición del gótico al renacimiento construida entre 1493 y 1516 por Cristóbal de Adonza en sillería caliza, que destaca por su monumental fachada plateresca diseñada por Lorenzo de Vázquez y sus bóvedas interiores de crucería estrellada de finísima ejecución.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19192','iglesia','Ruinas del Monasterio de San Antonio de Antonio de Padua','Primer cenobio edificado en estilo renacentista puro en España fuera de la corte, trazado por Lorenzo de Vázquez en 1489 por orden de los Condes de Tendilla, del que se conservan los potentes arcos y pilares de la iglesia conventual en piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19192','ermita','Ermita de San Sebastián y Cripta de los Judíos','Construcción del siglo XVI en mampostería que alberga en su subsuelo una serie de pasos de la Pasión modelados en yeso policromado a tamaño natural de estilo tardogótico-renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19193','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo barroco rural del siglo XVII edificado con muros de mampostería caliza, con una espadaña tradicional de dos vanos para las campanas y un interior de nave única muy austero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19194','monumento','La Picota de Moratilla','Joya absoluta del arte renacentista plateresco civil (siglo XVI) situada en la Plaza Mayor; colosal y esbelta columna de piedra caliza calavera magníficamente tallada con motivos platerescos, gárgolas con cabezas de león y un remate que atestigua el rango de villa judicial autónoma.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19194','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Monumental templo del siglo XVI de tres naves de gran altura, edificado con grandes sillares de piedra caliza de la Alcarria, con un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19195','monumento','Núcleos de población de Morenilla','El término municipal incluye los siguientes núcleos de población: Herbeset, La Pobleta d''Alcolea, Ortells y Xiva de Morella.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19195','monumento','Castillo de Morella','Extraordinaria e inexpugnable fortaleza militar universal erigida de forma monumental sobre una colosal muela rocosa caliza escarpada con niveles defensivos superpuestos islámicos, templarios y carlistas que conserva su plaza de armas, aljibes y la recia torre del homenaje.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19195','monumento','Recinto Amurallado de Morella','Impresionante sistema fortificado bajomedieval del siglo XIV construido con potentes muros de sillería caliza regular y mampostería que rodea por completo el casco histórico conservando de forma monumental catorce torres y seis puertas fortificadas intactas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19195','iglesia','Basílica de Santa María la Mayor','Obra cumbre del gótico valenciano construida en cantería caliza de primer orden que exhibe una fachada monumental con las puertas de los Apóstoles y de las Vírgenes, una espectacular escalera de coro de caracol exenta','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19195','monumento','Acueducto de Santa Lucía','Monumental obra de ingeniería civil e hidráulica del gótico gótico-mudéjar del siglo XIV construida en sillería de cantería que salva los desniveles del valle mediante una imponente doble arquería superpuesta de arcos apuntados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19195','iglesia','Convento de San Francisco','Complejo monacal gótico del siglo XIII edificado en piedra que conserva una monumental sala capitular decorada con una pintura macabra universal de la Danza de la Muerte y un bellísimo claustro desmantelado de arquerías ojivales caladas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19196','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica de mampostería caliza en el valle del río Badiel, con una robusta espadaña de líneas sencillas y un interior muy austero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19198','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Sencillo templo de arquitectura barroca popular (siglo XVII) construido con piedras calizas y mampostería, con un interior sobrio de una sola nave y espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19199','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica de mampostería caliza en los cañones del Alto Tajo, con una robusta espadaña de líneas sencillas y un interior desprovisto de grandes adornos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19202','iglesia','Iglesia Parroquial de San Mateo','Joya del románico de transición (siglo XII); conserva un espectacular ábside de sillería caliza calavera con tres pisos de arquerías ciegas de gran pureza formal e hleras de aparejo tradicional castellano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19204','iglesia','Iglesia de la Asunción','Templo de grandes dimensiones del siglo XVII edificado en sillería de piedra arenisca de rodeno y caliza, con planta de cruz latina y una gran torre campanario adosada que destaca por sus potentes paramentos ciegos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19204','monumento','Casa de la tía Javiera','Ejemplar notable de arquitectura civil montañesa del siglo XVIII construido en piedra y entramado de madera pesada, provisto de rejerías de forja artística en sus vanos exteriores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19204','monumento','65 - 79 (Excelencia Regional / Conjuntos Notables)','Municipios con cascos urbanos bien conservados, iglesias parroquiales de grandes dimensiones (góticas, renacentistas o barrocas) con retablos o portadas de valor singular, castillos parcialmente en ruinas pero de gran porte, o monasterios de relevancia provincial (Ej: Alba de Tormes, Peñaranda de Duero, Alaejos, Madrigal de las Altas Torres, Fermoselle).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19204','monumento','50 - 64 (Notable Interés Comarcal)','Localidades que albergan un monumento principal destacado (como una iglesia románica o un palacio solariego) combinado con arquitectura popular homogénea bien mantenida, restos de fortificaciones, ermitas de peregrinación o puentes históricos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19204','monumento','35 - 49 (Valor Patrimonial Estándar / Disperso)','Municipios que no forman un conjunto histórico homogéneo, pero conservan su iglesia parroquial con modificaciones estructurales, ermitas rurales, muestras de arquitectura tradicional (adobe, piedra rústica, entramados) o restos arqueológicos catalogados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19204','monumento','1 - 34 (Interés Local / Testimonial)','Localidades con patrimonio muy modificado, reconstruido o escaso, limitado a pequeñas ermitas de época moderna, fuentes históricas, picotas/rollos de justicia aislados o muestras sencillas de arquitectura etnográfica (molinos, lagares, palomares).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19204','monumento','[Nombre del Monumento 1]','[Redacción en una única frase compleja con densidad terminológica, materiales y cronología].','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19204','monumento','[Nombre del Monumento 2]','[Redacción en una única frase compleja con densidad terminológica, materiales y cronología].','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19208','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica mixta de mampostería caliza y sillería en los esquinales, que destaca por su espadaña de tres vanos en la cuenca del río Cañamares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19209','iglesia','Iglesia de San Pedro Apóstol','Construcción rural modesta del siglo XVII levantada con aparejo tosco de piedra caliza del terreno y aglutinante de cal,','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19210','iglesia','Iglesia Parroquial de San Julián y Santa Basilisa','Joya del románico de transición (siglo XII); conserva un espectacular ábside semicircular de sillería caliza con canecillos labrados y una hermosa portada abocinada de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19211','monumento','Núcleos de población de Pareja','El término municipal incluye los siguientes núcleos de población: Cereceda, Casasana y Tabladillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19211','iglesia','Iglesia de la Asunción de Nuestra Señora (Pareja)','Magna edificación renacentista del siglo XVI construida en excelente sillería caliza por los maestros de la escuela de cantería de la Alcarria, notable por sus grandes proporciones, contrafuertes exteriores cilíndricos y amplias bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19211','palacio','Palacio de los Obispos de Cuenca','Restos de la residencia veraniega episcopal del siglo XIV edificada en sillarejo y cantería, de la que subsiste la portada principal con arco apuntado y potentes lienzos de muralla almenados integrados en el caserío urbano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19211','iglesia','Iglesia de la Asunción (Cereceda)','Templo románico de finales del siglo XII construido en cantería caliza, que conserva intacto su ábside semicircular con saeteras abocinadas y una cornisa ornamentada con canecillos de temática zoomorfa y geométrica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19211','iglesia','Iglesia de la Santa Cruz (Casasana)','Construcción del siglo XVI en mampostería con esquinas de sillería bien','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19212','palacio','Palacio Ducal','Obra cumbre del Renacimiento español diseñada en la década de 1540 por el arquitecto Alonso de Covarrubias en sillería caliza calavera, caracterizada por su fachada simétrica con torres angulares, suntuosos artesonados mudéjares y platerescos interiores y los aposentos donde estuvo recluida la Princesa de Éboli.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19212','iglesia','Colegiata de Nuestra Señora de la Asunción','Templo monumental gótico-renacentista ampliado en el siglo XVII en sillería regular, cuyo interior alberga el panteón ducal bajo el altar mayor, una valiosísima colección de tapices flamencos góticos del siglo XV de Alfonso V de Portugal y un coro con sillería de nogal tallada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19212','iglesia','Convento del Carmen','Cenobio fundado por Santa Teresa de Jesús y San Juan de la Cruz en 1569 a las afueras de la villa, erigido en mampostería caliza y sillería, que destaca por la severa austeridad de su iglesia barroca y su claustro procesional rústico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19212','iglesia','Convento de San Francisco','Complejo conventual del siglo XV reformado en el siglo XVII en aparejo toledano y ladrillo, del que resalta su claustro clasicista de dos pisos con arquerías de medio punto sobre pilastras toscanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19212','monumento','Fuente de los Cuatro Caños','Monumento civil de estilo renacentista del siglo XVI labrado en piedra caliza, compuesto por un gran pilón octogonal y un templete central profusamente decorado con mascarones heráldicos de los que manan los caños.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19214','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica de mampostería caliza en el corazón del Alto Tajo, con una robusta espadaña de líneas sencillas y un interior muy austero adaptado al entorno serrano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19215','iglesia','Iglesia de Santa Eulalia de Mérida','Edificio renacentista del siglo XVI ejecutado en sillería y sillarejo calizo, que destaca exteriormente por su soberbia portada meridional de estilo plateresco con decoración de grutescos y columnas abalaustradas, y un espacioso interior de tres naves.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19215','iglesia','Ruinas del Convento de San Francisco (La Salceda)','Vestigios del histórico cenobio franciscano fundado en el siglo XIV, construidos en mampostería rústica, de los que apenas subsisten lienzos desmochados de las celdas y la base perimetral de la antigua iglesia conventual.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19216','iglesia','Iglesia Parroquial de San Mateo','Monumental templo del gótico tardío y renacimiento (siglo XVI) en el corazón del Alto Tajo; construido íntegramente con grandes sillares de piedra arenisca roja de canteras locales, destaca por su ábside poligonal con recios contrafuertes y su torre fortificada adaptada al clima serrano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19218','iglesia','Iglesia de Nuestra Señora de los Asados','Excepcional ejemplo de románico rural del siglo XII levantado en regular cantería caliza, caracterizado por conservar intacta su galería porticada meridional con arquerías de medio punto apoyadas sobre columnas geminadas con capiteles decorados con motivos vegetales y arpías.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19220','monumento','Castillo de Pioz','Obra maestra de la arquitectura militar señorial y residencial del gótico tardío (siglo XV) encargada por el cardenal Mendoza y diseñada por Lorenzo Vázquez; espectacular fortaleza de planta cuadrada edificada en sillería caliza calavera, destacando su foso defensivo perimetral abismal, su robusta Torre del Homenaje cilíndrica y un recinto exterior de barbacanas circulares en perfecto estado de conservación.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19220','iglesia','Iglesia Parroquial de San Juan Bautista','Templo del siglo XVI de estilo renacentista rural castellano con una robusta torre de sillería caliza calavera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19221','monumento','Castillo de Piqueras','Vestigios de una pequeña fortaleza señorial del siglo XV erigida en sillería y mampostería caliza de la que subsisten paños de muralla y los restos de una torre defensiva de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19221','iglesia','Iglesia Parroquial de la Asunción','Templo renacentista del siglo XVI construido en mampostería con contrafuertes de sillería que aloja un presbiterio cubierto por bóveda de cañón con lunetos y un coro alto con balaustrada de madera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19223','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica de mampostería caliza en los cañones del Alto Tajo, con una robusta espadaña de líneas sencillas y un interior desprovisto de grandes adornos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19224','iglesia','Iglesia Parroquial de San Martín','Edificio del siglo XVI de estilo renacentista rural castellano, construido con fábrica mixta de ladrillo visto y cajones de mampostería caliza, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19226','monumento','Casco Urbano (Arquitectura Negra)','Conjunto de viviendas e infraestructuras agrarias tradicionales hechas de lajas de pizarra rústica local sin argamasa adaptadas a la Sierra de Ayllón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19226','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Edificio religioso barroco popular edificado siguiendo los cánones constructivos tradicionales de pizarra rústica local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19227','monumento','Núcleos de población de Prados Redondos','El término municipal incluye los siguientes núcleos de población: Chera y Pradilla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19227','monumento','Monumentos Medicinales','Monumentos Medicinales','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19227','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI de estilo renacentista rural del Señorío de Molina, construido con fábrica rústica de mampostería de piedra arenisca, con una espadaña castellana tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19228','iglesia','Iglesia de San Roque','Fábrica barroca del siglo XVII construida mediante aparejo de sillería basta y mampostería, caracterizada por su espadaña escalonada de ladrillo y piedra y un presbiterio con arco triunfal de medio punto moldurado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19229','monumento','Casco de la Puebla (Arquitectura de Arcilla Roja)','Todo el entramado urbano destaca por su arquitectura popular que combina la mampostería de pizarra con el uso extensivo de tapial y arcilla de color rojo intenso, mimetizándose con los barrancos del entorno.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19229','iglesia','Iglesia Parroquial de San Juan Bautista','Templo que conserva trazas del románico de transición (siglo XII) en su portada abocinada de piedra caliza calavera y espadaña tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19230','iglesia','Iglesia Parroquial de Nuestra Señora de la Blanca','Templo de origen renacentista (siglo XVI) con','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19231','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Joya del románico rural de la sierra (siglo XII); destaca su espectacular ábside semicircular de sillería caliza limpia con canecillos labrados y una hermosa portada abocinada de arcos de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19233','iglesia','Iglesia de la Asunción de Nuestra Señora','Fábrica del siglo XVI levantada en aparejo mixto de piedra caliza calavera y cajones de mampostería, rematada por una torre campanario de planta cuadrangular adosada al muro norte con dos vanos de medio punto en su cuerpo superior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19234','iglesia','Ruinas del Monasterio de Santa María de Bonaval','Impresionante cenobio cisterciense fundado en 1164 por Alfonso VIII y edificado en magnífica sillería caliza, del cual subsisten los imponentes restos de la iglesia del siglo XIII con bóvedas de crucería ojival, el ábside poligonal con ventanales apuntados y capiteles ricamente ornamentados con motivos vegetales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19234','iglesia','Iglesia de la Asunción','Templo parroquial de tipología rural construido en el siglo XVII con lajas de pizarra rústica y sillarejo, que alberga elementos artísticos procedentes del expolio del vecino monasterio cisterciense.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19235','monumento','Núcleos de población de Riba de Saelices','El término municipal incluye los siguientes núcleos de población: Ribarredonda, La Loma y Ablanque.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19235','monumento','Cueva de los Casares','Yacimiento arqueológico y cueva prehistórica de relevancia internacional que contiene grabados rupestres del Paleolítico Superior ejecutados sobre las paredes de caliza, además de un importante nivel arqueológico del Musteriense y restos paleontológicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19235','iglesia','Iglesia de Santa María Magdalena (Riba de Saelices)','Obra románica tardía del siglo XIII modificada en el siglo XVI en cantería roja de rodeno y caliza, de la que sobresale su portada meridional de arquivoltas apuntadas y capiteles con motivos heráldicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19235','iglesia','Iglesia de San Juan Bautista (Ribarredonda)','Fábrica rural del siglo XVI levantada en sillería arenisca, provista de una espadaña exenta sobre el hastial occidental y una pila bautismal románica troncocónica con decoración sogueada en su borde exterior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19237','iglesia','Iglesia de la Asunción','Templo del siglo XVI edificado en piedra arenisca roja (pétreo rodeno) típica del Señorío de Molina, dotado de un ábside de planta poligonal reforzado por estribos angulares y una portada de líneas clasicistas bajo arco adintelado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19237','monumento','El Capricho de Rillo','Singular construcción residencial del siglo XX diseñada en estilo modernista neogaudiniano por Juan Antonio Martínez empleando mampostería, ladrillo moldurado, azulejería polícroma y sinuosas formas orgánicas que imitan elementos de la naturaleza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19239','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hleras de ladrillo visto, que conserva una sobria torre campanario barroca de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19240','iglesia','Iglesia de San Gil','Templo románico de transición edificado en el siglo XIII en sillería arenisca y reformado en el siglo XVI, que muestra una hermosa portada meridional de tres arquivoltas de medio punto decoradas con puntas de diamante y capiteles zoomorfos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19242','iglesia','Iglesia de San Pedro Apóstol','Edificio renacentista del siglo XVI atribuido a las trazas de Alonso de Covarrubias, construido en sillarejo calizo con esquinas reforzadas, destacando su portada meridional purista y un coro soportado por un gran arco escarzano de cantería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19243','iglesia','Iglesia de Nuestra Señora de la Asunción','Magna edificación de origen románico del siglo XII ampliada en el siglo XVI en sillería de arenisca y caliza, sobresaliente por su ábside semicircular con semicolumnas adosadas, ventanales abocinados con capiteles historiados y una colosal torre almenada defensiva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19200','palacio','Palacio de los Centelles','Ruinas y restos consolidados de una suntuosa residencia señorial fortificada del siglo XVI de estilo renacentista-gótico, de la que destaca su fachada monumental de sillería de cantería regular y sus salones nobles integrados parcialmente en el casco antiguo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19200','iglesia','Iglesia Parroquial de Santa María la Mayor','Monumental templo columnario de estilo barroco academicista erigido en el siglo XVIII en sillería caliza de primer orden que exhibe una fachada monumental flanqueada por pilastras y un interior basilical de tres naves de gran altura cubiertas por bóvedas de cañón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19200','iglesia','Iglesia de San Roque','Templo edificado en el siglo XVIII sobre una antigua mezquita andalusí en el barrio del Raval que presenta muros perimetrales de aparejo mixto de piedra y ladrillo visto rematados por una gran cúpula sobre el crucero decorada con azulejería vidriada azul.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19201','iglesia','Monasterio de Santa María de Buenafuente del Sistal','Complejo cenobítico cisterciense fundado en el siglo XII, edificado en sillería caliza calavera, cuya iglesia románica posee una sola nave cubierta con bóveda de cañón apuntado y un claustro austero de arcos de medio punto sobre pilares macizos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19201','iglesia','Iglesia de la Asunción','Fábrica románica tardía del siglo XIII construida en cantería basta, que mantiene su ábside semicircular con saeteras abocinadas y capiteles interiores decorados con palmetas cistercienses.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19203','monumento','Núcleos de población de El Ordial','El término municipal incluye los siguientes núcleos de población: La Navas de de Sigüenza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19203','iglesia','Iglesia de San Sebastián (El Ordial)','Exponente de la arquitectura negra del siglo XVI erigido en lajas de pizarra rústica cementadas con barro, presentando un porche cubierto soportado por pies derechos de madera y una espadaña de pizarra compacta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19203','ermita','Ermita de San Roque (Las Navas de de Sigüenza)','Humilde capilla rural edificada en mampostería de pizarra con cubierta de teja plana, destacando su adaptación formal a las tipologías constructivas serranas tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90003','monumento','Núcleos de población de Abegondo','El término municipal incluye los siguientes núcleos de población: Abegondo, Cabanas, Crendes, Cullergondo, Figueroa, Folgoso, Leiro, Limiñón, Mabegondo, Meangos, Montouto, Orto, Presedo, Sarandóns, Vilacova, Vizoño y Meangos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90003','iglesia','Iglesia Parroquial de Santaia de Abegondo','Templo de factura románica del siglo XII que destaca por su ábside semicircular erigido en sillería granítica gálica y por su portada','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90003','palacio','Pazo de Macenda','Residencia palaciega solariega de los siglos XVII y XVIII construida con mampostería de pizarra rústica y refuerzos de sillería de granito berroqueño en las esquinas, cuyo conjunto exhibe una planta en L protegida por un imponente muro almenado donde resalta un escudo heráldico finamente tallado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90003','iglesia','Iglesia de San Pedro de Crendes','Construcción de origen medieval reformada en las etapas barroca y neoclásica que atesora en su presbiterio un retablo mayor de madera de sabina policromada, complementado en el exterior por una sacristía adosada y un crucero pétreo de excelente factura etnográfica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90003','palacio','Pazo de Figueroa','Complejo señorial edificado entre los siglos XVI y XVIII que se estructura en torno a una torre defensiva de traza gótica tardía, rodeada por extensos jardines con fuentes de cantería y un hórreo tradicional de cantería de granito de tipología gallega con tipología de múltiples claros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90184','monumento','Núcleos de población de Ames','El término municipal incluye los siguientes núcleos de población: Agrón, Ameixenda, Ames, Biduído, Bugallido, Covas, Lens, Ortoño, Piñeiro, Tapia y Trasmonte.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90184','monumento','Ponte Maceira','Monumental paso viario de origen romano reedificado en el siglo XIV sobre el río Tambre que cuenta con cinco arcos de sillería granítica calavera, destacando el gran arco apuntado central y un entorno etnográfico completado por antiguos molinos de agua y capillas barrocas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90184','palacio','Pazo de Lens','Conjunto residencial cortesano del siglo XVII levantado con aparejo granítico rústico y cubiertas de teja plana que conserva su portalón blasonado barroco, una capilla privada bajo la advocación de San José y un hórreo monumental de tipología mixta de piedra y madera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90184','iglesia','Iglesia de San Tomé de Ames','Templo parroquial de traza barroca clasicista del siglo XVIII edificado en cantería de granito que presenta una planta de cruz latina con bóvedas de cañón, albergando en su altar mayor un sagrario de madera noble dorada y una imaginería de gran devoción comarcal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90184','palacio','Pazo de San Lourenzo de Agrón','Edificación palaciega rural del siglo XVIII estructurada en dos plantas simétricas con balconadas de hierro forjado apoyadas sobre ménsulas pétreas, la cual se halla inmersa en una explotación agrícola histórica rodeada de robledales autóctonos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90185','monumento','Núcleos de población de Aranga','El término municipal incluye los siguientes núcleos de población: Aranga, Cambás, Feás, Muniferral, San Fiaz de Monfero y Vilarraso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90185','iglesia','Iglesia de San Tomé de Muniferral','Joya del románico rural gallego del siglo XII levantada íntegramente con sillería de granito gálico que presenta una nave única con cabecera rectangular, rematada por una interesante colección de canecillos esculpidos con motivos antropomorfos y geométricos bajo los aleros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90185','monumento','Ponte Vella de Aranga','Estructura de un solo arco ojival construida sobre el curso alto del río Mandeo durante la Baja Edad Media con mampostería de pizarra y dovelas graníticas, constituyendo un paso histórico fundamental en las antiguas rutas de arriería hacia el interior gallego.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90185','ermita','Ermita de San Pedro de Cambás','Pequeño santuario de romería edificado en el siglo XVII sobre una colina paisajística empleando piedra rústica y techumbre de madera de castaño, cuyo porche delantero sostenido por pilares ofrece cobijo a los peregrinos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90001','monumento','Núcleos de población de Ares','El término municipal incluye los siguientes núcleos de población: Caamouco, Cervás, Lubre y Redes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90001','iglesia','Monasterio de Santa Catalina de Montefaro','antiguo complejo monástico fortificado fundado en el siglo XIV por los condes de Andrade que conserva tres majestuosos claustros de sillería granítica berroqueña de estilos renacentista y barroco, una torre de planta cuadrada y pinturas murales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90001','monumento','Núcleo Marinero de Redes','extraordinario conjunto de arquitectura popular costera caracterizado por sus viviendas tradicionales construidas al borde del agua con fachadas provistas de galerías acristaladas de madera noble, accesos directos para las embarcaciones y portalones de cantería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90001','iglesia','Iglesia de San Miguel de Cervás','edificación de origen románico del siglo XII modificada en el barroco que conserva su cabecera rectangular primitiva de sillería isódoma perfecta, una portada occidental de arquivoltas lisas y una valiosa serie de canecillos geométricos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90002','monumento','Núcleos de población de Arteixo','El término municipal incluye los siguientes núcleos de población: Armentón, Arteixo, Barrañán, Chamín, Sorrizo, Suevos, Oseiro, Morás, Loureda, Pastoriza, Lañas y Larín.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90002','iglesia','Santuario de Nuestra Señora de la Pastoriza','Templo de peregrinación de origen medieval reformado profundamente durante el siglo XVII en estilo barroco que destaca por su fachada de cantería granítica gálica coronada por una robusta espadaña ornamental y por albergar una talla gótica de la Virgen de gran devoción marinera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90002','iglesia','Iglesia de Santiago de Arteixo','Joya del románico rural del siglo XII construida íntegramente con sillería de granito berroqueño que presenta una nave única rematada en ábside semicircular, donde sobresalen sus capiteles historiados con motivos zoomorfos y una magnífica colección de canecillos bajo el alero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90002','palacio','Pazo de Mosende','Complejo palaciego del siglo XVIII edificado con aparejo granítico rústico y muros de mampostería de pizarra que conserva su portalón almenado con escudo de armas familiar, un hórreo tradicional de seis pies de piedra y una pequeña capilla privada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90002','iglesia','Iglesia de San Estevo de Larín','Edificio de transición al gótico levantado en el siglo XIII empleando sillería caliza calavera en sus vanos primordiales, cuyo interior custodia pinturas murales renacentistas fragmentarias descubiertas tras el retablo mayor barroco de madera de sabina policromada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90186','monumento','Núcleos de población de Arzúa','El término municipal incluye los siguientes núcleos de población: Arzúa, Branzá, Burres, Campo, Castaneda, Dodro, Dombodán, Figueroa, Borraxeiros, Maroxo, Mella, Oyón, Pantiñobre, Rendal, San Martiño de Calvos, Santa María de Arzúa, Tronceda, Viñós, Viladavil y Vilantime.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90186','iglesia','Capilla de la Magdalena','Antiguo hospital de peregrinos agustinos fundado en el siglo XIV que fusiona elementos del gótico tardío con sillería granítica gálica bien escuadrada, conservando una portada de arco apuntado y un interior umbrío de gran misticismo jacobeo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90186','iglesia','Iglesia de Santiago de Arzúa','Templo parroquial reedificado en el siglo XX sobre una base barroca anterior utilizando granito berroqueño de canteras locales, cuya monumental fachada historicista flanquea el paso de los peregrinos del Camino Francés hacia Santiago de Compostela.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90186','palacio','Pazo de Brandeso','Residencia solariega de los siglos XVII y XVIII vinculada a la literatura gallega que cuenta con una planta en escuadra levantada en mampostería de pizarra rústica, una solana apoyada sobre ménsulas pétreas y un monumental palomar circular exento.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90186','iglesia','Iglesia de San Pedro de Mella','Pequeña construcción románica del siglo XII que mantiene su fábrica original de sillería granítica a pesar de las adiciones barrocas del siglo XVIII, destacando la sobria portada occidental con tímpano liso apoyado sobre mocárgenes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15081','monumento','Núcleos de población de As Somozas','El término municipal incluye los siguientes núcleos de población: As Somozas, Recemel, Seixas y Enchousas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15081','iglesia','Iglesia Parroquial de Santiago Seré','Templo rural del siglo XVIII erigido con fábrica mixta de mampostería de pizarra y refuerzos angulares de granito berroqueño que presenta una planta de cruz latina con una modesta espadaña de dos ojos y un crucero pétreo tradicional situado en el atrio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15081','monumento','Crucero de San Roque','Elemento de la arquitectura etnográfica sacra del siglo XIX tallado en piedra rústica granítica que muestra en su capitel imágenes esquemáticas de la Pasión, constituyendo un hito devocional en los antiguos senderos que comunicaban los valles interiores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15070','monumento','Núcleos de población de As Pontes de García Rodríguez','El término municipal incluye los siguientes núcleos de población: Aparral, Bermuy, Deveso, Espiñaredo, Goente, Ribadeume, San Pedro de Eume, Seoane, Somede, Vilavella y As Pontes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15070','monumento','Puente de los Moros','Estructura viaria de origen medieval reconstruida en el siglo XV sobre el río Eume empleando aparejo de pizarra rústica combinada con dovelas de granito gálico, cuyo arco apuntado central ha resistido las crecidas históricas de la cuenca fluvial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15070','iglesia','Iglesia de Santa María de As Pontes','Templo de traza barroca clasicista del siglo XVIII levantado en sillería de granito berroqueño que destaca por la volumetría de su nave central y su torre campanario exenta, la cual dota al perfil urbano de una notable verticalidad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90187','monumento','Núcleos de población de A Baña','El término municipal incluye los siguientes núcleos de población: Barcala, Corneira, Fiopáns, Lañas, Monte y Troitosende.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90187','iglesia','Iglesia de San Juan de Barcala','templo de origen románico profundamente modificado en el siglo XVIII que destaca por conservar su cabecera rectangular medieval','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90187','palacio','Pazo de Guimaráns','gran residencia hidalga del siglo XVII de planta rectangular adaptada al entorno rural que presenta muros macizos de mampostería vista combinada con granito, portalón adintelado con escudo de armas familiares labrado y solainas de madera noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90187','monumento','Cruceiro de Troitosende','monumento etnográfico religioso exento del siglo XIX labrado en granito por maestros canteros locales que presenta un fuste octogonal sobre tres gradas cuadradas, capitel jónico moldurado y una cruz superior con el relieve de la Piedad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90003','monumento','Núcleos de población de Bergondo','El término municipal incluye los siguientes núcleos de población: Cortiñán, Guísamo, Lubre, Moruxo, Ouces y Rois.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90003','iglesia','Monasterio de San Salvador de Bergondo','cenobio medieval de la Orden de San Benito fundado en el siglo XII que conserva una monumental iglesia románica de tres naves con absidiolos poligonales de cantería regular, una portada de arquivoltas profundas labradas y pinturas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90003','palacio','Pazo de Mariñán','magno complejo palaciego barroco del siglo XVIII declarado Conjunto Histórico-Artístico que destaca por su suntuosa fachada de sillería granítica gálica perfectamente labrada, una escalinata imperial simétrica con estatuas y unos jardines románticos botánicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90003','iglesia','Iglesia de San Juan de Lubre','edificación románica rural de finales del siglo XII que preserva su nave única original de sillería isódoma perfecta, una portada occidental de arquivoltas lisas y una valiosa serie de canecillos geométricos bajo el alero del tejado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01003','monumento','Núcleos de población de Betanzos','El término municipal incluye los siguientes núcleos de población: Brabío, Piadela, Pontellas, Requián y Tiobre.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01003','iglesia','Iglesia de San Francisco','monumental templo gótico mendicante del siglo XIV que alberga en su interior el célebre sepulcro de Fernán Pérez de Andrade sustentado por las figuras esculpidas de un oso y un jabalí bajo una cubierta de arcos apuntados de gran finura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01003','iglesia','Iglesia de Santa María del Azogue','joya del gótico gallego de transición construido entre los siglos XIV y XV por el Gremio de Mareantes que destaca por su fachada occidental con un gran rosetón calado y un testero con tres ábsides poligonales de sillería granítica gálica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01003','iglesia','Iglesia de Santiago','templo gótico del siglo XV erigido sobre una fábrica románica anterior que presenta una portada principal con el relieve ecuestre del apóstol Santiago Matamoros y una esbelta torre-campanario barroca del siglo XVIII.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01003','monumento','Murallas y Puertas de Betanzos','restos del recinto fortificado medieval que conservan tramos de lienzos construidos con aparejo regular junto a tres de sus puertas originales conocidas como la Porta da Vila, la Porta de San Pedro y la Porta de de la Ribeira.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01003','monumento','Parque del Pasatiempo','singular jardín enciclopédico y monumental de principios del siglo XX concebido por los hermanos García Naveira que congrega grutas artificiales, estanques y colosales relieves figurativos esculpidos en piedra y cemento tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90188','monumento','Núcleos de población de Boimorto','El término municipal incluye los siguientes núcleos de población: Andavao, Cardeiro, Mercurín, Rodieiros, Sendelle y Os Ánxeles.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90188','iglesia','Iglesia de Santa María de Sendelle','edificación de origen románico de finales del siglo XII estrechamente vinculada al Camino de Santiago que conserva en su ábside rectangular unas extraordinarias pinturas murales al fresco de época renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90188','palacio','Pazo de de Os Ánxeles','gran residencia hidalga del siglo XVII de planta rectangular que exhibe una fachada de sillería granítica berroqueña, un portalón de acceso provisto de pináculos heráldicos y grandes escudos nobiliarios labrados en piedra noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90188','monumento','Cruceiro de Mercurín','monumento etnográfico exento del siglo XVIII labrado en granito por maestros canteros locales que presenta un fuste octogonal sobre gradería cuadrada, capitel jónico moldurado y una cruz superior ornamentada con las imágenes de la Pasión.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01004','monumento','Núcleos de población de Boiro','El término municipal incluye los siguientes núcleos de población: Abanqueiro, Cespón, Macenda, Runs y Os Ánxeles.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01004','monumento','Yacimiento de los Castros de Neixón','complejo arqueológico musealizado al borde de la ría que conserva dos poblados fortificados de la Edad del Hierro y época romana con defensas perimetrales de fosos y bases de viviendas de mampostería en seco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01004','palacio','Pazo de Goiáns','monumental conjunto palaciego fortificado del siglo XVI profundamente reformado en el siglo XVIII que destaca por su imponente torre del homenaje almenada, su portalón con escudo de armas y un frondoso jardín cercado por murallas de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01004','iglesia','Iglesia de San Vicenzo de Cespón','templo de origen románico modificado en época barroca que conserva de su fábrica medieval la estructura de su cabecera rectangular de sillería isódoma perfecta y una valiosa serie de canecillos geométricos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90189','monumento','Núcleos de población de Boqueixón','El término municipal incluye los siguientes núcleos de población: Codeso, Ledesma, Loureda, Sergude, Vigo y Oural.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90189','iglesia','Monasterio de San Sebastian de de de de Pico Sacro','restos consolidados de una antigua fundación monástica erigida en lo alto de una prominente aguja de roca cuarcítica que conserva una pequeña iglesia románica de nave única y ábside semicircular regular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90189','monumento','Puente de Ledesma','monumental estructura civil de origen medieval reformada en el siglo XVIII que salva el curso del río Ulla mediante una sucesión de nueve grandes arcos apuntados de sólida cantería granítica provistos de potentes tajamares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90189','palacio','Pazo de de Casal de de de de Loureda','gran casona hidalga del siglo XVII que presenta una fisionomía maciza construida con aparejo mixto de piedra combinada con granito, portalón adintelado con un escudo de armas familiar labrado y una amplia solaina.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90190','monumento','Núcleos de población de Brión','El término municipal incluye los siguientes núcleos de población: Bastavales, Boullón, Ons, San Salvador, V◌े ◌ं स y Os Ánxeles.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90190','monumento','Torres de Altamira','restos monumentales de una imponente fortaleza medieval del siglo IX que sirvió de matriz a la poderosa casa noble de los Moscoso, conservando sus basamentos de sillería granítica gálica y lienzos defensivos derruidos por las revueltas irmandiñas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90190','iglesia','Iglesia de San Julián de Bastavales','célebre santuario barroco del siglo XVIII inmortalizado por Rosalía de Castro que destaca por su imponente fachada clasicista de cantería, su planta de cruz latina y una esbelta torrecampanario de dos cuerpos bien proporcionados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90190','palacio','Pazo de de de Pousada','casona solariega hidalga del siglo XVII construida con aparejo regular que presenta un monumental portalón de acceso adintelado con los grandes blasones de los llinajes locales, amplias solainas corridas y un antiguo palomar circular exento.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90004','monumento','Núcleos de población de Cabana de Bergantiños','El término municipal incluye los siguientes núcleos de población: Anos, Borneiro, Canduas, Cesullas, Corcoesto y Riobó.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90004','monumento','Dolmen de Dombate','la indiscutible "Catedral del Megalitismo Gallego" musealizada mediante un pabellón protector que conserva una colosal cámara poligonal de la Edad del Cobre formada por siete grandes losas graníticas de sillería berroqueña y pinturas rupestres geométricas en su interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90004','monumento','Castro de Borneiro (A Cidá)','extraordinario poblado fortificado de la Edad del Hierro excavado y excelentemente consolidado que preserva su muralla perimetral defensiva de mampostería en seco, sus fosos y decenas de viviendas circulares indígenas dotadas de vestíbulo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90004','iglesia','Iglesia de San Martiño de de de Riobó','joya del románico rural de finales del siglo XII que destaca por su ábside rectangular de cantería regular perfecta, su portada occidental de arquivoltas molduradas sobre capiteles vegetales y una rica serie de canecillos geométricos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01005','monumento','Núcleos de población de Camariñas','El término municipal incluye los siguientes núcleos de población: Camelle, Xaviña, A Ponte do Porto y Buría.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01005','monumento','Faro de Cabo Vilán','el primer faro eléctrico de España inaugurado en 1896 de arquitectura monumental','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01005','iglesia','Santuario de la Virgen del Monte','oratorio barroco de montaña del siglo XVIII edificado sobre una plataforma pétrea azotada por el océano que presenta una portada adintelada sobria construida con aparejo granítico regular, espadaña de doble vano y una panorámica privilegiada de la ría.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01005','palacio','Pazo de de de de Mourín (A Ponte do Porto)','casona solariega barroca del siglo XVII que presenta una fachada monumental de sillería granítica perfectamente labrada con los blasones heráldicos familiares, amplias solainas orientadas al río y una capilla privada con retablo de tipo cajón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90191','monumento','Núcleos de población de Cambre','El término municipal incluye los siguientes núcleos de población: Anceis, Andeiro, Brexo, Bribes, Cecebre, Pravio, Sigrás y Cela.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90191','iglesia','Iglesia de Santa María de Cambre','monumental obra cumbre del románico compostelano de finales del siglo XII que destaca por su planta basilical de tres naves con transepto y una girola provista de cinco capillas absidiales, una severa fachada con un gran rosetón calado y capiteles historiados de gran finura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90191','palacio','Pazo de Anceis','soberbio complejo palaciego barroco del siglo XVII edificado en sólida sillería granítica que cuenta con un monumental portalón fortificado flanqueado por pináculos heráldicos, grandes blasones de las familias nobles y unos espléndidos jardines simétricos protegidos por murallas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90191','monumento','Villa Romana de Cambre','yacimiento arqueológico romano de época imperial musealizado que preserva los restos habitacionales de un asentamiento residencial, destacando los fragmentos de pinturas murales al fresco conservados in situ y las canalizaciones de un sistema de baño privado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22080','monumento','Núcleos de población de A Capela','El término municipal incluye los siguientes núcleos de población: Caaveiro, Cabalar y A Capela.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22080','iglesia','Monasterio de San Juan de Caaveiro','Cenobio cenobítico fundado en el año 936 emplazado en un risco rocoso en el corazón de las Fragas del Eume que conserva su iglesia monacal románica del siglo XII erigida en sillería de granito gálico, junto a una imponente torre campanario barroca del siglo XVIII y estancias medievales de mampostería de pizarra rústica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22080','iglesia','Iglesia de Santiago de Requián','Templo de filiación románica rural modificado en las etapas moderna y barroca empleando piedra rústica granítica que se caracteriza por su','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15901','monumento','Núcleos de población de Cariño','El término municipal incluye los siguientes núcleos de población: Feás, Landoi, Sismundi, A Pedra y Cariño.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15901','ermita','Ermita de San Xiao de Trebo','pequeño oratorio barroco rural del siglo XVIII levantado sobre los cimientos de un asentamiento romano eclesial que destaca por su techumbre de teja tradicional, sus gruesos muros de mampostería vista granítica y una esbelta espadaña de un solo vano adaptada al clima costero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15901','monumento','Cruces de Término de Landoi','monumentos etnográficos exentos del siglo XIX labrados en granito del país por maestros canteros locales que presentan un fuste octogonal sobre tres gradas cuadradas, capitel jónico moldurado y un remate esculpido con la imagen tradicional de la Piedad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15901','monumento','Casas de Indianos de Cariño','conjunto arquitectónico decimonónico de principios del siglo XX edificado por emigrantes retornados que exhibe fachadas polícromas revestidas de azulejos, grandes ventanales con carpinterías de madera noble y balconadas de hierro forjado de estilo modernista regionalista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01007','monumento','Núcleos de población de Carnota','El término municipal incluye los siguientes núcleos de población: Lariño, Lira, O Pindo, San Mamede y Carnota.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01007','monumento','Hórreo de Carnota','colosal monumento nacional etnográfico construido en el siglo XVIII por el arquitecto Gregorio Quintela que constituye uno de los hórreos más grandes de Galicia al alcanzar casi treinta y cinco metros de longitud, sustentado por veintidós pares de robustos pies de sillería granítica berroqueña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01007','monumento','Hórreo de Lira','monumental estructura etnográfica e industrial menor del siglo XVIII edificada en sillería de cantería regular perfecta que rivaliza en dimensiones con el de Carnota al estar asentado de forma escalonada sobre una gran plataforma rocosa comunal provista de veintidós pies graníticos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01007','iglesia','Iglesia de Santa Columba de Carnota','templo parroquial barroco de mediados del siglo XVIII proyectado con elegante planta de cruz latina que destaca por su fachada clasicista de líneas severas, su torre-campanario de dos cuerpos rematada por pináculos y un retablo mayor churrigueresco de rica talla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15022','monumento','Núcleos de población de Cedeira','El término municipal incluye los siguientes núcleos de población: Cedeira, Cervo, Esteiro, San Román de Montoxo, Piñeiro, Régoa y San Facundo de de Cedeira.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15022','iglesia','Santuario de San Andrés de Teixido','Célebre templo de peregrinación de los siglos XVI y XVIII empotrado en los acantilados marinos que combina la mampostería de pizarra rústica encalada con sillería de granito gálico visto en su portada apuntada de transición al gótico, custodiando en su interior un retablo barroco de madera de sabina policromada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15022','monumento','Castillo de la Concepción','Fortaleza defensiva costera del siglo XVIII levantada sobre un promontorio rocoso para proteger la ría mediante gruesos muros de cantería de granito berroqueño y baluartes artilleros adaptados a la topografía, hoy rehabilitada como centro de interpretación histórica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15022','iglesia','Iglesia de la Virgen del Mar','Templo tardogótico del siglo XV reformado en épocas posteriores que se estructura en una planta de tres naves separadas por arcos apuntados de piedra rústica, donde destaca su techumbre de madera de castaño labrada y su retablo mayor de estilo churrigueresco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15023','monumento','Núcleos de población de Cee','El término municipal incluye los siguientes núcleos de población: Ameixenda, Brens, Lires, Pereiriña, Toba y Cee.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15023','iglesia','Iglesia de Santa María de la Xunqueira','templo de origen gótico del siglo XIV reconstruido en época barroca tras los daños de las invasiones francesas que destaca por conservar su ábside ojival primitivo de sillería granítica gálica y una bóveda de crucería sobre arcos apuntados perfectamente labrados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15023','palacio','Pazo de Cotón (Ameixenda)','gran casona hidalga fortificada del siglo XVII levantada con potentes muros de sillería regular y mampostería granítica que presenta un portalón de acceso adintelado con grandes blasones heráldicos exentos, almenas defensivas y una solaina corrida.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15023','monumento','Fábrica de Carburos de Brens','extraordinario complejo de arqueología industrial de principios del siglo XX edificado con paramentos macizos de piedra vista y estructuras de hierro que testimonia la introducción de la industria hidráulica menor y metalúrgica en los puertos atlánticos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15024','monumento','Núcleos de población de Cerceda','El término municipal incluye los siguientes núcleos de población: Cerceda, Encrobas, Meirama, Queixas, Rodís y Xesteda.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15024','iglesia','Iglesia de San Martiño de Rodís','Templo de origen románico profundamente reformado en el siglo XVIII que destaca por su ábside cuadrangular levantado en sillería de granito berroqueño y por su fachada barroca rematada con una espadaña bicéfala de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15024','palacio','Pazo de Lavandeira','Residencia palaciega rural del siglo XVII construida con muros de mampostería de pizarra rústica y cadenas de sillería granítica gálica en los vanos, la cual conserva un monumental palomar circular exento y un hórreo tradicional de ocho pies de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15025','monumento','Núcleos de población de Cerdido','El término municipal incluye los siguientes núcleos de población: A Barqueira, Os Casás y Cerdido.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15025','iglesia','Iglesia de San Martiño de Cerdido','templo parroquial del siglo XVIII adscrito al estilo barroco rural de la comarca de Ortegal que resalta por su techumbre tradicional de losas de pizarra rústica, sus muros limpios de mampostería granítica y una esbelta espadaña de doble cuerpo rematada por pináculos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15025','monumento','Cruceiro de la Barqueira','monumento etnográfico exento del siglo XIX labrado en granito por canteros locales de la zona que presenta un pedestal moldurado sobre tres gradas, fuste cilíndrico estriado y una cruz superior ornamentada con las imágenes exentas de la Pasión.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15027','monumento','Núcleos de población de Coirós','El término municipal incluye los siguientes núcleos de población: Armea, Coirós de Abaixo, Coirós de Arriba, Lesa, Ois y Santiago de Ois.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15027','iglesia','Iglesia de San Julián de Coirós','joya del románico rural de finales del siglo XII que destaca por su ábside rectangular de sillería isódoma perfecta con saeteras abocinadas, una hermosa portada occidental de tres arquivoltas molduradas sobre capiteles historiados zoomorfos y una valiosa serie de canecillos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15027','palacio','Pazo de de de Ois','casona solariega barroca del siglo XVII construida en aparejo de cantería granítica regular que presenta un monumental portalón de acceso flanqueado por pináculos heráldicos, amplias solainas orientadas al valle sobre columnas pétreas y una capilla privada con retablo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15027','monumento','Yacimiento del Castro de Espenuca','poblado fortificado prehistórico de la Edad del Hierro emplazado sobre un promontorio estratégico que conserva los','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15028','monumento','Núcleos de población de Corcubión','El término municipal incluye los siguientes núcleos de población: Corcubión y Redonda.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15028','iglesia','Iglesia de San Marcos','Templo de estilo gótico marinero construido en el siglo XIV con sillería de granito berroqueño que destaca por su fachada con un magnífico rosetón calado y por albergar en su interior una valiosa talla gótica del evangelista traída de Venecia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15028','monumento','Castillo de San Carlos','Fortaleza defensiva costera del siglo XVIII levantada sobre un promontorio rocoso para proteger la ría mediante gruesos muros de cantería de granito gálico y baluartes artilleros adaptados a la topografía, hoy rehabilitada como museo marítimo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15028','palacio','Pazo de los Condes de Altamira','Residencia señorial del siglo XV reformada profundamente en el XVIII que muestra una fachada de excelente cantería granítica vista con balconadas de hierro forjado apoyadas sobre ménsulas pétreas y un portalón blasonado heráldico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15029','monumento','Núcleos de población de Coristanco','El término municipal incluye los siguientes núcleos de población: Agualada, Cereo, Oca, San Xusto, Seavia y Valenza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15029','iglesia','Iglesia de San Tomé de Oca','templo de origen románico profundamente modificado en el siglo XVIII que destaca por su ábside rectangular medieval de sillería granítica regular con saeteras abocinadas y una serie de canecillos geométricos bajo el alero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15029','palacio','Pazo de Cereo','casona solariega barroca del siglo XVII construida en aparejo de cantería granítica que presenta un portalón de acceso adintelado con blasón familiar flanqueado por pináculos heráldicos, amplias solainas corridas y un palomar circular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15029','monumento','Puente de Lubiáns','estructura civil de origen medieval erigida en sillería de granito berroqueño que salva el curso del río Anllóns mediante arcos apuntados perfectamente consolidados, habiendo servido históricamente para asegurar las comunicaciones de la comarca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15031','monumento','Núcleos de población de Culleredo','El término municipal incluye los siguientes núcleos de población: Almeiras, Burgo, Castelo, Celas, Ledoño, Orro y Sueiro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15031','monumento','Torre de Celas de Peiro','esbelta torre del homenaje exenta de planta cuadrada perteneciente a una fortaleza medieval de la casa de Altamira del siglo XIV que se eleva con potentes muros de sillería granítica berroqueña y conserva sus saeteras defensivas junto a un blasón familiar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15031','iglesia','Iglesia de Santiago de O Burgo','joya del románico de transición de finales del siglo XII estrechamente vinculada al Camino de Santiago Inglés que presenta una planta de nave única con tres ábsides absidiales de sillería regular perfecta, una portada de arquivoltas lisas y capiteles historiados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15031','monumento','Puente del Burgo','monumental estructura civil de origen medieval reformada en época barroca que salva la ría mediante una sucesión de robustos arcos de medio punto ejecutados con grandes bloques de cantería granítica y potentes tajamares triangulares diseñados para resistir las mareas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15032','monumento','Núcleos de población de Curtis','El término municipal incluye los siguientes núcleos de población: Fisteus, Foxado, Santaia de Curtis y Curtis.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15032','iglesia','Iglesia de Santa Eulalia de Fisteus','edificación de origen románico de finales del siglo XII modificada en época barroca que conserva de su antigua fábrica medieval la estructura de su ábside rectangular de sillería isódoma perfecta y una valiosa serie de canecillos geométricos bajo el alero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15032','palacio','Pazo de Bodeus','gran casona hidalga del siglo XVII de planta rectangular que exhibe una fachada de mampostería concertada de pizarra combinada con granito del país, un portalón de acceso provisto de pináculos heráldicos y grandes escudos nobiliarios labrados en piedra noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15032','monumento','Cruceiro de Foxado','monumento etnográfico religioso exento del siglo XVIII labrado en granito por maestros canteros locales que presenta un fuste octogonal sobre tres gradas cuadradas, capitel jónico moldurado y una cruz superior ornamentada con las imágenes exentas de la Pasión.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15033','monumento','Núcleos de población de Dodro','El término municipal incluye los siguientes núcleos de población: Dodro, Laíño y San Xoán de Laíño.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15033','palacio','Pazo de Hermida','Complejo residencial cortesano de los siglos XVII y XVIII donde residieron Rosalía de Castro y Manuel Murguía que cuenta con muros de sillería granítica gálica, una gran solana barroca de piedra y un monumental palomar de planta circular exento.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15033','iglesia','Iglesia de Santa María de Dodro','Templo de traza barroca clasicista del siglo XVIII levantado en sillería de granito berroqueño que destaca por la volumetría de su nave central y su fachada rematada por dos esbeltas torres campanario profusamente ornamentadas con pináculos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15034','monumento','Núcleos de población de Dumbría','El término municipal incluye los siguientes núcleos de población: Berdeogas, Buxantes, Dumbría, O Ézaro, Olveira, Olveiroa y Salgueiros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15034','iglesia','Iglesia de Santa Baia de Dumbría','Templo de origen románico reformado en profundidad en el siglo XVIII por el arquitecto Domingo de Andrade que destaca por su monumental fachada barroca erigida en cantería de granito berroqueño y por su esbelta torre campanario clasicista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15034','monumento','Aldea Etnográfica de Olveiroa','Núcleo rural fortificado tradicional vinculado al Camino de Santiago a Fisterra que conserva una excepcional concentración de hórreos y casas de labranza construidos con sillería de granito gálico y mampostería de pizarra rústica bien restaurados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15035','monumento','Núcleos de población de Fene','El término municipal incluye los siguientes núcleos de población: Barallobre, Fene, Limodre, Magalofes, Maniños, Perlío y San Valentín.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15035','iglesia','Iglesia de San Salvador de Maniños','Templo barroco de la segunda mitad del siglo XVIII levantado con aparejo granítico rústico que cuenta con una planta de cruz latina y una espadaña de dos cuerpos rematada por pináculos barrocos, albergando en su interior un retablo de madera de castaño.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15036','monumento','Núcleos de población de Ferrol','El término municipal incluye los siguientes núcleos de población: Brión, Doniños, Esmelle, Ferrol, Covas, Mandiá, Marmancón, San Xurxo de da Mariña, Santa Cecilia de de Trasancos, Serantes y Vilón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15036','monumento','Arsenal Militar y Astilleros Reales','Monumental complejo de ingeniería naval de la Ilustración proyectado en el siglo XVIII por Jorge Juan que cuenta con diques, tinglados y almacenes erigidos con sillería de granito berroqueño de canteras locales, cuya obra cumbre de la arquitectura neoclásica europea está catalogada como Bien de Interés Cultural.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15036','monumento','Cuartel de Dolores y Puerta del Dique','Recinto militar del siglo XVIII diseñado por Francisco Sabatini que exhibe una fachada palaciega neoclásica labrada en cantería granítica gálica, la cual se organiza en torno a un gran patio de armas porticado con arcos de medio punto y pilastras toscanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15036','monumento','Castillo de San Felipe','Fortaleza baluartada del siglo XVI reformada profundamente en el XVIII que se asienta en la orilla de la ría con imponentes muros cortina de granito berroqueño y baterías artilleras dispuestas en terrazas escalonadas, diseñada para cruzarse los fuegos defensivos con el frente fortificado del Castillo de la Palma.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15036','monumento','Barrio de la Magdalena','Trazado urbano racionalista de la Ilustración diseñado en 1761 en forma de tableta de chocolate que conserva casas burguesas con galerías de madera noble blancas y miradores de hierro forjado, combinados con fachadas con ménsulas de sillería de granito y portales catalogados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01011','monumento','Núcleos de población de Fisterra','El término municipal incluye los siguientes núcleos de población: Duio, Fisterra, San Martiño de de Duio y Sardiñeiro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01011','iglesia','Iglesia de Santa María de las Arenas','Templo de estilo gótico marinero de finales del siglo XII y principios del XIII levantado con sillería de granito gálico que custodia la célebre y devota talla del Santo Cristo de Fisterra, destacando por su','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01011','monumento','Castillo de San Carlos','Reducto defensivo de planta abaluartada mandado construir en el siglo XVIII por el rey Carlos III para guarecer la costa de los ataques corsarios empleando robustos sillares de granito berroqueño, cuyo espacio interior ha sido rehabilitado integralmente como Museo de la Pesca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15038','monumento','Núcleos de población de Frades','El término municipal incluye los siguientes núcleos de población: Abellá, Aiazo, Añá, Céltigos, Frades, Gafoi, Galegos, Ledoira, Moar, Papucín, Vitre y Papucín.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15038','iglesia','Iglesia de San Sanzo de Abellá','Templo parroquial de traza barroca rural modificado en los siglos XVIII y XIX que cuenta con una fábrica mixta de mampostería de pizarra rústica y esquinales reforzados con sillería granítica, abriéndose su atrio tradicional a un paisaje de praderías.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15038','palacio','Pazo de Moar','Antigua casa solariega del siglo XVII construida con piedra rústica y sillería en los vanos que conserva su portalón blasonado barroco con el escudo de armas tallado, un hórreo tradicional de seis pies de granito y restos de una antigua solana de madera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15041','monumento','Núcleos de población de A Laracha','El término municipal incluye los siguientes núcleos de población: Cabovilaño, Caión, Coiro, Erboedo, Golmar, Lemaio, Lendo, Lestón, Montemaior, Soandres, Vilaño, Torás y Soutullo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15041','iglesia','Monasterio de San Pedro de Soandres','Antiguo cenobio benedictino fundado en el siglo X cuya iglesia monacal gótica de transición (siglo XIV) destaca por su ábside rectangular erigido en excelente sillería granítica gálica y por sus capiteles historiados con escenas de cacería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15041','iglesia','Santuario de los Milagros de Caión','Templo barroco del siglo XVIII enclavado sobre un acantilado costero con fábrica de mampostería de pizarra rústica encalada y sillería de granito berroqueño que alberga una venerada imagen mariana vinculada históricamente a los gremios de balleneros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15041','iglesia','Iglesia de San Martiño de Lendo','Joya del románico rural gallego de finales del siglo XII que mantiene su estructura de sillería granítica gálica con portadas de arcos apuntados ornamentados con baquetones geométricos y una rica colección de canecillos fitomorfos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15042','monumento','Núcleos de población de Lousame','El término municipal incluye los siguientes núcleos de población: Camboño, Fruíme, Lesende, Lousame, Leroño, Tállara, Vilacova y San Xusto de Toxosoutos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15042','iglesia','Monasterio de San Xusto de Toxosoutos','Cenobio de la orden del Císter fundado en el siglo XII a la orilla del río San Xusto que conserva su iglesia de sillería de granito berroqueño junto con un bucólico claustro renacentista y restos de canalizaciones preindustriales de piedra rústica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90192','monumento','Núcleos de población de Irixoa','El término municipal incluye los siguientes núcleos de población: Ambroa, Churío, Coruxou, Irixoa, Mántaras, Verís, A Viña y Verís.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90192','iglesia','Iglesia de San Tomé de Ambroa','Templo de origen románico del siglo XII modificado en la época barroca que conserva su nave única de sillería de granito gálico y un tímpano liso en la portada occidental, rodeado por un cementerio tradicional de carácter rural.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90192','monumento','Crucero de Conces en Mántaras','Hito de la arquitectura etnográfica sacra del siglo XVIII esculpido en granito berroqueño que muestra un fuste estriado y un capitel con relieves policromados fragmentarios de la Piedad y la Crucifixión asentados sobre gradas de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15043','monumento','Núcleos de población de Malpica de Bergantiños','El término municipal incluye los siguientes núcleos de población: Barizo, Buño, Cambre, Cerqueda, Leiloio, Malpica, Mens y Vilanova.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15043','monumento','Torres de Mens','Fortaleza bajomedieval del siglo XV reconstruida sobre una estructura anterior del siglo XII que consta de tres torres de planta cuadrada erigidas con sillería de granito berroqueño y mampostería de pizarra rústica, rodeadas por un patio de armas amurallado que fue escenario de las Revueltas Irmandiñas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15043','ermita','Ermita de San Adrián de Malpica','Santuario costero del siglo XVIII levantado en un promontorio azotado por el mar empleando aparejo granítico rústico con esquinales bien escuadrados, cuya arquitectura marinera destaca por su sobria espadaña barroca y por ser el epicentro de una multitudinaria romería comarcal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15043','monumento','Fornos de Buño (Patrimonio Etnográfico e Industrial)','Conjunto de alfares y hornos comunales de tipología tradicional construidos con piedra rústica y barro refractario que testimonian la histórica actividad alfarera de la localidad,','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15045','monumento','Núcleos de población de Mazaricos','El término municipal incluye los siguientes núcleos de población: Alborés, Antes, Arcos, Beba, Chacín, Coiro, Colúns, Corzón, Maroñas, Mazaricos, San Fins de de Eirón y Os Maroñas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15045','iglesia','Iglesia de San Juan de Chacín','Templo románico de finales del siglo XII modificado durante el periodo barroco que mantiene su cabecera rectangular erigida en sillería de granito gálico y una portada occidental con un tímpano esculpido con motivos vegetales y canecillos antropomorfos bajo los aleros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15045','monumento','Puente de Olveiroa (Frontera Municipal)','Construcción viaria de origen medieval que salva el curso del río Xallas mediante arcos de medio punto construidos con aparejo','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15049','monumento','Núcleos de población de Moeche','El término municipal incluye los siguientes núcleos de población: Abade, Labacengos, San Juan de de Moeche, San Jorge de de Moeche y Santa Cruz de de Moeche.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15049','monumento','Castillo de Moeche','Fortaleza feudal del siglo XIV vinculada a la casa de Andrade que presenta una planta poligonal erigida en mampostería de pizarra rústica y una monumental torre del homenaje de sillería de granito berroqueño, cuyo patio de armas fue el epicentro del asalto de la Gran Revolución Irmandiña de 1467.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15049','iglesia','Iglesia de Santiago de Labacengos','Templo de origen medieval reedificado en el siglo XVIII en estilo barroco utilizando aparejo granítico gálico que destaca por su portada clasicista coronada por una espadaña de dos ojos y por albergar un retablo mayor de madera de castaño con imaginería policromada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15050','monumento','Núcleos de población de Monfero','El término municipal incluye los siguientes núcleos de población: O Alto de de Xestoso, Queixeiro, San Fins de de Monfero, Santaxiña de de Xestoso, Taboada, Vilachá y Monfero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15050','iglesia','Monasterio de Santa María de Monfero','Extraordinario cenobio cisterciense fundado en el siglo XII cuya fachada de la iglesia barroca del siglo XVII es única en España por su ajedrezado de sillería de granito berroqueño y placas de pizarra rústica oscura, albergando en su interior los monumentales sepulcros góticos de los Andrade tallados en sillería caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15050','ermita','Ermita de San Xoán de Xestoso','Modesto santuario rural del siglo XVIII levantado en un paraje natural con fábrica mixta de mampostería de pizarra y sillares graníticos gálicos en sus esquinales, cuyo entorno conserva un crucero etnográfico que delimita los antiguos términos señoriales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15051','monumento','Núcleos de población de Mugardos','El término municipal incluye los siguientes núcleos de población: Franza, Meá, Mugardos y Piñeiro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15051','monumento','Castillo de la Palma','Fortaleza militar costera levantada en el siglo XVI a la entrada de la ría de Ferrol y reformada profundamente a finales del siglo XIX mediante baluartes artilleros de hormigón ciclópeo y muros de sillería de granito berroqueño, conformando un sistema de defensa cruzada inexpugnable con el Castillo de San Felipe.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15051','iglesia','Iglesia de San Julián de Mugardos','Templo barroco del siglo XVIII construido con aparejo granítico rústico que presenta una planta de cruz latina con bóveda de cañón y una esbelta torre campanario de líneas clasicistas orientada hacia el núcleo marinero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15053','monumento','Núcleos de población de Muros','El término municipal incluye los siguientes núcleos de población: Abelleira, Louro, Muros, Serres y Torea.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15053','iglesia','Santuario de la Virgen del Camino','Joya del gótico marinero del siglo XV edificada en sillería de granito gálico que presenta una robusta portalada apuntada con un tímpano que representa la Epifanía, custodiando en su interior una devota talla de la Virgen rodeada de maquetas exvoto de embarcaciones.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15053','monumento','Casco Histórico y Soportales de Muros','Conjunto urbano medieval y marinero del siglo XV construido con sillería de granito berroqueño vista y mampostería encalada, cuyas viviendas tradicionales se organizan sobre soportales de arcos rebajados donde los antiguos pescadores reparaban los aparejos a resguardo de la lluvia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01013','monumento','Núcleos de población de Muxía','El término municipal incluye los siguientes núcleos de población: Bardullas, Caberta, Coucieiro, Frixe, Leis, Morquintián, Muxía, Nemiña, Moraime, Ozón, San Martiño de de Ozón, Vilastose y Suxo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01013','iglesia','Santuario de la Virgen de la Barca','Célebre templo de peregrinación erigido en el siglo XVIII a orillas del océano Atlántico sobre una base románica anterior utilizando sillería de granito berroqueño, cuyo conjunto barroco clasicista está rodeado por las legendarias piedras megalíticas "de abalar" y "de cadera" que forman parte de la tradición jacobea.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01013','iglesia','Monasterio de San Julián de Moraime','Antiguo cenobio benedictino del siglo XII cuya iglesia románica posee una fachada occidental con una monumental portada de tres arquivoltas profusamente esculpidas con figuras bíblicas en piedra rústica granítica gálica y un interior que atesora unos valiosos frescos renacentistas del siglo XVI.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01013','monumento','Hórreo de San Martiño de Ozón','Estructura monumental de almacenamiento agrícola del siglo XVIII vinculada al priorato benedictino que destaca por sus descomunales dimensiones al contar con 22 pares de pies esculpidos en granito berroqueño, superando los 27 metros de longitud bajo una cubierta de teja y pináculos barrocos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15054','monumento','Núcleos de población de Narón','El término municipal incluye los siguientes núcleos de población: Castro, Doso, Narón, Pedroso, San Sanzo de de A Gándara, Sedes, Seyanes, Trasancos y O Val.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15054','iglesia','Monasterio de San Martín de Couto (Xuvia)','Cenobio benedictino del siglo XII modificado en la etapa barroca que conserva intacta su cabecera románica de tres ábsides semicirculares erigidos con sillería granítica gálica y capiteles historiados con motivos zoomorfos, constituyendo el corazón histórico de la comarca de Trasancos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15055','monumento','Núcleos de población de Neda','El término municipal incluye los siguientes núcleos de población: Anca, Neda, Santa María de de Neda y Viladonelle.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15055','iglesia','Iglesia de Santa María de Neda','Templo de origen gótico medieval reedificado en el siglo XVIII en estilo barroco que custodia el célebre Cristo de la Cadena, una pieza de imaginería gótica inglesa de alabastro calizo traída por los marineros durante las persecuciones religiosas anglicanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15055','monumento','Casco Viejo y Soportales de la Calle Real','Tramo urbano histórico vinculado al Camino Inglés de Santiago que conserva viviendas burguesas de los siglos XVII y XVIII sustentadas sobre pilares de cantería granítica gálica y vigas de castaño, conformando una estructura de abrigo para la antigua arriería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15056','monumento','Núcleos de población de Negreira','El término municipal incluye los siguientes núcleos de población: Alvite, Aro, Arzón, Broño, Bugallido, Campelo, Campolongo, Covas, Gonte, Landeira, Liñares, Logrosa, Lueiro, Negreira, San Roman, San Sanzo, Pesadoira y Zas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15056','iglesia','Pazo de Cotón y Capilla de San Mauro','Espectacular complejo señorial fortificado del siglo XIV modificado en el XVIII que destaca por su galería de piedra granítica que cruza a modo de puente sobre la antigua carretera real, rematado con almenas defensivas de mampostería de pizarra rústica y un imponente despliegue de blasones heráldicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15056','iglesia','Iglesia de San Julián de Negreira','Templo parroquial de traza barroca clasicista del siglo XVIII erigido en cantería de granito berroqueño que presenta una fachada simétrica rematada por una robusta espadaña bicéfala y un crucero pétreo situado en el centro del atrio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01014','monumento','Núcleos de población de Noia','El término municipal incluye los siguientes núcleos de población: Argalo, Barro, Boa, Noia y Roo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01014','iglesia','Iglesia de Santa María a Nova','Joya del gótico marinero del siglo XIV declarada Monumento Nacional que funciona como museo arqueológico al albergar la mayor colección de laudas sepulcrales gremiales de Europa, talladas entre los siglos XIV y XVII en piedra rústica granítica con inscripciones antropomorfas, marcas de cantero y símbolos heráldicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01014','iglesia','Iglesia de San Martín','Templo de estilo gótico flamígero del siglo XV erigido en sillería de granito gálico que presenta una fachada monumental con un rosetón calado de tracería calada y una espectacular portada esculpida a imitación del Pórtico de la Gloria compostelano, flanqueada por una única torre inacabada según la leyenda señorial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01014','palacio','Pazo de los Churruchaos','Residencia noble fortificada de la Baja Edad Media construida con potentes muros de sillería de granito berroqueño que conserva sus ventanas ojivales','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90193','monumento','Núcleos de población de Ordes','El término municipal incluye los siguientes núcleos de población: Ardemil, Barbeiros, Beán, Buscás, Leira, Mercurín, Ordes, Parada, Pereira, Poulo y Vilamaior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90193','iglesia','Iglesia de San Julián de Poulo','Templo románico del siglo XII modificado en la etapa barroca utilizando sillería de granito gálico que destaca por su portada occidental de arco de medio punto apoyada en capiteles vegetales y por albergar un crucero etnográfico medieval en las inmediaciones del Camino Inglés.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15060','monumento','Núcleos de población de Oroso','El término municipal incluye los siguientes núcleos de población: Deixebre, A Gándara, Marzoa, Oroso, Pasarelos, Senra, Trasmonte y Vilarromarís.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15060','monumento','Puente de Sigüeiro','Monumental viaducto de origen medieval reconstruido en el siglo XIV por la orden franciscana sobre el río Tambre que cuenta con arcos apuntados tallados en sillería de granito berroqueño y potentes tajamares aguas arriba, constituyendo un paso histórico ineludible para los peregrinos del Camino Inglés.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15060','iglesia','Iglesia de San Estevo de Trasmonte','Templo de factura barroca rural del siglo XVIII erigido en aparejo granítico gálico que presenta una planta rectangular con espadaña de dos cuerpos rematada por pináculos barrocos, cuyo interior custodia un retablo de madera de castaño con imaginería policromada fragmentaria.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15061','monumento','Núcleos de población de Ortigueira','El término municipal incluye los siguientes núcleos de población: Barbos, Céltigos, Couzadoiro, Cuíña, Devesos, Espasante, Freires, Insua, Ladrido, Loiba, Luama, Mera de de Arriba, Mera de de Baixo, Mosteiro, San Claudio, San Salvador de de Couzadoiro, Senra, Veiga y Ortigueira.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15061','iglesia','Convento de Santo Domingo e Iglesia Parroquial de Santa Marta','Excepcional complejo conventual fundado en el siglo XIV y reedificado en el XVIII en estilo barroco academicista con sillería de granito berroqueño de canteras locales, cuya fachada destaca por la sobriedad clasicista de sus líneas y por albergar una esbelta torre campanario cupulada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15061','monumento','Antiguo Grupo Escolar "Asilo de Ortigueira" (Patrimonio Indiano)','Espectacular edificio de arquitectura indiana de principios del siglo XX construido con fondos de los emigrantes en América empleando muros portantes de mampostería hidráulica y grandes ventanales simétricos enmarcados por sillares de piedra caliza calavera labrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15062','monumento','Núcleos de población de Outes','El término municipal incluye los siguientes núcleos de población: Cando, Carcoeste, Roo, San Ourente de de Entíns, Santo André de de Outes, Tarás, Valadares y Outes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15062','iglesia','Iglesia de San Ourente de Entíns','Templo de origen románico del siglo XII muy modificado en las etapas barroca y neoclásica que mantiene su cabecera cuadrangular de sillería granítica gálica y una interesante colección de lápidas sepulcrales gremiales medievales decoradas con marcas de cantero en su atrio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15062','palacio','Pazo de la Trava','Residencia solariega cortesana de los siglos XVII y XVIII levantada con mampostería de pizarra rústica encalada y cadenas de sillería granítica en las esquinas que conserva su portalón blasonado barroco, una larga solana de piedra apoyada sobre ménsulas molduradas y un palomar de planta circular exento.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15902','monumento','Núcleos de población de Oza-Cesuras','El término municipal incluye los siguientes núcleos de población: Bandoxa, Carres, Cis, Cuíña, Cutián, Dordaño, Figueredo, Filgueira de de Barranca, Filgueira de de Traba, Loureda, Mandayo, Mondoi, Oza, Paderne, Parada, Porzomillos, Reboredo, Regueira, Rodeiro, Salto, Trasanquelos y Vivente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15902','monumento','Sanatorio de Cesuras (Patrimonio Modernista)','Espectacular e inconcluso edificio antituberculoso diseñado en 1922 por el arquitecto modernista Antonio Tenreiro en medio de un denso bosque de pinos, cuya estructura destaca por el uso pionero de hormigón armado combinado con zócalos de sillería de granito berroqueño y vanos de líneas geométricas puras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15902','iglesia','Iglesia de San Salvador de Trasanquelos','Joya del románico rural del siglo XII levantada íntegramente con sillería de granito gálico que presenta una nave única rematada en ábside semicircular, donde sobresalen sus capiteles historiados con motivos fitomorfos y una magnífica colección de canecillos esculpidos bajo los aleros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15902','palacio','Pazo de Paizás','Complejo señorial fortificado del siglo XVI reformado en el XVIII que se estructura en torno a una torre defensiva de planta cuadrangular erigida en mampostería de pizarra rústica, rodeada por un muro almenado que custodia un patio interior con un portalón heráldico finamente tallado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15065','monumento','Núcleos de población de Padrón','El término municipal incluye los siguientes núcleos de población: Carcacía, Cruces, Herbón, Iria Flavia y Padrón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15065','iglesia','Colegiata de Santa María de Iria Flavia','Monumental templo de fundación paleocristiana reconstruido en el siglo XII por el arzobispo Gelmírez y reformado en el XVII en estilo barroco compostelano utilizando excelente cantería de granito berroqueño, cuyo atrio arbolado cobija más de una veintena de sarcófagos altomedievales esculpidos en piedra rústica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15065','iglesia','Iglesia de Santiago de Padrón y "El Pedrón"','Templo neoclásico de finales del siglo XVIII edificado en sillería granítica gálica que custodia bajo su altar mayor la célebre ara romana de piedra rústica donde, según la tradición jacobea, los discípulos de Santiago el Mayor amarraron la barca de piedra que conducía el cuerpo del apóstol.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15065','iglesia','Convento de San Antonio de Herbón','Complejo monacal franciscano fundado en el siglo XIV y reformado profundamente durante las etapas barroca y neoclásica que destaca por su claustro de dos plantas erigido en cantería granítica y por albergar las históricas huertas donde los monjes introdujeron el cultivo de los célebres pimientos en el siglo XVII.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15065','palacio','Pazo de Quito (Fundación Camilo José Cela)','Residencia palaciega de los siglos XVII y XVIII compuesta por un conjunto de casas canónicas de sillería granítica vista y cubiertas de teja plana que conserva sus solanas de piedra y herrajes de forja tradicionales, hoy rehabilitada como sede del legado del Premio Nobel gallego.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15066','monumento','Núcleos de población de O Pino','El término municipal incluye los siguientes núcleos de población: Arca, Budiño, Carboeiro, Cebreiro, Cerceda, Ferreiros, Gonzar, Lardeiros, Medín, Pastor, Pereira, San Mamede de de Ferreiros, San Miguel de de Cerceda, San Vicente de de Gonzar y O Pino.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15066','iglesia','Iglesia de San Eulalia de Arca','Templo parroquial de traza neoclásica del siglo XIX edificado en sillería de granito berroqueño que presenta una fachada monumental simétrica con un frontón triangular, destacando en su presbiterio un espectacular retablo mayor en forma de concha de vieira vinculado al Camino de Santiago Francés.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15066','monumento','Puente de Lardeiros','Estructura viaria medieval que cruza el río Brandelos mediante arcos de medio punto construidos con aparejo granítico rústico, cuyas dovelas e infraestructuras de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90194','monumento','Núcleos de población de Ponteceso','El término municipal incluye los siguientes núcleos de población: Anllóns, Brantuas, Cores, Corme Aldea, Corme Porto, Cospindo, A Graña, Langueirón, Nemeño, Niñóns, Pazos, Tallo, Tella y Xornes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90194','iglesia','Iglesia de San Julián de Brantuas','Templo de origen románico profundamente reformado durante la etapa barroca del siglo XVIII que destaca por su ábside cuadrangular de sillería granítica gálica y por su fachada rematada en espadaña bicéfala, en cuyo atrio se asienta un crucero pétreo tradicional de alto valor etnográfico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90194','monumento','Puente sobre el río Anllóns','Estructura de ingeniería civil del siglo XIX construida con gruesos arcos rebajados de cantería granítica y mampostería de pizarra que une las dos riberas del estuario, inmortalizada en la literatura gallega por su proximidad a la casa natal del poeta Eduardo Pondal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90194','monumento','Faro de Punta Candelaria (Acceso Comarcal / Corme)','Antigua torre de señalización marítima y control costero erigida en sillería de granito berroqueño y hormigón hidráulico primitivo para guiar a los navegantes frente a los peligrosos acantilados de la Costa de la Muerte.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01017','monumento','Núcleos de población de Pontedeume','El término municipal incluye los siguientes núcleos de población: Andrade, Boebre, Breamo, Centroña, Nogueiros, Ombre, Quintandona y Pontedeume.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01017','monumento','Torre de los Andrade','Monumental torre del homenaje fortificada del siglo XIV que se conserva exenta en el casco urbano con su imponente planta cuadrangular erigida en sillería de granito berroqueño de dieciocho metros de altura, luciendo en su fachada occidental un enorme escudo heráldico con el oso y el jabalí del linaje feudal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01017','iglesia','Iglesia de San Miguel de Breamo','Joya del románico pleno de finales del siglo XII declarada Monumento Nacional que presenta una inusual planta de cruz de Malta con tres ábsides semicirculares construidos con excelente sillería granítica gálica, destacando la pureza de sus bóvedas de cañón y sus portadas con capiteles de motivos geométricos y vegetales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01017','monumento','Puente de Piedra sobre el río Eume','Reconstrucción neoclásica del siglo XIX sobre el monumental paso medieval mandado edificar originalmente por Fernán Pérez de Andrade que cuenta con quince arcos de cantería de granito berroqueño y potentes tajamares, uniendo la villa eumesa con el municipio de Cabanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01017','iglesia','Iglesia Parroquial de Santiago','Templo de transición del gótico al renacimiento del siglo XVI mandado levantar por el arzobispo Fernando de Andrade que custodia en su capilla','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01018','monumento','Núcleos de población de Rianxo','El término municipal incluye los siguientes núcleos de población: Asados, Isorna, Leiro, O Araño, Rianxo y Taragoña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01018','iglesia','Iglesia de Santa Comba de Rianxo','Templo de estilo gótico marinero tardío del siglo XV levantado en sillería de granito berroqueño que destaca por su imponente portada occidental con arco apuntado y un rosetón de tracería calada, la cual cobija en su interior bóvedas de crucería y un retablo barroco de madera de sabina policromada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01018','monumento','Hórreo de O Araño','Estructura monumental de almacenamiento agrícola del siglo XVIII vinculada a la rectoral de la parroquia que constituye uno de los más largos de Galicia con sus 37 metros de longitud, erigido íntegramente en sillería de granito gálico y asentado sobre una hilera de pies de piedra rematados por muelas circulares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01018','monumento','Castillo de la Luna','Ruinas de la fortaleza medieval del siglo XIII erigida por los templarios y desmantelada durante las Revueltas Irmandiñas que conserva lienzos de muralla y los cimientos de la torre del homenaje hechos con mampostería de pizarra rústica y sillería granítica a la orilla de la ría de Arousa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15073','monumento','Núcleos de población de Ribeira','El término municipal incluye los siguientes núcleos de población: Aguiño, Artes, Carreira, Castiñeiras, Corrubedo, Oleiros, Palmeira y Ribeira.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15073','monumento','Dolmen de Axeitos','Monumento megalítico datado en el IV milenio a.C. conocido como la obligación pétrea del Barbanza que consta de una cámara poligonal formada por ocho grandes losas de granito berroqueño y una gigantesca piedra de cubierta intacta, configurando uno de los ejemplos funerarios más puros del neolítico peninsular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15073','iglesia','Iglesia de San Pedro de Palmeira','Templo de origen medieval reedificado en la etapa barroca del siglo XVIII utilizando aparejo granítico gálico que presenta una planta de cruz latina de gran sobriedad exterior, cuya fachada se ve rematada por una espadaña de dos ojos profusamente ornamentada con pináculos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15074','monumento','Núcleos de población de Rois','El término municipal incluye los siguientes núcleos de población: Augasantas, Buxán, Costa, Ermedelo, Herbogo, Leroño, Oín, Ribasar, Rois, Seira, Sorribas y Urdilde.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15074','palacio','Pazo de Antequeira','Residencia señorial de los siglos XVII y XVIII construida con muros de mampostería de pizarra rústica encalada y cadenas de sillería de granito en las esquinas que se organiza en torno a un patio porticado, destacando su portalón blasonado heráldico y una escalinata monumental decorada con balaustradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15074','iglesia','Iglesia de San Vicente de Oín','Templo barroco de mediados del siglo XVIII proyectado bajo la influencia del estilo compostelano con excelente cantería de granito berroqueño, el cual destaca por la volumetría de su fachada principal flanqueada por una esbelta torre campanario cupulada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15075','monumento','Núcleos de población de Sada','El término municipal incluye los siguientes núcleos de población: Carnoedo, Meirás, Mondego, Mosteirón, Osedo, Sada y Soñeiro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15075','palacio','Pazo de Meirás','Complejo palaciego de estilo historicista y neomedieval edificado a finales del siglo XIX sobre las ruinas de una antigua fortificación empleando mampostería de pizarra y sillería de granito gálico, cuyas tres torres almenadas y portadas blasonadas custodian una valiosa biblioteca histórica y piezas de arte catalogadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15076','monumento','Núcleos de población de San Sadurniño','El término municipal incluye los siguientes núcleos de población: Bardaos, Ferreira, Iglesiafeita, Lamas, Naraío, San Sadurniño y Santa Mariña do Monte.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15076','monumento','Castillo de Naraío','Fortaleza feudal del siglo XIV emplazada sobre un escarpado peñasco rocoso que domina el valle del río Grande, construida íntegramente con muros de mampostería de pizarra rústica y una torre del homenaje de planta cuadrangular con esquinales de granito berroqueño que resistió los asaltos irmandiños.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15076','iglesia','Convento del Rosario e Iglesia Parroquial','Antiguo cenobio fundado en el siglo XVI por los señores de la villa que muestra una transición arquitectónica del gótico tardío al barroco en su claustro e iglesia erigidos con sillería granítica gálica bien labrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15077','monumento','Núcleos de población de Santa Comba','El término municipal incluye los siguientes núcleos de población: Alón, Arantón, Bazar, Cícere, Fontecada, Freixeiro, Grixoa, Mallón, Montouto, Padreiro, Santa Comba, Santa Sabiña y Vilamaior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15077','iglesia','Iglesia de San Pedro de Santa Sabiña','Templo de origen románico reformado profundamente durante las etapas barroca y neoclásica que mantiene su cabecera rectangular erigida en sillería de granito gálico y una portada occidental con espadaña de dos cuerpos en su atrio parroquial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15078','monumento','Núcleos de población de Santiago de Compostela','El término municipal incluye los siguientes núcleos de población: Aríns, Bando, Carballal, Cascajales, Conxo, Conxo de Abaixo, Enfesta, Fecha, Figueras, Grixoa, Laraño, Marantes, San Lázaro, Santa Cristina de Fecha, Santiago de Compostela, Verdía y Vidán.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15078','catedral','Catedral Metropolitana de Santiago','Obra cumbre del arte románico, barroco y neoclásico europeo declarada Patrimonio de la Humanidad que se erige sobre la tumba del apóstol con una monumental estructura de sillería de granito berroqueño, destacando el Pórtico de la Gloria tallado por el Maestro Mateo en el siglo XII, la fastuosa fachada barroca del Obradoiro levantada por Casas y Novoa en el siglo XVIII y las suntuosas portadas de Platerías y la Quintana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15078','iglesia','Monasterio de San Martín Pinario','Inmenso complejo monacal benedictino fundado en el siglo X y reedificado entre los siglos XVI y XVIII que constituye el segundo edificio religioso más grande de España, cuya fachada barroca de cantería granítica gálica presenta columnas toscanas colosales y un remate esculpido con San Martín partiendo su capa con un mendigo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15078','monumento','Hostal de los Reyes Católicos','Antiguo hospital real de peregrinos fundado en 1501 por orden de Isabel de Castilla y Fernando de Aragón que combina elementos del gótico flamígero, plateresco y renacentista, cuya portada principal labrada en finísima sillería caliza calavera por Enrique Egas da paso a cuatro majestuosos claustros porticados de cantería granítica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15078','palacio','Palacio de Rajoy','Edificio de traza neoclásica francesa proyectado en el siglo XVIII por el arquitecto Charles Charles Lemaur para servir como seminario de confesores y','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15078','iglesia','Colegiata de Santa María la Real del Sar','Joya del románico de transición del siglo XII edificada con sillería granítica gálica que destaca por el asombroso desplome e inclinación de los muros de su nave central provocados por los empujes de las bóvedas, obligando a la construcción en el siglo XVIII de unos monumentales contrafuertes exteriores de piedra rústica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15079','monumento','Núcleos de población de Santiso','El término municipal incluye los siguientes núcleos de población: Barazón, Beigondo, Belmil, Liñares, Novela, Pezobre, Pezobrés, Ribadulla, San Román, Santiso, Suñide, Visantoña y Vimianzo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15079','iglesia','Iglesia de San Estevo de Pezobre','Templo románico rural del siglo XII levantado con sillería de granito gálico que presenta una nave única con cabecera rectangular, rematada por una interesante colección de canecillos esculpidos con motivos geométricos bajo los aleros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15080','monumento','Núcleos de población de Sobrado','El término municipal incluye los siguientes núcleos de población: Carelle, A Ciadella, Codesoso, Cumbraos, Folgoso, Grixalba, Nogueira, Porta, Pousada, Roade, Sobrado y Vilariño.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15080','iglesia','Monasterio de Santa María de Sobrado de los Monjes','Monumental cenobio cisterciense fundado en el siglo X y reedificado monumentalmente entre los siglos XVI y XVIII que destaca por la imponente fachada barroca de su iglesia monacal, labrada en excelente sillería de granito berroqueño con un dinamismo de líneas curvas que da paso a una colosal cúpula y a los claustros de los Caballeros, de la Hospedería y de las Procesiones.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15080','monumento','Campamento Romano de Ciadella (Frontera Arqueológica)','Yacimiento militar del siglo II d.C. que conserva los cimientos perimetrales de sillería de granito y piedra rústica de un recinto fortificado romano de la Cohors I Celtiberorum, destacando los restos de la praetoria y los muros de los barracones.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15082','monumento','Núcleos de población de Teo','El término municipal incluye los siguientes núcleos de población: Bamonde, Cacheiras, Calo, Reis, Lucí, Luou, Oza, Rarís, Vilariño y Teo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15082','palacio','Pazo de Faramello','Espectacular complejo señorial del siglo XVIII erigido sobre el cañón del río Tinto empleando sillería granítica gálica que se integra perfectamente con el entorno natural, el cual conserva una antigua fábrica de papel preindustrial de piedra rústica, capillas barrocas y jardines de influencia decimonónica franceses.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15082','iglesia','Iglesia de San Simón de Ons de Cacheiras','Templo de traza barroca clasicista del siglo XVIII levantado en sillería de granito berroqueño que destaca por la volumetría de su nave central y su fachada rematada por dos esbeltas torres campanario profusamente ornamentadas con pináculos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15083','monumento','Núcleos de población de Toques','El término municipal incluye los siguientes núcleos de población: A Capela, Mangüeiro, Ordes, Paradela, San Martiño de de Oleiros, San Xiao de de Vilouriz, Santa María de de Brañas, Vilamor y Toques.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15083','iglesia','Iglesia de San Antolín de Toques','Joya del prerrománico y románico gallego de los siglos X y XI declarada Monumento Nacional que se asienta en un entorno boscoso recóndito, construida con muros de mampostería de pizarra rústica y esquinales de granito gálico, albergando en su ábside rectangular un valioso calvario gótico de madera policromada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15084','monumento','Núcleos de población de Tordoia','El término municipal incluye los siguientes núcleos de población: Andoio, Anxeriz, Bardaos, Cabaleiros, Castenda, Gorgullos, Leobalde, Numide, Tordoia y Vila de de Abade.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15084','monumento','Dolmen de Cabaleiros','Monumento megalítico prehistórico del III milenio a.C. conocido popularmente como "Casa da Moura" que consta de una cámara funeraria poligonal formada por siete grandes losas verticales de granito berroqueño','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15086','monumento','Núcleos de población de Trazo','El término municipal incluye los siguientes núcleos de población: Benza, Berreo, Campo, Castelo, Chaián, Monzo, Morlan, Restande, Toar, Trazo y Xavestre.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15086','monumento','Puente de Chaián (Frontera Municipal)','Estructura viaria preindustrial reconstruida en el siglo XIX sobre el río Tambre que cuenta con pilares y tajamares de cantería granítica y mampostería de pizarra rústica, comunicando los valles agrícolas tradicionales a través de un entorno recreativo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90195','monumento','Núcleos de población de Val do Dubra','El término municipal incluye los siguientes núcleos de población: Arabexo, Bembibre, Buxán, Coucieiro, Erviñou, Niveiro, Paramos, Rial, San Román y Vilariño.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90195','iglesia','Iglesia de San Sanzo de Bembibre','Templo rural del siglo XVIII levantado con fábrica mixta de mampostería de pizarra y refuerzos angulares de granito berroqueño que presenta una planta de cruz latina con una modesta espadaña de dos ojos y un crucero pétreo tradicional situado en el atrio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15087','monumento','Núcleos de población de Valdoviño','El término municipal incluye los siguientes núcleos de población: Lago, Loira, Lourido, Meirás, Pantín, O Sequeiro, Valdoviño, Vilaboa y Vilarrube.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15087','iglesia','Iglesia de Santiago de Vilarrube','Templo de filiación barroca clasicista del siglo XVIII erigido en sillería de granito gálico que destaca por su fachada austera coronada por una espadaña de dos vanos y por un crucero pétreo exento, orientándose sus vistas hacia el estuario y la playa homónima.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15089','monumento','Núcleos de población de Vedra','El término municipal incluye los siguientes núcleos de población: Illobre, Merín, A Ponte Ulla, San Fins de de Sales, San Pedro de de Vilanova, San Tomé de de de Vedra, Santa Cruz de de Ribadulla, Trobe y Vedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15089','palacio','Pazo de Santa Cruz de Ribadulla (Torre de Ortigueira)','Monumental palacio del siglo XVI reformado en el XVIII que cuenta con una robusta torre defensiva de sillería de granito berroqueño, el cual está rodeado por un jardín botánico histórico que alberga una de las colecciones de camelias más antiguas de Europa y cascadas barrocas de piedra rústica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15089','monumento','Puente Antiguo de la Ulla (A Ponte Ulla)','Monumental paso viario del siglo XVIII construido con gruesos arcos de sillería granítica gálica y potentes tajamares sobre el río Ulla, sirviendo históricamente como aduana y nexo fundamental en la ruta entre Santiago de Compostela y el interior de Galicia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15091','monumento','Núcleos de población de Vilarmaior','El término municipal incluye los siguientes núcleos de población: Doroña, Goimil, Grandal, Torres, Vilamateo y Vilarmaior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15091','iglesia','Iglesia de Santa María de Doroña','Pequeña construcción románica rural del siglo XII que mantiene su fábrica original de sillería granítica a pesar de las adiciones barrocas del siglo XVIII, destacando la sobria portada occidental con tímpano liso apoyado sobre mocárgenes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15090','monumento','Núcleos de población de Vilasantar','El término municipal incluye los siguientes núcleos de población: Armental, Barbeito, Mezonzo, Présaras, San Vicenzo de de Curtis, Vilariño y Vilasantar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15090','iglesia','Iglesia del Monasterio de Santa María de Mezonzo','Joya del románico pleno de finales del siglo XII declarada Monumento Nacional que presenta una inusual planta basilical de tres naves rematadas en tres ábsides semicirculares erigidos con excelente sillería granítica gálica, destacando la pureza de sus bóvedas y sus capiteles historiados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15092','monumento','Núcleos de población de Vimianzo','El término municipal incluye los siguientes núcleos de población: Baíñas, Bamiro, Berdoias, Calo, Cambeda, Carantoña, Carnio, Cereixo, Salto, Serramo, Tines, Treos y Vimianzo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15092','monumento','Castillo de Vimianzo (Torres de Martelo)','Espectacular fortaleza bajomedieval del siglo XIV que se conserva en perfecto estado con su planta poligonal erigida en sillería de granito berroqueño, sus murallas almenadas con camino de ronda, sus cuatro torres y una robusta torre del homenaje de planta cuadrada que domina todo el valle de Soneira.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15092','iglesia','Iglesia de Santiago de Cereixo y "Torres de Cereixo"','Conjunto monumental compuesto por una iglesia románica del siglo XII de sillería granítica gálica cuyo tímpano occidental muestra la representación más antigua del traslado del cuerpo de Santiago en barca, flanqueada por un pazo fortificado del siglo XVII con dos torres de piedra rústica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15093','monumento','Núcleos de población de Zas','El término municipal incluye los siguientes núcleos de población: Baio, Brandoñas, Brantomil, Carreira, Gándara, Lamas, Loroño, Muíño, San Martin de de Meanos, Vilar, Zas y Zas de de Rei.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15093','monumento','Puente de Brantomil','Estructura viaria bajomedieval reedificada sobre una antigua cimentación romana que cruza el río Anllóns mediante arcos apuntados construidos con','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15093','palacio','Pazo de las Torres de Allo','Uno de los palacios señoriales más antiguos de Galicia (siglo XVI) de estilo gótico tardío y renacentista que presenta dos monumentales torres levantadas en sillería de granito gálico, cuyas fachadas lucen valiosas ventanas labradas en tracería calada y gárgolas figurativas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26001','monumento','Núcleos de población de Acebedo','El término municipal incluye los siguientes núcleos de población: Acebedo, La Uña y Liegos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26001','iglesia','Iglesia Parroquial de San Nicolás de Bari en Acebedo','Templo de traza gótica tardía y clasicista edificado entre los siglos XVI y XVII que destaca por sus recios muros de sillería caliza de Boñar, su portada occidental de medio punto protegida por un porche de vigas de madera de roble y una esbelta espadaña de dos cuerpos que domina el valle del Alto Esla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26001','palacio','Casona de los Álvarez de Acebedo','Residencia solariega montañesa del siglo XVII construida con aparejo mampuesto calizo y refuerzos de sillería en los vanos que exhibe en su fachada principal un monumental escudo heráldico finamente labrado en piedra calcárea, flanqueado por ventanas saetadas defensivas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90196','iglesia','Iglesia de la Asunción de Nuestra Señora','Construcción de carácter mudéjar rural profundamente reformada durante los siglos XVII y XVIII empleando muros de tapial arcilloso combinado con cajones de ladrillo macizo, cuyo interior atesora un artesonado de madera de pino neomudéjar estructurado mediante vigas de par y nudillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90197','monumento','Núcleos de población de Alija del Infantado','El término municipal incluye los siguientes núcleos de población: Alija del Infantado, La Valiza y Navianos de la Vega.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90197','palacio','Castillo de los Pimentel (Palacio de los Ponce de León)','Fortaleza monumental de los siglos XIII y XV declarada Bien de Interés Cultural que presenta una imponente muralla almenada de cantos rodados compactados y argamasa hidráulica, reforzada por cubos semicirculares de sillería y una gran torre del homenaje parcialmente restaurada que domina la llanura del río Órbigo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90197','iglesia','Iglesia de San Esteban','Templo de origen románico y mudéjar reformado en el siglo XVI que destaca por su monumental ábside de ladrillo visto decorado con arquerías ciegas dobladas, albergando en su nave única un espectacular artesonado mudéjar policromado del tipo de limas mohamares que constituye una joya de la carpintería de lo blanco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90197','monumento','Puente del Vizconde','Infraestructura viaria preindustrial del siglo XVII construida con potentes pilares de cantería caliza y','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90198','monumento','Núcleos de población de Ardón','El término municipal incluye los siguientes núcleos de población: Ardón, Benamariel, Cillanueva, Fresnellino y Villalobar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90198','iglesia','Iglesia de la Asunción de Ardón','Templo rural del siglo XVII edificado con muros de tapial arcilloso revestido y contrafuertes de sillería caliza calavera en los puntos de empuje de las bóvedas, el cual destaca por su espadaña exenta de ladrillo visto y por albergar un retablo mayor barroco de madera noble tallada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90199','monumento','Núcleos de población de Arganza','El término municipal incluye los siguientes núcleos de población: Arganza, Campelo, Canedo, Juan de la Reguera, Magaz de Arriba, San Juan de la Mata y Vicente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90199','palacio','Palacio de Canedo','Monumental casona palaciega del siglo XVIII vinculada a la viticultura berciana que cuenta con una planta en U levantada con gruesos muros de piedra rústica pizarrosa y sillería caliza en los vanos, la cual conserva sus lagares de madera tradicionales y un portalón blasonado barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90199','iglesia','Iglesia de San Juan de la Mata','Templo de origen medieval reformado en el siglo XVI con una robusta torre campanario de sillería de Boñar, cuyo interior custodia pinturas murales fragmentarias del renacimiento temprano y una techumbre de vigas de madera de castaño labradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26002','monumento','Núcleos de población de Astorga','El término municipal incluye los siguientes núcleos de población: Astorga, Castrillo de los Polvazares, Murias de Rechivaldo, Santa Catalina de Somoza, Valdeviejas y Val de San Lorenzo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26002','catedral','Catedral de Santa María de Astorga','Magna catedral gótica, renacentista y barroca iniciada en el siglo XV sobre una base románica anterior empleando sillería caliza de tonalidades rojizas y doradas de las canteras locales, cuya fachada barroca churrigueresca del siglo XVIII es una filigrana pétrea que se integra con dos imponentes torres gemelas y una espectacular cabecera gótica de finas tracerías caladas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26002','palacio','Palacio Episcopal de Astorga (Palacio Gaudí)','Obra maestra del arquitecto modernista Antoni Gaudí construida entre 1889 y 1913 empleando una suntuosa sillería de granito gris de El Bierzo combinada con arcos neogóticos y torres cilíndricas, cuyo interior modernista destaca por sus bóvedas de crucería de cerámica vidriada, columnas exentas y vidrieras historiadas únicas en España.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26002','monumento','Muralla Romana de Astorga','Recinto fortificado del siglo III d.C. reedificado en la Baja Edad Media que rodea por completo el casco histórico de Asturica Augusta con imponentes muros cortina de mampostería de cuarcita, pizarra y cantos rodados, jalonados por cubos semicirculares defensivos exentos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26002','monumento','Ayuntamiento de Astorga','Palacio civil barroco del siglo XVII proyectado por Manuel de la Lastra que presenta una fachada monumental de sillería caliza con una gran balconada de hierro forjado, rematada por tres torres caladas de pizarra negra y el célebre reloj de autómatas donde los maragatos Juan Zancuda y Colasa marcan las horas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26002','monumento','Conjunto Histórico de Castrillo de los Polvazares','Núcleo urbano tradicional maragato protegido por la UNESCO que destaca por la homogeneidad de sus casonas de arriería de los siglos XVIII y XIX construidas con piedra rústica rojiza, grandes portalones de arco de medio punto para los carros y calles pavimentadas con cantos rodados fluviales intactos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90200','monumento','Núcleos de población de Balboa','El término municipal incluye los siguientes núcleos de población: Balboa, Cantejeira, Chan de Villar, Ruideferros, Pumarín, Quintela, Ruideiras, Val de la Fuente, Villafeile, Villanueva y Villaverde.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90200','monumento','Castillo de Balboa','Fortaleza feudal del siglo XIV levantada sobre un castro celta anterior empleando gruesos muros de mampostería de pizarra negra rústica y esquinales de caliza, del cual se conserva una imponente torre del homenaje de planta rectangular que domina el valle de Valcarce.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90200','monumento','Palloza de Balboa (Patrimonio Etnográfico)','Construcción etnográfica prehistórica de origen celta adaptada al clima de los Ancares que cuenta con muros bajos y circulares de piedra rústica pizarrosa sin argamasa, coronada por una techumbre cónica de paja de centeno trenzada ("teito") apoyada sobre una robusta estructura interior de vigas de madera de roble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90200','iglesia','Iglesia de Santa Marina','Templo de origen románico reformado en el siglo XVI que destaca por su techumbre mudéjar de madera de castaño con decoración geométrica de par y nudillo, albergando un presbiterio erigido en sillería caliza y un crucero pétreo tradicional en su atrio arbolado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26009','monumento','Núcleos de población de La Bañeza','El término municipal incluye los siguientes núcleos de población: La Bañeza, San Mamés de la Vega y Santiago de la Vega.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26009','iglesia','Iglesia de Santa María de la Plaza','Templo de planta gótica tardía y portadas renacentistas edificado en el siglo XVI con sillería caliza de Boñar y tapial revestido que alberga en su presbiterio un monumental retablo mayor barroco esculpido por el maestro Gregorio Fernández, complementado en el exterior por una esbelta torre-campanario clasicista de pizarra y piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26009','iglesia','Iglesia de San Salvador','Construcción de origen mozárabe del siglo X reedificada en las etapas románica y barroca que conserva un ábside semicircular con ventanas saetadas y una robusta espadaña de ladrillo macizo, cuyo interior atesora una valiosa colección de imaginería procesional de la Semana Santa comarcal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90201','monumento','Núcleos de población de Barjas','El término municipal incluye los siguientes núcleos de población: Barjas, Albaredos, Barrosas, Busmayor, Campo de da Liebre, Corporales, Corrales, Cruces, Hermide, Moldes, Mosteiros, Peñacabalera, Quintela, Serviz, Vegas do Seo y Vilarrubín.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90201','iglesia','Iglesia de San Pedro de Barjas','Templo rural montañés del siglo XVII erigido con fábrica mixta de mampostería de pizarra local y refuerzos angulares de sillería caliza que presenta una planta de cruz latina con una modesta espadaña de dos ojos, constituyendo un hito de la arquitectura sacra berciana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26004','monumento','Núcleos de población de Bembibre','El término municipal incluye los siguientes núcleos de población: Bembibre, Arlanza, Labaniego, Losada, Rodanillo, San Esteban del Toral, San Román de Bembibre, Santibáñez del Toral y Viñales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26004','iglesia','Santuario del Santo Ecce Homo','Templo de traza barroca y neoclásica edificado en el siglo XVIII sobre una base medieval utilizando sillería caliza dorada y mampostería pizarrosa que presenta una gran planta de cruz latina con bóvedas de cañón, albergando en su altar un camarín barroco profusamente ornamentado que es objeto de una multitudinaria devoción comarcal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26004','iglesia','Iglesia de San Pedro','Antiguo templo de origen románico y mudéjar del siglo XII reformado en el siglo XIV que se estructura sobre los restos de una antigua sinagoga medieval empleando piedra rústica y ladrillo visto, destacando por su portada occidental de arcos apuntados doblados y sus inscripciones epigráficas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90202','monumento','Núcleos de población de Benavides','El término municipal incluye los siguientes núcleos de población: Benavides de Órbigo, Antoñán del Valle, Gualtares de Órbigo, Quintanilla del Valle, Vega de Antoñán y San Antolín de de Órbigo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90202','iglesia','Iglesia de San Martín de Benavides','Templo parroquial de traza barroca clasicista del siglo XVIII levantado en sillería de piedra arenisca y caliza calavera que presenta una fachada simétrica coronada por un frontón triangular, flanqueada por una robusta torre de campanas rematada por un chapitel de pizarra negra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90203','monumento','Núcleos de población de Benuza','El término municipal incluye los siguientes núcleos de población: Benuza, Lomba, Llamas de Cabrera, Pombriego, Santalavilla, Sigüeya, Silván y Sotillo de Cabrera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90203','iglesia','Iglesia de San Esteban de Sigüeya','Templo rural de origen románico del siglo XII modificado en las etapas moderna y barroca empleando piedra rústica pizarrosa y techumbre de vigas de madera de castaño, cuyo presbiterio de sillería caliza custodia un crucero etnográfico situado en las inmediaciones del Camino de Santiago de Invierno.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90203','monumento','Canteras Históricas de Pizarra de la Cabrera (Patrimonio Etnográfico)','Frentes de explotación preindustriales del siglo XIX que muestran los métodos tradicionales de extracción y labrado manual de la pizarra negra, con antiguas cabañas de operarios construidas con piedra rústica sin argamasa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90204','monumento','Núcleos de población de Boca de Huérgano','El término municipal incluye los siguientes núcleos de población: Boca de Huérgano, Barniedo de la Reina, Besande, Los Espejos de la Reina, Llánaves de la Reina, Portilla de la Reina, Siero de la Reina, Valverde de la Reina y Villafrea de la Reina.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90204','iglesia','Iglesia de San Salvador de Los Espejos de la Reina','Templo gótico de transición del siglo XIV edificado con recia sillería caliza de Boñar que destaca por su ábside rectangular con contrafuertes escalonados y por su portada de arcos apuntados, albergando en su interior una pila bautismal románica finamente labrada con motivos sogueados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90204','monumento','Torre de los Tiros de Boca de Huérgano','Restos de una antigua casa-fuerte defensiva bajomedieval del siglo XIV erigida en mampostería caliza con esquinales reforzados de cantería, cuya estructura de planta cuadrangular conserva los vanos de las saeteras adaptadas para armas de fuego primitivas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26005','monumento','Núcleos de población de Boñar','El término municipal incluye los siguientes núcleos de población: Boñar, Adrados, Barrio de las Ollas, Las Bodas, Cerecedo, Colle, Grandoso, Llama de Colle, Oceo, Oville, Poblado de Lillo, Remellán, Rucayo, Valdecastillo, Valdehuesa, Veneros, Voznuevo y Vozmediano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26005','iglesia','Iglesia Parroquial de San Pedro de Boñar','Templo de traza barroca clasicista del siglo XVII levantado íntegramente con la célebre sillería caliza de Boñar extraída de sus propias canteras históricas, cuya fachada monumental destaca por su simetría y por una esbelta torre campanario donde el célebre reloj con el autómata "El Negrillón" marca las horas de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26005','monumento','Puente Viejo sobre el río Porma','Estructura viaria de origen romano reedificada en los siglos XVI y XVII mediante grandes arcos de medio punto construidos con aparejo calizo rústico y potentes tajamares triangulares, constituyendo un paso','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26005','iglesia','Iglesia de San Vicente de Colle','Templo románico rural del siglo XII modificado en las etapas renacentista y barroca que mantiene su estructura de sillería caliza con capiteles vegetales románicos en su interior, abriéndose su atrio tradicional hacia los valles de la comarca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90205','monumento','Núcleos de población de Borrenes','El término municipal incluye los siguientes núcleos de población: Borrenes, La Chana, Orellán, San Juan de Paluezas y Voces.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90205','monumento','Yacimiento Romano de Las Médulas (Área de Borrenes y Orellán)','Entorno arqueológico de la mayor mina de oro a cielo abierto del Imperio Romano (siglo I d.C.) protegido por la UNESCO, donde se conservan las redes de canales de lavado excavados en la roca viva, galerías de explotación hidráulica como el "Ruina Montium" y los miradores de Orellán que dominan los picachos arcillosos rojizos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90205','monumento','Castro de San Juan de Paluezas','Poblado fortificado de la cultura astur prerromana habitado entre los siglos III a.C. y I d.C. que conserva intactas sus murallas defensivas de piedra rústica caliza sin argamasa y la planta de varias viviendas ovaladas adaptadas a las terrazas del terreno.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90206','monumento','Núcleos de población de Brazuelo','El término municipal incluye los siguientes núcleos de población: Brazuelo, Bonillos, Combarros, El Ganso, Pradorrey, Requejo de Pradorrey, Rodrigatos de la Obispalía y Veldedo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90206','iglesia','Iglesia de Santiago Apóstol de El Ganso','Templo de origen medieval profundamente reformado durante los siglos XVII y XVIII en las rutas del Camino de Santiago Francés que destaca por sus robustos muros de mampostería de cuarcita rústica, su porche delantero de vigas de madera de roble para cobijo de peregrinos y una espadaña bicéfala de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90207','monumento','Núcleos de población de Cabañas Raras','El término municipal incluye los siguientes núcleos de población: Cabañas Raras y Cortiguera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90207','iglesia','Iglesia de Santa Ana de Cabañas Raras','Templo parroquial de traza barroca clasicista del siglo XVIII levantado con fábrica mixta de mampostería pizarrosa y refuerzos de sillería caliza en los esquinales, rematado en su fachada por una esbelta torre campanario cupulada con pizarra negra de El Bierzo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90208','monumento','Núcleos de población de Cabreros del Río','El término municipal incluye los siguientes núcleos de población: Cabreros del Río y Jabares de los Oteros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90208','iglesia','Iglesia de San Miguel de Jabares de los Oteros','Templo rural del siglo XVII edificado con muros de tapial arcilloso tradicional leones y cajones de ladrillo macizo mudéjar, cuyo interior atesora un artesonado de madera de pino con decoración de alfardas e imaginería barroca comarcal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26006','monumento','Núcleos de población de Cabrillanes','El término municipal incluye los siguientes núcleos de población: Cabrillanes, El Puerto, Huergas de Babia, Lago de Babia, Mena de Babia, Meroy, Las Murias, Piedrafita de Babia, Quintanilla de Babia, San Felix de las Rozas, Torre de Babia, Vega de Viejos y La Cueta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26006','palacio','Casona de los Quiñones en Riolago (Acceso Comarcal)','Monumental palacio solariego montañés del siglo XVI edificado con muros de sillería caliza y mampostería de piedra rústica calavera que exhibe una planta rectangular defendida por un portalón almenado y un imponente despliegue de blasones heráldicos vinculados al linaje de los Condes de Luna.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26006','iglesia','Iglesia de San Vicente de Torre de Babia','Templo parroquial del siglo XVII levantado con aparejo calizo rústico y techumbre de vigas de madera de haya que conserva una robusta espadaña de dos cuerpos y un crucero etnográfico en su atrio,','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90209','monumento','Núcleos de población de Calzada del Coto','El término municipal incluye los siguientes núcleos de población: Calzada del Coto y Codornillos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90209','iglesia','Iglesia Parroquial de San Esteban','Templo de factura rural edificado en el siglo XVII combinando muros de tapial arcilloso con cajones de ladrillo macizo mudéjar y contrafuertes de sillería caliza de Boñar en las esquinas, cuya estructura se sitúa sobre el trazado histórico de la Vía Trajana del Camino de Santiago Francés.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90209','ermita','Ermita de San Roque','Modesta construcción sacra del siglo XVIII levantada con aparejo de adobe y entramado de madera de pino por las cofradías de arrieros locales, la cual conserva','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90210','monumento','Núcleos de población de Candín','El término municipal incluye los siguientes núcleos de población: Candín, Balouta, Espinareda de Ancares, Lumeras, Pereda de Ancares, Sorbeira, Suárbol, Tejedo de Ancares, Villasumil y Villarbón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90210','monumento','Conjunto Etnográfico de Pallozas de Balouta','Extraordinario núcleo de arquitectura tradicional de los Ancares leoneses compuesto por viviendas de origen prerromano con plantas ovaladas y muros bajos de mampostería de pizarra negra rústica, techadas con techumbres cónicas de paja de centeno trenzada ("teito") apoyadas sobre entramados de madera de roble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90210','iglesia','Iglesia de Santa María de Suárbol','Templo del siglo XVII declarado Bien de Interés Cultural que rompe con la tipología rural montañesa al exhibir una traza barroca clasicista de sillería caliza calavera excelentemente escuadrada, complementada por una gran torre campanario y un pórtico renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90210','monumento','Hórreos de Pereda de Ancares','Estructuras agrícolas preindustriales de planta cuadrada construidas con tablones de madera de castaño ("colondras") sobre cuatro pies de piedra rústica o muelas calcáreas para evitar la entrada de roedores, constituyendo un hito de la etnografía montañesa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90211','monumento','Núcleos de población de Carracedelo','El término municipal incluye los siguientes núcleos de población: Carracedelo, Carracedo del Monasterio, Posada del Bierzo, Villadepalos, Villamartín de la Abadía y Villaverde de la Abadía.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90211','iglesia','Monasterio de Santa María de Carracedo','Monumental cenobio benedictino y cisterciense fundado en el año 990 por el rey Bermudo II cuya abadía gótico-renacentista, declarada Monumento Nacional, destaca por el Palacio Real de la reina Doña Sancha con su mirador de triple arcada apuntada erigido en excelente sillería caliza dorada, el claustro reglar y la imponente Sala Capitular barroca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90211','palacio','Palacio de los Condes de Toreno (Carracedelo)','Residencia solariega cortesana del siglo XVII construida con una fábrica de piedra rústica pizarrosa y refuerzos de cantería en los vanos, la cual conserva su portalón blasonado barroco con el escudo de armas familiar finamente tallado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90211','iglesia','Iglesia Parroquial de Carracedo del Monasterio','Templo neoclásico del siglo XVIII edificado reaprovechando elementos del complejo monacal anterior utilizando sillería caliza de Boñar, cuya monumental fachada geométrica se ve rematada por una robusta torre campanario de líneas clasicistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90212','monumento','Núcleos de población de Carrizo','El término municipal incluye los siguientes núcleos de población: Carrizo de la Ribera, Huerga del Río, La Milla del Río, Quiñones del Río y Villanueva de Carrizo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90212','iglesia','Monasterio de Santa María de Carrizo','Cenobio de monjas cistercienses fundado en 1176 por la condesa Doña Estefanía Ramírez que destaca por su iglesia románica de transición erigida en sillería caliza de Boñar, conservando tres ábsides','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90212','ermita','Ermita del Villar','Templo barroco rural del siglo XVIII levantado con aparejo de canto rodado compactado y mampuesto calizo que alberga en su presbiterio una notable colección de imaginería mariana medieval y un crucero etnográfico en su atrio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90213','monumento','Núcleos de población de Carrocera','El término municipal incluye los siguientes núcleos de población: Carrocera, Benllera, Otero de las Dueñas, Piedrasecha, Santiago de las Villas, Viñayo y Cuevas de Viñayo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90213','iglesia','Santuario de Nuestra Señora de Camposagrado','Templo de peregrinación barroco del siglo XVII enclavado en un páramo estratégico construido con sillería caliza dorada y mampostería, cuya fachada monumental barroco-clasicista presenta una gran espadaña de tres cuerpos y un pórtico delantero que conmemora las legendarias batallas de la Reconquista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90213','iglesia','Iglesia de San Facundo de Piedrasecha','Templo rural montañés encajado en un desfiladero calizo que cuenta con muros de piedra rústica calavera y una espadaña de dos ojos del siglo XVIII, cuyo interior se techa con una robusta estructura de vigas de madera de haya.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90214','monumento','Núcleos de población de Castilfalé','El término municipal incluye los siguientes núcleos de población: Castilfalé y sus fincas agrarias.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90214','iglesia','Iglesia Parroquial de San Juan Bautista','Templo mudéjar de la meseta leonesa edificado en el siglo XVI empleando muros portantes de tapial arcilloso revestido y arquerías interiores de ladrillo macizo, cuyo elemento principal es una gran espadaña barroca de tres cuerpos que domina el paisaje de oteros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90215','monumento','Núcleos de población de Castropodame','El término municipal incluye los siguientes núcleos de población: Castropodame, Calamocos, Matachana, San Pedro de Trones, Turienzo de los Caballeros, Viloria y Viloria de la Jurisdicción.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90215','iglesia','Iglesia de la Asunción de Castropodame','Templo de origen medieval profundamente reformado en el periodo barroco utilizando aparejo pizarroso rústico y esquinales de sillería caliza, el cual conserva en su interior un artesonado mudéjar de madera de castaño labrada y un retablo mayor de estética churrigueresca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90215','monumento','Ruinas de los Lavaderos de Oro de la Mina de Valdeazores (Patrimonio Romano)','Vestigios arqueológicos industriales de época romana (siglo I d.C.) que muestran los canales de corte y las balsas de decantación excavadas directamente sobre los estratos de cuarcita rústica para la explotación del mineral aurífero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90216','monumento','Núcleos de población de Cea','El término municipal incluye los siguientes núcleos de población: Cea, Bustillo de Cea, San Pedro de Cansoles y Sahelices de Río Pisuerga.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90216','monumento','Castillo de Cea','Ruinas de la fortaleza medieval del siglo XV erigida sobre un cerro estratégico empleando muros de mampostería de canto rodado compactado y cal, de la cual se conserva una singular torre de vigía de planta circular irregular que domina históricamente las vegas del río Cea.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90216','iglesia','Iglesia de San Miguel','Templo de tradición mudéjar rural edificado en el siglo XVI con muros portantes de tapial arcilloso y cajones de ladrillo macizo visto, cuyo interior atesora un artesonado de madera de pino estructurado mediante vigas de par y nudillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26008','monumento','Núcleos de población de Cistierna','El término municipal incluye los siguientes núcleos de población: Cistierna, Carbonera y de Cistierna, Fuentes de Peñacorada, Modino, Pesquera, Quintana de la Peña, Modino, Santibáñez de de la Peña, Sorriba, Valmartino y Vidanes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26008','iglesia','Iglesia de San Julián de Valmartino','Templo románico del siglo XII modificado en las etapas renacentista y barroca que conserva su ábside semicircular levantado en sillería caliza de Boñar, donde sobresalen sus canecillos geométricos esculpidos con minuciosidad bajo los aleros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90217','monumento','Núcleos de población de Congosto','El término municipal incluye los siguientes núcleos de población: Congosto, Almázcara, Cobrana y San Miguel de de las Dueñas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90217','iglesia','Monasterio de San Miguel de las Dueñas','Cenobio de monjas cistercienses fundado en el siglo X y profundamente reconstruido en estilo barroco clasicista durante los siglos XVII y XVIII con una suntuosa sillería caliza calavera y mampostería pizarrosa, cuyo conjunto conserva un bellísimo claustro reglar clasicista y un presbiterio decorado con retablos de madera noble labrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90217','iglesia','Santuario de la Virgen de la Peña','Templo de peregrinación del siglo XVIII emplazado sobre una abrupta cima rocosa que domina el embalse de Bárcena, construido con aparejo de cuarcita rústica y sillería en los esquinales, destacando por su pórtico delantero que ofrece cobijo a las romerías de El Bierzo Alto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90218','monumento','Núcleos de población de Corullón','El término municipal incluye los siguientes núcleos de población: Corullón, Cadafresnas, Melezna, Dragonte, Horta, Viariz y San Martin de de la Melezna.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90218','iglesia','Iglesia de San Miguel de Corullón','Joya del románico pleno del siglo XII declarada Monumento Nacional que muestra la influencia directa de la escuela compostelana en sus muros de excelente sillería caliza dorada, destacando su espectacular portada occidental de arcos de medio punto con capiteles historiados y una célebre colección de canecillos eróticos e iconográficos esculpidos bajo los aleros de la techumbre.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90218','iglesia','Iglesia de San Esteban','Templo románico de finales del siglo XII levantado íntegramente con aparejo de piedra rústica y caliza bien escuadrada que presenta una nave única con cabecera rectangular, la cual destaca por la pureza de sus líneas arquitectónicas y por albergar enterramientos medievales labrados con inscripciones epigráficas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90218','monumento','Castillo de Corullón','Palacio fortificado del siglo XIV perteneciente a la casa de los marqueses de Villafranca que conserva su imponente torre del homenaje de planta cuadrada erigida en mampostería de pizarra negra rústica, jalonada por ventanas saetadas y remates almenados adaptados a la topografía del viñedo berciano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90219','monumento','Núcleos de población de Cuadros','El término municipal incluye los siguientes núcleos de población: Cuadros, Cabanillas, Campo y Santibáñez, Cascantes, Lorenzana, La Seca y Valsemana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90219','iglesia','Iglesia de San Juan Bautista de Cabanillas','Templo parroquial de traza barroca clasicista del siglo XVIII levantado con fábrica mixta de canto rodado compactado fluvial y cadenas angulares de sillería de Boñar, cuya fachada se caracteriza por su robusta espadaña de dos cuerpos rematada por pináculos barrocos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90220','monumento','Núcleos de población de Destriana','El término municipal incluye los siguientes núcleos de población: Destriana, Robledo de la Valduerna y Robledino de la Valduerna.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90220','iglesia','Iglesia de San Salvador','Templo de origen románico del siglo XII con importantes remodelaciones mudéjares y barrocas que destaca por sus robustos muros de mampostería de cuarcita y caliza, albergando en su nave única una valiosa colección de capiteles con motivos sogueados e inscripciones medievales vinculadas a la Orden del Temple.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90221','monumento','Núcleos de población de Encinedo','El término municipal incluye los siguientes núcleos de población: Encinedo, Ambasaguas, Castrohinojo, Forna, Losadilla, Quintanilla de de Yuso, Robledo de de Losada, Santa Eulalia de de Cabrera, Trabazos y La Baña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90221','monumento','Conjunto Etnográfico de Arquitectura de la Cabrera Alta','Núcleo tradicional montañés que destaca por la conservación homogénea de sus viviendas de los siglos XVIII y XIX erigidas con gruesos muros de mampostería de pizarra negra rústica y techumbres de losas de pizarra tosca, cuyos corredores de madera de castaño volados se orientan para maximizar la insolación invernal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90221','iglesia','Iglesia de Santa Eulalia de Cabrera','Templo rural del siglo XVII levantado con aparejo pizarroso local y techumbre de vigas de madera de roble, cuya modesta espadaña de dos ojos custodia un crucero pétreo de excelente factura popular en el centro de su umbrío atrio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90222','monumento','Núcleos de población de La Ercina','El término municipal incluye los siguientes núcleos de población: La Ercina, Acisa de las Arrimadas, Barrillos de las Arrimadas, Corral de las Arrimadas, La Devesa de Boñar, Overayo, Palacio de las Arrimadas, San Pedro de Foncollada, Santa Olaja de la Varga, Val de San Justo, Valdehuesa, La Velilla de Valdoré, Veneros y Yugueros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90222','iglesia','Iglesia de San Pedro de Foncollada','Templo de origen románico del siglo XII modificado en las etapas renacentista y barroca que mantiene su estructura original en el ábside semicircular levantado en sillería caliza de Boñar, flanqueada por una esbelta espadaña y un crucero pétreo de excelente factura tradicional en su atrio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90222','monumento','Museo Etnográfico de Veneros','Complejo cultural ubicado en una antigua casona señorial del siglo XVIII construida con muros de mampostería caliza y cadenas angulares de cantería fina, la cual conserva sus vigas de madera de roble e instalaciones destinadas a preservar la indumentaria y las herramientas del pastoreo montañés.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90223','monumento','Núcleos de población de Fabero','El término municipal incluye los siguientes núcleos de población: Fabero, Fontoria, Lillo del Bierzo, Otero de Naraguantes, San Pedro de Paradela y Bárcena de la Abadía.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90223','iglesia','Iglesia de San Blas de Otero de Naraguantes','Templo rural de origen medieval profundamente reformado en el periodo barroco utilizando mampostería de pizarra negra rústica berciana y refuerzos de sillería caliza en los vanos, cuyo interior atesora un artesonado de vigas de madera de castaño con decoración geométrica de par y nudillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90224','monumento','Núcleos de población de Folgoso de la Ribera','El término municipal incluye los siguientes núcleos de población: Folgoso de la Ribera, Boeza, La Ribera de Folgoso, Rozuelo, Tedejo, El Valle y Villaviciosa de San Miguel.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90224','iglesia','Iglesia de San Pedro de Tedejo','Templo de filiación románica montañesa modificado en el siglo XVII que cuenta con gruesos muros de piedra rústica pizarrosa y una robusta espadaña barroca exenta de dos ojos, constituyendo un destacado hito de la arquitectura sacra tradicional en los valles del Bierzo Alto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90224','monumento','Instalaciones Hidráulicas Preindustriales de Boeza','Conjunto de molinos de agua y canales de riego tradicionales construidos en los siglos XVIII y XIX con aparejo de mampostería de pizarra sin argamasa que testimonian los métodos de molienda de grano de la comarca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90225','monumento','Núcleos de población de Fresno de la Vega','El término municipal incluye los siguientes núcleos de población: Fresno de la Vega y sus explotaciones hortícolas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90225','iglesia','Iglesia Parroquial de San Andrés','Templo mudéjar de la meseta leonesa edificado en el siglo XVI empleando muros portantes de tapial arcilloso revestido y arquerías de ladrillo macizo, cuya fachada destaca por una gran espadaña barroca de tres cuerpos que aloja el campanario que domina la llanura aluvial del río Esla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90226','monumento','Núcleos de población de Garrafe de Torío','El término municipal incluye los siguientes núcleos de población: Garrafe de Torío, Abadengo de Torío, Altobar de Torío, Fontanos de Torío, Gallegos de Torío, Manzaneda de Torío, Matueca de Torío, Otero de Torío, Palacio de Torío, Pedrún de Torío, Riosequino de Torío, Ruiforco de Torío, San Feliz de Torío, Valderilla de Torío y Villaverde de Abajo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90226','iglesia','Iglesia Parroquial de San Juan Bautista de Fontanos de Torío','Templo rural de origen medieval profundamente reformado durante el periodo barroco que destaca por sus robustos muros de mampostería caliza y arenisca combinados con refuerzos de sillería de Boñar en las cadenas angulares, coronándose su fachada con una robusta espadaña bicéfala ornamentada con pináculos pétreos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90226','palacio','Casona Solariega de los Marqueses de Torío en San Feliz','Residencia noble cortesana del siglo XVIII construida con aparejo mampuesto calizo y sillares bien labrados en los marcos de sus ventanas saetadas, exhibiendo en su cuerpo','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90227','monumento','Núcleos de población de Gordoncillo','El término municipal incluye los siguientes núcleos de población: Gordoncillo y sus explotaciones vitivinícolas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90227','iglesia','Iglesia Parroquial de San Juan Bautista','Templo de traza barroca clasicista del siglo XVIII levantado con aparejo de tapial revestido y contrafuertes de ladrillo en las esquinas, el cual alberga en su presbiterio un notable retablo mayor de madera policromada y una colección de imaginería religiosa comarcal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90228','monumento','Núcleos de población de Gradefes','El término municipal incluye los siguientes núcleos de población: Gradefes, Cañizal de Rueda, Garfín, Mellanzos, Nava de los Caballeros, Rueda del Almirante, San Bartolomé de Rueda, San Cibrián de Rueda, Santa Olaja de Eslonza, Villacorta, Villaldún, Villamizar, Villandiego y Valdealcón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90228','iglesia','Monasterio de Santa María de Gradefes','Cenobio de monjas cistercienses fundado en 1164 por Doña Teresa Balbina cuya iglesia románica de transición, declarada Monumento Nacional, destaca por su singular cabecera con girola o deambulatorio de cinco capillas absidales erigida en excelente sillería de Boñar, jalonada por arquerías polilobuladas de influencia mudéjar y capiteles de fina ejecución escultórica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90228','iglesia','Ruinas del Monasterio de San Pedro de Eslonza (Santa Olaja de Eslonza)','Vestigios monumentales de un gran cenobio benedictino fundado en el año 912 y reedificado en el siglo XVI por Juan de Badajoz el Mozo en estilo renacentista, cuyos lienzos de muros de sillería caliza, columnas exentas y portadas monumentales desmanteladas testimonian la pasada grandeza eclesiástica de la cuenca del Esla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90228','monumento','Torre y Cerca de Rueda del Almirante','Restos del recinto fortificado medieval del siglo XIII perteneciente al señorío de los Enríquez, almirantes de Castilla, construidos con una fábrica mixta de canto rodado compactado y mampuesto calizo que domina estratégicamente un cerro sobre el río Esla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90229','monumento','Núcleos de población de Hospital de Órbigo','El término municipal incluye los siguientes núcleos de población: Hospital de Órbigo y Puente de Órbigo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90229','monumento','Puente del Passo Honroso','Monumental viaducto bajomedieval del siglo XIII, erigido sobre pilares romanos en sillería caliza de Boñar y cantos rodados compactados, que cuenta con diecinueve arcos apuntados y potentes tajamares triangulares, célebre en la historia europea por ser el escenario de las justas caballerescas del caballero Suero de Quiñones en el año 1434.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90229','iglesia','Iglesia Parroquial de San Juan Bautista','Templo edificado en el siglo XVIII por la Orden de San Juan de Jerusalén utilizando aparejo mixto de sillería caliza calavera y tapial arcilloso que exhibe una fachada sobria con frontón triangular y alberga en su presbiterio una notable cruz procesional plateresca de plata repujada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90230','monumento','Núcleos de población de Igüeña','El término municipal incluye los siguientes núcleos de población: Igüeña, Almagarinos, Colinas del Campo de Martín Moro Toledano, Espina de Tremor, Pobladura de las Regueras, Quintana de Fuseros, Rodrigatos de las Regueras y Tremor de Arriba.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90230','monumento','Conjunto Histórico de Colinas del Campo de Martín Moro Toledano','Núcleo de arquitectura tradicional de la alta montaña berciana, declarado Bien de Interés Cultural, que destaca por sus casonas homogéneas de los siglos XVII y XVIII construidas con gruesos muros de mampostería de pizarra negra rústica y cubiertas de losas de pizarra tosca, articuladas en torno a un arco de piedra medieval que sirve de acceso al recinto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90230','iglesia','Iglesia de San Juan Bautista de Quintana de Fuseros','Templo de origen medieval profundamente reformado durante la etapa barroca que cuenta con una fábrica rústica pizarrosa y una robusta espadaña bicéfala, cuyo interior custodia un','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90231','monumento','Núcleos de población de Izagre','El término municipal incluye los siguientes núcleos de población: Izagre, Albires y Valdemorilla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90231','iglesia','Iglesia Parroquial de San Andrés en Albires','Templo mudéjar de la meseta leonesa edificado en el siglo XVI empleando muros portantes de tapial arcilloso tradicional leones y cajones de ladrillo macizo cocido, cuya fachada principal destaca por una gran espadaña barroca de tres cuerpos que domina el paisaje de oteros cerealistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90232','monumento','Núcleos de población de Joarilla de las Matas','El término municipal incluye los siguientes núcleos de población: Joarilla de las Matas, San Miguel de Montañán y Valdesbida.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90232','iglesia','Iglesia de Nuestra Señora de la Asunción','Templo de tradición mudéjar rural edificado en el siglo XVI con muros de adobe y entramados de madera de pino revestidos, el cual se caracteriza por su gran torre campanario exenta de ladrillo visto y por albergar un retablo mayor barroco de estética churrigueresca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90233','monumento','Núcleos de población de Laguna de Negrillos','El término municipal incluye los siguientes núcleos de población: Laguna de Negrillos, Cabañeros, Conforcos y Villamorico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90233','monumento','Castillo de los Quiñones','Fortaleza bajomedieval del siglo XV levantada por orden de Diego Fernández de Quiñones que destaca por su imponente torre del homenaje erigida con una fábrica mixta de tapial arcilloso de gran dureza, mampostería de canto rodado y esquinales reforzados de sillería caliza de Boñar, luciendo en su frente el escudo heráldico del linaje de los Condes de Luna.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90233','iglesia','Iglesia de San Juan Bautista','Templo parroquial de transición gótico-renacentista del siglo XVI construido con aparejo de mampuesto y sillería caliza calavera que alberga en su nave única una rica techumbre de madera noble y un retablo mayor barroco, constituyendo el eje de las célebres procesiones históricas de la festividad del Corpus Christi.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90234','monumento','Núcleos de población de Laguna Dalga','El término municipal incluye los siguientes núcleos de población: Laguna Dalga, San Pedro de las Dueñas, Santa Cristina de Valmadrigal y Saelices del Payuelo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90234','iglesia','Iglesia de San Pedro de las Dueñas','Templo de tradición mudéjar de la meseta leonesa edificado en el siglo XVI empleando muros portantes de tapial arcilloso revestido y cajones de ladrillo macizo cocido, cuya fachada principal se ve coronada por una gran espadaña barroca de tres cuerpos que domina el relieve de la llanura cerealista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26010','monumento','Núcleos de población de León','El término municipal incluye los siguientes núcleos de población: León, Armunia, Belme, Las Grañeras, Oteruelo de la Valdoncina, Trobajo del Cerecedo, Puente Castro y Villabalter.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26010','catedral','Catedral de Santa María de Regla (La Pulchra Leonina)','Obra cumbre del gótico clásico de los siglos XIII y XIV de influencia francesa, declarada Monumento Nacional, erigida con una suntuosa sillería caliza de Boñar de tonalidades cálidas que destaca por la desmaterialización de sus muros cortina en favor de un majestuoso conjunto de 134 ventanales y 3 rosetones de vidrieras medievales polícromas únicas en el mundo, flanqueada en el exterior por dos torres caladas exentas y un espectacular Pórtico de la Virgen Blanca tallado con exquisita minuciosidad escultórica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26010','iglesia','Real Colegiata de San Isidoro','Magna basílica románica de los siglos XI y XII consagrada como el hito arquitectónico más importante del románico pleno peninsular que custodia el Panteón de los Reyes de León, un espacio subterráneo denominado la Capilla Sixtina del arte románico por conservar intactos sus frescos murales del siglo XII policromados sobre mortero de cal, sustentados por columnas exentas con capiteles historiados de sillería caliza labrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26010','monumento','Hostal de San Marcos','Monumental monasterio y antiguo hospital de peregrinos fundado en el siglo XVI por orden del rey Fernando el Católico que constituye la obra maestra del estilo plateresco y renacentista español, cuya larguísima','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26010','palacio','Palacio de los Guzmanes','Palacio señorial renacentista del siglo XVI proyectado por el célebre arquitecto Rodrigo Gil de Hontañón para la familia de los Guzmanes que presenta una fachada monumental de cantería caliza con arquerías altas platerescas, balconadas de hierro forjado apoyadas sobre ménsulas molduradas y un suntuoso patio interior porticado con columnas jónicas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26010','palacio','Casa Botines (Palacio de los Botines)','Espectacular edificio de estilo neogótico y modernista diseñado entre 1891 y 1892 por el arquitecto catalán Antoni Gaudí que destaca por su planta trapezoidal erigida con muros de sillería de granito gris de El Bierzo bien escuadrados, rematada por cuatro torres cilíndricas angulares coronadas por chapiteles de pizarra negra y una portada principal protegida por una escultura de San Jorge y el dragón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26010','monumento','Muralla Romana y Medieval de León','Recinto amurallado de origen romano (siglo III d.C.) levantado por la Legio VII Gemina con potentes muros de mampostería de cuarcita y cantos rodados compactados con mortero hidráulico, reconstruido sustancialmente en la Baja Edad Media con sillares calcáreos y jalonado por una treintena de cubos semicirculares exentos conocidos popularmente como "los Caños".','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90235','monumento','Núcleos de población de Llamas de la Ribera','El término municipal incluye los siguientes núcleos de población: Llamas de la Ribera, Quintanilla de Sollamas, San Román de los Caballeros y Villaviciosa de la Ribera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90235','iglesia','Iglesia de San Pedro de Llamas de la Ribera','Templo parroquial de traza barroca clasicista del siglo XVIII levantado con fábrica mixta de canto rodado fluvial compactado y cadenas angulares de sillería de Boñar, cuya fachada se caracteriza por su robusta espadaña de dos cuerpos rematada','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90236','monumento','Núcleos de población de Magaz de Cepeda','El término municipal incluye los siguientes núcleos de población: Magaz de Cepeda, Benamarías, Porqueros, Vanidodes, Vega de Magaz y Zacos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90236','iglesia','Iglesia Parroquial de San Mamés de Zacos','Templo de factura rural del siglo XVII edificado sobre vestigios románicos mediante muros de mampostería de cuarcita rústica y esquinales de sillería caliza, el cual destaca por su espadaña de dos cuerpos y por situarse en un enclave histórico vinculado a los antiguos señoríos de la comarca de La Cepeda.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90236','monumento','Crucero Pétreo de Vega de Magaz','Hito devocional de la arquitectura etnográfica sacra del siglo XVIII labrado en piedra calcárea local que presenta un fuste liso asentado sobre gradas cuadrangulares, coronado por un capitel moldurado con relieves esquemáticos de la Crucifixión.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26011','monumento','Núcleos de población de Mansilla de las Mulas','El término municipal incluye los siguientes núcleos de población: Mansilla de las Mulas, Mansilla del Esla y Villómar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26011','monumento','Muralla Medieval de Mansilla de las Mulas','Imponente recinto fortificado del siglo XII mandado erigir por el rey Fernando II de León empleando una fábrica monumental de cantos rodados compactados con cal y canto de gran dureza, cuyos lienzos conservan gran parte de sus cubos semicirculares exentos y el monumental Arco de la Concepción, configurado mediante sillares de caliza de Boñar escuadrados en arco apuntado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26011','iglesia','Iglesia de Santa María','Templo parroquial de traza barroca clasicista del siglo XVIII edificado en ladrillo macizo y tapial arcilloso revestido sobre una antigua fábrica medieval que destaca por la amplitud de su nave única, albergando en su interior un suntuoso retablo mayor de madera policromada y una imaginería de gran arraigo en la ruta del Camino de Santiago Francés.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26011','iglesia','Antiguo Convento de San Agustín (Museo de los Pueblos Leoneses)','Complejo conventual agustino del siglo XV reformado en el XVIII que conserva su portada renacentista de sillería caliza y su estructura claustral de muros portantes de ladrillo visto, hoy rehabilitado integralmente con estructuras vanguardistas de hormigón y vidrio para albergar una de las colecciones etnográficas más completas del noroeste peninsular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90237','monumento','Núcleos de población de Mansilla Mayor','El término municipal incluye los siguientes núcleos de población: Mansilla Mayor, Nogales, San Justo de de los Oteros y Villamoros de de Mansilla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90237','iglesia','Monasterio de Santa María de Sandoval (Nogales)','Cenobio de la orden del Císter fundado en 1167 por el conde Ponce de Minaya cuya iglesia románica de transición y gótica primitiva, declarada Monumento Nacional, destaca por su cabecera de tres ábsides semicirculares erigidos en excelente sillería de Boñar, jalonada por una portada occidental de tres arquivoltas apuntadas y capiteles historiados, un claustro renacentista y estancias medievales parcialmente arruinadas de alto valor místico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90237','iglesia','Iglesia Parroquial de San Miguel de Mansilla Mayor','Templo de filiación mudéjar rural modificado en los siglos XVII y XVIII utilizando aparejo de tapial tradicional leonés y cajones de ladrillo macizo, cuyo interior atesora un valioso retablo mayor barroco de estética churrigueresca y un artesonado de madera de pino con decoración de alfardas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16122','monumento','Núcleos de población de Maraña','El término municipal incluye los siguientes núcleos de población: Maraña y las explotaciones ganaderas de la alta montaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16122','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo montañés del siglo XVI levantado bajo la protección del macizo de Mampodre utilizando muros de sillería caliza tosca y mampuesto local con techumbre de vigas de madera de haya, cuya fachada occidental exhibe una robusta espadaña bicéfala diseñada para resistir las inclemencias del clima invernal cantábrico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24099','monumento','Núcleos de población de Matadeón de los Oteros','El término municipal incluye los siguientes núcleos de población: Matadeón de los Oteros, Fontanil de los Oteros, San Pedro de los Oteros y Santa María de los Oteros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24099','iglesia','Iglesia de San Pedro de los Oteros','Templo mudéjar de la meseta leonesa edificado en el siglo XVI empleando muros portantes de tapial arcilloso tradicional y cajones de ladrillo macizo cocido, cuya fisonomía exterior se caracteriza por una gran espadaña barroca de tres cuerpos que domina el paisaje llano y cerealista de la comarca de Los Oteros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24098','monumento','Núcleos de población de Matallana de Torío','El término municipal incluye los siguientes núcleos de población: Matallana de Torío, Barrio de la Estación, Orzonaga, Pardavé, Robles de la Valcueva, Serrilla, Valquero, Villalfeide y Naredo de de Fenar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24098','monumento','Ruinas del Castillo de Fenar (Serrilla)','Restos de la fortaleza medieval del siglo XI emplazada sobre un escarpado risco calizo que conserva fragmentos de sus lienzos de murallas y la base de su torre defensiva erigidos con mampostería caliza y cal, sirviendo históricamente como punto de control en los pasos de la montaña central leonesa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24098','iglesia','Iglesia de Santa Eulalia de Pardavé','Templo rural del siglo XVII modificado en el XVIII levantado a la orilla del río Torío combinando aparejo de mampuesto calizo con esquinales de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24100','monumento','Núcleos de población de Molinaseca','El término municipal incluye los siguientes núcleos de población: Molinaseca, Acebo, Castrillo de los Polvazares, Onamio, Paradasolana, Riego de Ambrós y El Acebo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24100','monumento','Puente de los Peregrinos','Monumental paso viario de origen romano reedificado sustancialmente en los siglos XII y XIII sobre el río Meruelo en sillería de pizarra rústica negra y cantos rodados compactados con mortero de cal, cuyos siete arcos de luces variables guían a los caminantes del Camino de Santiago Francés.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24100','iglesia','Santuario de Nuestra Señora de las Angustias','Templo de traza barroca clasicista del siglo XVIII erigido con fábrica de piedra pizarrosa berciana y esquinales reforzados en sillería caliza dorada que destaca por su gran pórtico de arcos rebajados para cobijo de los peregrinos y por su cúpula octogonal central linterna.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24100','iglesia','Iglesia Parroquial de San Nicolás de Bari','Templo tardorrenacentista y barroco del siglo XVII emplazado en un promontorio urbano que exhibe una monumental fachada de cantería pizarrosa bien labrada con una robusta torre campanario de líneas geométricas, albergando en su interior un retablo mayor churrigueresca de madera policromada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24101','monumento','Núcleos de población de Murias de Paredes','El término municipal incluye los siguientes núcleos de población: Murias de Paredes, Barrio de la Puente, Los Barrios de Luna, Fasgar, Lazado, Montrondo, Posada de Omaña, Rodicol, Sabugo, Senra, Torrecillo, Vegapujín, Vivero y El Castillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24101','palacio','Casona de los Condes de Luna (Murias de Paredes)','Residencia palaciega montañesa del siglo XVIII construida con recios muros de mampostería de cuarcita y sillería caliza en los vanos que cuenta con un patio porticado central de postes de madera de roble, una solana tradicional y un portalón blasonado heráldico restaurado como centro de interpretación de la Reserva de la Biosfera de Omaña y Luna.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24101','iglesia','Iglesia de Santa María de la Asunción en Fasgar','Templo rural montañés edificado en el siglo XVII empleando aparejo de piedra rústica calavera y techumbre de losas de pizarra negra tosca, el cual se caracteriza por su ruda espadaña de dos cuerpos diseñada para soportar los rigores climáticos de la Cordillera Cantábrica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24103','monumento','Núcleos de población de Oencia','El término municipal incluye los siguientes núcleos de población: Oencia, Arnado, Castropetre, Gestoso, Leiroso, Lusio, San Pedro de de Olleros, Villarrubín y Vilarrubín.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24103','iglesia','Iglesia Parroquial de Santa Marina de Oencia','Templo rural de origen medieval profundamente reformado en los siglos XVII y XVIII con una fábrica rústica de mampostería de pizarra negra berciana y refuerzos de sillería caliza en los esquinales, destacando su porche de vigas de madera de castaño y su espadaña de dos ojos adaptada a la arquitectura de alta montaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24104','monumento','Núcleos de población de Las Omañas','El término municipal incluye los siguientes núcleos de población: Las Omañas, Escuredo, Mataluenga, Pedregal, San Martín de de la Falamosa, Santiago de de las Omañas y Villaviciosa de de la Ribera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24104','monumento','Castillo de San Martín de la Falamosa','Ruinas de la fortaleza altomedieval del siglo X emplazada de forma estratégica sobre un cerro rocoso empleando lienzos de mampostería de cuarcita rústica y cal, de la cual se preserva la base perimetral de su torre de vigía señorial destinada al control del valle del río Omaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24105','monumento','Núcleos de población de Onzonilla','El término municipal incluye los siguientes núcleos de población: Onzonilla, Antimio de de Abajo, Sotico, Torneros de de la Valdoncina, Vilecha y Viloria de de la Jurisdicción.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24105','iglesia','Iglesia de San Juan Bautista de Vilecha','Templo de la meseta leonesa del siglo XVII edificado con muros portantes','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24108','monumento','Núcleos de población de Palacios de la Valduerna','El término municipal incluye los siguientes núcleos de población: Palacios de la Valduerna y Ribas de de la Valduerna.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24108','palacio','Castillo de los Señoríos de Palacios (Castillo de los Bazán)','Fortaleza bajomedieval del siglo XV erigida por orden de la familia Bazán utilizando una fábrica mixta de cantos rodados fluviales compactados y sillería caliza de Boñar en sus cadenas angulares, del cual se conservan notables tramos de sus muros perimetrales almenados y la impronta de su torre del homenaje señorial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24109','monumento','Núcleos de población de Palacios del Sil','El término municipal incluye los siguientes núcleos de población: Palacios del Sil, Corbón del Sil, Cuevas del Sil, Matalavilla, Salientes, Tejedo del Sil, Valdeprado y Valseco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24109','monumento','Conjunto Etnográfico de Cortines de Salientes (Patrimonio Etnográfico)','Estructuras defensivas circulares preindustriales levantadas en las laderas montañosas con gruesos muros de piedra rústica pizarrosa sin argamasa, diseñadas específicamente para proteger las colmenas de abejas tradicionales de los ataques de los osos pardos cantábricos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24109','iglesia','Iglesia Parroquial de Palacios del Sil','Templo rural de tradición montañesa edificado en el siglo XVII combinando aparejo de mampostería de pizarra con esquinales de sillería caliza tosca, rematado en su fachada por una robusta espadaña de dos cuerpos que cobija las campanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24112','monumento','Núcleos de población de Peranzanes','El término municipal incluye los siguientes núcleos de población: Peranzanes, Cariseda, Chano, Faro, Guímara, Trascastro y Vega de de Espinareda.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24112','monumento','Castro de Chano','Extraordinario poblado fortificado del siglo I a.C. perteneciente a la cultura astur prerromana que conserva una docena de plantas de viviendas circulares de mampostería de pizarra negra rústica con muros de gran espesor exentos, dispuestas en terrazas defensivas protegidas por fosos excavados en la ladera del valle de Fornela.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24112','iglesia','Santuario de Nuestra Señora de Trascastro','Templo de peregrinación barroco del siglo XVIII levantado sobre vestigios medievales con aparejo pizarroso y piedra caliza calavera en los vanos que destaca por albergar en su altar un camarin barroco profusamente tallado en madera noble y por ser el epicentro de las tradicionales danzas folclóricas fornelas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24113','monumento','Núcleos de población de Pobladura de Pelayo García','El término municipal incluye los siguientes núcleos de población: Pobladura de Pelayo García y sus explotaciones agrícolas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24113','iglesia','Iglesia Parroquial de San Miguel Arcángel','Templo barroco de la meseta leonesa del siglo XVII edificado mediante muros portantes de tapial arcilloso tradicional y cajones de ladrillo macizo mudéjar que se ve rematado en su cabecera por una esbelta torre-campanario clasicista de ladrillo visto, cuyo interior atesora un artesonado de madera de pino restaurado mediante el sistema de par y nudillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24116','monumento','Núcleos de población de Posada de Valdeón','El término municipal incluye los siguientes núcleos de población: Posada de Valdeón, Caín, Caldevilla, Cordiñanes, Los Llanos, Prada, Santa Marina de Valdeón, Soto de Valdeón y Vegabaño.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24116','monumento','Conjunto de Hórreos de Soto de Valdeón (Patrimonio Etnográfico)','Extraordinario muestrario de hórreos tradicionales de los Picos de Europa de los siglos XVI al XVIII construidos con tablones exentos de madera de roble ("colondras") ensamblados a hueso y techumbres a dos aguas de losas de pizarra negra rústica o teja, los cuales se elevan sobre cuatro pies de piedra caliza de Boñar cónicos para evitar el acceso de roedores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24116','iglesia','Iglesia de Santa Eulalia en Posada','Templo de origen románico profundamente reformado en el siglo XVI que cuenta con muros de mampostería caliza calavera extraída de los macizos calcáreos orientales de los Picos de Europa, en cuyo umbrío porche delantero se conserva una valiosa pila bautismal románica decorada con motivos geométricos tallados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24116','monumento','El Chorco de los Lobos (Cordiñanes - Patrimonio Etnográfico)','Antigua y monumental trampa preindustrial para la caza del lobo de origen altomedieval que se compone de empalizadas de piedra rústica y fosas de mampostería dispuestas en embudo sobre el desfiladero del río Cares, catalogada como un hito etnográfico único de la vida montañesa cantábrica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24117','monumento','Núcleos de población de Pozuelo del Páramo','El término municipal incluye los siguientes núcleos de población: Pozuelo del Páramo, Altobar de la Encomienda y Saludes de Castroponce.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24117','iglesia','Iglesia de San Juan Bautista de Altobar de la Encomienda','Templo de origen mudéjar rural muy reformado en las etapas moderna y barroca utilizando aparejo de tapial revestido y contrafuertes angulares de ladrillo macizo, cuyo principal hito es una gran espadaña barroca de tres cuerpos que domina visualmente las llanuras cerealistas del Páramo leonés.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24118','monumento','Núcleos de población de Prado de la Guzpeña','El término municipal incluye los siguientes núcleos de población: Prado de la Guzpeña, Cerezal de la Guzpeña, Llama de la Guzpeña y Robledo de la Guzpeña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24118','iglesia','Iglesia Parroquial de San Martín','Templo de traza rural edificado en el siglo XVII combinando mampuesto calizo local con esquinales de sillería de Boñar bien escuadrada, la cual presenta una planta rectangular con una espadaña de dos ojos del periodo barroco clasicista que cobija un crucero pétreo en su atrio arbolado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24119','monumento','Núcleos de población de Priaranza del Bierzo','El término municipal incluye los siguientes núcleos de población: Priaranza del Bierzo, Ferradillo, Paradela de Muces, Santalla del Bierzo, Villalibre de la Jurisdicción y Villavieja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24119','monumento','Castillo de Cornatel (Villavieja)','Monumental fortaleza medieval de los siglos XII y XV vinculada originariamente a la Orden del Temple y posteriormente a los Condes de Lemos que se asienta sobre un escarpado farallón rocoso calizo utilizando imponentes murallas de mampostería de pizarra negra rústica y cuarcita, del cual se conservan la torre del homenaje almenada, las aspilleras defensivas y un patio de armas restaurado que domina las cuencas mineras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24119','iglesia','Iglesia de San Salvador de Santalla del Bierzo','Templo barroco del siglo XVIII levantado con fábrica de piedra','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24122','monumento','Núcleos de población de Puente de Domingo Flórez','El término municipal incluye los siguientes núcleos de población: Puente de Domingo Flórez, Castroquilame, Robledo de sobre el Castro, Salas de la Ribera, San Pedro de de Trones, Vega de de Yuso y Yeres.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24122','monumento','Canales Romanos de Las Médulas (Área de Yeres y Castroquilame)','Monumental infraestructura de ingeniería hidráulica de época romana (siglo I d.C.) labrada directamente sobre las escarpadas laderas de cuarcita rústica y pizarra de los montes de la Cabrera para conducir el agua desde el río Cabrera hasta el yacimiento aurífero, conservando muros cortina de retención de piedra seca y tramos de calzadas excavadas en la roca viva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24122','iglesia','Iglesia de San Pedro de Trones','Templo parroquial de origen medieval profundamente reformado en la etapa barroca utilizando aparejo de mampostería de pizarra negra rústica y sillería caliza calavera en los vanos, rematado por una robusta espadaña de dos ojos adaptada a la arquitectura tradicional de la cuenca minera de la pizarra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24123','monumento','Núcleos de población de Quintana del Castillo','El término municipal incluye los siguientes núcleos de población: Quintana del Castillo, Abano, Castro de la Cepeda, Donillas, Escuredo, Ferreras, Morriondo, Palaciosmil, Porqueros, Robledo de la Cepeda, San Feliz de las Lavanderas, Villarmeriel, Villameca y Villamejil.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24123','iglesia','Iglesia de San Feliz de las Lavanderas','Templo rural montañés de la comarca de La Cepeda edificado en el siglo XVII empleando aparejo mixto de mampostería de cuarcita rústica y cadenas angulares de sillería caliza calavera, cuya fachada occidental se caracteriza por una robusta espadaña bicéfala de dos cuerpos que dota de gran fijeza al conjunto del atrio parroquial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24124','monumento','Núcleos de población de Quintana del Marco','El término municipal incluye los siguientes núcleos de población: Quintana del Marco y Genestacio de la Vega.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24124','monumento','Castillo de los Condes de Luna (Torre de Quintana del Marco)','Restos fortificados de un gran palacio señorial bajomedieval del siglo XIV erigido con una fábrica de mampostería de canto rodado fluvial compactado y sillares calizos escuadrados en los esquinales, del cual destaca su imponente torre del homenaje almenada que luce empotrado en su frente un valioso busto romano tardío de piedra calcárea conocido popularmente como "El Rey Ramiro".','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24127','monumento','Núcleos de población de Regueras de Arriba','El término municipal incluye los siguientes núcleos de población: Regueras de Arriba y Regueras de Abajo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24127','iglesia','Iglesia Parroquial de San Lorenzo','Templo mudéjar de la ribera del Órbigo edificado en el siglo XVI mezclando muros portantes de tapial arcilloso con cajones de ladrillo macizo cocido, cuyo mayor elemento de interés interior es una techumbre de madera de pino con decoración de alfardas e hileras preindustriales labradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24129','monumento','Núcleos de población de Reyero','El término municipal incluye los siguientes núcleos de población: Reyero, Carande, Pallide, Primajas y Viego.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24129','iglesia','Iglesia de San Juan Bautista de Pallide','Templo rural de montaña construido en el siglo XVII combinando mampuesto calizo local con esquinales de la célebre sillería de Boñar, cuya fachada presenta una ruda espadaña de dos ojos adaptada para soportar las inclemencias del clima de la cordillera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24130','monumento','Núcleos de población de Riaño','El término municipal incluye los siguientes núcleos de población: Riaño, Carande, Horcadas, Las Friesas, Remolina y Tejerina.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24130','iglesia','Iglesia de Nuestra Señora del Rosario (Pedrosa de Rey Trasladada)','Templo románico de transición del siglo XIII que fue rescatado piedra a piedra del antiguo valle inundado por el embalse y reconstruido en el nuevo asentamiento empleando sus sillares calizos originales, destacando su portada apuntada de tres arquivoltas y sus valiosas pinturas murales góticas recuperadas en el presbiterio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24130','iglesia','Iglesia de San Pedro de Tejerina','Templo de traza montañesa del siglo XVI edificado con recia sillería caliza de Boñar y mampuesto que conserva una robusta espadaña medieval y un porche de vigas de madera de roble, en cuyo interior se custodia un retablo renacentista de gran mérito comarcal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33057','monumento','Núcleos de población de Ribera de Arriba','El término municipal incluye los siguientes núcleos de población: La Robla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33057','ermita','Ermita de Celada','Santuario de peregrinación de origen medieval profundamente reformado durante la etapa barroca utilizando aparejo de mampostería caliza y sillería en las esquinas, el cual destaca por su pórtico delantero de cobijo y','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24132','monumento','Núcleos de población de Riello','El término municipal incluye los siguientes núcleos de población: Riello, Andarraso, Ariego de Abajo, Ariego de Arriba, Bonella, Campo de la Lomba, El Castillo, Cirujales, Cornombre, Curueña, Folloso, Garueña, Guisatecha, Inicio, Laris, Manzaneda de Omaña, Marzán, Oencia, Omañón, Orallo, Pandorado, Rosales, Salce, Santibáñez de la Lomba, Socil, Sosas de la Lomba, Torrecillo, Valbueno, Vegarienza, La Velilla, Villadepán, Villar de Omaña, Villarín de Riello y Villaverde de Omaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24132','iglesia','Santuario de Nuestra Señora de Pandorado','Templo de peregrinación barroco del siglo XVII que constituye el corazón devocional de la comarca de Omaña, construido con una fábrica de mampostería de cuarcita rústica y esquinales de sillería caliza bien escuadrada, destacando su monumental torre campanario y su amplio pórtico sustentado por recias columnas pétreas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24132','monumento','Castillo de Benal (El Castillo)','Ruinas de la fortaleza feudal del siglo XV erigida sobre un cerro rocoso por orden del linaje de los Quiñones empleando muros de mampuesto cuarcítico y mortero de cal, del cual se conserva parte del lienzo','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24134','monumento','Núcleos de población de La Robla','El término municipal incluye los siguientes núcleos de población: La Robla, Alcedo de Alba, Brugos de Fenar, Candanedo de Fenar, Llanos de Alba, Olleros de Alba, Puente de Alba, Rabanal de Fenar, Solana de Fenar y Sorribos de Alba.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24134','iglesia','Iglesia de San Juan Bautista de Puente de Alba','Templo de origen medieval con reformas neoclásicas construido en sillería caliza de Boñar que destaca por su ábside cuadrangular y por su vinculación histórica a las rutas de paso de la montaña central leonesa, abriéndose su atrio tradicional hacia la cuenca del Bernesga.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24134','monumento','Castillo de Alba (Ruinas en Llanos de Alba)','Vestigios fortificados de una fortaleza altomedieval clave en la defensa del reino de León frente a las incursiones musulmanas, cuyos muros de piedra rústica caliza sin argamasa se confunden con el escarpado peñasco rocoso sobre el que se asienta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24136','monumento','Núcleos de población de Roperuelos del Páramo','El término municipal incluye los siguientes núcleos de población: Roperuelos del Páramo, Moscas del Páramo y Valcabado del Páramo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24136','iglesia','Iglesia de San Esteban de Valcabado del Páramo','Templo de tradición mudéjar de la meseta leonesa edificado en el siglo XVI empleando muros portantes de tapial arcilloso tradicional leones y cajones de ladrillo macizo cocido, cuyo elemento interior más valioso es un artesonado mudéjar de madera de pino policromada con decoración de lazo de par y nudillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24137','monumento','Núcleos de población de Sabero','El término municipal incluye los siguientes núcleos de población: Sabero, Alejico, Olleros de Sabero, Sahelices de Sabero y Sotillos de Sabero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24137','monumento','Instalaciones Minero-Siderúrgicas de San Blas (Museo de la Siderurgia y la Minería)','Monumental complejo de arqueología industrial del año 1846 catalogado como Bien de Interés Cultural que destaca por su espectacular nave de la Ferrería, una catedral laica del trabajo erigida con una suntuosa sillería caliza de Boñar y arcos neogóticos de mampostería que albergaron los primeros altos hornos de cok de España.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24139','monumento','Núcleos de población de Sahagún','El término municipal incluye los siguientes núcleos de población: Sahagún, Arenillas de Valderaduey, Celada de Cea, Gallegillos de Campos, Joara, San Martín de la Cueza, San Pedro de las Dueñas, Sotillo de Cea, Villalebrín y Villalmán.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24139','iglesia','Iglesia de San Lorenzo','Obra cumbre del románico mudéjar español del siglo XIII construida íntegramente con ladrillo macizo visto cocido sobre un zócalo de sillería caliza calavera, cuya espectacular torre campanario de cuatro cuerpos decrecientes presenta arquerías ciegas de herradura y apuntadas caladas de perfecta ejecución preindustrial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24139','iglesia','Iglesia de San Tirso','Templo del siglo XII considerado el prototipo del mudéjar leonés que destaca por su ábside semicircular construido en ladrillo que fusiona las formas románicas con la técnica constructiva islámica, rematado por','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24139','iglesia','Monasterio de Real de San Benito y Arco de San Benito','Vestigios del que fuera uno de los cenobios benedictinos más poderosos de la España medieval, del cual se conserva intacta la monumental portada barroca del siglo XVII proyectada por Felipe Berrojo a modo de arco de triunfo triunfal empleando sillería caliza de Boñar y esculturas heráldicas exentas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24139','iglesia','Iglesia de la Peregrina y Convento de San Francisco','Antiguo cenobio franciscano del siglo XIII emplazado sobre una colina que destaca por la rica decoración de yeserías mudéjares de su ábside interior, cuyas estructuras de ladrillo y tapial reflejan el esplendor de las fundaciones reales en el Camino de Santiago Francés.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24139','iglesia','Monasterio de Santa María de las Dueñas (San Pedro de las Dueñas)','Cenobio benedictino del siglo XII cuya iglesia destaca por la riqueza escultórica de sus capiteles románicos labrados en piedra arenisca y caliza por el maestro de la Colegiata de San Isidoro, integrados en una arquitectura de naves de ladrillo mudéjar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24142','monumento','Núcleos de población de San Andrés del Rabanedo','El término municipal incluye los siguientes núcleos de población: San Andrés del Rabanedo, Ferral del Bernesga, San Juan de Dios, Trobajo del Camino y Villabalter.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24142','ermita','Ermita de Santiago Apóstol en Trobajo del Camino','Templo de factura tradicional barroca del siglo XVIII vinculado históricamente a las rutas jacobeas que cuenta con muros de mampostería caliza y cantos rodados compactados, destacando su portada neoclásica de sillería de Boñar y una espadaña de ladrillo macizo de dos ojos que daba la bienvenida a los peregrinos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24145','monumento','Núcleos de población de San Emiliano','El término municipal incluye los siguientes núcleos de población: San Emiliano, Candemuela, Cospedal, Genestosa, La Majúa, Pinos, Riolago, Robledo de Babia, Torrebarrio, Torrestío, Truébano, Villafeliz de Babia, Villasecino y Villargusan.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24145','palacio','Palacio de los Quiñones de Riolago (Casa de los Condes de Luna)','Monumental palacio solariego montañés del siglo XVI edificado con robustos muros de sillería caliza y mampostería de piedra rústica calavera que exhibe una planta rectangular defendida por un patio de armas almenado, un portalón con un imponente despliegue de blasones heráldicos y defensas adaptadas a los rigores de la comarca de Babia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24145','monumento','Conjunto Etnográfico de Hórreos y Hórreas de Torrestío','Extraordinario muestrario de estructuras agrícolas preindustriales construidas con tablones exentos de madera de roble ("colondras") ensamblados a hueso y techumbres a dos aguas de losas de pizarra negra, sobreelevados mediante pies piramidales calcáreos que marcan la transición cultural hacia el territorio asturiano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24146','monumento','Núcleos de población de San Esteban de Nogales','El término municipal incluye los siguientes núcleos de población: San Esteban de Nogales y sus fincas ganaderas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24146','iglesia','Ruinas del Real Monasterio de Santa María de Nogales','Vestigios monumentales de un cenobio cisterciense fundado en el siglo XII bajo el mecenazgo de los condes de Alfonso VII','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24152','monumento','Núcleos de población de Santa Colomba de Somoza','El término municipal incluye los siguientes núcleos de población: Santa Colomba de Somoza, Andiñuela, Argañoso, Foncebadón, La Maluenga, Murias de Pedredo, Pedredo, Rabanal del Camino, Rabanal Viejo, San Martín de Agostedo, Santa Marina de Somoza, Turienzo de los Caballeros, Val de San Lorenzo, Valdemanzanas, Veldedo y Villar de Ciervos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24152','monumento','Torre de los Osorio en Turienzo de los Caballeros','Espectacular torre del homenaje exenta del siglo XIV construida con mampostería de cuarcita rústica y cadenas angulares de sillería caliza bien escuadrada que formaba parte del antiguo castillo defensivo de la Orden del Temple, conservando intacto su adarve almenado y sus estrechas saeteras medievales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24152','monumento','Casco Etnográfico Maragato de Santa Colomba y Villar de Ciervos','Conjunto urbano histórico que destaca por la homogeneidad de sus casonas de arriería de los siglos XVIII y XIX erigidas con gruesos muros de piedra rojiza cuarcítica vista, grandes portalones de medio punto con dovelas de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24158','monumento','Núcleos de población de Santa María de Ordás','El término municipal incluye los siguientes núcleos de población: Santa María de Ordás, Adrados de Ordás, Callejo de Ordás, Formigones, Rioseco de Tapia, Santibáñez de Ordás, Selga de Ordás, Villapodame y Villarroquel.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24158','monumento','Torre de Ordás','Restos fortificados de una antigua torre de vigía señorial del siglo XIV emplazada sobre un otero estratégico que domina el valle del Luna, erigida con gruesos muros de mampuesto calizo y cal que atestiguan las luchas jurisdiccionales entre la nobleza leonesa medieval.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24160','monumento','Núcleos de población de Santas Martas','El término municipal incluye los siguientes núcleos de población: Santas Martas, Luengos, Malillos de los Oteros, Valdearcos, Villamarco y Villamuñío.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24160','iglesia','Iglesia de San Pelayo en Villamuñío','Templo de la meseta leonesa edificado en el siglo XVII empleando muros portantes de tapial arcilloso tradicional y cajones de ladrillo macizo mudéjar, cuyo volumen destaca por una robusta espadaña barroca de tres cuerpos que sirve de referencia visual en las llanuras cerealistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24163','monumento','Núcleos de población de Sariegos','El término municipal incluye los siguientes núcleos de población: Sariegos, Azadinos, Carbajal de la Legua y Pobladura de Bernesga.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24163','iglesia','Iglesia Parroquial de San Julián en Carbajal de la Legua','Templo rural de la ribera del Bernesga reformado en el siglo XVIII que cuenta con muros de mampostería de cuarcita fluvial y cantos rodados compactados, destacando su portada neoclásica de sillería de Boñar y una espadaña de dos cuerpos rematada por pináculos barrocos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24164','monumento','Núcleos de población de Sena de Luna','El término municipal incluye los siguientes núcleos de población: Sena de Luna, Abelgas de Luna, Aralla de Luna, Caldas de Luna, Pobladura de Luna, Rabanal de Luna, Robledo de Caldas y Vega de Gordón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24164','iglesia','Iglesia de San Juan Bautista de Rabanal de Luna','Templo montañes del siglo XVII edificado con recia sillería caliza y mampuesto que conserva una robusta espadaña medieval adaptada a los rigores de la cordillera, albergando en su atrio un crucero pétreo de excelente factura popular y un porche de vigas de madera de roble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24164','palacio','Casona Solariega de los Quiñones (Sena de Luna)','Antigua residencia de verano de los Condes de Luna construida en el siglo XVIII con aparejo mampuesto de caliza gris y esquinales de cantería fina que exhibe un blasón heráldico deteriorado sobre su portalón de arco rebajado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24165','monumento','Núcleos de población de Sobrado','El término municipal incluye los siguientes núcleos de población: Sobrado, Aguiar, Cabarcos, Cabeza de Campo, Friera, Portela de Aguiar, Requejo y Robledo de la Sobrefrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24165','iglesia','Iglesia de San Julián de Cabeza de Campo','Templo de filiación barroca berciana construido con aparejo de mampostería de pizarra negra rústica y refuerzos angulares de sillería caliza en los vanos primordiales, rematado en su fachada principal por una espadaña de dos ojos y un crucero etnográfico en su atrio umbrío.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24166','monumento','Núcleos de población de Soto de la Vega','El término municipal incluye los siguientes núcleos de población: Soto de la Vega, Alcaidón, Huerga de Garaballes, Oteruelo de la Vega, Requejo de la Vega, San Juan de la Torres, Vecilla de la Vega y Garaballes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24166','iglesia','Iglesia de San Juan de la Torres','Templo de tradición mudéjar de la vega del Órbigo edificado en el siglo XVI empleando muros portantes de tapial arcilloso revestido y cajones de ladrillo macizo cocido, cuya fachada principal se ve coronada por una gran espadaña barroca de tres cuerpos que dota de notable verticalidad a la llanura aluvial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24167','monumento','Núcleos de población de Soto y Amío','El término municipal incluye los siguientes núcleos de población: Soto y Amío, Camposalinas, Canales-La Magdalena, Carrizal, Garaño, Irián, Lago de Omaña, Quintanilla, San Pedro de de Pegas, Villaceid y Villayuste.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24167','iglesia','Santuario de Nuestra Señora de las Pegas','Templo de peregrinación barroco del siglo XVII que cuenta con una fábrica de mampostería de cuarcita rústica y esquinales de sillería caliza de Boñar, destacando su amplio pórtico delantero que ofrece cobijo tradicional a las romerías de la comarca de Omaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24206','monumento','Núcleos de población de Toral de los Vados','El término municipal incluye los siguientes núcleos de población: Toral de los Vados, Iglesia de Campo, Otero, Parandones, Penedelo, Peón, Sorribas, Valiña, Villadecanes y Viloria.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24206','palacio','Pazo de Toral de los Vados (Casa Grande)','Residencia solariega cortesana del siglo XVIII construida con una fábrica de piedra rústica pizarrosa y sillería caliza dorada en los vanos, la cual conserva su portalón blasonado barroco y un gran palomar circular exento integrado en el viñedo berciano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24169','monumento','Núcleos de población de Toreno','El término municipal incluye los siguientes núcleos de población: Toreno, Librán, Matarrosa del Sil, Pardamaza, Pradilla, San Pedro Mallo, Santa Marina del Sil, Tombrio de Abajo, Tombrio de Arriba, Valdelaloba y Villar de las Ollas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24169','monumento','Pinturas Rupestres de Librán (Sésamo - Acceso Comarcal)','Estación arqueológica de arte esquemático prehistórico de la Edad del Bronce pintadas con pigmentos de óxido de hierro en los abrigos rocosos de cuarcita viva del cañón del río Primout, catalogadas de alto interés arqueológico por sus representaciones antropomorfas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24169','iglesia','Iglesia de San Juan Bautista de Toreno','Templo parroquial de traza barroca clasicista del siglo XVIII erigido con fábrica mixta de mampostería pizarrosa y refuerzos angulares de sillería caliza calavera, rematado en su fachada por una esbelta torre campanario de líneas clasicistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24170','monumento','Núcleos de población de Torre del Bierzo','El término municipal incluye los siguientes núcleos de población: Torre del Bierzo, Albares de la Ribera, Las Ventas de Albares, La Granja de San Vicente, Matavenero, Poibueno, San Facundo, San Andrés de las Puentes, Santa Cruz de Montes y Tremor de Abajo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24170','iglesia','Iglesia de San Facundo','Templo románico de transición profundamente reformado en el periodo barroco que destaca por su ábside cuadrangular levantado en sillería de piedra caliza dorada y mampostería de pizarra rústica, enclavado en un angosto valle que potencia su carácter místico y su fijeza arquitectónica tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24170','monumento','Puente Romano de Albares de la Ribera','Estructura viaria preindustrial modificada en la Baja Edad Media sobre el río Boeza que cuenta con arcos de medio punto construidos con aparejo pizarroso rústico y tajamares triangulares, testigo mudo de las históricas rutas de arriería y comunicación hacia el centro de la provincia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24171','monumento','Núcleos de población de Trabadelo','El término municipal incluye los siguientes núcleos de población: Trabadelo, Moral de de Valcarce, Parada de de Soto, Pereje, Pradela, San Fiz do Seo, Sotoparada, Villar de de Corrales y Pereje.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24171','iglesia','Iglesia de Santa María de Pereje','Templo de factura románica rural modificado sustancialmente durante el siglo XVII en el trazado histórico del Camino de Santiago Francés que cuenta con robustos muros de mampostería de pizarra encalada y cadenas de sillería caliza calavera en las esquinas, destacando su porche de madera de castaño para cobijo de los peregrinos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24172','monumento','Núcleos de población de Truchas','El término municipal incluye los siguientes núcleos de población: Truchas, Baillo, Corporales, Iruela, Manzaneda, Pozos, Quintanilla de de Yuso, Truchillas, Valdavido, Villar de de Ciervos, Villarino y Villarino de de Cabrera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24172','monumento','Conjunto de Arquitectura Tradicional de la Cabrera Alta (Corporales e Iruela)','Núcleos tradicionales que destacan por la conservación homogénea de sus viviendas de los siglos XVIII y XIX erigidas con gruesos muros de mampostería de pizarra negra rústica y techumbres de grandes losas toscas,','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24172','iglesia','Iglesia de San Julián de Truchas','Templo rural del siglo XVII levantado con aparejo pizarroso local y techumbre de vigas de madera de castaño labrada, cuya modesta espadaña de dos ojos custodia un crucero pétreo de excelente factura popular en el centro de su umbrío atrio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24175','monumento','Núcleos de población de Valdefresno','El término municipal incluye los siguientes núcleos de población: Valdefresno, Arcahueja, Carbajosa, Corbillos de de la Sobarriba, Golpejar de de la Sobarriba, Las Grañeras, Navafría, Paradilla de de la Sobarriba, Sanfelismo, Santa Olaja de de Porma, Santovenia de de la Sobarriba, Tendal, Valdelafuente, Villacete, Villachalambre, Villacil, Villafañe, Villalobar, Villaseca de de la Sobarriba y Villaturiel.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24175','iglesia','Iglesia de San Juan Bautista de Villafañe','Templo parroquial de traza barroca clasicista del siglo XVIII levantado con fábrica mixta de canto rodado compactado y cadenas angulares de sillería de Boñar, cuya fachada principal se caracteriza por su robusta espadaña de dos cuerpos rematada por pináculos barrocos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24181','monumento','Núcleos de población de Valderas','El término municipal incluye los siguientes núcleos de población: Valderas y sus fincas cerealistas de la meseta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24181','monumento','Arco de Santiago y Puerta de las Arreitadas','Puertas monumentales del recinto amurallado bajomedieval del siglo XIV levantadas con aparejo toledano mampuesto y sillería caliza de Boñar en sus arcos apuntados, constituyendo los accesos principales a la antigua villa fortificada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24181','palacio','Seminario Mayor o Palacio de los Osorio','Monumental edificio civil barroco del siglo XVIII que cuenta con una fachada palaciega de ladrillo visto y zócalo de sillería caliza de gran esbeltez, organizada en torno a un amplio patio porticado con pilastras toscanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24181','iglesia','Iglesia de Santa María del Azogue','Templo renacentista e historicista edificado en el siglo XVI sobre una base románica anterior que presenta una imponente planta basilical con bóvedas de crucería, albergando en su altar mayor un retablo de madera de castaño con imaginería policromada atribuida a discípulos de Berruguete.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24183','monumento','Núcleos de población de Valderrueda','El término municipal incluye los siguientes núcleos de población: Valderrueda, Caminayo, Carrizal, Cegoñal, La Espina, GuardoEstación, Morgovejo, Las Muñecas, Otero de de Guardo, Puente Almuhey, Renedo de de Valderrueda, San Martín de de Valdetuéjar, Soto de de Valderrueda, Taranilla, Valdetuéjar, Villacorta, Villalmonte, Villamane, Villamartín de de Don Sancho y de Valderrueda.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24183','iglesia','Santuario de la Virgen de la Velilla (San Martín de Valdetuéjar)','Monumental templo de peregrinación barroco del siglo XVII proyectado en sillería de piedra caliza calavera de gran porte que cuenta con una esbelta torre campanario de líneas clasicistas y un claustro reglar exento, cuyo altar mayor custodia un retablo churrigueresco de madera policromada de altísima calidad artística.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24183','iglesia','Iglesia del Antiguo Monasterio de San Guillermo','Ruinas místicas de un cenobio medieval encajado en un desfiladero rocoso calizo del que se conservan los muros perimetrales de su iglesia y arcos fajones construidos con mampostería caliza y cal, catalogado de alto interés etnográfico por las leyendas eremíticas asociadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24188','monumento','Núcleos de población de Valencia de Don Juan','El término municipal incluye los siguientes núcleos de población: Valencia de Don Juan y Cabañas de de Valencia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24188','monumento','Castillo de los Acuña (Castillo de Coyanza)','Obra cumbre de la arquitectura militar gótica tardía del siglo XV mandada erigir por los condes de Valencia de Don Juan empleando una suntuosa y masiva fábrica de tapial de gran dureza, mampostería de ladrillo cocido y torres cilíndricas angulares','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24188','iglesia','Iglesia de Nuestra Señora del Castillo Vieja','Templo neoclásico del siglo XVIII edificado en aparejo de ladrillo macizo visto que alberga en su presbiterio el célebre Retablo de los Acuña, una pieza plateresca excepcional tallada en madera noble con policromías flamencas catalogada como Bien de Interés Cultural.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24196','monumento','Núcleos de población de Vega de Espinareda','El término municipal incluye los siguientes núcleos de población: Vega de Espinareda, Burbia, El Espino, Moreda, Penoselo, San Martín de Moreda, Sésamo, Valle de Finolledo y Villar de Acero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24196','iglesia','Monasterio de San Andrés de Espinareda','Monumental cenobio benedictino fundado en el siglo X y reedificado majestuosamente tras un incendio en el siglo XVIII en estilo neoclásico y barroco academicista con sillería caliza dorada de El Bierzo, cuyo conjunto destaca por su grandiosa fachada palaciega, un claustro reglar porticado de proporciones monumentales y una iglesia de tres naves que custodia retablos de gran mérito artístico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24196','monumento','Pinturas Rupestres de Sésamo (Peña Piñera)','Estación arqueológica de arte esquemático prehistórico de la Edad del Bronce pintada con pigmentos de óxido de hierro sobre abrigos rocosos de cuarcita viva, considerada el conjunto pictórico rupestre más importante de la provincia de León y declarado Bien de Interés Cultural.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24196','monumento','Puente Romano sobre el río Cúa','Estructura viaria preindustrial reedificada en la etapa medieval empleando mampostería de pizarra rústica y grandes tajamares para canalizar las crecidas fluviales, constituyendo un hito de la ingeniería civil que articula el acceso a los valles interiores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24202','monumento','Núcleos de población de Villablino','El término municipal incluye los siguientes núcleos de población: Villablino, Caboalles de Abajo, Caboalles de Arriba, Lumajo, Orallo, Rioscuro, Robles de Laciana, San Miguel de Laciana, Sosas de Laciana, Villaseca de Laciana y Villager de Laciana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24202','iglesia','Iglesia de San Julián de Robles de Laciana','Joya del románico rural del siglo XI erigida en sillería caliza tosca y mampuesto que conserva su cabecera rectangular primitiva y un ábside con saeteras, constituyendo el templo religioso más antiguo de la comarca de Laciana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24202','palacio','Casona de los Sierra en Llamas de Laciana (Acceso Comarcal)','Monumental palacio solariego montañés del siglo XVII construido con recios muros de piedra rústica y esquinales de cantería fina que exhibe un portalón almenado con un imponente despliegue heráldico vinculado al linaje de los Sierra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24209','monumento','Núcleos de población de Villafranca del Bierzo','El término municipal incluye los siguientes núcleos de población: Villafranca del Bierzo, Campo del Agua, Cela, Corullón, Landoiro, Paradela, Pobladura de Somoza, Prado de la Somoza, Ribera de Abajo, Tejeira, Valtuille de Abajo, Valtuille de Arriba, Vilela y Villasinde.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24209','iglesia','Iglesia de Santiago Apóstol','Templo románico de finales del siglo XII levantado con excelente sillería caliza dorada y mampostería pizarrosa que destaca universalmente por su "Puerta del Perdón", la única portada junto a la de la Catedral de Santiago de Compostela donde los peregrinos impedidos físicamente pueden ganar el jubileo jacobeo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24209','monumento','Castillo de los Marqueses de Villafranca','Fortaleza señorial fortificada del siglo XVI erigida con una masiva fábrica de mampostería de pizarra negra rústica y potentes torreones cilíndricos angulares almenados con escaraguaitas, proyectada por orden de don Pedro de Toledo como residencia cortesana adaptada al uso del armamento de artillería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24209','iglesia','Colegiata de Santa María de la Clerecía','Monumental templo gótico tardío y renacentista del siglo XVI proyectado por Rodrigo Gil de Hontañón sobre un antiguo monasterio cluniacense empleando excelente cantería caliza bien escuadrada, la cual destaca por la grandiosidad de sus','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24209','iglesia','Convento de San Francisco','Cenobio fundado en el siglo XIII según la tradición por el propio San Francisco de Asís que conserva una espectacular iglesia gótica de sillería con un monumental artesonado mudéjar policromado del siglo XV, el cual cubre la nave central con una intrincada tracería de lazo de par y nudillo única en El Bierzo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24209','monumento','Barrio y Conjunto Etnográfico de Campo del Agua','Núcleo tradicional de alta montaña que conserva de forma homogénea sus "pallozas" preindustriales de origen celta con muros bajos de mampostería de pizarra sin argamasa y techumbres cónicas de paja de centeno trenzada ("teito"), constituyendo un testimonio etnográfico excepcional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24222','monumento','Núcleos de población de Villaquilambre','El término municipal incluye los siguientes núcleos de población: Villaquilambre, Navatejera, Robledo de la Valdoncina, Villasinta de Torío, Villamoros de las Regueras, Castrillino y Canalejas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24222','monumento','Yacimiento de la Villa Romana de Navatejera','Complejo arqueológico residencial e industrial de los siglos II al IV d.C. que conserva los cimientos de piedra rústica caliza y ladrillo de sus estancias señoriales, destacando una magnífica colección de mosaicos geométricos polícromos y los restos de un sistema de calefacción subterránea por hipocausto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24222','iglesia','Iglesia de San Esteban de Villaquilambre','Templo de traza barroca rural modificado en el siglo XVIII empleando aparejo mixto de canto rodado compactado y esquinales de sillería de Boñar, cuya fachada destaca por una robusta espadaña de dos cuerpos rematada por pináculos barrocos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34025','monumento','Núcleos de población de Abarca de Campos','El término municipal incluye los siguientes núcleos de población: Abarca de Campos y sus explotaciones agrícolas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34025','iglesia','Iglesia Parroquial de San Sebastián','Templo de traza mudéjar y barroca edificado en el siglo XVII combinando muros portantes de tapial arcilloso con cajones de ladrillo macizo cocido, cuya torre campanario de tres cuerpos de ladrillo visto destaca en el perfil llano de Tierra de Campos por albergar en su interior un valioso órgano histórico castellano del año 1778.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90238','monumento','Núcleos de población de Alar del Rey','El término municipal incluye los siguientes núcleos de población: Alar del Rey, Barrio de San Vicente, Becerril del Carpio, Nogales de Pisuerga y San Quirce de Río Pisuerga.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90238','iglesia','Iglesia de San Juan Bautista de Becerril del Carpio','Templo de filiación románica rural modificado en las etapas renacentista y barroca que mantiene su estructura de nave única con cabecera rectangular erigida en sillería arenisca, destacando sus canecillos geométricos esculpidos bajo los aleros del tejado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90239','monumento','Núcleos de población de Alba de Cerrato','El término municipal incluye los siguientes núcleos de población: Alba de Cerrato y sus caseríos agrarios.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90239','iglesia','Iglesia de Nuestra Señora de la Asunción','Templo de traza rural edificado en el siglo XVI mezclando muros portantes de tapial de yeso y caliza con contrafuertes angulares de ladrillo macizo mudéjar, rematado en su fachada por una robusta espadaña barroca de tres cuerpos que dota de verticalidad al perfil urbano de la localidad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90240','monumento','Núcleos de población de Ampudia','El término municipal incluye los siguientes núcleos de población: Ampudia, Dehesa de de Valdepero, Esquileo de de Abajo, Monte la Torre, Rayaces, Valoria del Alcor y Valdebusto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90240','monumento','Castillo de Ampudia','Espectacular fortaleza militar del siglo XV de estilo gótico tardío que constituye el modelo de castillo señorial castellano con una masiva planta trapezoidal erigida en sillería caliza de Hontoria, jalonada por tres imponentes torres de planta cuadrada almenadas con elegantes escaraguaitas y un patio de armas porticado restaurado que alberga una valiosa colección arqueológica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90240','iglesia','Colegiata de San Miguel','Templo monumental de los siglos XV y XVI de transición del gótico al renacimiento levantado íntegramente con excelente cantería caliza bien escuadrada, cuya fachada occidental exhibe la célebre "Giralda de Campos", una esbelta torre campanario de siete cuerpos y más de sesenta metros de altura calada con finas tracerías góticas flamígeras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90240','monumento','Casco Histórico y Calles Soportandadas','Trazado urbano medieval de los siglos XVI y XVII catalogado como Conjunto Histórico-Artístico que destaca por sus calles porticadas sustentadas sobre robustos pilares exentos de piedra rústica y','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90240','iglesia','Iglesia de San Fructuoso de Valoria del Alcor','Joya del románico temprano del siglo XII que destaca por su pureza de líneas y por su galería porticada lateral levantada en sillería arenisca dorada, cuyos capiteles muestran una decoración de motivos vegetales y zoomorfos arcaizantes de gran valor escultórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90241','monumento','Núcleos de población de Amusco','El término municipal incluye los siguientes núcleos de población: Amusco, Monzón de de Campos-Estación, San Juan de de Ceballos y Valdespina.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90241','iglesia','Iglesia de San Pedro (El Pajarón de Campos)','Templo monumental de origen románico reedificado a gran escala en los siglos XVI y XVII que destaca por las descomunales proporciones de su nave central erigida en sillería caliza calavera, albergando en su presbiterio un suntuoso retablo mayor barroco churrigueresco de madera noble policromada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90241','ermita','Ermita de Nuestra Señora de las Fuentes','Joya del románico de transición de comienzos del siglo XIII construida con aparejo calizo bien escuadrado que presenta una nave única con bóvedas de crucería primitivas, destacando su portada occidental de arcos apuntados doblados y sus inscripciones de la Orden de San Juan de Jerusalén.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34017','monumento','Núcleos de población de Astudillo','El término municipal incluye los siguientes núcleos de población: Astudillo, Palacios del Alcor y Valdeolmos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34017','iglesia','Monasterio de Santa Clara','Complejo monacal palaciego mudéjar fundado en 1356 por el rey Pedro I de Castilla y Doña María de Padilla que conserva una espectacular iglesia erigida en sillería arenisca, cuyo interior atesora un bellísimo artesonado mudéjar policromado con tracerías de lazo de par y nudillo y un palacio anejo transformado en espacio museístico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34017','monumento','Recinto Amurallado y Puerta de San Martín','Restos de la fortificación medieval del siglo XII construidos con mampostería caliza regular y mortero de cal, de la cual se conserva intacta la puerta monumental norte configurada mediante un arco apuntado flanqueado por cubos defensivos rebajados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34017','iglesia','Iglesia de Santa María','Templo gótico tardío del siglo XV levantado íntegramente con excelente cantería caliza bien escuadrada que presenta una planta de tres naves separadas por pilares fasciculados, rematada exteriormente por una robusta torre campanario de líneas clasicistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34018','monumento','Núcleos de población de Autilla del Pino','El término municipal incluye los siguientes núcleos de población: Autilla del Pino y sus caseríos agrarios del páramo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34018','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo de traza barroca clasicista del siglo XVIII levantado con fábrica mixta de mampostería caliza y cadenas angulares de sillería fina en los esquinales, rematado en su fachada por una robusta espadaña de tres cuerpos que domina visualmente el espectacular mirador natural sobre la inmensidad de Tierra de Campos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34022','monumento','Núcleos de población de Baltanás','El término municipal incluye los siguientes núcleos de población: Baltanás y Valdecañas de de Cerrato.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34022','iglesia','Iglesia Parroquial de San Millán','Templo de traza renacentista y barroca del siglo XVI proyectado a gran escala en sillería caliza de las canteras locales del Cerrato, el cual destaca por la volumetría de su fachada principal flanqueada por una robusta torre campanario y por albergar en su interior un valioso órgano histórico barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34022','monumento','Barrio de Bodegas Subterráneas de El Castillo (Patrimonio Etnográfico)','Extraordinario conjunto etnográfico preindustrial compuesto por casi cuatrocientas bodegas subterráneas excavadas directamente en las lomas arcillosas','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34027','monumento','Núcleos de población de Barruelo de Santullán','El término municipal incluye los siguientes núcleos de población: Barruelo de Santullán, Bustillo de de Santullán, Cillamayor, Matabuena, Nava de de Santullán, Porquera de de Santullán, Revilla de de Santullán, Santa María de de Redondo, Verbios y Villabella.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34027','iglesia','Iglesia de San Cornelio y San Cipriano en Revilla de Santullán','Joya del románico rural palentino del siglo XII erigida en sillería arenisca dorada que destaca universalmente por su galería porticada lateral, cuyos capiteles e intradoses de la portada muestran una asombrosa colección de relieves escultóricos donde destaca el propio maestro escultor esculpiendo sus obras firmado con caracteres epigráficos medievales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34027','iglesia','Iglesia de Santa María la Real de Cillamayor','Templo románico de finales del siglo XII levantado con aparejo arenisco bien escuadrado que conserva su ábside semicircular con ventanas saetadas y una robusta espadaña exenta, cuyo interior custodia una pila bautismal románica decorada con motivos sogueados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34029','monumento','Núcleos de población de Becerril de Campos','El término municipal incluye los siguientes núcleos de población: Becerril de Campos y sus dehesas agrícolas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34029','iglesia','Iglesia-Museo de Santa María','Monumental templo de estilo gótico tardío del siglo XV y reformas renacentistas erigido en sillería caliza de Hontoria que conserva un bellísimo pórtico clasicista y un interior suntuoso habilitado como espacio museístico, donde destaca una de las colecciones de tablas pintadas y esculturas policromadas más importantes del maestro Pedro Berruguete y del escultor Alejo de Vahía.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34029','iglesia','Iglesia de San Pedro (Centro Cultural y Astronómico)','Antiguo templo en ruinas del siglo XII reconstruido de forma vanguardista con estructuras de acero y vidrio que mantiene su portada románica y su cabecera de sillería arenisca, rehabilitado como el único centro astronómico de España ubicado dentro de una iglesia con un péndulo de Foucault suspendido en su nave central.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34029','monumento','Ayuntamiento de Becerril de Campos','Palacio civil del siglo XIX de estilo historicista construido con fábrica de ladrillo macizo y zócalos de piedra caliza bien escuadrada que presenta una fachada monumental decorada con rejerías de forja y cartelas preindustriales, constituyendo el eje de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34031','monumento','Núcleos de población de Belmonte de Campos','El término municipal incluye los siguientes núcleos de población: Belmonte de Campos y sus fincas cerealistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34031','monumento','Castillo de Belmonte de Campos','Espectacular fortaleza militar de los siglos XV y XVI vinculada a la familia de los Manrique que destaca por su imponente torre del homenaje de planta rectangular y más de treinta metros de altura erigida en sillería caliza dorada, rematada por un elegante adarve almenado con voladizos sobre ménsulas y un espectacular balcón heráldico plateresco calado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34041','monumento','Núcleos de población de Calahorra de Boedo','El término municipal incluye los siguientes núcleos de población: Calahorra de Boedo y sus fincas ganaderas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34041','iglesia','Iglesia Parroquial de la Purificación','Templo rural de la comarca de Boedo-Ojeda edificado en el siglo XVII combinando muros portantes de mampostería arenisca con esquinales reforzados de sillería tosca, cuya fachada principal se ve coronada por una robusta espadaña barroca de tres cuerpos que aloja el campanario comunal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34047','monumento','Núcleos de población de Carrión de los Condes','El término municipal incluye los siguientes núcleos de población: Carrión de los Condes y sus granjas agrícolas de la vega.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34047','iglesia','Iglesia de Santiago','Obra cumbre del románico pleno del siglo XII declarada Monumento Nacional en la ruta del Camino de Santiago Francés que destaca universalmente por el friso escultórico de su fachada occidental tallado en piedra arenisca dorada, donde un Pantocrátor rodeado por el Tetramorfos y los veinticuatro ancianos del Apocalipsis exhibe una finura técnica inigualable sobre una portada de arcos de medio punto jalonada por el célebre apostolado de los músicos y artesanos medievales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34047','iglesia','Monasterio de San Zoilo','Magna abadía benedictina fundada en el siglo X cuya obra maestra es su claustro renacentista y plateresco del siglo XVI proyectado por Juan de Badajoz el Mozo, erigido en excelente sillería de Hontoria con una profusión escultórica que cubre las bóvedas de crucería estrellada con centenares de medallones e imágenes historidadas únicas en España.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34047','iglesia','Iglesia de Santa María del Camino (Santa María de la Victoria)','Monumental basílica románica de mediados del siglo XII levantada íntegramente con aparejo calizo bien escuadrada que presenta una planta de tres naves con bóvedas de cañón, cuya portada meridional exhibe relieves del ciclo de la Natividad y la leyenda del Tributo de las Cien Doncellas, complementada en el interior por un valioso Cristo gótico del siglo XIV.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34047','iglesia','Real Monasterio de Santa Clara','Complejo conventual fundado en el siglo XIII por orden de la reina Doña Mencía que presenta una sobria y recia arquitectura gótica de muros portantes de sillería y mampuesto, cuyo espacio interior atesora una valiosa colección de imaginería sacra barroca y un retablo mayor atribuido a la escuela vallisoletana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34049','monumento','Núcleos de población de Castrejón de la Peña','El término municipal incluye los siguientes núcleos de población: Castrejón de la Peña, Cantoral de la Peña, Cubillo de la Peña, Loma de Castrejón, Pisón de Castrejón, Recueva de la Peña, Roscales de la Peña, Tarilonte de la Peña, Traspeña de la Peña, Villanueva de la Peña y Villalbeto de la Peña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34049','iglesia','Iglesia del Salvador en Transpeña de la Peña (Traspeña)','Joya del románico de transición de comienzos del siglo XIII erigida con aparejo arenisco bien escuadrado a los pies de la gran peña calcárea que destaca por su monumental portada de arcos apuntados doblados, cuyos capiteles e intradoses muestran una asombrosa colección de relieves de motivos heráldicos e históricos integrados en su estructura de nave única.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34049','iglesia','Iglesia de San Juan Bautista en Pisón de Castrejón','Templo románico del siglo XII modificado en las etapas gótica y barroca que mantiene su estructura de sillería con capiteles vegetales románicos en su presbiterio, abriéndose su atrio tradicional hacia los valles de la Montaña Palentina.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34051','monumento','Núcleos de población de Castrillo de Onielo','El término municipal incluye los siguientes núcleos de población: Castrillo de Onielo y sus caseríos ganaderos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34051','iglesia','Iglesia Parroquial de la Paz','Templo de origen románico profundamente reformado en el periodo barroco que destaca por su ábside cuadrangular levantado en sillería caliza de los páramos del Cerrato palentino y por su fachada occidental rematada por una robusta espadaña bicéfala, albergando en','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34057','monumento','Núcleos de población de Cevico de la Torre','El término municipal incluye los siguientes núcleos de población: Cevico de la Torre y sus caseríos agrícolas del Cerrato.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34057','iglesia','Iglesia de San Martín','Templo de traza barroca clasicista del siglo XVII levantado a gran escala en sillería caliza de Hontoria que domina el perfil del valle del Cerrato gracias a la monumentalidad de su fachada principal simétrica flanqueada por una robusta torre campanario de líneas clasicistas, la cual se comunica con el casco urbano mediante una espectacular escalinata barroca de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34058','monumento','Núcleos de población de Cevico Navero','El término municipal incluye los siguientes núcleos de población: Cevico Navero y sus dehesas de encinar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34058','iglesia','Iglesia Parroquial de Nuestra Señora de la Paz','Templo de origen románico del siglo XII modificado en las etapas gótica y barroca empleando aparejo calizo rústico local que mantiene su portada románica de arcos de medio punto apuntados con capiteles historiados, en cuyo atrio umbrío se sitúa un crucero pétreo tradicional de alto valor etnográfico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34059','monumento','Núcleos de población de Cisneros','El término municipal incluye los siguientes núcleos de población: Cisneros y sus fincas cerealistas de Tierra de Campos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34059','iglesia','Iglesia de San Facundo y San Primitivo','Joya del arte mudéjar de Tierra de Campos del siglo XVI construida con una fábrica monumental de tapial arcilloso tradicional y ladrillo macizo visto cocido que custodia en su nave central un espectacular artesonado mudéjar polícromo del tipo de limas mohamares, el cual está considerado una de las obras cumbres de la carpintería de lo blanco en España por la intrincada minuciosidad de sus lazos geométricos y mocárabes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34059','iglesia','Iglesia de San Pedro','Templo monumental de transición gótico-renacentista del siglo XVI levantado en cantería caliza bien escuadrada que presenta una planta de tres naves separadas por pilares fasciculados, albergando en su interior el suntuoso retablo mayor ejecutado por el maestro Francisco Giralte con policromías de la escuela vallisoletana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34069','monumento','Núcleos de población de Dueñas','El término municipal incluye los siguientes núcleos de población: Dueñas y las fincas agrícolas de la vega del Pisuerga.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34069','iglesia','Iglesia de Santa María de la Asunción','Magna basílica románica de transición y gótica primitiva de los siglos XII y XIII levantada íntegramente con excelente sillería de Hontoria que presenta una monumental cabecera con ábsides escalonados, albergando en su presbiterio un espectacular retablo mayor tardogótico del año 1515 atribuido al taller del maestro Alejo de Vahía y una suntuosa sillería de coro plateresca tallada en madera noble noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34069','iglesia','Monasterio de San Isidro de Dueñas (La Trapa)','Complejo monacal de origen altomedieval reedificado en el periodo barroco academicista con sillería caliza dorada que destaca por su iglesia románica del siglo XI exenta que conserva capiteles de filiación jaquesa, configurando uno de los hitos espirituales más importantes de la cuenca del Pisuerga.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34069','monumento','Ojo de la Virgen y Restos de la Muralla Medieval','Puerta monumental del recinto fortificado bajomedieval del siglo XIV levantada con aparejo toledano mampuesto y sillería caliza en sus arcos apuntados, de la cual se conservan notables tramos de lienzos de murallas almenadas integradas en las bodegas tradicionales excavadas en el cerro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34070','monumento','Núcleos de población de Espinosa de Cerrato','El término municipal incluye los siguientes núcleos de población: Espinosa de Cerrato y sus caseríos agrarios.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34070','iglesia','Iglesia Parroquial de San Martín','Templo rural del siglo XVI edificado con muros portantes de mampostería caliza y cadenas de sillería de las canteras del Cerrato en los esquinales, el cual destaca por su espadaña barroca de tres cuerpos que dota de verticalidad al perfil urbano y por albergar en su interior un retablo mayor de madera noble tallada de estética barroco-clasicista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34071','monumento','Núcleos de población de Espinosa de Villagonzalo','El término municipal incluye los siguientes núcleos de población: Espinosa de Villagonzalo y sus fincas cerealistas de Tierra de Campos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34071','iglesia','Iglesia de San Cecilia','Templo mudéjar de la meseta palentina construido en el siglo XVI empleando muros portantes de tapial arcilloso tradicional y cajones de ladrillo macizo visto cocido, cuya fachada principal destaca por una','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34074','monumento','Núcleos de población de Frómista','El término municipal incluye los siguientes núcleos de población: Frómista y Población de Campos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34074','iglesia','Iglesia de San Martín de Tours','Obra cumbre e hito absoluto del románico pleno mundial construida en el año 1066 por orden de la reina Doña Mayor de Castilla que destaca universalmente por la asombrosa pureza y simetría geométrica de sus tres naves, erigidas en excelente sillería arenisca dorada, flanqueadas exteriormente por dos esbeltas torres cilíndricas angulares y coronadas por un cimborrio octogonal, cuyo alero y capiteles interiores exhiben una legendaria colección de más de trescientos canecillos e historias pétreas esculpidas con una finura escultórica inigualable.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34074','iglesia','Iglesia de Santa María del Castillo','Templo monumental de estilo gótico tardío y renacentista del siglo XVI levantado en cantería caliza de Hontoria que presenta una planta basilical de tres naves con bóvedas de crucería estrellada, albergando en su presbiterio el célebre retablo mayor pictórico tardogótico de finales del siglo XV compuesto por veintinueve tablas castellanas de altísima calidad artística.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34076','monumento','Núcleos de población de Fuentes de Nava','El término municipal incluye los siguientes núcleos de población: Fuentes de Nava y el área de la Laguna de la Nava.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34076','iglesia','Iglesia de San Pedro','Templo monumental de los siglos XV y XVI erigido con excelente cantería caliza calavera que presenta una fachada neoclásica dominada por la célebre "Estrella de Campos", una imponente y esbelta torre campanario de traza gótico-flamígera de más de sesenta metros de altura calada con tracerías finas, cuyo interior atesora un espectacular artesonado mudéjar policromado en su coro alto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34076','iglesia','Iglesia de Santa María','Templo románico modificado a gran escala en el periodo barroco del siglo XVII utilizando aparejo mixto de sillería y ladrillo que destaca por albergar en su presbiterio un suntuoso retablo mayor plateresco con tallas atribuidas a la escuela de Alonso Berruguete y por conservar las puertas medievales de su cerca porticada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34080','monumento','Núcleos de población de Guardo','El término municipal incluye los siguientes núcleos de población: Guardo, Muñeca, Intorcisa y San Pedro de Cansoles.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34080','palacio','Palacio del Arzobispo Bullón','Monumental casona civil de traza barroca del siglo XVIII construida con excelente sillería caliza de canteras montañesas que destaca por la suntuosidad de su fachada, ornamentada con grandes blasones heráldicos eヒrrajes de hierro forjado apoyados sobre ménsulas molduradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34080','iglesia','Iglesia Parroquial de San Juan Bautista','Templo erigido en el siglo XVI combinando sillería arenisca bien escuadrada con mampostería regular que presenta una robusta torre campanario de líneas clasicistas, cuyo presbiterio atesora un notable retablo mayor tardorrenacentista y una pila bautismal románica remanente del templo medieval primitivo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34081','monumento','Núcleos de población de Guaza de Campos','El término municipal incluye los siguientes núcleos de población: Guaza de Campos y sus fincas cerealistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34081','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo de tradición mudéjar de la meseta palentina edificado en el siglo XVI empleando muros portantes de tapial arcilloso tradicional y cajones de ladrillo macizo visto cocido, cuya fisonomía exterior está dominada por una gran espadaña barroca de tres cuerpos que aloja el campanario comunal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34083','monumento','Núcleos de población de Herrera de Pisuerga','El término municipal incluye los siguientes núcleos de población: Herrera de Pisuerga, Naveros de Pisuerga, Olmos de Pisuerga, Ventosa de Pisuerga y Villabermudo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34083','monumento','Aula Arqueológica Pisoraca y Restos de la Legio IIII Macedonica','Conjunto arqueológico romano de los siglos I a.C. y I d.C. que conserva los cimientos y estructuras de mampostería, calzadas y zócalos de piedra rústica de los antiguos campamentos militares estables que dieron origen a la localidad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34083','monumento','Puerta Nueva y Restos de la Muralla Medieval','Acceso monumental del antiguo recinto fortificado bajomedieval del siglo XIV levantado con aparejo de sillería caliza bien labrada en arco apuntado, la cual luce empotrado un relieve heráldico con las armas de los Lara y los Velasco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34083','ermita','Ermita de la Virgen de la Piedad','Templo barroco clasicista del siglo XVIII erigido con aparejo mixto de piedra y ladrillo que destaca por la volumetría de su presbiterio, albergando en su altar un suntuoso camarín que custodia la venerada imagen mariana patronal de gran devoción comarcal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34086','monumento','Núcleos de población de Hontoria de Cerrato','El término municipal incluye los siguientes núcleos de población: Hontoria de Cerrato y sus caseríos agrarios del páramo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34086','iglesia','Iglesia de San Miguel Arcángel','Templo de origen románico del siglo XII con importantes remodelaciones neoclásicas levantado íntegramente con la célebre y duradera piedra caliza calavera de Hontoria extraída de sus propias canteras','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34088','monumento','Núcleos de población de Husillos','El término municipal incluye los siguientes núcleos de población: Husillos y las fincas agrarias de la vega del Carrión.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34088','iglesia','Iglesia de la Abadía de Santa María de Husillos','Monumental basílica de origen altomedieval reedificada en el estilo románico pleno del siglo XII y reformada en las etapas gótica y barroca empleando excelente cantería caliza bien escuadrada, la cual destaca por su cabecera rectangular con canecillos historiados y por haber sido la sede de importantes concilios históricos de la Corona de Castilla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34089','monumento','Núcleos de población de Itero de la Vega','El término municipal incluye los siguientes núcleos de población: Itero de la Vega y sus caseríos agrarios de la vega del Pisuerga.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34089','monumento','Puente Fitero (Ponte Fitero)','Monumental paso viario medieval de origen románico reedificado sustancialmente en el siglo XIV por orden del rey Alfonso VI de León y Castilla sobre el río Pisuerga empleando sillería caliza bien escuadrada en sus once imponentes arcos apuntados, constituyendo uno de los hitos arquitectónicos y de ingeniería civil más célebres y fotografiados por los peregrinos del Camino de Santiago Francés en su entrada a tierras palentinas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34089','ermita','Ermita de Nuestra Señora de la Piedad','Templo románico de transición de comienzos del siglo XIII levantado con aparejo arenisco dorado que conserva una magnífica portada','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90242','monumento','Núcleos de población de Lomas','El término municipal incluye los siguientes núcleos de población: Lomas de Campos y sus fincas cerealistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90242','iglesia','Iglesia de San Cristóbal','Templo de traza barroca rural del siglo XVII levantado sobre un montículo estratégico en plena Tierra de Campos empleando aparejo mixto de tapial arcilloso tradicional y contrafuertes angulares de ladrillo macizo, cuya fachada se ve coronada por una robusta espadaña de tres cuerpos que sirve de referencia visual en la inmensidad del paisaje agrario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34098','monumento','Núcleos de población de Magaz de Pisuerga','El término municipal incluye los siguientes núcleos de población: Magaz de Pisuerga y sus caseríos de la vega aluvial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34098','ermita','Ermita de la Virgen de Villaverde','Santuario románico rural modificado en las etapas renacentista y barroca utilizando aparejo de mampostería caliza y cadenas de sillería de Hontoria en los esquinales, el cual conserva en su presbiterio una notable colección de capiteles con motivos fitomorfos toscos y un porche delantero adaptado para las romerías comarcales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34098','monumento','Castillo-Fortaleza de Magaz y Cuevas Rupestres','Ruinas de un antiguo recinto fortificado altomedieval emplazado sobre un cerro testigo que domina estratégicamente el nudo de comunicaciones del Pisuerga, en cuyas laderas se conserva un extraordinario conjunto de cuevas y viviendas rupestres excavadas directamente sobre los estratos arcilloso-calcáreos de alto interés etnográfico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34102','monumento','Núcleos de población de Mazariegos','El término municipal incluye los siguientes núcleos de población: Mazariegos y sus fincas cerealistas de la llanura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34102','iglesia','Iglesia Parroquial de la Asunción','Templo de traza barroca clasicista del siglo XVII edificado en Tierra de Campos combinando muros portantes de tapial arcilloso con cajones de ladrillo macizo visto, cuya fachada occidental exhibe una robusta torre campanario de tres cuerpos de ladrillo que rompe la horizontalidad del paisaje mesetario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34104','monumento','Núcleos de población de Melgar de Yuso','El término municipal incluye los siguientes núcleos de población: Melgar de Yuso y sus dehesas agrícolas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34104','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo de origen mudéjar rural muy reformado en las etapas moderna y barroca utilizando aparejo de tapial revestido y contrafuertes angulares de ladrillo macizo mudéjar, cuyo presbiterio de sillería arenisca custodia en su interior un retablo mayor de madera noble policromada de la escuela castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34106','monumento','Núcleos de población de Meneses de Campos','El término municipal incluye los siguientes núcleos de población: Meneses de Campos y sus explotaciones ganaderas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34106','iglesia','Iglesia de Nuestra Señora de Tovar','Templo monumental de los siglos XV y XVI de transición gótico-renacentista levantado con excelente cantería caliza bien escuadrada que presenta una esbelta torre campanario de líneas clasicistas, en cuyo','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34110','monumento','Núcleos de población de Mudá','El término municipal incluye los siguientes núcleos de población: Mudá y San Cebrián de Mudá-Estación.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34110','iglesia','Iglesia del Salvador','Joya del románico rural de la Montaña Palentina del siglo XII erigida en excelente sillería arenisca dorada que presenta una nave única con ábside semicircular, donde sobresalen sus capiteles historiados con motivos zoomorfos y una magnífica colección de pinturas murales góticas del siglo XIV descubiertas tras el retablo mayor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34114','monumento','Núcleos de población de Olmos de Ojeda','El término municipal incluye los siguientes núcleos de población: Olmos de Ojeda, Amayuelas de de Ojeda, Moñux, Quintanatello de de Ojeda, San Pedro de de Moñux, Vega de de Bur, San Pedro de de Ojeda y Villavega de de Ojeda.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34114','iglesia','Monasterio de Santa Eufemia de Cozollos','Joya universal del románico pleno del siglo XII declarada Monumento Nacional que se asienta en un recóndito valle, cuya iglesia exenta destaca por su monumental cabecera con ábside semicircular erigido en excelente sillería arenisca dorada y por un cimborrio octogonal linterna único, albergando en su interior capiteles historiados de exquisita factura escultórica palentina.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34114','iglesia','Iglesia de San Vicente en Vega de Bur','Templo de filiación románica rural modificado en las etapas renacentista y barroca empleando piedra rústica calavera que conserva en su ábside capiteles fitomorfos de gran interés arcaizante, abriéndose su atrio tradicional hacia los valles de la comarca de la Ojeda.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34901','monumento','Núcleos de población de Osorno la Mayor','El término municipal incluye los siguientes núcleos de población: Osorno la Mayor, Las Cabañas de de Castilla, Santillana de de Campos, Villadiezma y Villodrigo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34901','iglesia','Iglesia Parroquial de la Asunción de Osorno','Templo monumental de los siglos XV y XVI de transición del gótico al renacimiento levantado en sillería caliza de Hontoria que presenta una planta basilical de tres naves con bóvedas de crucería estrellada, albergando en su presbiterio el célebre retablo mayor pictórico tardorrenacentista y una suntuosa pila bautismal románica profusamente labrada con decoración calada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34901','monumento','Yacimiento Romano de Dessobriga (Frontera Municipal)','Área arqueológica de una gran ciudad de la Edad del Hierro y campamento militar romano estabilizado que conserva estructuras residenciales, fosos defensivos excavados y cimientos perimetrales de mampostería de cuarcita y piedra rústica catalogados de alto interés científico internacional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34120','monumento','Núcleos de población de Palencia','El término municipal incluye los siguientes núcleos de población: Palencia, Paredes de Monte y Villamuriel de CerratoEstación.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34120','catedral','Catedral de San Antolín (La Bella Desconocida)','Magna catedral gótica construida principalmente entre los siglos XIV y XVI sobre vestigios visigodos y románicos empleando una suntuosa sillería caliza de Hontoria que destaca por la inmensidad de su interior de tres naves con bóvedas de crucería estrellada gótico-flamígeras, albergando en su presbiterio el fastuoso retablo mayor plateresco con esculturas de Juan de de Juni y pinturas de Juan de de Flandes, la cripta visigoda de San Antolín del siglo VII erigida con arcos de herradura de piedra rústica y el célebre trascoro tardogótico esculpido con exquisita minuciosidad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34120','iglesia','Iglesia de San Miguel','Monumental templo gótico del siglo XIII levantado en sillería caliza bien escuadrada que destaca por su imponente torre campanario de carácter defensivo calada con grandes ventanales apuntados y rematada por almenas y un chapitel calado, cuyo interior basilical conserva restos de pinturas murales góticas y un retablo renacentista de gran mérito artístico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34120','iglesia','Monasterio de San Pablo','Complejo conventual dominico de los siglos XIV a XVI cuya iglesia destaca por su majestuosa','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34120','iglesia','Iglesia de San Juan Bautista (San Juan de Baños Trasladada)','Pequeño templo románico rural del siglo XII que fue rescatado piedra a piedra de su emplazamiento original inundado y reconstruido en los jardines de la Huerta de Guadián empleando sus sillares originales areniscos, sirviendo como un hito expositivo de la arquitectura medieval de la cuenca del Carrión.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34121','monumento','Núcleos de población de Palenzuela','El término municipal incluye los siguientes núcleos de población: Palenzuela y las fincas agrícolas de la vega del Arlanza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34121','iglesia','Iglesia de San Juan Bautista','Templo monumental gótico de transición al renacimiento (siglos XV y XVI) erigido con excelente cantería caliza de las canteras locales del Cerrato que presenta una majestuosa planta basilical de tres naves separadas por pilares fasciculados, destacando exteriormente por su gran torre clasicista y sus portadas esculpidas con motivos heráldicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34121','monumento','Ruinas del Castillo de Palenzuela y Murallas','Vestigios del recinto fortificado medieval del siglo XII levantados con mampostería de caliza y mortero de cal sobre un cerro estratégico, del cual se conservan potentes lienzos de murallas almenadas y cubos defensivos angulares que atestiguan el pasado cortesano de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34123','monumento','Núcleos de población de Paredes de Nava','El término municipal incluye los siguientes núcleos de población: Paredes de Nava y las dehesas cerealistas de Tierra de Campos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34123','iglesia','Iglesia de Santa Eulalia','Joya universal de los siglos XIII al XVI declarada Monumento Nacional que combina elementos románicos, góticos, mudéjares y renacentistas en una','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34123','iglesia','Iglesia de San Martín','Templo monumental mudéjar del siglo XV reformado en el barroco utilizando una fábrica de tapial arcilloso y ladrillo macizo visto cocido que conserva su esbelta torre calada de arquerías apuntadas dobladas, hoy rehabilitado de forma vanguardista como Centro de Interpretación de la Tierra de Campos ("El Sueño de de los Berruguete").','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34123','iglesia','Iglesia de Santa María','Templo neoclásico del siglo XVIII edificado en cantería caliza calavera sobre una base gótica anterior que presenta una fachada monumental geométrica de líneas clasicistas, cuyo interior atesora un suntuoso retablo mayor ejecutado por maestros de la escuela vallisoletana y un órgano barroco histórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34124','monumento','Núcleos de población de Payo de Ojeda','El término municipal incluye los siguientes núcleos de población: Payo de Ojeda y sus fincas ganaderas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34124','iglesia','Iglesia Parroquial de las Santas Justa y Rufina','Templo rural de la comarca de la Ojeda edificado en el siglo XVII combinando muros portantes de mampostería arenisca con esquinales reforzados de sillería tosca, cuya fachada principal destaca por su robusta espadaña barroca de tres cuerpos que dota de verticalidad al perfil del atrio parroquial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34125','monumento','Núcleos de población de Pedraza de Campos','El término municipal incluye los siguientes núcleos de población: Pedraza de Campos y sus explotaciones ovinas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34125','iglesia','Iglesia de San Cipriano','Templo de traza barroca rural del siglo XVII levantado en plena Tierra de Campos empleando aparejo mixto de tapial arcilloso tradicional leones y','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34130','monumento','Núcleos de población de Piña de Campos','El término municipal incluye los siguientes núcleos de población: Piña de Campos y sus caseríos agrarios de la vega del Carrión.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34130','iglesia','Iglesia Parroquial de San Miguel','Templo monumental de transición del gótico al renacimiento (siglos XV y XVI) erigido con excelente sillería caliza de Hontoria que presenta una planta de tres naves cubiertas por bóvedas de crucería estrellada, destacando en su presbiterio un suntuoso retablo mayor renacentista y una notable colección de platería sacra custodiada en su sacristía catalogada. [1]','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34130','ermita','Ermita de la Virgen de los de la Vega','Santuario románico rural modificado profundamente en el periodo barroco utilizando aparejo mixto de mampostería y ladrillo visto, el cual conserva en su ábside rectangular capiteles fitomorfos toscos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34135','monumento','Núcleos de población de Pomar de Valdivia','El término municipal incluye los siguientes núcleos de población: Pomar de Valdivia, Báscones de de Valdivia, Camesa de de Valdivia, Helecha de de Valdivia, Lastrilla, Olleros de de Pisuerga, Quintanilla de de las Torres, Rebolledo de de la Inera, Respenda de de Aguilar, Revilla de de Pomar, Villaescusa de de Ebro, Villallano y Villarén de de Valdivia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34135','iglesia','Iglesia Rupestre de los de Santos Justo y Pastor en Olleros de Pisuerga','Obra cumbre del eremitismo rupestre altomedieval del siglo X declarada Bien de Interés Cultural, la cual está totalmente excavada de forma preindustrial sobre un gigantesco farallón rocoso de arenisca viva y presenta dos naves con bóvedas de cañón talladas, columnas exentas exculpidas en la roca, un ábside semicircular y un campanario exterior de tipo espadaña exento.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34135','monumento','Yacimiento Romano de Camesa-Rebolledo','Complejo arqueológico que alberga los restos consolidados de una gran villa romana de los siglos II al IV d.C. y una necrópolis visigoda posterior, destacando sus estructuras habitacionales perimetrales de piedra rústica, restos de pinturas murales geométricas y las canalizaciones de un sistema de calefacción por hipocausto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34135','monumento','Cueva de los de los Franceses (Revilla de Pomar)','Cavidad cárstica prehistórica vinculada a la arqueología y etnográfica local debido al hallazgo de restos arqueológicos y enterramientos de la Guerra de la Independencia, cuyo entorno paisajístico sobre el páramo de la Lora cuenta con un centro de interpretación de alta tecnología.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34136','monumento','Núcleos de población de Poza de la Vega','El término municipal incluye los siguientes núcleos de población: Poza de la Vega, San Jose de de la Vega, Villalta, Villapadierna de de la Vega y Villazan.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34136','iglesia','Iglesia Parroquial de San Lorenzo','Templo rural de la comarca de la Vega-Valdavia edificado en el siglo XVII combinando muros portantes de mampostería arenisca con esquinales reforzados de sillería caliza tosca, cuya fachada principal destaca por su robusta espadaña barroca de tres cuerpos que dota de verticalidad al perfil del atrio parroquial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34139','monumento','Núcleos de población de Prádanos de Ojeda','El término municipal incluye los siguientes núcleos de población: Prádanos de Ojeda y sus fincas ganaderas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34139','iglesia','Iglesia Parroquial de San Cristóbal','Templo románico de transición profundamente reformado en el periodo renacentista (siglo XVI) empleando aparejo calizo de las canteras de la Ojeda que mantiene su estructura de sillería bien escuadrada en la cabecera, destacando exteriormente por una monumental portada esculpida con motivos platerescos y una esbelta torre campanario de líneas clasicistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34141','monumento','Núcleos de población de Quintana del Puente','El término municipal incluye los siguientes núcleos de población: Quintana del Puente y sus caseríos agrarios de la vega del Arlanza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34141','monumento','Puente de Quintana del Puente','Estructura monumental de ingeniería civil preindustrial del siglo XVIII reedificada sobre una cimentación medieval que cruza el río Arlanza mediante dieciocho majestuosos arcos de medio punto construidos con excelente cantería caliza calavera y potentes tajamares triangulares perfectamente escuadrados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34141','iglesia','Iglesia Parroquial de San Esteban','Templo de traza barroca clasicista del siglo XVIII levantado con aparejo mixto de sillería y ladrillo visto que presenta una fachada geométrica simétrica, flanqueada por una robusta espadaña de dos ojos que dota de notable verticalidad al núcleo urbano histórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34146','monumento','Núcleos de población de Reinoso de Cerrato','El término municipal incluye los siguientes núcleos de población: Reinoso de Cerrato y sus dehesas agrícolas de los páramos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34146','iglesia','Iglesia Parroquial de San Miguel','Templo rural del Cerrato palentino edificado en el siglo XVI con estilo renacentista tardío utilizando muros portantes de mampostería caliza y cadenas de sillería fina en los esquinales, rematado en su fachada por una robusta espadaña de tres cuerpos que aloja el campanario comunal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34155','monumento','Núcleos de población de Ribas de Campos','El término municipal incluye los siguientes núcleos de población: Ribas de Campos y sus fincas de regadío.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34155','iglesia','Monasterio de Santa Cruz de Ribas','Joya del románico de transición y gótico primitivo de finales del siglo XII fundada por el rey Alfonso VIII de Castilla que destaca universalmente por su iglesia monacal, declarada Monumento Nacional, erigida con una suntuosa sillería de Hontoria calavera que conserva','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34155','monumento','BLOG VIAJE POR PALENCIA CONTORSIONISTAS DE PIEDRA','BLOG VIAJE POR PALENCIA CONTORSIONISTAS DE PIEDRA (ESPAÑA) En el interior, el templo tiene una planta dividida en tres naves y cinco tramos por pilares fasciculados, que soportan bóvedas de...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34157','monumento','Núcleos de población de Saldaña','El término municipal incluye los siguientes núcleos de población: Saldaña, Carbonera, Caserío de de Villalafuente, Membrillar, Relea de de la Loma, Renedo de de la Inera, San Martín del Obispo, Valcavadillo, Valenoso, Vega de de Doña Olimpa, Villafruela de de la Peña, Villalafuente, Villamoronta, Villán de de Tordesillas, Villasur y Villorquite de de Herrera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34157','monumento','Yacimiento de la Villa Romana de La Olmeda (Pedrosa de la Vega - Acceso Comarcal)','Extraordinario complejo residencial romano de los siglos III y IV d.C. protegido por una vanguardista estructura museística que custodia la mayor y más espectacular colección de mosaicos geométricos y figurativos polícromos del Imperio Romano en España, destacando la escena del palacio de Licomedes en Skyros y la cacería de fieras tejidas con teselas milimétricas sobre los cimientos de piedra rústica y ladrillo del hipocausto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34157','monumento','Plaza Vieja y Casco Histórico de Saldaña','Conjunto urbano de traza medieval catalogado como Conjunto HistóricoArtístico que destaca por su plaza mayor porticada del siglo XVI, cuyas viviendas tradicionales sustentadas sobre postes','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34157','monumento','Ruinas del Castillo de los Duques de del Infantado (Castillo de la Banda)','Vestigios fortificados de una fortaleza bajomedieval que corona un cerro estratégico sobre el río Carrión, erigidos con gruesos muros cortina de mampostería de canto rodado compactado con cal y sillería en los esquinales, cuyos cubos defensivos circulares flanqueaban el solar originario del linaje de los Manrique de Lara.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34157','iglesia','Iglesia de San Pedro (Museo Arqueológico de la Olmeda)','Antigua iglesia gótica de sillería caliza de Hontoria rehabilitada como espacio expositivo para albergar las valiosas piezas de ajuar, cerámicas de terra sigillata y bronces excavados en la villa romana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34159','monumento','Núcleos de población de San Cebrián de Campos','El término municipal incluye los siguientes núcleos de población: San Cebrián de Campos y Amayuelas de de Abajo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34159','iglesia','Iglesia Parroquial de San Cornelio y San Cipriano','Monumental basílica de transición del gótico al renacimiento (siglos XV y XVI) declarada Monumento Nacional que se alza con una masiva e imponente fábrica de excelente sillería caliza bien escuadrada, cuya fachada destaca por una portada plateresca de sutil ejecución y por albergar en su altar mayor un suntuoso retablo renacentista esculpido por maestros de la escuela vallisoletana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34160','monumento','Núcleos de población de San Cebrián de Mudá','El término municipal incluye los siguientes núcleos de población: San Cebrián de Mudá, Perazancas de de Ojeda, San Martín de de Perazancas y Valsadornín.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34160','iglesia','Iglesia de San Cornelio y San Cipriano (San Cebrián Capital)','Templo románico de finales del siglo XII erigido en excelente sillería arenisca dorada que destaca por conservar en su presbiterio unas valiosísimas pinturas murales góticas del siglo XIV de estilo lineal que representan escenas de la','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34181','monumento','Núcleos de población de Tariego de Cerrato','El término municipal incluye los siguientes núcleos de población: Tariego de Cerrato y las bodegas del páramo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34181','iglesia','Iglesia Parroquial de San Miguel','Templo de traza barroca clasicista del siglo XVIII erigido en sillería caliza de Hontoria sobre las laderas de un cerro testigo que destaca por su fachada austera de líneas geométricas, complementada en los alrededores por un singular conjunto de viviendas rupestres y bodegas subterráneas de alto interés etnográfico comarcal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34182','monumento','Núcleos de población de Torquemada','El término municipal incluye los siguientes núcleos de población: Torquemada y las fincas agrícolas de la vega del Pisuerga.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34182','monumento','Gran Puente de Piedra de Torquemada','Monumental estructura viaria de ingeniería civil de los siglos XVI y XVIII que cruza el río Pisuerga mediante veinticinco majestuosos arcos de medio punto y rebajados labrados en excelente cantería caliza, constituyendo uno de los puentes históricos más largos de la meseta norte y un nexo logístico fundamental en las antiguas rutas reales castellanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34182','iglesia','Iglesia de Santa Eulalia','Magna basílica gótico-renacentista del siglo XVI levantada en sillería de gran porte que presenta una planta de tres naves separadas por pilares fasciculados, cuyo presbiterio custodia un suntuoso retablo mayor ejecutado por maestros de la escuela vallisoletana y enterramientos nobiliarios blasonados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34189','monumento','Núcleos de población de Valdeolmillos','El término municipal incluye los siguientes núcleos de población: Robladillo de Ucieza, Villamuera de de la Cueza y Miñanes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34189','iglesia','Iglesia de San Julián en Robladillo de Ucieza','Templo de origen románico profundamente reformado durante el periodo barroco que destaca por sus recios muros mixtos de mampostería de canto rodado fluvial y cadenas de sillería arenisca en los esquinales, albergando en su atrio un crucero pétreo de excelente factura popular tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34023','monumento','Núcleos de población de Venta de Baños','El término municipal incluye los siguientes núcleos de población: Venta de Baños y Baños de Cerrato.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34023','iglesia','Basílica de San Juan de Baños (Baños de Cerrato)','Joya universal y obra cumbre de la arquitectura hispanovisigoda mandada erigir en el año 661 por el rey Recesvinto como exvoto por sus curaciones termales que constituye el templo religioso en pie más antiguo de toda España, levantado con una monumental sillería caliza labrada a hueso y caracterizado por su portada con arco de herradura visigodo, su iconografía de capiteles corintios paleocristianos y un ábside rectangular que cobija la histórica fuente de aguas medicinales santas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34225','monumento','Núcleos de población de Villamuriel de Cerrato','El término municipal incluye los siguientes núcleos de población: Villamuriel de Cerrato, Calabazanos y Soto de Cerrato.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34225','iglesia','Iglesia de Santa María la Mayor','Magna iglesia fortificada de transición del románico al gótico del siglo XIII declarada Monumento Nacional que perteneció a la Orden del Temple y sirvió como residencia de los obispos de Palencia, la cual destaca por su robusta torre del homenaje almenada, un monumental cimborrio octogonal de filiación aquitana erigido en sillería caliza de Hontoria y un interior de gran pureza donde resalta un coro alto mudéjar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34225','iglesia','Monasterio de Santa Clara de Calabazanos','Complejo monacal fundado en el siglo XV por el linaje de los Manrique de Lara que conserva tres claustros de diferentes etapas constructivas (gótico, renacentista y barroco), levantados con fábrica mixta de ladrillo y sillería caliza de gran valor histórico y devocional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34243','monumento','Núcleos de población de Villoldo','El término municipal incluye los siguientes núcleos de población: Villoldo, Castrillejo de de la Olra, Villanueva del Río y Villanueva de de los de Nabos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34243','iglesia','Iglesia Parroquial de San Esteban','Templo de origen gótico tardío muy reformado en las etapas moderna y barroca utilizando aparejo de tapial arcilloso tradicional y ladrillo macizo mudéjar que se estructura sobre pilares de piedra en sus naves, albergando en su presbiterio un retablo mayor barroco churrigueresco de madera noble policromada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90243','monumento','Núcleos de población de Ampuero','El término municipal incluye los siguientes núcleos de población: Ampuero, Ahedo, Bernales, Bulco, Cerbiago, Hoz de Marrón, Marrón, Udalla y La Aparecida.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90243','iglesia','Santuario de la Bien Aparecida','Célebre templo de peregrinación del siglo XVII que custodia la patrona de Cantabria, enclavado en una eminencia montañosa estratégica con muros de sillería arenisca y mampuesto, cuya arquitectura barroco-clasicista destaca por su gran retablo mayor churrigueresco labrado en madera noble policromada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90243','iglesia','Iglesia de Santa Marina de Udalla','Joya de transición del románico al gótico del siglo XIII levantada en cantería caliza bien escuadrada que presenta una planta de dos naves con bóvedas de crucería primitivas, destacando la sobriedad de sus capiteles historiados con motivos vegetales y zoomorfos arcaizantes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90244','monumento','Núcleos de población de Anievas','El término municipal incluye los siguientes núcleos de población: Barriopalacio, Cotillo, Villasuso y Calga.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90244','iglesia','Iglesia de San Andrés de Cotillo','Templo románico rural del siglo XII erigido en sillería caliza compacta que destaca por conservar su ábside semicircular con ventanas saetadas y una robusta espadaña exenta en su atrio parroquial arbolado, cuyos canecillos esculpidos bajo los aleros muestran motivos geométricos e iconográficos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90245','monumento','Núcleos de población de Arenas de Iguña','El término municipal incluye los siguientes núcleos de población: Arenas de Iguña, Bostronizo, Cohiño, Las Fraguas, Hebreros, Pedredo, San Cristóbal, San Juan de Raicedo y de Iguña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90245','ermita','Ermita de San Román de Bostronizo','Joya excepcional de la arquitectura mozárabe del siglo X declarada Monumento Nacional que se asienta en un recóndito paraje forestal, construida con una masiva fábrica de sillería arenisca labrada','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90245','iglesia','Palacio de los Hornillos e Iglesia de San Jorge (Las Fraguas)','Espectacular complejo señorial neoclásico e historicista del siglo XIX proyectado por el arquitecto Ralph Selden Wornam en estilo neopaladiano británico utilizando excelente cantería caliza bien escuadrada, cuya iglesia aneja imita la estructura de un templo griego clásico con un monumental pórtico de columnas hexástilo jónicas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90245','iglesia','Iglesia de San Juan de Raicedo','Templo románico pleno del siglo XII erigido con excelente aparejo arenisco dorado que presenta una nave única rematada en ábside semicircular, donde sobresale su portada meridional con capiteles esculpidos y una interesante colección de canecillos eróticos bajo los aleros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90246','monumento','Núcleos de población de Bárcena de Pie de Concha','El término municipal incluye los siguientes núcleos de población: Pie de Concha y Pujayo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90246','monumento','Calzada Romana del Valle del Besaya','Monumental tramo de infraestructura viaria imperial de época romana que unía Pisoraca con Portus Blendium, caracterizado por la impecable conservación de sus grandes losas de piedra caliza compactada y muros de contención laterales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90246','iglesia','Iglesia de San Cosme y San Damián (Bárcena)','Joya del románico rural del siglo XII que presenta una planta de nave única con bóveda de cañón, un ábside semicircular perfecto edificado con aparejo de sillería y una espléndida colección de canecillos historiados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90246','monumento','Conjunto Histórico de Pujayo','Núcleo urbano tradicional de alta montaña que destaca por la conservación impecable de sus casonas solariegas de los siglos XVII y XVIII, caracterizadas por sus fachadas de cantería vista con grandes portaladas y solanas de madera noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90029','monumento','Núcleos de población de Bareyo','El término municipal incluye los siguientes núcleos de población: Bareyo, Ajo y Güemes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90029','iglesia','Iglesia de Santa María de Bareyo','Obra cumbre del románico costero cántabro del siglo XII que destaca por su espectacular ábside semicircular erigido en excelente sillería arenisca, cuyo deambulatorio interior presenta arquerías polilobuladas de influencia mudéjar y una de las colecciones de capiteles historiados y pilas bautismales románicas más complejas del norte peninsular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90029','iglesia','Convento de San Ildefonso de Güemes','Complejo monacal del siglo XVII levantado con aparejo mixto de mampostería caliza y cadenas de sillería bien escuadrada en los vanos, cuyo presbiterio custodia un suntuoso retablo mayor de madera de castaño policromada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39016','monumento','Núcleos de población de Camargo','El término municipal incluye los siguientes núcleos de población: Muriedas, Cacicedo, Camargo, Escobedo, Herrera, Igollo, Maliaño y Revilla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39016','monumento','Termas Romanas de San Juan de Maliaño','Conjunto arqueológico residencial e industrial de los siglos I al IV d.C.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39016','palacio','Casona de los de Velarde en Muriedas (Museo Etnográfico)','Residencia señorial del siglo XVII levantada con aparejo mixto de sillería arenisca y mampuesto que conserva su portalón blasonado barroco y una rica balconada de forja tradicional, constituyendo un hito de la arquitectura civil palaciega costera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39018','monumento','Núcleos de población de Cartes','El término municipal incluye los siguientes núcleos de población: Cartes, Bedicó, Corral, Mercadal, Mijarojos, Riocorvo, San Miguel, Santiago de Cartes, Sierra y Yermo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39018','monumento','Torreones de Cartes','Espectacular complejo defensivo bajomedieval del siglo XV erigido por la casa de Manrique como aduana señorial que consta de dos recias torres de planta cuadrangular unidas por un gran arco apuntado central levantado en excelente cantería caliza, luciendo aspilleras defensivas y saeteras adaptadas a la artillería de la época.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39018','iglesia','Iglesia de Santa María de Yermo','Joya del románico pleno de comienzos del siglo XIII declarada Monumento Nacional construida con recia sillería arenisca dorada que destaca por su ábside semicircular con columnas adosadas y por una portada meridional de ricas arquivoltas historiadas con motivos eróticos y geométricos bajo los aleros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39018','monumento','Conjunto Histórico-Artístico de Riocorvo','Trazado urbano medieval homogéneo de los siglos XVII y XVIII compuesto por casonas montañesas de sillería fina con portalones de arco de medio punto y balconadas apaisadas de madera noble que reflejan la prosperidad caminera del valle del Besaya.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39021','monumento','Núcleos de población de Cieza','El término municipal incluye los siguientes núcleos de población: Villayuso, Villasuso y Collado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39021','monumento','Yacimiento Arqueológico del Castro de Las Rabas','Poblado fortificado de la Edad del Hierro habitado por la tribu de los cántabros que conserva lienzos de murallas defensivas de piedra rústica caliza sin argamasa y cimientos perimetrales de cabañas circulares, testigo de los enfrentamientos de las Guerras Cántabras de época romana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39024','monumento','Núcleos de población de Comillas','El término municipal incluye los siguientes núcleos de población: Comillas, La Rabia, Rioturbio, Trasvía y Ruiseñada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39024','monumento','El Capricho de Gaudí (Villa Quijano)','Obra maestra del modernismo catalán diseñada en 1883 por el célebre arquitecto Antoni Gaudí que destaca por su planta asimétrica levantada con un basamento de sillería de piedra arenisca, muros decorados con hileras de azulejos cerámicos vidriados polícromos con relieves de girasoles y una esbelta torre cilíndrica minarete revestida de cerámica y hierro forjado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39024','iglesia','Palacio de Sobrellano y Capilla-Panteón','Monumental complejo historicista y neogótico diseñado por el arquitecto Joan Martorell en el siglo XIX utilizando una suntuosa cantería caliza bien escuadrada calada con arcos apuntados, gárgolas figurativas y vidrieras historiadas, cuyo interior atesora mobiliario diseñado por Gaudí y mausoleos de mármol calizo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39024','monumento','Universidad Pontificia de Comillas','Inmenso complejo de arquitectura neogótica y mudéjar de finales del siglo XIX proyectado por Lluís Domènech i Montaner que se alza sobre una colina combinando la sillería arenisca dorada con un profuso y espectacular despliegue decorativo de ladrillo visto, azulejos polícromos y puertas monumentales de bronce esculpido.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39024','iglesia','Iglesia de San Adrián de Ruiseñada','Templo gótico tardío del siglo XV modificado en las etapas renacentista y barroca empleando aparejo calizo bien labrado que presenta una planta de tres naves separadas por pilares fasciculados, albergando en su sacristía una valiosa colección de platería sacra indiana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90030','monumento','Núcleos de población de El Astillero','El término municipal incluye los siguientes núcleos de población: Guarnizo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90030','monumento','Cargadero de Mineral de Orconera','Monumental estructura de la arqueología industrial del hierro construida a finales del siglo XIX sobre la ría que destaca por su entramado de viguerías de fundición metálica y pasarelas de madera destinadas a la estiba de los mercantes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90030','iglesia','Iglesia de San José','Templo parroquial de factura historicista y neogótica construido a principios del siglo XX que muestra una amplia nave longitudinal con arcos apuntados, una fachada principal enlucida con un gran rosetón moldurado y una esbelta aguja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39028','monumento','Núcleos de población de Entrambasaguas','El término municipal incluye los siguientes núcleos de población: Entrambasaguas, El Ansar, Hoznayo, Navajeda, Puente Agüero, Santa Marina y Termillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39028','palacio','Palacio de los Acebedo de Hoznayo','Monumental complejo palaciego de estilo renacentista herreriano de finales del siglo XVI, proyectado por orden del arzobispo de Burgos empleando excelente cantería caliza bien escuadrada, cuya fachada destaca por sus arquerías de medio punto de orden gigante flanqueadas por dos imponentes torres angulares almenadas de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39028','monumento','Puente Mayor de Puente Agüero','Estructura de ingeniería civil preindustrial del siglo XVII que salva el río Miera mediante una robusta fábrica de arcos de medio punto construidos con aparejo calizo y potentes tajamares triangulares diseñados para resistir las avenidas fluviales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39031','monumento','Núcleos de población de Hazas de Cesto','El término municipal incluye los siguientes núcleos de población: Beranga, Hazas de Cesto y Praves.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39031','palacio','Casona-Palacio de los Villa en Beranga','Residencia señorial montañesa del siglo XVII construida con una fábrica mixta de mampostería caliza y sillería fina en los esquinales que exhibe una fachada monumental flanqueada por dos torres de planta cuadrada, presidida por un escudo heráldico barroco y rodeada por una cerca de piedra con portalada de arco de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39031','iglesia','Iglesia de Santiago Apóstol en Praves','Templo de traza renacentista y barroca finalizado en el siglo XVII levantado con aparejo de cantería arenisca bien escuadrada, cuya fachada destaca por una robusta torre campanario de líneas clasicistas y un pórtico de columnas toscanas que cobija el acceso principal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39032','monumento','Núcleos de población de Hermandad de Campoo de Suso','El término municipal incluye los siguientes núcleos de población: Abajada, Argüeso, Barrio, Brañavieja, Camino, Celada de los Calderones, Entrambasaguas, Espinilla, Fontibre, Hoz de Abajada, Izara, La Lomba, Mazandrero, La Miña, Naveda, Ormas, Paracuelles, Población de Suso, Proaño, Salces, La Serna, Soto, Suano, Villacantid y Villar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39032','monumento','Castillo de San Vicente de Argüeso','Imponente fortaleza medieval de los siglos XIII y XIV emplazada sobre un cerro rocoso estratégico que consta de dos torres de planta cuadrada unidas por un cuerpo central y una muralla barbacana erigidas con mampostería caliza y sillería en los vanos, restaurado integralmente con estructuras de madera noble para albergar un centro cultural.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39032','iglesia','Iglesia de Santa María la Mayor de Villacantid','Joya del románico rural del siglo XII que destaca por su ábside semicircular levantado en excelente sillería arenisca dorada con canecillos historiados de gran finura escultórica bajo los aleros, complementada por una portada de arquivoltas apuntadas y un interior que custodia el Centro de Interpretación del Románico de Cantabria.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39032','monumento','Nacimiento del Río Ebro en Fontibre','Entorno natural y patrimonial acondicionado en torno al manantial kárstico donde afloran las aguas, presidido por una estela de piedra caliza conmemorativa y rodeado de arbolado autóctono que sacraliza geográficamente el origen del río más caudaloso de la península.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39035','monumento','Núcleos de población de Laredo','El término municipal incluye los siguientes núcleos de población: Laredo, La Arenas, Las Cárcobas, Tarrueza y Villante.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39035','iglesia','Iglesia de Santa María de la Asunción','Magna basílica gótica de los siglos XIII al XV, declarada Monumento Nacional, erigida con excelente sillería arenisca dorada en el corazón de la Puebla Vieja que destaca por su planta de cuatro naves de gran esbeltez cubiertas por bóvedas de crucería y por albergar en su interior el espectacular Retablo de la Virgen de Belén, considerado una obra cumbre de la escultura gótica flamenca en España.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39035','monumento','Puebla Vieja y Arcos de la Muralla','Trazado urbano medieval de los siglos XIII y XIV catalogado como Conjunto Histórico-Artístico que conserva notables tramos de sus muros defensivos de mampostería caliza y puertas monumentales como el Arco de San Lorenzo o el Arco de la Blanca, configurados mediante gruesos sillares escuadrados en arco apuntado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39037','monumento','Núcleos de población de Liérganes','El término municipal incluye los siguientes núcleos de población: Liérganes, Calgar, Los Prados, Rubalcaba y Rucandio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39037','monumento','Puente Mayor de Liérganes','Monumental estructura viaria preindustrial del siglo XVII proyectada por el maestro Bartolomé de Hermosa sobre el río Miera empleando excelente cantería caliza bien escuadrada en sus arcos de medio punto apoyados sobre tajamares triangulares, constituyendo un hito de la ingeniería civil que articula el casco histórico de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39037','palacio','Conjunto Palaciego y de Casonas Montañesas','Núcleo urbano tradicional que destaca por la homogeneidad de sus residencias señoriales de los siglos XVII y XVIII, tales como el Palacio de Elsedo en Pámanes o la Casa de los de Cañones, erigidas con fachadas simétricas de sillería arenisca dorada, solanas de madera noble de castaño y espectaculares escudos heráldicos labrados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39042','monumento','Núcleos de población de Medio Cudeyo','El término municipal incluye los siguientes núcleos de población: Solares, Anaz, Ceceñas, Heras, Santiago de Cudeyo, Hermosa, Overo, San Vitores, Sobremazas y Valdecilla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39042','monumento','Finca del Marqués de Valdecilla (Valdecilla)','Espectacular complejo residencial historicista y ecléctico de principios del siglo XX de arquitectura indiana que consta de varios pabellones construidos con un basamento de cantería caliza, forjados de madera noble, grandes galerías acristaladas de hierro y jardines de aclimatación botánica exótica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39042','iglesia','Iglesia de Santa María de Cudeyo en Sobremazas','Templo de traza renacentista y barroca finalizado en el siglo XVII levantado con aparejo de sillería arenisca bien escuadrada, cuya fachada destaca por una robusta torre campanario de líneas clasicistas y un interior cubierto por bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39044','monumento','Núcleos de población de Miengo','El término municipal incluye los siguientes núcleos de población: Miengo, Bárcena de de Cudeyo, Cuchía, Cudón, Mogro y Gornazo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39044','iglesia','Iglesia Parroquial de San Miguel Arcángel de Miengo','Templo barroco rural del siglo XVII edificado mediante muros de aparejo toledano mampuesto con refuerzos de sillería arenisca fina en los esquinales angulares, rematado en su fachada por una robusta espadaña bicéfala orientada hacia el estuario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39047','monumento','Núcleos de población de Noja','El término municipal incluye los siguientes núcleos de población: Noja y sus barrios históricos costeños.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39047','palacio','Palacio de Albaicín (Palacio de los de Velasco)','Monumental casona señorial de estilo ecléctico y regionalista del siglo XVIII reformada profundamente a principios del siglo XX por el arquitecto Leonardo Rucabado que destaca por su portalada monumental y sus muros de sillería arenisca dorada combinados con una imponente torre almenada y solanas tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39047','palacio','Casa-Palacio de Zilla','Residencia palaciega barroca del siglo XVII construida con excelente cantería caliza bien escuadrada','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39052','monumento','Núcleos de población de Piélagos','El término municipal incluye los siguientes núcleos de población: Renedo, Arce, Barcenilla, Carandía, Ciórraga, Quijano, Vioño, Zurita, Liencres, Mortera y Boo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39052','monumento','Puente Mayor de Arce','Monumental estructura viaria preindustrial del siglo XVI reedificada en el XVII sobre el río Pas empleando excelente cantería caliza bien escuadrada en sus cinco majestuosos arcos de medio punto protegidos por potentes tajamares triangulares, constituyendo un nexo logístico e hito de la ingeniería civil de la antigua ruta costera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39052','iglesia','Santuario de la Virgen de Valencia (Vioño)','Templo de peregrinación de traza barroca clasicista del siglo XVII erigido en sillería arenisca dorada sobre una elevación paisajística que destaca por su fachada sobria con espadaña de tres cuerpos y por albergar en su presbiterio un suntuoso retablo mayor churrigueresco labrado en madera noble policromada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39055','monumento','Núcleos de población de Potes','El término municipal incluye los siguientes núcleos de población: Potes y las dehesas históricas de Liébana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39055','monumento','Torre del Infantado','Espectacular fortaleza militar de planta cuadrangular del siglo XV vinculada al linaje de los Mendoza que destaca por su masiva e imponente fábrica de mampostería caliza y cadenas angulares de sillería fina, rematada por un adarve almenado con cuatro torrecillas esquinales apoyadas sobre ménsulas molduradas y una escalinata monumental de cantería vista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39055','iglesia','Iglesia de San Vicente','Complejo religioso gótico de los siglos XIV al XVI erigido con aparejo de mampuesto calizo y esquinales de cantería arenisca que presenta una planta de dos naves cubiertas por bóvedas de crucería sencillas, cuya sobria portada de arcos apuntados doblados comunica con el Casco Histórico de la villa de Potes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39056','monumento','Núcleos de población de Puente Viesgo','El término municipal incluye los siguientes núcleos de población: Puente Viesgo, Aes, Las Presillas y Vargas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39056','monumento','Complejo Arqueológico de las Cuevas del Monte Castillo','Conjunto de cavidades kársticas prehistóricas declaradas Patrimonio de la Humanidad por la UNESCO que custodia una de las muestras de arte rupestre paleolítico más importantes de Europa, destacando las cuevas de El Castillo y Las Monedas por sus representaciones de manos en negativo polícromas, bisontes y caballos trazados con pigmentos de óxido de hierro sobre las paredes calcáreas vivas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39056','palacio','Casona-Palacio de los de Fuentes-Pila (Ayuntamiento)','Residencia palaciega de estilo regionalista montañés de principios del siglo XX diseñada por el arquitecto Javier González de Riancho que destaca por su portalada de sillería arenisca dorada, solanas de madera de castaño labradas hacia el mediodía y un entramado decorativo tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39060','monumento','Núcleos de población de Reocín','El término municipal incluye los siguientes núcleos de población: Puente San Miguel, Barcenaciones, Caranceja, Cerrazo, Helguera, Quijas, Reocín, San Esteban, Villapresente y Valles.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39060','palacio','Palacio de la Cajiga en Quijas','Casona señorial barroca del siglo XVII construida con excelente cantería caliza bien escuadrada que presenta una fachada simétrica con una planta baja porticada de arcos de medio punto y balconadas de hierro forjado, presidida por un monumental blasón heráldico finamente tallado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39061','monumento','Núcleos de población de Ribamontán al Mar','El término municipal incluye los siguientes núcleos de población: Carriazo, Castanedo, Galizano, Langre, Loredo, Somo y Suesa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39061','iglesia','Iglesia Parroquial de Santa Eulalia de Suesa','Templo gótico tardío del siglo XV modificado profundamente en la etapa barroca del siglo XVII empleando aparejo calizo bien labrado que presenta una planta de cruz latina con bóvedas de crucería estrellada, destacando exteriormente por una robusta torre campanario de líneas clasicistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39076','monumento','Núcleos de población de Santillana del Mar','El término municipal incluye los siguientes núcleos de población: Santillana del Mar, Arroyo, Camplengo, Herrán, Mijares, Queveda, Ubiarco, Vispieres, Viveda y Yuso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39076','iglesia','Colegiata de Santa Juliana','Obra cumbre e hito absoluto del románico pleno del norte de España del siglo XII, declarada Monumento Nacional, erigida con una suntuosa sillería arenisca dorada que destaca por su majestuoso interior de tres naves con bóvedas de crucería primitivas, un cimborrio linterna octogonal exterior y un espectacular claustro reglar cuyos capiteles historiados exhiben una legendaria colección de motivos bíblicos, heráldicos y zoomorfos esculpidos con una finura técnica inigualable.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39076','monumento','Cueva de Altamira (Museo de Altamira)','Santuario universal del paleolítico superior declarado Patrimonio de la Humanidad por la UNESCO y calificado tradicionalmente como la Capilla Sixtina del arte cuaternario, cuya réplica científica ("Neocueva") conserva intactos sobre relieves calcáreos los célebres techos de bisontes polícromos grabados y pintados con carbón vegetal y ocres rojos hace más de quince mil años.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39076','monumento','Torre de Don Borja y Torre del Merino','Imponentes torres de defensa bajomedievales de los siglos XIV y XV de planta cuadrangular erigidas con recios muros de mampostería regular caliza y esquinales de cantería fina, jalonadas por ventanas ojivales con arcos apuntados, saeteras y remates almenados que delimitan la histórica Plaza Mayor de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39076','palacio','Palacio de Velarde','Residencia señorial fortificada de transición del gótico al renacimiento del siglo XVI construida en excelente sillería de cantería arenisca bien escuadrada que presenta una fachada con pináculos decorativos altos y ventanas ajimezadas, constituyendo uno de los hitos civiles de mayor pureza arquitectónica de la localidad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39091','monumento','Núcleos de población de Valdáliga','El término municipal incluye los siguientes núcleos de población: Roiz, Caviedes, Labarces, Lamadrid, San Vicente del de Monte y El Tejo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39091','palacio','Casona-Palacio de los de de la Campa en Lamadrid','Monumental casona palaciega montañesa del siglo XVIII construida con excelente sillería arenisca dorada y mampuesto que presenta una fachada monumental simétrica con arquerías de medio punto en su planta baja y una gran solana de madera de castaño flanqueada por un escudo heráldico labrado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39091','monumento','Torre de Labarces','Antigua torre de defensa bajomedieval del siglo XV de planta cuadrangular erigida con recios muros de piedra rústica caliza y esquinales de cantería fina, jalonada por estrechas ventanas ojivales y adarve almenado adaptado a la topografía de la montaña occidental.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39080','monumento','Núcleos de población de San Vicente de la Barquera','El término municipal incluye los siguientes núcleos de población: San Vicente, Abaño, El Barcenal, Gandarilla, Hortigal, Los Llaos, La Acebosa y Santillán-Boria.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39080','iglesia','Iglesia de Santa María de los Ángeles','Obra cumbre del gótico clásico del siglo XIII, declarada Monumento Nacional, erigida sobre un promontorio rocoso con una masiva y monumental sillería arenisca dorada que destaca por sus dos imponentes portadas de ricas arquivoltas historiadas con motivos geométricos y por albergar en su interior de tres naves el fastuoso sepulcro renacentista del inquisidor Antonio del de Corro tallado en finísimo mármol calizo exento.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39080','monumento','Castillo del Rey','Fortaleza defensiva medieval del siglo XII emplazada junto a la muralla sobre el peñasco costero empleando gruesos muros cortina de mampostería caliza y cal de gran dureza, cuya estructura de planta poligonal conserva su torre del homenaje almenada adaptada como centro de interpretación de la villa marinera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39080','monumento','Puente de la Maza','Monumental viaducto bajomedieval del siglo XV reedificado en el siglo XVIII por orden de los Reyes Católicos sobre la ría que cuenta con veintiocho arcos de cantería caliza de Hontoria y potentes tajamares triangulares, configurando una de las obras de ingeniería civil preindustrial más largas e imponentes del norte peninsular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90247','monumento','Núcleos de población de Aia','El término municipal incluye los siguientes núcleos de población: Aia, Altzola, Andatza, Arrutiegia, Elkano, Etxetaballa, Iruretaegia, Kurpidea, Laurgain, Olaskoegia, Santio Erreka, Urdaneta y de Aia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90247','iglesia','Iglesia de San Miguel de Aia','Templo monumental gótico tardío del siglo XV edificado en un promontorio que domina el litoral guipuzcoano empleando excelente sillería caliza bien escuadrada, cuyo interior basilical cobija bóvedas de crucería y un suntuoso retablo mayor ejecutado por maestros de la escuela vasca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90248','monumento','Núcleos de población de Aizarnazabal','El término municipal incluye los siguientes núcleos de población: Aizarnazabal, Saiatz y Zubialde.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90248','monumento','Puente de Zubialde','Estructura viaria bajomedieval del siglo XIV reedificada sobre el río Urola mediante una sólida fábrica de arcos de medio punto construidos con aparejo calizo y potentes tajamares triangulares, constituyendo un paso histórico ineludible en las antiguas rutas litorales de transporte de mineral.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90249','monumento','Núcleos de población de Albiztur','El término municipal incluye los siguientes núcleos de población: Albiztur y las explotaciones del valle del Salubilla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90249','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo monumental de traza barroca clasicista del siglo XVIII erigido en sillería de piedra arenisca bien escuadrada que presenta una fachada geométrica simétrica coronada por un frontón triangular, la cual se comunica con el núcleo de caseríos tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90250','monumento','Núcleos de población de Alegia','El término municipal incluye los siguientes núcleos de población: Alegia y sus caseríos de la ribera del Oria.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90250','monumento','Casa Consistorial de Alegia','Palacio civil barroco del siglo XVIII que presenta una fachada monumental de sillería arenisca dorada con una gran balconada de hierro forjado, rematada por un suntuoso escudo heráldico labrado con las armas de la villa y sustentada sobre una planta baja porticada con arcos rebajados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90251','monumento','Núcleos de población de Alkiza','El término municipal incluye los siguientes núcleos de población: Alkiza, Aldapa y Caseríos del Hernio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90251','iglesia','Iglesia de San Martín','Templo gótico de transición del siglo XVI edificado con muros de mampostería caliza y refuerzos angulares de sillería en los vanos primordiales, rematado en su fachada por una robusta torre campanario de líneas clasicistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20906','monumento','Núcleos de población de Altzaga','El término municipal incluye los siguientes núcleos de población: Altzaga, Altzagarate y fincas agrarias.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20906','ermita','Ermita de Nuestra Señora de Altzagarate','Santuario rural de montaña edificado en el siglo XVII utilizando aparejo mixto de mampostería caliza gris y esquinales de sillería arenisca, el cual conserva en su presbiterio una notable colección de capiteles con motivos fitomorfos toscos y una venerada imagen mariana medieval de gran devoción comarcal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90252','monumento','Núcleos de población de Altzo','El término municipal incluye los siguientes núcleos de población: Altzo Azpi y Altzo Muño.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90252','iglesia','Iglesia de San Salvador de Altzo Azpi','Templo de origen gótico medieval reedificado en el siglo XVI empleando aparejo calizo bien labrada que presenta una nave única con una robusta portada de arco apuntado, en cuyo atrio porticado tradicional de vigas de roble se reunían los infanzones de la comarca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90253','monumento','Núcleos de población de Amezketa','El término municipal incluye los siguientes núcleos de población: Amezketa, Ugarte y Caseríos del Aralar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90253','iglesia','Iglesia Parroquial de San Bartolomé','Templo gótico tardío del siglo XV modificado en la etapa barroca utilizando aparejo mixto de sillería y mampuesto calizo que destaca por albergar en su interior la célebre colección de argizaiolas tradicionales, unas tablillas de madera noble tallada con cera enrollada utilizadas de forma preindustrial para el culto a los difuntos sobre las sepulturas familiares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90254','monumento','Núcleos de población de Andoain','El término municipal incluye los siguientes núcleos de población: Andoain, Buruntza, Goiburu, Sorabilla y de Andoain.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90254','iglesia','Iglesia de San Martín de Tours','Monumental templo de traza barroca clasicista del siglo XVIII proyectado por el arquitecto Francisco de Ibero en sillería de piedra arenisca bien escuadrada que presenta una majestuosa planta de cruz latina, cuya fachada principal destaca por su gran torre campanario cupulada de influencia clasicista y un interior que cobija imaginería de gran mérito artístico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90254','palacio','Palacio de Berrozpe','Residencia señorial barroca del siglo XVII construida con excelente cantería caliza vista y mampuesto encalado que conserva un monumental portalón blasonado heráldico con las armas de los de Berrozpe y un amplio patio interior porticado con columnas toscanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90255','monumento','Núcleos de población de Antzuola','El término municipal incluye los siguientes núcleos de población: Antzuola, Basalde, Galartza, Lizargarate y Uzarraga.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90255','iglesia','Iglesia Parroquial de la Piedad','Templo monumental de los siglos XVI y XVII erigido con excelente cantería caliza gris que presenta una planta de tres naves cubiertas por bóvedas de crucería estrellada gótico-flamígeras, cuyo presbiterio custodia un suntuoso retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90255','ermita','Ermita de San Juan de Uzarraga','Pequeño templo que perteneció a la Orden de San Juan de Jerusalén levantado íntegramente con aparejo calizo rústico, considerada una de las iglesias de fundación templaria más antiguas del valle del Deba.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90256','monumento','Núcleos de población de Arama','El término municipal incluye los siguientes núcleos de población: Arama y sus caseríos cerealistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90256','iglesia','Iglesia de San Martín','Templo rural del siglo XVII levantado con aparejo mixto de mampostería caliza y cadenas angulares de sillería arenisca, cuya fachada se caracteriza por una robusta espadaña bicéfala orientada hacia la vega aluvial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21001','monumento','Núcleos de población de Aretxabaleta','El término municipal incluye los siguientes núcleos de población: Aretxabaleta, Aoiz, Areantza, Bedoña, Galartza, Goroeta, Larrino, Oro y Izurieta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21001','iglesia','Iglesia de Nuestra Señora de la Asunción','Templo monumental de los siglos XV y XVI de transición góticorenacentista levantado en sillería caliza del Duranguesado que presenta una planta basilical de tres naves con bóvedas de crucería estrellada, albergando en su presbiterio un espectacular retablo mayor pictórico tardorrenacentista y una suntuosa pila bautismal románica profusamente labrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21001','palacio','Palacio de Otalora (Izurieta)','Residencia palaciega solariega del siglo XVI levantada con aparejo mampuesto calizo y esquinales reforzados en cantería fina, cuya fachada principal exhibe un monumental portalón blasonado barroco flanqueada por herrajes de hierro forjado apoyados sobre ménsulas molduradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21002','monumento','Núcleos de población de Arrasate/Mondragón','El término municipal incluye los siguientes núcleos de población: Arrasate, Bedoña, Garagartza, Gesalibar, Udala y Musakola.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21002','iglesia','Iglesia de San Juan Bautista','Obra cumbre del gótico clásico del siglo XIV en el interior de Guipúzcoa, declarada Monumento Nacional, erigida en el corazón del casco histórico con una masiva y monumental sillería caliza gris que destaca por su imponente cabecera exenta con ventanales apuntados y un sistema de bóvedas de crucería de gran esbeltez, rematada exteriormente por una robusta torre campanario defensiva del siglo XVI.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21002','palacio','Palacio de Báñez de Artazubiaga','Espectacular edificio residencial señorial del siglo XVI que presenta una suntuosa fachada de cantería caliza bien escuadrada con plateresca molduración en sus vanos, la cual conserva sus herrajes de forja tradicionales y escudos de armas familiares catalogados de alto valor histórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90257','monumento','Núcleos de población de Asteasu','El término municipal incluye los siguientes núcleos de población: Asteasu, Elizmendi y Caseríos del Hernio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90257','iglesia','Iglesia de San Pedro de Elizmendi','Templo de origen gótico del siglo XIV modificado profundamente en la etapa barroca del siglo XVII empleando aparejo calizo de las canteras locales que mantiene su estructura de sillería bien escuadrada en la cabecera, destacando exteriormente por una monumental portada de arcos apuntados y una esbelta torre campanario de líneas clasicistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20903','monumento','Núcleos de población de Astigarraga','El término municipal incluye los siguientes núcleos de población: Astigarraga, Ergobia, Santiagomendi y Ventas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20903','palacio','Palacio de Murguía','Espectacular complejo señorial fortificado que se remonta al siglo XIV y fue profundamente reconstruido en el XVIII en estilo barroco cortesano, el cual presenta una majestuosa planta rectangular erigida en excelente sillería arenisca dorada con cadenas de cantería caliza vista y grandes escudos heráldicos labrados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20903','ermita','Ermita de Santiagomendi','Joya de la arquitectura medieval y románica de transición enclavada en una eminencia montañosa del Camino de Santiago del Interior construida con fábrica de mampostería caliza y sillería, cuyo interior custodia una valiosa colección de exvotos y restos de una necrópolis altomedieval excavada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90258','monumento','Núcleos de población de Ataun','El término municipal incluye los siguientes núcleos de población: San Martín, San Gregorio, Aia y Caseríos de Aralar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90258','iglesia','Iglesia de San Martín de Ataun','Templo monumental gótico tardío del siglo XV levantado íntegramente con excelente sillería de piedra caliza gris de montaña que presenta una majestuosa fachada occidental con portadas apuntadas profusamente esculpidas, cuyo interior basilical cobija un suntuoso retablo mayor y el célebre órgano barroco histórico fabricado en madera noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90258','monumento','Conjunto Etnográfico y de Caseríos Tradicionales (Patrimonio Etnográfico)','Núcleo de arquitectura tradicional que destaca por la conservación homogénea de sus baserris de los siglos XVII y XVIII erigidos con gruesos muros de mampostería de piedra caliza, grandes portalones de medio punto y vigas de madera noble de roble voladas, estrechamente vinculados al legado del antropólogo Joxemiel Barandiaran.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21003','monumento','Núcleos de población de Azkoitia','El término municipal incluye los siguientes núcleos de población: Azkoitia, Altzibar, Aratz-Matxinbenta, Azkarate, Elosua, Madariaga, Martirieta y Ormaiztegi.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21003','palacio','Palacio de Insausti','Espectacular edificio residencial señorial del siglo XVIII vinculado a los "Caballeritos de Azkoitia" y a la Real Sociedad Bascongada de Amigos del País que presenta una simétrica planta rectangular de sillería arenisca dorada, flanqueada por una fachada de líneas barroco-clasicistas francesas de gran elegancia arquitectónica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21003','monumento','Torre de Idiáquez (Casa-Torre Negra)','Antigua torre de defensa bajomedieval del siglo XIV levantada con potentes muros de ladrillo visto de tipología mudéjar sobre un basamento de piedra rústica caliza, cuyos vanos ajimezados y remates almenados atestiguan las encarnizadas luchas banderizas entre Oñacinos y Gamboínos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21003','iglesia','Iglesia de Santa María la Real','Magna basílica renacentista y barroca del siglo XVI erigida con aparejo calizo gris bien escuadrado que presenta un interior de proporciones monumentales cubierto por bóvedas de crucería estrellada, destacando exteriormente por su majestuosa torre campanario diseñada por Ventura Rodríguez en el siglo XVIII y por albergar en su interior un valioso órgano romántico CavailléColl.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21004','monumento','Núcleos de población de Azpeitia','El término municipal incluye los siguientes núcleos de población: Azpeitia, Loiola, Urrestilla, Nuarbe, Aratz-Matxinbenta, Eizagirre, Elosiaga, Izarraitz, Oñatz y de Azpeitia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21004','iglesia','Santuario de San Ignacio de Loyola','Obra cumbre e hito absoluto del barroco internacional churrigueresco y clasicista construida entre los siglos XVII y XVIII por el arquitecto italiano Carlo Fontana en torno a la casa-torre medieval natal del santo erigida con una suntuosa sillería caliza gris de las canteras del monte Izarraitz, cuyo conjunto destaca universalmente por su espectacular basílica de planta circular coronada por una colosal cúpula linterna de sesenta y cinco metros de altura labrada con filigranas pétreas únicas en el mundo y por una fachada monumental cóncava flanqueada por amplias escalinatas y porticados jónicos colosales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21004','iglesia','Iglesia de San Sebastián de Soreasu','Templo monumental de origen gótico reedificado profundamente en el siglo XVI bajo trazas renacentistas y neoclásicas empleando cantería de gran porte, la cual destaca por su imponente fachada con un arco de triunfo monumental diseñado por Ventura Rodríguez y por albergar en su interior la valiosa capilla gótica de los de Anchieta esculpida con un suntuoso despliegue plateresco de yeserías caladas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21004','palacio','Palacio de Antxieta','Joya de la arquitectura civil de finales del siglo XV que presenta una espectacular fachada mudéjar decorada con un intrincado paño de ladrillos calados con motivos geométricos y ventanas ojivales geminadas labradas','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48017','monumento','Núcleos de población de Bermeo','El término municipal incluye los siguientes núcleos de población: Bermeo, Almika, Arronategi, Demiku, Mañu y San Juan de Gaztelugatxe.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48017','ermita','Ermita de San Juan de Gaztelugatxe','Célebre santuario marinero de origen medieval (siglo X) emplazado de forma mística sobre un escarpado islote rocoso azotado por el mar Cantábrico y conectado a la costa mediante un monumental puente de piedra rústica ferruginosa y una escalinata de 241 peldaños serpenteantes esculpidos sobre la roca viva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48017','monumento','Torre Ercilla (Museo del Pescador)','Única torre de defensa y de carácter gótico civil que se conserva exenta en el casco urbano medieval de la villa marinera, erigida en el siglo XV con gruesos muros de mampostería regular y sillería caliza gris bien escuadrada, la cual exhibe saeteras defensivas, ventanas ajimezadas y escudos heráldicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48017','iglesia','Iglesia de Santa María de la Asunción','Templo monumental de traza neoclásica pura diseñado por el arquitecto Silvestre Pérez a principios del siglo XIX que destaca por su monumental pórtico de columnas dóricas exentas inspiradas en los templos de la antigüedad grecorromana y erigido con una masiva y excelente cantería caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48027','monumento','Núcleos de población de Durango','El término municipal incluye los siguientes núcleos de población: Durango, Santa Lucía, Orozketa y Larrinbe.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48027','iglesia','Iglesia de Santa María de Uribarri','Magna basílica gótica y renacentista de los siglos XIV al XVI erigida con excelente sillería caliza gris de las canteras del Duranguesado que','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48027','monumento','Arco de Santa Ana','Puerta monumental barroca y barrococlasicista erigida en el siglo XVIII por el arquitecto Francisco de Ibero sobre los restos de la antigua muralla medieval empleando excelente cantería caliza bien escuadrada a modo de arco de triunfo triunfal, jalonada por una balconada superior y un gran despliegue heráldico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48027','monumento','Cruz de Kurutziaga','Monumento religioso y etnográfico excepcional del siglo XV tallado en piedra arenisca fina de traza gótico-flamígera que constituye una de las cruces de término más complejas de Europa, exhibiendo una profusa iconografía que representa de forma intrincada el Pecado Original, la expulsión del Paraíso y la Pasión.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48032','monumento','Núcleos de población de Elorrio','El término municipal incluye los siguientes núcleos de población: Elorrio, Aldape, Arauna, Berrio, Lezeta, Mendraka y Miota.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48032','monumento','Necrópolis de Argiñeta','Extraordinario conjunto arqueológico altomedieval de los siglos VII y IX que se compone de una veintena de tumbas antropomorfas y estelas discoidales precristianas perfectamente talladas en piedra arenisca de Oiz, dispuestas exentas en un entorno boscoso en el atrio de la ermita de San Adrián.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48032','iglesia','Basílica de la Purísima Concepción','Templo monumental del siglo XV de estilo gótico tardío y renacentista levantado en sillería caliza gris bien escuadrada que presenta una majestuosa planta basilical de tres naves de igual altura (estilo hallenkirche) cubiertas por bóvedas de crucería estrellada gótico-flamígeras, rematada exteriormente por una esbelta torre campanario de influencia barroca barroco-clasicista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48032','palacio','Conjunto de Palacios Blasonados de Elorrio','Casco urbano histórico protegido que destaca por la homogeneidad de sus casonas señoriales y cortesanas de los siglos XVI al','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21006','monumento','Núcleos de población de Bergara','El término municipal incluye los siguientes núcleos de población: Bergara, Angiozar, Elosua, Osintxu y Ubera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21006','palacio','Palacio de Egino-Mallea','Espectacular edificio residencial señorial del siglo XVI proyectado por el arquitecto renacentista Pedro de Ibarra que presenta una suntuosa fachada de cantería caliza bien escuadrada con plateresca molduración en sus vanos y un suntuoso friso con inscripciones epigráficas humanistas de alto valor histórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21006','monumento','Real Seminario de Nobles de Bergara','Monumental complejo educativo de la Ilustración (siglo XVIII) erigido con','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21006','iglesia','Iglesia de San Pedro de Ariznoa','Magna basílica gótico tardía del siglo XV reformada en el barroco utilizando aparejo calizo gris bien escuadrado que presenta un interior de proporciones monumentales cubierto por bóvedas de crucería estrellada, albergando en su presbiterio el célebre Santo Cristo de la Agonía esculpido por el maestro Juan de Mesa en el siglo XVII.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21016','iglesia','Basílica de Santa María del Coro','Obra cumbre de la arquitectura barroca churrigueresca y barroco-clasicista del siglo XVIII erigida en el corazón de la Parte Vieja empleando excelente sillería arenisca dorada del monte Urgull, cuya fachada monumental destaca por su espectacular portadahornacina cóncava profusamente labrada flanqueada por dos imponentes torres campanario gemelas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21016','iglesia','Iglesia de San Vicente','Templo monumental del siglo XV de estilo gótico tardío edificado en sillería caliza gris bien escuadrada que presenta una planta basilical de tres naves con bóvedas de crucería estrellada gótico-flamígeras, cuyo presbiterio custodia un suntuoso retablo mayor de la escuela plateresca ejecutado por Ambrosio de Bengoechea.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21016','monumento','Castillo de la Mota y Fortificaciones del Monte Urgull','Complejo defensivo y de ingeniería militar bajomedieval modificado sustancialmente en los siglos XVIII y XIX por ingenieros reales franceses y españoles que cuenta con una robusta fortaleza de planta cuadrangular erigida con muros portantes de mampostería caliza, baluartes artilleros, polvorines y murallas adaptadas a la escarpada topografía costera que domina la bahía de la Concha.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21016','palacio','Palacio de Miramar','Espectacular residencia real de veraneo de la reina María Cristina de Habsburgo diseñada a finales del siglo XIX por el arquitecto inglés Ralph Selden Wornum en estilo historicista cottage británico empleando una suntuosa cantería arenisca dorada combinada con entramados de madera noble de roble rojos y cubiertas de mansardas de pizarra negra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21008','monumento','Núcleos de población de Eibar','El término municipal incluye los siguientes núcleos de población: Eibar, Aginaga, Arrate, Mandiola y Otaola.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21008','iglesia','Santuario de la Virgen de Arrate','Templo de peregrinación de traza gótica modificada en el periodo barroco del siglo XVII que se alza con una masiva e imponente fábrica de mampostería caliza y esquinales de sillería arenisca dorada sobre un monte estratégico, cuyo presbiterio de sillería custodia en su interior un valioso retablo barroco con pinturas renacentistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21008','iglesia','Iglesia Parroquial de San Andrés','Templo monumental de los siglos XV y XVI de transición del gótico al renacimiento levantado en cantería de gran porte que presenta una planta basilical con bóvedas de crucería estrellada, albergando en su interior un espectacular retablo mayor ejecutado por maestros de la escuela de los de de Ancheta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21008','monumento','OTRAS DISPOSICIONES 2 may 2019 — DECRETO 68/2019, de 16 de abril, por el que','OTRAS DISPOSICIONES 2 may 2019 — DECRETO 68/2019, de 16 de abril, por el que se califica como Bien Cultural, con la categoría de Conjunto Monumental, la Parte Viej...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47008','monumento','Núcleos de población de Getxo','El término municipal incluye los siguientes núcleos de población: Algorta, Las Arenas, Neguri, Romo y Andra Mari.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47008','monumento','Puente de Vizcaya (Puente Colgante - Frontera Municipal)','Obra cumbre de la arquitectura del hierro de la Revolución Industrial inaugurada en 1893 y declarada Patrimonio de la Humanidad por la UNESCO, cuyo espectacular transbordador diseñado por el ingeniero Alberto Palacio y construido en metal remachado une los muelles de sillería granítica de Getxo y Portugalete.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47008','monumento','Paseo de las Grandes Villas de Neguri (Patrimonio Arquitectónico)','Extraordinario conjunto de palacetes de principios del siglo XX de estilos ecléctico, neovasco y regionalista inglés construidos con zócalos de sillería caliza compacta, vigas de madera noble y cubiertas de pizarra','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20040','monumento','Núcleos de población de Hernani','El término municipal incluye los siguientes núcleos de población: Hernani, Ereñozu, Karabel, Martindegia y Osinaga.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20040','iglesia','Iglesia de San Juan Bautista','Templo monumental de traza renacentista y barroca del siglo XVI levantado con excelente cantería caliza gris que presenta un interior de cruz latina con un suntuoso retablo mayor churrigueresco de madera noble policromada ejecutado por Bernabé Cordero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20040','ermita','Puente y Humilladero de Santa Cruz (Ereñozu)','Estructura viaria preindustrial del siglo XVII que salva el río Urumea mediante una sólida fábrica de arcos de medio punto construidos con aparejo calizo y potentes tajamares triangulares, flanqueada por un templete etnográfico tradicional exento.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21011','monumento','Núcleos de población de Hondarribia','El término municipal incluye los siguientes núcleos de población: Hondarribia, Amute-Kosta, Arkoll, Jauriz, Montaña y Portu Auzoa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21011','palacio','Castillo de Carlos V (Palacio de los de Zuloaga)','Fortaleza y palacio fortificado señorial del siglo X profundamente reconstruido en el XVI por orden del emperador Carlos V empleando una masiva fábrica de sillería de piedra arenisca de gran dureza con adarves almenados, aspilleras defensivas y un imponente patio de armas de sillería toscana adaptado como parador nacional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21011','monumento','Recinto Amurallado y Puerta de Santa María','Imponentes lienzos de fortificación militar bajomedieval y renacentista diseñados por ingenieros reales italianos utilizando sillería caliza compacta y baluartes baluartados que rodean el casco histórico, del cual se conserva intacta la puerta monumental sur con un relieve heráldico con las armas de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21011','iglesia','Iglesia de Santa María de la Asunción y del Manzano','Magna basílica gótico-renacentista de los siglos XV y XVI erigida sobre la muralla en cantería de gran porte que presenta una planta de tres naves con bóvedas de crucería','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90259','monumento','Núcleos de población de Markina-Xemein','El término municipal incluye los siguientes núcleos de población: Markina, Xemein, Barinaga, Ilunzar, Iturreta y Larruskain.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90259','iglesia','Iglesia de Santa María de la Asunción de Xemein','Templo monumental del siglo XVI de estilo gótico renacentista columnario (estilo hallenkirche) levantado en sillería caliza bien escuadrada que presenta tres naves de igual altura cubiertas por bóvedas de crucería estrellada apoyadas sobre colosales columnas exentas, declarada Monumento Nacional junto a su singular cementerio neoclásico ilustrado exento.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90259','ermita','Ermita de San Miguel de Arretxinaga','Joya etnográfica y religiosa del siglo XVIII de planta hexagonal construida con aparejo calizo mampuesto que alberga en su interior un insólito altar natural configurado por tres gigantescas rocas de cuarcita rústica que se sostienen entre sí por equilibrio kárstico, protegiendo en su centro la talla policromada del arcángel.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48069','monumento','Núcleos de población de Mungia','El término municipal incluye los siguientes núcleos de población: Mungia, Belako, Emerando, Iturribalzaga, Larrauri, Laukariz y Markaida.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48069','palacio','Palacio de Torrebillela','Antigua torre de defensa bajomedieval del siglo XIV profundamente reconstruida en las etapas renacentista e historicista neogótica empleando una recia fábrica de mampostería regular y sillería caliza gris en','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90039','monumento','Núcleos de población de Mutriku','El término municipal incluye los siguientes núcleos de población: Mutriku, Astigarribia, Laranga, Mijoa y Olatz.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90039','iglesia','Iglesia de San Andrés de Astigarribia','Joya monumental considerada una de las iglesias más antiguas de Guipúzcoa (siglo XI) que conserva en su estructura muros de mampostería caliza con una inusual ventana de arco de herradura de filiación prerrománica o mozárabe embutida en una fábrica románica posterior de gran valor arqueológico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90039','palacio','Palacio de Galdona','Residencia palaciega barroca del siglo XVII situada en el casco histórico marinero que cuenta con una monumental fachada de cantería arenisca dorada bien escuadrada, coronada por un suntuoso blasón heráldico finamente tallado y grandes balcones apoyados sobre repisas molduradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90260','monumento','Núcleos de población de Oiartzun','El término municipal incluye los siguientes núcleos de población: Elizalde, Altzibar, Arragua, Ergoien, Itturriotz, Karrika y Ugaldetxo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90260','iglesia','Iglesia de San Esteban de Elizalde','Templo monumental gótico del siglo XVI edificado con muros portantes de mampostería caliza gris de montaña y esquinales de sillería que presenta una inmensa planta basilical con bóvedas de crucería estrellada, albergando en su presbiterio un espectacular retablo mayor barroco churrigueresco tallado en madera noble noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90260','monumento','Cromlechs de Oieleku y Kairuak (Patrimonio Arqueológico)','Conjunto arqueológico de monumentos megalíticos funerarios de la Edad del Bronce compuestos por círculos de piedras exentas de roca arenisca y cuarcita viva hincadas en la ladera montañosa de alto interés científico internacional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90261','monumento','Núcleos de población de Orozko','El término municipal incluye los siguientes núcleos de población: Zubiaur, Ibarra, San Martín, Urigoiti, Zaloa y caseríos del Gorbeia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90261','monumento','Torre de Aranguren','Robustísima torre de defensa y casafuerte señorial del siglo XVI emplazada en un bucólico valle a los pies del Parque Natural del Gorbeia que cuenta con muros portantes de mampostería caliza gris de gran espesor y esquinales de cantería fina, luciendo un portalón almenado de medio punto y saeteras defensivas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48078','monumento','Núcleos de población de Portugalete','El término municipal incluye los siguientes núcleos de población: Portugalete y los muelles de la margen izquierda.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48078','iglesia','Basílica de Santa María de Portugalete','Templo monumental de los siglos XV y XVI de estilo gótico tardío y renacentista levantado en sillería caliza compacta que domina la ría de Bilbao desde una atalaya urbana, cuya estructura presenta una planta de tres naves de gran esbeltez cubiertas por bóvedas de crucería estrellada y una robusta torre campanario de líneas clasicistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48078','monumento','Torre de Salazar','Única casa-torre medieval del siglo XV que se preserva en el casco viejo de la villa, edificada en mampostería regular y sillería arenisca con ventanas ojivales con arcos apuntados, la cual fue restaurada integralmente como espacio histórico tras los incendios de las guerras carlistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90262','monumento','Núcleos de población de Ordizia','El término municipal incluye los siguientes núcleos de población: Ordizia y las dehesas del valle del Oria.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90262','palacio','Palacio de Zabala','Residencia señorial y casona barroca del siglo XVII construida con una suntuosa fachada de excelente sillería arenisca dorada bien escuadrada que presenta balconadas de hierro forjado apoyadas sobre ménsulas molduradas y monumentales blasones heráldicos finamente tallados que delimitan la plaza histórica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21015','monumento','Núcleos de población de Pasaia','El término municipal incluye los siguientes núcleos de población: distritos de Pasai Donibane, Pasai San Pedro, Pasai Antxo y Trintxerpe.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21015','monumento','Conjunto Histórico-Marinero de Pasai Donibane (San Juan)','Trazado urbano medieval de la antigua ribera ballenera estructurado en una única calle pavimentada que discurre embutida entre los acantilados de piedra arenisca y la ría, cuyas viviendas tradicionales se sustentan sobre soportales de arcos rebajados de sillería y pasadizos cubiertos de entramados de madera preindustriales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21015','palacio','Palacio de Arizabalo','Edificio civil barroco del siglo XVIII situado en el distrito de Donibane erigido con una excelente cantería caliza gris que exhibe una fachada simétrica coronada por un suntuoso blasón heráldico moldurado y grandes balcones apoyados sobre ménsulas pétreas, hoy restaurado como consistorio municipal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20067','monumento','Núcleos de población de Errenteria','El término municipal incluye los siguientes núcleos de población: Errenteria, Beraun, Ergoien, Fanderia, Pontika y Zamalbide.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20067','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo monumental gótico tardío del siglo XVI edificado con muros portantes de mampostería caliza gris de montaña y esquinales de sillería que presenta una inmensa planta basilical columnaria con bóvedas de crucería estrellada, albergando en su presbiterio un espectacular retablo mayor barroco churrigueresco tallado en madera noble y una notable colección de platería sacra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48074','monumento','Núcleos de población de Urduña/Orduña','El término municipal incluye los siguientes núcleos de población: Urduña, Belandia, Lendoño de de Abajo, Lendoño de de Arriba y Mendeika.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48074','palacio','Palacio de la Antigua Aduana Real','Monumental edificio civil de traza neoclásica pura diseñado a finales del siglo XVIII por orden de la corona borbónica empleando una suntuosa cantería caliza gris bien escuadrada, cuya fachada monumental simétrica destaca por sus pilastras jónicas y por albergar un suntuoso patio interior porticado con columnas toscanas destinado históricamente al control foral de mercaderías.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48074','iglesia','Iglesia Parroquial de Santa María','Magna basílica gótica del siglo XIV embutida en el recinto fortificado medieval de la villa que presenta una robusta fisonomía exterior de muralla defensiva erigida con aparejo regular calizo, destacando su espectacular ábside circular jalonado por un adarve de ronda','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48074','monumento','Plaza Foral y Calles Soportandadas','Trazado urbano medieval protegido compuesto por casonas y palacios de los siglos XVI al XVIII, tales como el Palacio de Ortés de de Velasco, erigidos con sillería de gran porte sobre amplios soportales de arcos rebajados y pies derechos de madera de roble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20071','monumento','Núcleos de población de Tolosa','El término municipal incluye los siguientes núcleos de población: Tolosa, Aldaba, Bedaio, Urkizu y de Tolosa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20071','iglesia','Iglesia de Santa María','Obra cumbre del gótico columnario vasco de los siglos XVI y XVII levantada en excelente cantería caliza gris de montaña que destaca por las monumentales proporciones de su interior de tres naves de gran esbeltez cubiertas por bóvedas de crucería estrellada apoyadas sobre colosales columnas exentas, rematada exteriormente por una majestuosa fachada barroca de líneas clasicistas diseñada por Martín de de Zaldua.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20071','palacio','Palacio de Idiáquez','Espectacular edificio residencial señorial del siglo XVII que presenta una suntuosa fachada de cantería arenisca dorada bien escuadrada con plateresca molduración en sus vanos, la cual conserva sus herrajes de forja tradicionales y escudos de armas familiares catalogados de alto valor histórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20071','monumento','Puente de Naparratxo (Puente de Navarra)','Estructura de ingeniería civil preindustrial del siglo XIV que salva el río Oria mediante una sólida fábrica de arcos de medio punto construidos con aparejo calizo y potentes tajamares triangulares diseñados para resistir las avenidas fluviales, enclavado en el casco histórico de la villa foral.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21018','monumento','Núcleos de población de Zarautz','El término municipal incluye los siguientes núcleos de población: Zarautz, Talaimendi, Urteta y Elkano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21018','palacio','Palacio de Narros','Monumental palacio solariego fortificado del siglo XVI erigido frente a la playa con una excelente cantería caliza vista y mampuesto pizarroso encalado que presenta una majestuosa planta en L con una robusta torre angular almenada de herencia bajomedieval, el cual conserva sus herrajes de forja tradicionales y un monumental escudo heráldico labrado en su cuerpo central donde reza la histórica divisa familiar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21018','monumento','Torre Luzea','Joya de la arquitectura del gótico civil del siglo XV embutida en el casco histórico medieval que presenta una recia planta cuadrangular levantada con aparejo regular arenisco y cadenas angulares de sillería bien escuadrada, la cual destaca por sus ventanas ajimezadas labradas en','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21018','iglesia','Iglesia de Santa María la Real y Yacimiento Arqueológico','Complejo gótico-renacentista del siglo XVI edificado en sillería arenisca dorada que alberga en su subsuelo una de las estaciones arqueológicas medievales más complejas del litoral vasco, conservando los cimientos de piedra rústica de una necrópolis altomedieval y restos de estructuras de poblamiento romano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21019','monumento','Núcleos de población de Zumaia','El término municipal incluye los siguientes núcleos de población: Zumaia, Artadi, Narrondo y Oikia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21019','iglesia','Iglesia de San Pedro','Magna iglesia fortificada gótica del siglo XIV declarada Monumento Nacional que domina el litoral costero desde un promontorio urbano, erigida con una masiva y recia sillería caliza gris de montaña que destaca exteriormente por su aspecto inexpugnable de torre fortificada, albergando en su interior de nave única un suntuoso retablo mayor de la escuela plateresca ejecutado por el maestro Juan de de Ancheta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21019','palacio','Palacio de Foronda','Espectacular residencia palaciega historicista y ecléctica de principios del siglo XX diseñada por el arquitecto Juan José Gorosabel empleando una suntuosa cantería caliza combinada con torreones almenados de influencia neogótica, el cual se halla inmerso en una extensa dehesa costera que domina los acantilados geológicos del flysch.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21019','monumento','La Comunidad Foral de Navarra, para abrir la cabecera del Pirineo y la cuenca del Ebro','La Comunidad Foral de Navarra, para abrir la cabecera del Pirineo y la cuenca del Ebro (iniciando por la letra A con municipios como Agoitz/Aoiz, Alsasua o Abárzuza).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50002','monumento','Núcleos de población de Amurrio','El término municipal incluye los siguientes núcleos de población: Amurrio, Alardardo, Astobiza, Baranbio, Delika, Larrinbe, Lekamaña, Lezama, Saratxo y Tartanga.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50002','palacio','Palacio de Larrako (Amurrio Capital)','Residencia señorial y palaciega de los siglos XVI y XVII construida con una suntuosa fachada de excelente sillería arenisca que presenta balconadas de hierro forjado apoyadas sobre ménsulas molduradas y un monumental escudo heráldico labrado en su cuerpo central, flanqueada por ventanas saetadas herederas de las antiguas casas-fuerte banderizas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50002','iglesia','Iglesia de Santa María de Amurrio','Templo gótico tardío del siglo XV modificado en la etapa barroca utilizando aparejo mixto de sillería caliza y mampuesto que destaca por su amplio pórtico asambleario de vigas de madera noble de roble y por albergar en su presbiterio un valioso retablo mayor plateresco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50002','monumento','Cascada de Delika e infraestructuras del Salto del Nervión (Patrimonio Etnográfico)','Entorno de alta montaña caliza que conserva antiguas loberas preindustriales compuestas por empalizadas de piedra rústica dispuestas en embudo sobre el desfiladero para la caza histórica del lobo, constituyendo un hito etnográfico de gran interés antropológico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01049','monumento','Núcleos de población de Añana','El término municipal incluye los siguientes núcleos de población: Salinas de Añana y Atiega.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01049','monumento','Valle Salado de Añana (Patrimonio Mundial de la UNESCO)','Extraordinario complejo arqueológico e industrial hidráulico con más de siete mil años de explotación ininterrumpida que se compone de una intrincada red preindustrial de miles de plataformas de evaporación de salmuera escalonadas sobre palafitos construidos con entramados de madera de pino y roble y muros de piedra seca caliza, alimentados de forma perenne por canales de agua salada (veneros) labrados en troncos de árbol exentos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01049','iglesia','Convento de San Juan de Acre','Complejo monacal fundado en el siglo XII por la Orden de los Caballeros Hospitalarios que conserva lienzos de muros de sillería caliza calavera y una portada de transición al gótico con arquivoltas ojivales, sirviendo históricamente como hospital asistencial para los peregrinos del Camino de Santiago del Interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01049','iglesia','Iglesia Parroquial de Santa María de las Vilas','Templo de origen gótico medieval reedificado en el siglo XVI empleando aparejo calizo bien labrado que presenta una nave única sobreelevada con contrafuertes monumentales, cuyo presbiterio custodia un suntuoso retablo mayor pictórico tardorrenacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90263','monumento','Núcleos de población de Aramaio','El término municipal incluye los siguientes núcleos de población: Ibarra, Azkoaga, Barajuen, Etxaguen, Ganzaga, Gureia, Olaeta, Uribarri y Untzilla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90263','iglesia','Iglesia de San Martín de Barajuen','Templo de origen gótico tardío del siglo XV profundamente modificado en el periodo barroco (siglo XVII) utilizando aparejo calizo gris de montaña que mantiene su cabecera rectangular primitiva y un pórtico delantero de madera noble de castaño para cobijo de las asambleas vecinales de la Hermandad de Aramayona.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90263','monumento','Caserío Iturriotz (Patrimonio Etnográfico)','Excepcional ejemplo de arquitectura tradicional (baserri) del siglo XVII construido con gruesos muros portantes de mampostería caliza, un monumental portalón de medio punto y un entramado de madera de roble visto en su fachada superior adaptado a la ganadería de montaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90264','monumento','Núcleos de población de Armiñón','El término municipal incluye los siguientes núcleos de población: Armiñón, Estavillo y Lacervilla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90264','monumento','Puente Medieval sobre el río Zadorra (Armiñón)','Monumental paso viario bajomedieval del siglo XIV reedificado sobre cimentaciones romanas mediante una sólida fábrica de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90264','iglesia','Iglesia de San Martín de Estavillo','Templo monumental gótico del siglo XV edificado en un promontorio que domina la cuenca fluvial empleando excelente cantería caliza bien escuadrada, cuyo interior de nave única cobija bóvedas de crucería estrellada y un suntuoso retablo mayor de la escuela clasicista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50004','monumento','Núcleos de población de Arraia-Maeztu','El término municipal incluye los siguientes núcleos de población: Maeztu, Apellániz, Atauri, Azáceta, Cicujano, Corres, Elorza, Igoroin, Musitu, Onraita, Sabando y Virgala Mayor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50004','iglesia','Iglesia de la Asunción de Nuestra Señora en Apellániz','Templo románico de transición profundamente reformado en el periodo renacentista (siglo XVI) empleando aparejo calizo de las canteras locales que mantiene su estructura de sillería bien escuadrada en la cabecera, destacando exteriormente por una monumental portada de arcos apuntados y una esbelta torre campanario de líneas clasicistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50004','iglesia','Ruinas del Castillo de Corres e Iglesia de San Esteban','Vestigios de un recinto fortificado altomedieval emplazado sobre un escarpado risco calizo del Parque Natural de Izki erigidos con mampostería caliza y cal, de los cuales se conservan notables fragmentos de lienzos de murallas y cubos defensivos angulares destinados al control foral de los valles de la Montaña Alavesa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50005','monumento','Núcleos de población de Arratzua-Ubarrundia','El término municipal incluye los siguientes núcleos de población: Durana, Arzubiaga, Betolaza, Ciriano, Landa, Luko, Mendívil, Nanclares de de Gamboa, Ullíbarri-Gamboa y Zurbano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50005','palacio','Palacio de los Otalora-Guevara en Zurbano','Espectacular palacio solariego barroco del siglo XVII que cuenta con una suntuosa fachada de excelente sillería arenisca dorada bien escuadrada que presenta balconadas de hierro forjado apoyadas sobre ménsulas molduradas y monumentales blasones heráldicos finamente tallados que delimitan la plaza histórica del concejo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50005','monumento','Puente de Luko','Estructura de ingeniería civil preindustrial del siglo XVI que salva el curso del río Zadorra mediante una sólida fábrica de arcos de medio punto construidos con aparejo calizo y potentes tajamares triangulares diseñados para resistir las avenidas fluviales, enclavado en las rutas camineras de la Llanada Alavesa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50007','monumento','Núcleos de población de Asparrena','El término municipal incluye los siguientes núcleos de población: Araia, Albéniz, Ametzaga, Andoin, Arriola, Egino, Gordoa, Ibarguren, Ilarduia y Urabain.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50007','ermita','Cueva y Ermita Rupestre de San Román de Egino','Joya del eremitismo rupestre altomedieval excavada de forma preindustrial de manera directa sobre un descomunal farallón rocoso calizo del macizo de Aizkorri, la cual cuenta con un ábside semicircular tallado y una necrópolis de tumbas antropomorfas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50007','iglesia','Iglesia de San Juan Bautista de Albéniz','Templo monumental de los siglos XV y XVI erigido con excelente cantería caliza gris que presenta una planta de naves cubiertas por bóvedas de crucería estrellada góticoflamígeras, cuyo presbiterio custodia un suntuoso retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50008','monumento','Núcleos de población de Ayala/Aiara','El término municipal incluye los siguientes núcleos de población: Respaldiza, Aguiñiga, Añes, Costera, Llanteno, Luiaondo, Madaria, Maroño, Menagarai, Murga, Olabezar, Quejana y Salmantón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50008','palacio','Conjunto Monumental de Quejana (Palacio de los de Ayala)','Magna joya arquitectónica e histórica de los siglos XIV y XV declarada Monumento Nacional que consta del palacio fortificado de los señores de Ayala erigido con una masiva fábrica de sillería y mampuesto calizo, la torre-capilla de la Virgen del Cabello de planta cuadrangular almenada medieval y el convento de las Madres Dominicas que custodia en su iglesia los monumentales sepulcros civiles del canciller Pedro López de Ayala y su esposa tallados en mármol de alabastro calizo con exquisita minuciosidad escultórica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50008','monumento','Torre de Murga','Palacio fortificado y torre de defensa del gótico civil del siglo XV embutida en una dehesa del río Altube que presenta una recia planta cuadrangular levantada con aparejo regular arenisco y cadenas angulares de sillería bien escuadrada, la cual destaca por sus ventanas ajimezadas labradas en tracería calada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50012','monumento','Núcleos de población de Campezo/Kanpezu','El término municipal incluye los siguientes núcleos de población: Santa Cruz de Campezo, Antoñana, Bujanda, Oteo y Orbiso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50012','monumento','Casco Histórico y Recinto Amurallado de Antoñana','Conjunto urbano de traza medieval fortificada del siglo XII catalogado como Bien de Interés Cultural que destaca por la homogeneidad de sus casonas de piedra rústica cuarcítica integradas en la propia muralla defensiva, la cual conserva ventanas saetadas y tres puertas monumentales en arco apuntado con dovelas de sillería caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50012','iglesia','Iglesia de la Asunción de Nuestra Señora (Santa Cruz)','Templo monumental gótico del siglo XIV edificado en cantería de gran porte que presenta una planta basilical de cruz latina con bóvedas de crucería estrellada, complementada exteriormente por una esbelta torre campanario de líneas clasicistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01022','monumento','Núcleos de población de Elciego','El término municipal incluye los siguientes núcleos de población: Elciego y sus dehesas de viñedo de la Rioja Alavesa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01022','iglesia','Iglesia Parroquial de San Andrés','Magna basílica del siglo XVI de transición gótico-renacentista levantada con aparejo de sillería arenisca dorada bien escuadrada que presenta un interior de proporciones monumentales cubierto por bóvedas de crucería estrellada flamígeras, destacando exteriormente por sus dos esbeltas torres campanario asimétricas y una fachada clasicista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01022','monumento','Bodegas Marqués de Riscal (Patrimonio Arquitectónico e Industrial)','Espectacular e inconclusa obra vanguardista del siglo XXI diseñada por el arquitecto Frank Gehry que destaca por el uso pionero de láminas de titanio de coloraciones rosa, oro y plata que imitan los tonos del vino sobre una estructura de hormigón armado y zócalos de sillería caliza compacta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01023','monumento','Núcleos de población de Elvillar/Bilar','El término municipal incluye los siguientes núcleos de población: Elvillar y los caseríos agrarios del valle.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01023','monumento','Dolmen de la Chabola de la Hechicera','Monumento megalítico prehistórico del III milenio a.C. considerado una de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01023','iglesia','Iglesia de Nuestra Señora de la Asunción','Templo monumental del siglo XVI erigido con excelente cantería arenisca que presenta una planta de naves cubiertas por bóvedas de crucería, cuyo altar mayor custodia un retablo churrigueresco labrado por maestros de la escuela castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01901','monumento','Núcleos de población de Iruña Oka/Iruña de Oca','El término municipal incluye los siguientes núcleos de población: Nanclares de la Oca, Montevite, Ollávarre, Montevite y Víllodas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01901','monumento','Yacimiento Arqueológico de Veleia (Iruña-Veleia)','Extraordinario complejo residencial y militar fortificado romano de los siglos I al V d.C. que conserva el recinto amurallado bajoimperial levantado con gruesos muros de mampostería y sillería caliza compactada, jalonado por torres defensivas semicirculares, pavimentos de mosaicos y calzadas que constituyeron un hito de la vía Ab Asturica Burdigalam.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01901','monumento','Puente Medieval de Víllodas','Estructura viaria bajomedieval que cruza el río Zadorra mediante una sólida fábrica de diez arcos de medio punto construidos con aparejo caliza calavera y potentes tajamares triangulares diseñados para resistir las avenidas fluviales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01028','monumento','Núcleos de población de Labastida/Bastida','El término municipal incluye los siguientes núcleos de población: Labastida y Salinillas de Buradón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01028','palacio','Casco Histórico Portalado de Labastida y Palacios Blasonados','Trazado urbano medieval de la Rioja Alavesa que destaca por sus calles protegidas de los siglos XVI al XVIII, jalonadas por las puertas monumentales del Arco de Toloño y el Arco de Larrazuria construidas con sillares','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01028','iglesia','Iglesia de Nuestra Señora de la Asunción','Magna basílica renacentista y barroca del siglo XVI erigida con aparejo arenisco bien escuadrado que presenta un interior cubierto por bóvedas de crucería estrellada, destacando exteriormente por su portada-retablo churrigueresca profusamente labrada y un suntuoso coro alto de madera noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01031','monumento','Núcleos de población de Laguardia','El término municipal incluye los siguientes núcleos de población: Laguardia, Páganos, Laserna y El Campillar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01031','iglesia','Iglesia de Santa María de los Reyes','Obra cumbre e hito absoluto del gótico clásico y flamígero de los siglos XIV y XV que destaca universalmente por su espectacular pórtico interior labrado en sillería caliza, el cual se conserva intacto con su policromía original del siglo XVII gracias al abrigo del atrio de piedra, exhibiendo la representación de los apóstoles y la vida de la Virgen con una finura técnica inigualable.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01031','monumento','Casco Viejo Murado y Puertas de Laguardia','Imponente recinto fortificado del siglo XIII mandado erigir por el rey Sancho el Fuerte de Navarra utilizando mampostería regular caliza y cal, del cual se conservan sus cinco puertas monumentales (San Juan, Santa Engracia, Mercadal, Páganos y Carnicerías) con arcos apuntados intactos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01031','iglesia','Iglesia de San Juan Bautista','Templo monumental gótico de transición del siglo XIV edificado en cantería bien escuadrada que destaca por su portada meridional gótica y por su esbelta torre campanario exenta de carácter defensivo adaptada al relieve de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01031','monumento','Poblado de la Hoya','Área arqueológica consolidad de la Edad del Bronce y del Hierro que conserva las tramas de calles pavimentadas con cantos rodados, los zócalos de mampostería de pizarra rústica de las antiguas viviendas y un pabellón de interpretación de alta tecnología científica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50031','monumento','Núcleos de población de Oyón-Oion','El término municipal incluye los siguientes núcleos de población: Oyón, Barriobusto y Labraza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50031','monumento','Recinto Fortificado de la Villa de Labraza','Espectacular núcleo medieval de montaña catalogado por el Círculo de Ciudades Amuralladas que conserva intacto su adarve fortificado del siglo XII con torreones almenados de mampostería caliza, pasadizos cubiertos de entramados de madera preindustriales y pasarelas de ronda integradas en la topografía.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50031','iglesia','Iglesia Parroquial de Santa María de Oyón','Templo barroco del siglo XVIII levantado en excelente sillería arenisca dorada que destaca exteriormente por su majestuosa fachada plateresca y su esbelta torre-campanario apodada "El Giraldón" por el autómata de veleta que corona su chapitel.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50035','monumento','Núcleos de población de Agurain/Salvatierra','El término municipal incluye los siguientes núcleos de población: Salvatierra, Alangua, Arrizala, Eguileor, Iturrieta, Opacua y Sallurtegui.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50035','monumento','Casco Histórico Medieval y Soportales de Agurain','Trazado de tres calles paralelas flanqueadas por murallas bajomedievales que destaca por las iglesias fortificadas de Santa María y San Juan, erigidas en los siglos XIV y XV con excelente sillería caliza calavera y bóvedas de crucería estrellada, comunicadas por calles con soportales sustentados sobre pilares exentos de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50035','monumento','Dolmen de Sorginetxe (Arrizala)','Monumental monumento megalítico del neolítico levantado en medio de las praderías con losas exentas de arenisca calcárea de gran tonelaje, configurando uno de los hitos etnográficos e históricos más fotografiados de la Llanada Alavesa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50039','monumento','Núcleos de población de Vitoria-Gasteiz','El término municipal incluye los siguientes núcleos de población: Vitoria-Gasteiz, Aberásturi, Ali, Amarita, Aránguiz, Argandoña, Ariñez, Arkaia, Berrosteguieta, Castillo, Elorriaga, Foronda, Gámiz, Gamarra, Gobeo, Ilárraza, Lasarte, Lopidana, Matauco, Mendoza, Miñano, Monasterioguren, Oreitias, Otazu, Retana, Villafranca y de Vitoria.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50039','catedral','Catedral de Santa María (Catedral Vieja)','Magna catedral gótica construida principalmente entre los siglos XIII y XIV embutida en la propia muralla defensiva del casco viejo medieval que destaca por su colosal pórtico gótico polícromo labrado en sillería caliza calavera y por su pionero programa de restauración arqueológica ("Abierto por por Obras"), cuyo interior de tres naves de gran esbeltez se sustenta sobre un','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50039','monumento','Muralla Medieval de Vitoria','Recinto fortificado del siglo XI mandado erigir por el rey Sancho el Sabio de Navarra levantado con potentes muros de mampostería de cuarcita, caliza y cal de gran espesor que rodean el casco histórico en forma de almendra, jalonado por torres defensivas exentas y recuperado como espacio paisajístico y arqueológico de alto interés internacional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50039','palacio','Palacio de Bendaña y Palacio de Escoriaza-Esquíbel','Monumentales complejos residenciales renacentistas y platerescos del siglo XVI construidos con excelente cantería caliza bien escuadrada, destacando el de Escoriaza-Esquíbel por su espectacular patio interior porticado con arquerías altas y el de Bendaña por su torreón medieval exento que custodia el Museo Fournier de Naipes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50039','monumento','Plaza de España o Plaza Nueva','Colosal espacio civil de traza neoclásica pura diseñado a finales del siglo XVIII por el arquitecto Justo Antonio de de Olaguíbel empleando una excelente sillería caliza para salvar los desniveles urbanos del casco medieval, configurado mediante cuatro fachadas simétricas idénticas sustentadas sobre soportales de arcos de medio punto y pilastras toscanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50039','iglesia','Iglesia de San Miguel Arcángel','Templo gótico de transición de los siglos XIV al XVI edificado con aparejo calizo enclavado sobre la muralla medieval que destaca por presidir la Plaza de la Virgen Blanca mediante su hornacina exterior exenta y por albergar en su presbiterio un suntuoso retablo mayor ejecutado por el maestro Gregorio Fernández en el siglo XVII.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50039','monumento','Castilla y León','León, Palencia y Burgos cerradas (y el resto de provincias listas).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50039','monumento','Cantabria','100% Completada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50039','monumento','Asturias','100% Completada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50039','monumento','País Vasco','100% Completado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90265','monumento','Núcleos de población de Agoncillo','El término municipal incluye los siguientes núcleos de población: Agoncillo, Recajo y San Martín de de de Berberana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90265','monumento','Castillo de Aguas Mansas','Espectacular palacio fortificado y fortaleza militar del siglo XIV vinculado al linaje de los Medrano que destaca por su masiva e imponente planta cuadrangular erigida en sillería caliza compacta y mampuesto, configurando uno de los conjuntos fortificados civiles mejor conservados de La Rioja al mantener intactas sus cuatro robustas torres angulares almenadas medievales, sus fosos y los adarves de ronda adaptados como espacio institucional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90266','monumento','Núcleos de población de Aguilar del Río Alhama','El término municipal incluye los siguientes núcleos de población: Aguilar, Inestrillas y el yacimiento arqueológico de Contrebia Leucade.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90266','monumento','Yacimiento de la Ciudad Celtíbera y Romana de Contrebia Leucade','Extraordinario complejo arqueológico y residencial fortificado de los siglos III a.C. al IV d.C. que conserva un imponente foso defensivo excavado de forma directa sobre la roca viva arenisca, murallas bajoimperiales levantadas con gruesos muros de mampostería, viviendas rupestres','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90266','monumento','Barrio de Viviendas Rupestres de Inestrillas (Patrimonio Etnográfico)','Conjunto etnográfico preindustrial compuesto por decenas de cuevas y viviendas rupestres excavadas directamente sobre los acantilados arcillo-calcáreos que bordean el río Alhama, cuyas fachadas tradicionales de mampostería y adobe configuran un paisaje cultural de alto interés antropológico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90267','monumento','Núcleos de población de Albelda de Iregua','El término municipal incluye los siguientes núcleos de población: Albelda y las ruinas del Monasterio de San Martín.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90267','iglesia','Ruinas de las Cuevas del Monasterio de San Martín de Albelda','Vestigios eremíticos y arqueológicos altomedievales (siglo X) excavados en los escarpados farallones de conglomerado arcilloso sobre el río Iregua, célebres en la historia de la minería de las letras por haber sido el escritorio preindustrial donde se redactó el monumental Códice Vigilano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90268','monumento','Núcleos de población de Alberite','El término municipal incluye los siguientes núcleos de población: Alberite y las fincas agrícolas de la comarca de Logroño.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90268','iglesia','Iglesia Parroquial de San Martín','Templo monumental gótico tardío del siglo XVI modificado en la etapa barroca utilizando aparejo mixto de sillería arenisca y mampuesto que destaca por su portada meridional de arcos apuntados y por albergar en su presbiterio un espectacular retablo mayor romanista ejecutado por maestros de la escuela castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90269','monumento','Núcleos de población de Alfaro','El término municipal incluye los siguientes núcleos de población: Alfaro y el paraje del del de Bocal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90269','iglesia','Colegiata de San Miguel Arcángel','Magna basílica del siglo XVII de estilo barroco clasicista de la Ribera levantada','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90269','palacio','Palacio de los de Abaurrea / Casa de las de las de Cadenas','Espectacular palacio civil barroco del siglo XVIII que presenta una fachada con balconadas de hierro forjado apoyadas sobre ménsulas molduradas y monumentales blasones de armas familiares, rematada por un alero de madera de roble profusamente labrado de sutil ejecución arquitectónica cortesana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90270','monumento','Núcleos de población de Anguiano','El término municipal incluye los siguientes núcleos de población: Anguiano, las Cuevas y el Monasterio de Valvanera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90270','iglesia','Monasterio de Nuestra Señora de Valvanera','Cenobio benedictino de origen altomedieval enclavado de forma mística en un recóndito y umbrío valle calizo de la Sierra de la Demanda que destaca por su iglesia monacal exenta erigida con una recia fábrica de sillería, cuyo altar mayor custodia la venerada e histórica talla gótica de la patrona de La Rioja rodeada de un entorno de bosques autóctonos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90270','monumento','Puente de Madre de Dios','Estructura de ingeniería civil preindustrial del siglo XVIII que salva el curso del río Najerilla mediante una sólida fábrica de un solo arco de medio punto de treinta metros de luz construido con excelente sillería de piedra calcárea, suspendido a gran altura sobre un desfiladero rocoso natural.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90271','monumento','Núcleos de población de Arnedo','El término municipal incluye los siguientes núcleos de población: Arnedo, las cuevas de los de los de Moros y el despoblado de Turruncún.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90271','monumento','Cueva de los Cien Pilares (Patrimonio Etnográfico)','Extraordinario complejo arqueológico y rupestre altomedieval excavado en los escarpados cerros arcillosos que dominan la ciudad, el cual se compone de un intrincado laberinto preindustrial de decenas de estancias señoriales rupestres superpuestas conectadas por galerías y sustentadas por columnas excavadas en la roca viva destinados a usos monásticos y de vivienda defensiva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90271','monumento','Castillo-Fortaleza de Arnedo','Ruinas de la fortaleza militar y fortificada de origen musulmán (siglo IX) reconstruida en la Baja Edad Media con muros de mampostería de cantos rodados compactados, cal y canto y sillería en los esquinales angulares sobre una loma estratégica que controla el valle del río Cidacos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23001','monumento','Núcleos de población de Aínsa-Sobrarbe','El término municipal incluye los siguientes núcleos de población: localidades de Aínsa, Arcusa, Boltaña-Muga, Castejón de de Sobrarbe, Coscojuela de de Sobrarbe, Guaso, Lamiña, Paúles de de Sarsa, Santa María de de Buil, Sarsa de de Surta y Arro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23001','monumento','Casco Histórico Medieval y Plaza Mayor de Aínsa','Obra cumbre e hito absoluto del urbanismo fortificado bajomedieval de la península (siglos XII al XIV) catalogado como Conjunto Histórico-Artístico que destaca por la conservación homogénea de sus calles empedradas flanqueadas por casonas de piedra rústica con portalones de medio punto con dovelas de sillería caliza compacta, pasadizos cubiertos de entramados de madera de roble preindustriales y una espectacular plaza porticada con arquerías de medio punto y ojivales únicas en el Pirineo aragonés.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23001','monumento','Castillo-Fortaleza de Aínsa','Imponente recinto fortificado militar que se remonta al siglo XI y fue profundamente ampliado en el XVI por orden del ingeniero real Tiburcio Spanochi empleando una masiva fábrica de sillería y mampuesto calizo, el cual conserva sus murallas perimetrales con camino de ronda, baluartes abaluartados, un foso perimetral exento y una espectacular torre del homenaje de planta cuadrangular adaptada como espacio museístico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23001','iglesia','Iglesia de Santa María','Magna basílica románica de comienzos del siglo XII que presenta una majestuosa fisonomía exterior de fortaleza militar con su recia y robusta torre campanario almenada que servía de vigía y bastión, cuyo interior de nave única cubierta por una bóveda de cañón apuntada dota de gran misticismo al conjunto y da acceso a un claustro románico triangular de gran pureza litúrgica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90272','monumento','Núcleos de población de Alquézar','El término municipal incluye los siguientes núcleos de población: Alquézar, San Pelegrín y Radiquero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90272','iglesia','Colegiata y Castillo-Santuario de Santa María la Mayor','Joya universal del urbanismo mudéjar y del románico de transición levantada sobre una fortaleza califal musulmana del siglo IX enclavada de forma inexpugnable sobre un impresionante cañón kárstico del río Vero empleando una masiva fábrica de sillería caliza prepirenaica y ladrillo, cuyo conjunto destaca por albergar un bellísimo claustro románico de planta trapezoidal con capiteles historiados tallados con el ciclo del Génesis por el maestro de San Juan de la Peña y una iglesia de tres naves que custodia el célebre Cristo de Alquézar en madera noble policromada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22028','monumento','Núcleos de población de Ansó','El término municipal incluye los siguientes núcleos de población: Ansó y el exclave fronterizo del Valle de Zuriza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22028','monumento','Casco Etnográfico de la Villa de Ansó (Valle de Ansó)','Joya de la arquitectura tradicional pirenaica que destaca por la conservación homogénea de sus casonas de piedra rústica caliza vista de los siglos XVI al XVIII separadas por estrechas e inusuales callejuelas de evacuación (chamineras o saunas), grandes portalones de medio punto, tejados de teja plana con acusadas pendientes adaptados a las copiosas nevadas y chimeneas cilíndricas elevadas coronadas por espantabrujas de piedra rústica, manteniendo el legado vivo de su indumentaria tradicional única en Europa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26034','monumento','Núcleos de población de Briones','El término municipal incluye los siguientes núcleos de población: Briones y los barrios históricos del viñedo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26034','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Magna basílica del siglo XVI de transición del gótico tardío al renacimiento levantada con aparejo de sillería arenisca bien escuadrada que presenta un interior de proporciones monumentales (estilo columnario hallenkirche) cubierto por bóvedas de crucería estrellada, destacando exteriormente su portada clasicista y una majestuosa torre barroca de estilo riojano diseñada en el siglo XVIII.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26034','palacio','Palacio del Marqués de San Nicolás (Ayuntamiento)','Espectacular edificio civil barroco del siglo XVIII que presenta una fachada monumental simétrica de sillería vista con una gran balconada de hierro forjado apoyada sobre ménsulas','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26038','monumento','Núcleos de población de Canales de la Sierra','El término municipal incluye los siguientes núcleos de población: Canales y la ermita románica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26038','ermita','Ermita de San Cristóbal','Joya del románico rural del siglo XII que destaca por su galería porticada lateral levantada en sillería de piedra arenisca dorada, cuyos capiteles e intradoses muestran una asombrosa colección de relieves de motivos vegetales y zoomorfos arcaizantes de gran valor escultórico, enclavada en la alta montaña de la Sierra de la Demanda.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26042','monumento','Núcleos de población de Casalarreina','El término municipal incluye los siguientes núcleos de población: Casalarreina y el Monasterio de la Piedad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26042','iglesia','Monasterio de Nuestra Señora de la Piedad','Joya universal del gótico isabelino y plateresco del siglo XVI fundada por el obispo Juan Fernández de Velasco, levantada con una monumental e imponente sillería de piedra arenisca bien escuadrada que destaca por su portada a modo de retablo triunfal profusamente esculpida y un claustro renacentista de dos plantas de gran valor litúrgico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22054','monumento','Núcleos de población de Benasque','El término municipal incluye los siguientes núcleos de población: Benasque, Cerler, Anciles y las bordas del Pirineo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22054','palacio','Palacio de los Condes de Ribagorza','Espectacular palacio señorial y casa-fuerte del siglo XVI de estilo renacentista que destaca por su imponente planta cúbica erigida con gruesos muros de piedra rústica caliza gris de montaña y esquinales','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22054','palacio','Casco Etnográfico de Casonas Montañesas en Anciles','Conjunto urbano tradicional que destaca por la conservación homogénea de sus residencias señoriales de los siglos XVII y XVIII con enmarcados de sillería caliza compacta en los vanos, portalones de medio punto y tejados a dos aguas de losas de pizarra rústica adaptados a la nieve.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22057','monumento','Núcleos de población de Bielsa','El término municipal incluye los siguientes núcleos de población: localidades de Bielsa, Javierre, Parzán, Chisagüés y el Valle de Pineta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22057','monumento','Casa Consistorial de Bielsa','Palacio civil del siglo XVI de estilo renacentista pirenaico que presenta una fachada monumental de piedra rústica caliza vista con un porche bajo sustentado sobre arcos de medio punto y ventanas ajimezadas labradas en cantería, el cual constituye un hito de la arquitectura del alto Aragón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22066','monumento','Núcleos de población de Boltaña','El término municipal incluye los siguientes núcleos de población: Boltaña, Moriello de Tou, Ascaso y Silves.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22066','monumento','Castillo de Boltaña','Ruinas de la fortaleza militar de origen musulmán (siglo X) reedificada en el estilo románico pleno de la Baja Edad Media que corona un escarpado peñasco rocoso calizo sobre el río Ara, del cual se conservan notables lienzos almenados y el arranque de su torre del homenaje señorial poligonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22078','monumento','Núcleos de población de Canfranc','El término municipal incluye los siguientes núcleos de población: Canfranc Pueblo y Canfranc Estación.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22078','monumento','Torre de Fusileros','Fuerte defensivo y militar decimonónico de planta elíptica levantado en excelente cantería caliza bien escuadrada a los pies del desfiladero, jalonado por aspilleras defensivas y un foso perimetral adaptado a la ingeniería militar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26061','monumento','Núcleos de población de Ezcaray','El término municipal incluye los siguientes núcleos de población: Ezcaray y las aldeas de la alta montaña del Oja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26061','iglesia','Iglesia Parroquial de Santa María la Mayor','Joya monumental de los siglos XIV al XVI de estilo gótico tardío que presenta una inusual singularidad arquitectónica exterior al poseer el aspecto inexpugnable de un torreón fortificado con adarves almenadas y balconadas de vigas de madera de roble, cuyo interior cobija un espectacular retablo mayor romanista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26064','monumento','Núcleos de población de Fuenmayor','El término municipal incluye los siguientes núcleos de población: Fuenmayor y las bodegas tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26064','palacio','Palacio del Marqués de Terán','Casona señorial de traza barroca del siglo XVIII construida con excelente sillería arenisca dorada bien escuadrada que presenta una fachada monumental simétrica con balconadas de hierro forjado apoyadas sobre ménsulas molduradas, luciendo en su cuerpo central monumentales blasones heráldicos finamente tallados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26069','monumento','Núcleos de población de Grañón','El término municipal incluye los siguientes núcleos de población: Grañón y las fincas agrícolas del Camino de Santiago.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26069','iglesia','Iglesia de San Juan Bautista','Templo monumental del siglo XVI de estilo gótico tardío columnario levantado en cantería de gran porte que presenta una majestuosa planta de cruz latina, cuyo presbiterio de sillería custodia en su interior un valioso y monumental retablo mayor plateresco tallado por los maestros Juan de de de Ancheta y Forment.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22107','monumento','Núcleos de población de Fanlo','El término municipal incluye los siguientes núcleos de población: Fanlo, Buerba, Nerín, Vio y el Valle de Añisclo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22107','palacio','Casco Etnográfico de Casonas Montañesas de Fanlo (Valle de Vió)','Conjunto de arquitectura tradicional del alto Aragón que destaca por la conservación homogénea de sus grandes casas de piedra rústica caliza de los siglos XVI al XVIII con los característicos tejados de losas de pizarra, portales de medio punto y monumentales chimeneas cilíndricas elevadas coronadas por espantabrujas de piedra exentas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22112','monumento','Núcleos de población de Fraga','El término municipal incluye los siguientes núcleos de población: Fraga, Miralsot y las ruinas de Villa Fortunatus.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22112','monumento','Yacimiento de la Villa Romana de Villa Fortunatus','Extraordinario complejo residencial romano de los siglos II al IV d.C. protegido por una estructura museística que custodia los cimientos de piedra rústica caliza, una espectacular basílica paleocristiana del siglo IV superpuesta y una','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22112','iglesia','Iglesia de San Pedro','Templo de origen románico profundamente modificado en el periodo mudéjar y barroco que presenta una nave única con una robusta portada de arcos apuntados doblados, rematada exteriormente por una esbelta torre campanario de ladrillo mudéjar con arquerías ciegas de gran finura constructiva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22117','monumento','Núcleos de población de Graus','El término municipal incluye los siguientes núcleos de población: Graus, Panillo, Puebla de de de Castro, Torres del del del de Obispo, Güel y de Graus.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22117','iglesia','Basílica de Nuestra Señora de la Peña','Joya monumental de transición del gótico al renacimiento del siglo XVI enclavada de forma mística bajo un gigantesco farallón rocoso calizo que actúa como techumbre natural, la cual cuenta con una magnífica galería porticada columnaria o mirador exento levantado en sillería caliza prepirenaica que domina las riberas del río Ésera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22117','monumento','Plaza Mayor y Casco Histórico de Graus','Conjunto de traza urbana medieval catalogado como Conjunto Histórico-Artístico que destaca por sus fachadas pintadas al fresco con motivos alegóricos y heráldicos de los siglos XVII y XVIII, cuyas viviendas tradicionales sustentadas sobre postes exentos de madera de roble y soportales de arcos rebajados reflejan la prosperidad económica de la comarca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26071','monumento','Núcleos de población de Haro','El término municipal incluye los siguientes núcleos de población: Haro, el Barrio de la Estación y el paraje de San Felices.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26071','iglesia','Iglesia Parroquial de Santo Tomás Apóstol','Magna basílica de comienzos del siglo XVI de transición del gótico tardío al renacimiento plateresco, construida en excelente sillería arenisca dorada, que destaca universalmente por su espectacular portada meridional labrada por Felipe Bigarny a modo de monumental retablo pétreo y por un interior de tres naves cubiertas por intrincadas bóvedas de crucería estrellada apoyadas sobre colosales pilares columnarios.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26071','palacio','Palacio de los Condes de Haro (Palacio de Bendaña)','Residencia palaciega del siglo XVI de estilo plateresco que exhibe una fachada monumental de cantería fina con arquerías altas mudéjares, balconadas de forja tradicional apoyadas sobre ménsulas molduradas y un suntuoso torreón defensivo exento.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26073','monumento','Núcleos de población de Herramélluri','El término municipal incluye los siguientes núcleos de población: Herramélluri y el yacimiento arqueológico de Libia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26073','monumento','Yacimiento de la Ciudad Berona y Romana de Libia','Complejo arqueológico de la Edad del Hierro y época romana (siglos II a.C. al IV d.C.) que conserva los cimientos perimetrales de piedra rústica caliza, pavimentos de opus signinum y restos de estructuras defensivas que atestiguan la importancia estratégica del valle del Tirón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26080','monumento','Núcleos de población de Igea','El término municipal incluye los siguientes núcleos de población: Igea y el yacimiento paleontológico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26080','palacio','Palacio del Marqués de Casa Torre','Espectacular e hito de la arquitectura civil barroca del siglo XVIII que presenta una monumental fachada de ladrillo y sillería caliza compacta en las esquinas, caracterizada por sus balconadas con rejerías de hierro forjado apoyadas sobre repisas molduradas y un gran escudo de armas finamente labrado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22129','monumento','Núcleos de población de Isábena','El término municipal incluye los siguientes núcleos de población: localidades de Roda de Isábena, Isábena Pueblo, Merli, Mont de Roda, Nocellas, San Esteban de Mall y Serraduy.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22129','catedral','Catedral de San Vicente de Roda de Isábena','Joya universal de la arquitectura románica de transición y gótica primitiva de los siglos XI al XIII que constituye la localidad con catedral más pequeña de España, levantada con una monumental sillería caliza labrada a hueso en estilo románico lombardo, cuyo conjunto destaca por su espectacular cripta abierta de tres naves exenta destinada a salvar el desnivel litúrgico y por un bellísimo claustro románico con capiteles historiados y grabados epigráficos únicos en Europa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22130','monumento','Núcleos de población de Jaca','El término municipal incluye los siguientes núcleos de población: Jaca y las pedanías de Abay, Bernués, Botaya, Guasa, Novés, Orante y Ulle.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22130','catedral','Catedral de San Pedro de Jaca','Obra cumbre, prototipo e hito absoluto del románico pleno español del siglo XI (iniciada','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22130','monumento','Ciudadela de Jaca (Castillo de San Pedro)','Obra cumbre de la ingeniería militar de la península de finales del siglo XVI proyectada por el ingeniero real Tiburcio Spanochi que constituye el único ejemplo intacto en el mundo de fortificación abaluartada pentagonal exento que conserva todas sus defensas originales, levantada con potentes muros de mampostería caliza, baluartes abaluartados, revellines, un profundo foso perimetral y un puente levadizo monumental.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22130','monumento','Torre del Reloj','Joya de la arquitectura del gótico civil del siglo XV que presenta una recia planta cuadrangular levantada en excelente cantería caliza gris de montaña de gran espesor, la cual destaca por sus ventanas ojivales labradas en tracería calada y por haber servido históricamente como prisión foral de la villa real.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26082','monumento','Núcleos de población de Laguna de Cameros','El término municipal incluye los siguientes núcleos de población: Laguna y las bordas ganaderas del sistema ibérico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26082','iglesia','Iglesia Parroquial de la Asunción','Templo de traza gótica tardía y renacentista del siglo XVI edificado con muros portantes de mampostería de piedra rústica caliza gris y esquinales de sillería arenisca, la cual presenta una planta rectangular con bóvedas de crucería y un amplio pórtico asambleario adaptado a la climatología de la alta montaña riojana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26084','monumento','Núcleos de población de Lardero','El término municipal incluye los siguientes núcleos de población: Lardero y las fincas residenciales de la comarca de Logroño.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26084','iglesia','Iglesia Parroquial de San Pedro','Templo monumental de traza barroca clasicista del siglo XVIII levantado con fábrica mixta de sillería arenisca dorada bien escuadrada y contrafuertes angulares de cantería, cuya fisonomía exterior destaca por su robusta torre campanario de líneas clasicistas y un presbiterio que alberga un notable retablo mayor churrigueresco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26089','monumento','Núcleos de población de Logroño','El término municipal incluye los siguientes núcleos de población: Logroño, El Cortijo y Varea.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26089','catedral','Concatedral de Santa María de la Redonda','Magna basílica de los siglos XV al XVIII que destaca universalmente por su espectacular fachada occidental barroca de líneas clasicistas francesas proyectada por Juan de Ancheta en estilo retablo, flanqueada por las célebres y esbeltas "Torres Gemelas" caladas con hornacinas y pináculos, cuyo interior cobija un espectacular calvario al óleo atribuido a Miguel Ángel Buonarroti.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26089','iglesia','Iglesia de Santiago el Real','Templo monumental gótico del siglo XVI edificado sobre vestigios medievales en pleno Camino de Santiago Francés utilizando excelente cantería de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26089','iglesia','Iglesia de San Bartolomé','Templo románico de transición y gótico clásico del siglo XIII erigido con excelente sillería arenisca dorada bien escuadrada que destaca por poseer la única portada gótica monumental de Logroño, un espectacular tapiz pétreo esculpido con arcos apuntados profusamente ornamentados que cobijan relieves de la vida del santo y marcas de cantero medievales únicas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26089','monumento','Yacimiento Romano de Varea (Varia)','Área arqueológica consolidada que conserva los cimientos perimetrales de piedra rústica, pavimentos de opus signinum, alfares y estructuras habitacionales de la antigua ciudad romana de los siglos I al IV d.C., catalogada como un hito científico e histórico para el estudio de la romanización del valle del Ebro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26093','monumento','Núcleos de población de Mansilla de la Sierra','El término municipal incluye los siguientes núcleos de población: Mansilla y las ruinas del pueblo viejo bajo el embalse.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26093','ermita','Ermita de Santa Catalina (Trasladada - Pueblo Viejo)','Pequeño santuario románico rural del siglo XII que fue rescatado piedra a piedra de su emplazamiento original inundado por las aguas del embalse de Mansilla y reconstruido en la nueva ubicación empleando sus sillares originales areniscos, conservando su ábside rectangular primitivo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26099','monumento','Núcleos de población de Murillo de Río Leza','El término municipal incluye los siguientes núcleos de población: Murillo y las fincas agrícolas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26099','iglesia','Iglesia Parroquial de San Esteban','Templo monumental del siglo XVI de estilo gótico tardío columnario (estilo hallenkirche) levantado en sillería arenisca dorada de gran porte que presenta una majestuosa planta basilical de tres naves de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22149','monumento','Núcleos de población de Loarre','El término municipal incluye los siguientes núcleos de población: localidades de Loarre, Linás de Marcuello, Santa Engracia de Loarre y Sarsamarcuello.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22149','iglesia','Castillo-Abadía de Loarre','Obra cumbre, prototipo e hito absoluto de la arquitectura militar y románica europea de los siglos XI y XII (mandada construir por el rey Sancho Ramírez) declarada Monumento Nacional, la cual se alza de forma majestuosa e inexpugnable sobre un escarpado peñasco calizo prepirenaico empleando una suntuosa y masiva fábrica de excelente sillería labrada a hueso que destaca universalmente por poseer el recinto fortificado mejor conservado de Europa, conservando intactos sus murallas perimetrales con once torreones cilíndricos, la Torre del Homenaje almenada, la Torre de la Reina con ventanas ajimezadas y la monumental iglesia abacial de San Pedro coronada por una colosal cúpula linterna calada e interior con capiteles historiados de exquisita factura escultórica jaquesa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22149','iglesia','Iglesia de San Pedro en Sarsamarcuello y Mirador de los Buitres','Templo románico de finales del siglo XII levantado con aparejo calizo bien escuadrado que presenta una nave única con cabecera de ábside semicircular, flanqueada por las ruinas del antiguo castillo de Marcuello embutido sobre los escarpados muros de piedra rústica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22158','monumento','Núcleos de población de Monzón','El término municipal incluye los siguientes núcleos de población: Monzón, Conchel y Selgua.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22158','monumento','Castillo de Monzón','Espectacular fortaleza militar e hito absoluto de la arquitectura templaria de la península (siglos X al XVIII) vinculado originalmente al linaje de los caballeros templarios y de la Orden de San Juan de Jerusalén que se alza de forma estratégica sobre un cerro testigo de la comarca del Cinca Medio empleando una masiva fábrica de sillería de piedra caliza, cal y canto, baluartes abaluartados reales y un profundo foso perimetral, de cuyo conjunto destaca la Torre de Jaime I, la Sala Capitular románica abovedada y la Torre del Homenaje señorial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22158','catedral','Concatedral de Santa María del Romeral','Templo monumental iniciado en el siglo XII de estilo románico de transición y gótico que presenta una inmensa planta basilical con bóvedas de crucería estrellada, albergando en su interior la sillería del coro plateresca y una notable colección de marcas de cantero de alto valor arqueológico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26105','monumento','Núcleos de población de Navarrete','El término municipal incluye los siguientes núcleos de población: Navarrete y las dehesas agrícolas del Camino de Santiago.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26105','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Joya monumental del siglo XVI de estilo gótico tardío y estilo','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26105','monumento','Ruinas del Hospital de San Juan de Acre','Vestigios arqueológicos medievales de la Orden de los Caballeros Hospitalarios cuyo único elemento superviviente intacto es la portada románica de transición del siglo XIII, trasladada de forma preindustrial para servir de acceso monumental en el cementerio municipal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22164','monumento','Núcleos de población de Olvena','El término municipal incluye los siguientes núcleos de población: Olvena y el desfiladero de las Olivas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22164','monumento','Puente del Diablo y Foz de Olvena (Patrimonio Etnográfico)','Estructura viaria bajomedieval que cruza el río Ésera mediante una sólida fábrica de un solo arco apuntado de gran luz construido con aparejo calizo de piedra rústica','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22902','monumento','Núcleos de población de Puente la Reina de Jaca','El término municipal incluye los siguientes núcleos de población: Puente la Reina, Javierregay y Santa Cilia-Muga.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22902','monumento','Puente Medieval sobre el río Aragón','Estructura viaria preindustrial del siglo XIV que salva el cauce fluvial en el trazado histórico del Camino de Santiago Aragonés mediante una sólida fábrica de arcos de medio punto construidos con excelente aparejo calizo calavera y potentes tajamares triangulares diseñados para resistir las avenidas fluviales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19213','iglesia','Iglesia de San Pedro Apóstol','Edificio religioso del siglo XVI construido en mampostería de piedra arenisca roja, dotado de una portada sencilla bajo tejaroz y un presbiterio cubierto por una techumbre de madera de tradición artesanal alcarreña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19217','iglesia','Iglesia de la Asunción','Templo de transición del gótico al renacimiento del siglo XVI edificado en mampostería caliza, cuyo elemento más valioso es su pila bautismal románica decorada con gallones entrelazados y una cenefa superior trenzada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19219','iglesia','Iglesia de la Purísima Concepción','Modesta fábrica del siglo XVII construida en mampostería calcárea y sillarejo, con tejado a dos aguas y una espadaña de dos cuerpos rematada en frontón triangular dispuesta sobre el imafronte.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19222','iglesia','Iglesia de la Asunción','Edificio monumental del siglo XVI edificado en sillería de piedra arenisca roja, dotado de un interior de tres naves separadas por pilares cilíndricos y una notable portada renacentista con pilastras cajeadas y entablamento clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19225','iglesia','Iglesia de San Mateo Apóstol','Templo del gótico tardío y transición renacentista del siglo XVI edificado en mampostería y sillería, notable por su ábside poligonal reforzado por estribos y una portada renacentista bajo pórtico protegido.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19225','monumento','Picota-Rollo de Justicia','Monumento de término del siglo XVI labrado en caliza, compuesto por una escalinata circular sobre la que se asienta un fuste cilíndrico liso rematado por cuatro canes tallados en la corona superior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19232','iglesia','Iglesia de la Asunción','Templo renacentista del siglo XVI construido en regular sillería calcárea con recios contrafuertes exteriores, caracterizado por su interior de nave única cubierta con bóveda de crucería estrellada y nervaduras de sillar bien labrado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19238','monumento','Núcleos de población de Riofrío del Llano','El término municipal incluye los siguientes núcleos de población: Cardeñosa y Santamera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19238','iglesia','Iglesia de Santa Catalina (Riofrío del Llano)','Templo renacentista del siglo XVI construido en sillería y mampostería, que destaca por su interior compartimentado en tres naves separadas por pilares cilíndricos y cubiertas de viguería vista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19238','iglesia','Iglesia de Santa María Magdalena (Santamera)','Pequeño edificio románico del siglo XII emplazado en un desfiladero rocoso calizo, que conserva su estructura original de nave única con ábside semicircular decorado con canecillos lisos de labra románica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19241','iglesia','Iglesia de San Andrés Apóstol','Fábrica renacentista del siglo XVI levantada en cantería caliza regular, notable por su gran torre campanario adosada a los pies, su portada septentrional plateresca con medallones y un artesonado mudéjar de limas mohama en la sacristía.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19244','monumento','Núcleos de población de Sacecorbo','El término municipal incluye los siguientes núcleos de población: Canales del Ducado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19244','iglesia','Iglesia de San Bartolomé (Sacecorbo)','Templo de finales del siglo XVI edificado en sillería caliza y mampostería, rematado por una robusta torre campanario de planta cuadrangular y un interior barroco con bóvedas de lunetos ciegos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19244','iglesia','Iglesia de San Albert (Canales del Ducado)','Pequeña construcción de mampostería rústica caliza del siglo XVII con planta de cajón y espadaña exenta en el hastial occidental provista de dos troneras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19245','monumento','Núcleos de población de Sacedón','El término municipal incluye los siguientes núcleos de población: Corcoles y Alocén.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19245','iglesia','Monasterio de Monsalud (Córcoles)','Espectacular cenobio cisterciense del siglo XII ejecutado en sillería caliza calavera, del cual se conserva intacta la iglesia de tres naves con cabecera triple y bóvedas de crucería ojival, además de un imponente claustro gótico del siglo XIV.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19245','iglesia','Iglesia de Nuestra Señora de la Asunción (Sacedón)','Templo de transición plateresco-renacentista del siglo XVI atribuido a Juan de Alvear en sillería regular, con una gran portada meridional cobijada bajo arco de triunfo y bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19246','monumento','Salinas de Saelices de la Sal','Complejo etnográfico e industrial de origen romano y medieval modificado en el siglo XVIII, compuesto por albercas de evaporación de madera de pino, canales de distribución de salmuera y norias de tracción animal de cantería caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19246','iglesia','Iglesia de San Juan Bautista','Pequeño templo románico del siglo XII levantado en sillería arenisca, que mantiene su ábside semicircular con saeteras y una pila bautismal monolítica decorada con arquerías ciegas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19247','iglesia','Iglesia de Nuestra Señora de la Asunción','Magna construcción del siglo XVI con trazas de estilo gótico tardío y renacentista ejecutada en sillería regular, singular por su esbelta torre-campanario exenta y un sotocoro sostenido por un monumental arco escarzano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19248','iglesia','Iglesia de San Andrés Apóstol','Fábrica modesta del siglo XVII construida en aparejo de canto rodado y mampostería basta caliza, rematada por una espadaña de ladrillo de tradición mudéjar tardía con dos vanos de campana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19249','iglesia','Iglesia de San Andrés','Edificio parroquial del siglo XVI erigido con muros de mampostería de arcilla y sillarejo en las esquinas, dotado de un interior sencillo con viguería de madera de par y nudillo vista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19251','monumento','Núcleos de población de Saúca','El término municipal incluye los siguientes núcleos de población: Jodra del Pinar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19251','iglesia','Iglesia de Nuestra Señora de la Asunción (Saúca)','Excepcional templo románico de finales del siglo XII labrado en excelente cantería caliza, célebre por su galería porticada meridional con elegantes columnas pareadas y capiteles de fina talla vegetal cisterciense.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19251','iglesia','Iglesia de San Juan Bautista (Jodra del Pinar)','Notable ejemplo de románico rural del siglo XII en sillería caliza, caracterizado por su ábside semicircular perfecto, una espadaña de dos vanos y una portada de arquivoltas planas exenta de decoración escultórica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19252','iglesia','Iglesia de San Pedro','Obra renacentista del siglo XVI edificada en aparejo toledano combinando hileras de ladrillo macizo y cajones de mampostería caliza, dotada de una portada clasicista adintelada flanqueada por pilastras planas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19254','iglesia','Iglesia de la Virgen de la Minerva','Fábrica del siglo XVII integrada en el entorno del Alto Tajo, armada en sillería de piedra arenisca roja (pétreo rodeno) con planta rectangular de nave única y presbiterio plano con tejado a dos aguas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19901','monumento','Núcleos de población de Semillas','El término municipal incluye los siguientes núcleos de población: Las Cabezadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19901','iglesia','Iglesia de San Juan Bautista (Semillas)','Exponente de la arquitectura rural de la Sierra Norte del siglo XVI erigido en lajas de pizarra rústica cementadas con argamasa de cal, rematado por una espadaña de pizarra de dos vanos escalonados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19255','monumento','Casa Fuerte de los Malo de Molina','Palacio torreado de carácter defensivo del siglo XVI edificado en regular cantería arenisca, singular por sus ventanales moldurados con rejería artística de forja góticorenacentista y potentes garitones angulares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19256','monumento','Castillo de Senés (Ruinas)','Vestigios medievales de una importante fortaleza defensiva de origen andalusí de la que subsisten paños fragmentados de murallas de mampostería basta de pizarra rústica seca adaptados al relieve geológico de la montaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19256','iglesia','Iglesia Parroquial de Santa María','Fábrica mudéjar del siglo XVI levantada en la Sierra de los Filabres con recios muros de piedra que alberga una nave única techada por una espléndida armadura de madera de pino y sabina.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19257','monumento','Núcleos de población de Sigüenza','El término municipal incluye los siguientes núcleos de población: Palazuelos, Guijosa, Pelegrina, Riba de Santiuste, Imón, Pozancos y Carabias.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19257','catedral','Catedral de Santa María de Sigüenza','Magna basílica del gótico inicial e influjo cisterciense iniciada en el siglo XII en sillería caliza calavera, provista de una fachada monumental fortificada con dos torres almenadas, un espectacular rosetón central y el célebre sepulcro del Doncel labrado en alabastro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19257','palacio','Castillo-Palacio de los Obispos','Colosal fortaleza medieval del siglo XII construida sobre cimientos romanos y visigodos en sillería caliza regular, conformada por patios de armas, torres cuadrangulares de defensa y estancias palaciegas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19257','iglesia','Iglesia de San Vicente','Joya del románico urbano de principios del siglo XII edificada en cantería bien escuadrada, que destaca por su bellísima portada meridional cargada de arquivoltas talladas con motivos de dientes de sierra y capiteles historiados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19257','monumento','Murallas de Palazuelos','Complejo amurallado medieval del siglo XV mandado construir por el Marqués de Santillana en sillería caliza, conservando intacto su perímetro urbano jalonado por torreones cuadrangulares y cuatro monumentales puertas de acceso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19257','monumento','Castillo de Riba de Santiuste','Fortaleza roquera de origen califal del siglo X reedificada en el siglo XII en sillería y sillarejo de arenisca, asentada sobre un espolón rocoso inexpugnable con doble recinto amurallado y torres almenadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19257','iglesia','Iglesia de San Salvador (Carabias)','Extraordinario templo románico del siglo XIII en sillería caliza, célebre por poseer una de las galerías porticadas más completas de la provincia, rodeando los muros sur y oeste con arquerías de medio punto sobre columnas pareadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19257','monumento','Salinas de Imón','Conjunto etnográfico e industrial de explotación salinera documentado desde el siglo X y reformado por Carlos III en sillería caliza, compuesto por almacenes monumentales de cantería y albercas de evaporación de mampostería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19257','monumento','Castillo de Guijosa','Casa-fuerte palaciega bajomedieval del siglo XV ejecutada en sillería y mampostería, estructurada con una soberbia planta cuadrada reforzada por cuatro torreones angulares y una esbelta torre del homenaje central.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19258','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo del siglo XVI construido en mampostería caliza, notable por su ábside de testero plano reforzado por contrafuertes oblicuos de cantería y su portada renacentista de medio punto con dovelas radiales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19259','iglesia','Iglesia de Nuestra Señora de las Nieves','Templo del gótico tardío del siglo XV edificado en excelente cantería caliza, notable por su portada occidental de arquivoltas apuntadas con un gran rosetón superior calado y un interior de amplia nave única.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19260','monumento','Núcleos de población de El Sotillo','El término municipal incluye los siguientes núcleos de población: Aldehuela del Rincón y Molinos de Duero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19260','iglesia','Iglesia de San Martín (Sotillo del Rincón)','Fábrica renacentista de grandes dimensiones del siglo XVI levantada en sillería arenisca, provista de un presbiterio de planta poligonal con contrafuertes y un interior de tres naves con arcos formeros apuntados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19260','palacio','Casonas de Molinos de Duero','Conjunto históricoartístico de casonas carreteras construidas en los siglos XVII y XVIII en magnífica sillería de piedra arenisca roja pinariega, provistas de monumentales portadas adinteladas con arcos de medio punto adovelados y balconadas de forja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19261','iglesia','Iglesia de la Asunción','Templo de transición del gótico al renacimiento del siglo XVI en mampostería y sillería, dotado de un presbiterio con techumbre de madera de tradición mudéjar y una pila bautismal medieval monolítica de labra popular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19262','monumento','Núcleos de población de Tamajón','El término municipal incluye los siguientes núcleos de población: Almiruete, Palancares y Muriel.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19262','palacio','Palacio de los Mendoza','Espléndido edificio civil renacentista del siglo XVI construido en sillería caliza calavera, cuya fachada plateresca destaca por sus vanos moldurados, escudos heráldicos y un patio interior con arquerías sobre columnas toscanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19262','iglesia','Iglesia de la Asunción','Fábrica monumental del siglo XVI que engloba restos románicos del siglo XII en sillería regular, notable por su gran portada renacentista cobijada bajo pórtico y un interior de tres naves con arcos formeros apuntados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19262','iglesia','Iglesia de las Santa María (Almiruete)','Templo de filiación románica del siglo XIII edificado en lajas de pizarra rústica y sillarejo calcáreo, célebre por su espadaña exenta y su portada de arquivoltas románicas lisas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19263','iglesia','Iglesia de San Miguel','Construcción rural barroca del siglo XVII ejecutada en aparejo toledano combinando hiladas de ladrillo macizo y cajones de mampostería basta, rematada por una modesta espadaña de dos vanos en el hastial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19264','iglesia','Iglesia de la Asunción','Templo del siglo XVI edificado en piedra arenisca roja (pétreo rodeno) del Alto Tajo, caracterizado por sus paramentos de mampostería gruesa y una torre-campanario de planta cuadrangular adosada al presbiterio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19265','monumento','Núcleos de población de Tartanedo','El término municipal incluye los siguientes núcleos de población: Amayas, Concha e Hinojosa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19265','iglesia','Iglesia de San Bartolomé (Tartanedo)','Monumental templo plateresco del siglo XVI levantado en regular cantería caliza, dotado de una portada profusamente tallada con motivos de grutescos y un interior con bóvedas de crucería estrellada de gran complejidad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19265','iglesia','Iglesia de San Andrés (Hinojosa)','Fábrica románica tardía del siglo XIII construida en sillería arenisca, que conserva su ábside semicircular con saeteras abocinadas y capiteles interiores decorados con palmetas y motivos geométricos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19266','iglesia','Iglesia de la Asunción de Nuestra Señora','Magna obra inacabada del siglo XVI atribuida a Juan de Herrera en sillería caliza bien escuadrada, notable por las colosales proporciones de sus contrafuertes exteriores y sus potentes muros de corte clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19266','monumento','Soportales de la Calle Mayor','Conjunto de arquitectura civil porticada de los siglos XV y XVI, compuesto por hileras de columnas de piedra caliza y viguerías de madera que sostienen las viviendas tradicionales de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19266','iglesia','Ruinas del Monasterio de Santa Ana','Vestigios del cenobio jerónimo fundado en el siglo XV, edificado en mampostería y sillería, del que subsisten los arranques de las bóvedas de la iglesia y potentes arcos de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19267','iglesia','Iglesia de la Virgen de la Asunción','Edificio del siglo XVIII construido con planos de corte academicista en sillería y mampostería caliza, que destaca por su fachada simétrica y un interior barroco cubierto por cúpula sobre pechinas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19268','monumento','Casa-Fuerte de Vega de Arias','Complejo defensivo y residencial bajomedieval del siglo XV levantado en sillería de piedra arenisca roja, compuesto por una imponente torre del homenaje de planta cuadrada','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19269','iglesia','Iglesia de San Juan Bautista','Fábrica del siglo XVI ejecutada en mampostería caliza con sillares de refuerzo en los ángulos, que cuenta con una espadaña de dos vanos escalonados en el imafronte y un coro de madera tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19271','iglesia','Iglesia de San Juan Bautista','Templo del siglo XVI levantado en cantería arenisca compacta, que presenta una nave única con cabecera cuadrangular reforzada por contrafuertes exteriores y una portada con arco de medio punto moldurado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19270','iglesia','Iglesia de la Natividad','Obra rural del siglo XVI construida en mampostería tosca de pizarra y caliza, con una espadaña exenta sobre el muro occidental provista de dos troneras para las campanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19272','iglesia','Iglesia de la Asunción','Templo de finales del siglo XVI ejecutado en regular sillería de arenisca, con un presbiterio cubierto por una techumbre de madera de tradición mudéjar y una pila bautismal románica troncocónica de labra popular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19274','monumento','Castillo de Torija','Espectacular fortaleza bajomedieval del siglo XV construida por la familia Mendoza en excelente cantería caliza, estructurada con una planta rectangular flanqueada por tres cubos cilíndricos angulares y una colosal torre del homenaje exenta de vanos decorativos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19274','iglesia','Iglesia de la Asunción','Fábrica renacentista del siglo XVI ejecutada en mampostería y sillería, que destaca exteriormente por su elegante torre-campanario barroca y un interior de tres naves separadas por arcos de medio punto sobre pilares toscanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19279','iglesia','Monasterio de San Salvador de Sopetrán','Histórico cenobio fundado en época visigoda y reedificado en los','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19278','iglesia','Iglesia de San Juan Bautista','Fábrica del siglo XVI en mampostería caliza, caracterizada por su presbiterio poligonal reforzado por contrafuertes oblicuos y su portada de líneas clásicas bajo arco adintelado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19280','monumento','Núcleos de población de Torrejón del Rey','El término municipal incluye los siguientes núcleos de población: Horcajada de la Torre, Naharros, Villar del Águila, Villarejo-Sobre-Huerta y Villar del Horno.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19280','monumento','Mina de Lapis Specularis "La Mora Encantada"','Excepcional complejo arqueológico y minero de época romana explotado para la extracción de cristal de yeso que conserva una inmensa red de galerías subterráneas labradas a pico directamente sobre la roca viva caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19280','iglesia','Iglesia de San Martín Obispo (Torrejoncillo del Rey)','Monumental templo del siglo XVI levantado con sillería y','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19281','iglesia','Iglesia de San Miguel','Edificación del siglo XVI construida en sillería arenisca y mampostería, destacando su ábside cuadrangular y una portada renacentista purista de arco de medio punto flanqueada por pilastras lisas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19282','monumento','Núcleos de población de Torremocha del Campo','El término municipal incluye los siguientes núcleos de población: Pelegrina, Torrecilla del Ducado y Renales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19282','monumento','Castillo de Pelegrina','Ruinas de la fortaleza roquera de los obispos de Sigüenza construida en el siglo XII en sillería caliza, asentada sobre un espolón escarpado que conserva lienzos de muralla jalonados por cubos cilíndricos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19282','iglesia','Iglesia de la Asunción (Torremocha del Campo)','Templo renacentista del siglo XVI levantado en mampostería con esquinas de sillería bien labrada, rematado por una esbelta torre-campanario de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19283','iglesia','Iglesia de San Mitre','Fábrica del siglo XVI integrada en el paisaje del pinar, armada con gruesos muros de piedra calcárea del terreno y viguería de pino, albergando una pila aguabenditera monolítica de labra popular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19284','iglesia','Iglesia de la Asunción','Estructura de arquitectura popular del siglo XVI levantada en aparejo mixto de arcilla y sillarejo, rematada por una espadaña exenta en la fachada occidental y un sencillo pórtico de acceso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19286','iglesia','Iglesia de la Asunción','Templo del siglo XVI edificado en aparejo toledano combinando bandas de ladrillo y cajones de mampostería, con un porche de acceso soportado por columnas toscanas de piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19287','iglesia','Iglesia de San Pedro Apóstol','Fábrica renacentista de grandes dimensiones del siglo XVI construida en sillería de piedra arenisca de rodeno y caliza, con planta de cruz latina y una gran torre campanario adosada que destaca por sus paramentos ciegos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19288','iglesia','Iglesia de San Juan Bautista','Templo del siglo XVI levantado en lajas de pizarra rústica y sillarejo calcáreo de la Sierra Norte, que destaca por su espadaña escalonada y un interior con viguería de par y nudillo vista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19289','iglesia','Iglesia de Santa María','Obra rural del siglo XVI ejecutada en sillería de arenisca y sillarejo, con presbiterio sobrio de planta rectangular y coro de madera tallada a los pies.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19290','iglesia','Iglesia de Nuestra Señora de la Asunción','Templo plateresco del siglo XVI construido en regular sillería calcárea, que muestra una elegante portada meridional bajo arco de triunfo con decoración de grutescos y medallones en las enjutas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19290','monumento','Plaza Mayor y Soportales','Conjunto civil de los siglos XVI y XVII edificado con columnas de sillería caliza','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19291','monumento','Núcleos de población de Trillo','El término municipal incluye los siguientes núcleos de población: Azañón, Morillejo y Viana de Mondéjar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19291','iglesia','Iglesia de la Asunción (Trillo)','Fábrica renacentista del siglo XVI levantada en excelente sillería de cantería regular, notable por sus grandes dimensiones, contrafuertes exteriores y una portada de líneas clasicistas bajo arco de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19291','monumento','Puente sobre el río Tajo','Estructura monumental del siglo XVI ejecutada en sillería caliza compacta, formada por un gran ojo central de medio punto con tajamares triangulares aguas arriba para romper la corriente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19293','monumento','Núcleos de población de Uceda','El término municipal incluye los siguientes núcleos de población: Rebollo de Duero y Peñarrubia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19293','iglesia','Iglesia de Santa María de la Varga','Ruinas monumentales de un templo románico de finales del siglo XII construido en excelente sillería caliza, del que destaca su magnífico ábside semicircular con tres niveles de arquerías ciegas dobladas y capiteles de fina talla zoomorfa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19293','iglesia','Iglesia Parroquial de Nuestra Señora de la Varga','Obra herreriana de finales del siglo XVI diseñada por arquitectos de la escuela madrilena en sillería regular, con una severa planta de cruz latina, fachada con líneas desnudas de ornato y una cúpula de media naranja sobre pechinas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19297','iglesia','Iglesia de San Juan Bautista','Fábrica del siglo XVI ejecutada en aparejo toledano combinando bandas de ladrillo macizo y cajones de mampostería basta caliza, dotada de una nave única que remata en un presbiterio cubierto por armadura de madera a dos aguas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19298','iglesia','Iglesia de la Asunción de Nuestra Señora','Imponente fábrica gótico-mudéjar tardía del siglo XV construida en ladrillo y sillería caliza que destaca por su monumental Puerta de los Catecúmenos plateresca, sus potentes contrafuertes y tres naves a igual altura cubiertas por bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19298','monumento','Bodegas Tradicionales Subterráneas','Conjunto etnológico formado por extensas galerías excavadas en los terrenos calizos que mantienen las estructuras de arcos fajones de ladrillo y tinajas de barro destinadas a la crianza histórica del vino.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19298','ermita','Ermita de la Veracruz','Santuario barroco del siglo XVIII levantado en el casco urbano con aparejo toledano que cuenta con un crucero rematado en cúpula de media naranja ricamente decorada con yeserías polícromas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19299','iglesia','Iglesia de Nuestra Señora de la Asunción','Templo gótico tardío y renacentista del siglo XVI edificado en regular cantería arenisca, notable por su ábside de paños reforzado por contrafuertes oblicuos y un espacioso interior cubierto por bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19300','iglesia','Iglesia de San Juan Bautista','Fábrica del siglo XVI remodelada en el barroco empleando aparejo mixto de piedra caliza y ladrillo, cuyo elemento más señero es su pila bautismal románica troncocónica decorada con arquerías de medio punto entrelazadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19301','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo del siglo XVI construido en sillería basta y mampostería, caracterizado por su portada clasicista bajo arco adintelado con frontón triangular y una sacristía que conserva viguería vista de pino moldurado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19302','iglesia','Iglesia de la Asunción','Edificación religiosa del siglo XVII levantada en sillarejo y mampostería calcárea, estructurada en una sola nave con coro alto a los pies soportado por un recio pie derecho de madera labrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19303','iglesia','Iglesia de la Inmaculada Concepción','Obra rural del siglo XVI en mampostería de piedra caliza y arenisca, provista de un presbiterio con arco triunfal apuntado de sillería y una modesta espadaña de dos vanos para las campanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19305','monumento','Núcleos de población de Valdepeñas de la Sierra','El término municipal incluye los siguientes núcleos de población: Alpedrete de la Sierra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19305','iglesia','Iglesia de la Purificación de Nuestra Señora (Valdepeñas de la Sierra)','Templo del gótico tardío del siglo XVI edificado en sillería caliza, notable por su ábside poligonal con bóveda de crucería nervada y una portada meridional renacentista con arco de medio punto moldurado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19305','iglesia','Iglesia de la Inmaculada Concepción (Alpedrete de la Sierra)','Construcción serrana levantada en lajas de pizarra rústica y sillarejo, con una imponente espadaña de pizarra de tres vanos dispuestos en dos pisos decrecientes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19306','iglesia','Iglesia de Nuestra Señora de la Leche','Edificio parroquial de origen románico modificado en el siglo XVI con cantería caliza regular, que mantiene su portada meridional románica exenta de decoración con arquivoltas lisas de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19307','iglesia','Iglesia de la Asunción','Templo plenamente integrado en la arquitectura negra del siglo XVI erigido con gruesos muros de lajas de pizarra rústica y argamasa, singular por su pórtico protegido por tejaroz sobre pies derechos de madera de sabina.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19308','iglesia','Iglesia de San Pedro Apóstol','Fábrica renacentista del siglo XVI construida en sillería caliza, que destaca por su ábside de testero plano reforzado por contrafuertes y un interior de tres naves separadas por pilares toscanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19308','monumento','Ruinas del Castillo de Valfermoso','Restos fortificados de una fortaleza del siglo XV levantada en mampostería basta sobre el cerro, de la que subsisten los arranques de la muralla perimetral y la base de una torre cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19309','iglesia','Iglesia de la Asunción','Modesta construcción rural del siglo XVII edificada en piedra arenisca roja (pétreo rodeno) del Señorío de Molina, con tejado a dos aguas y espadaña exenta en el hastial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19310','iglesia','Iglesia de la Asunción','Pequeño oratorio del siglo XVII integrado en el entorno del Alto Tajo, edificado con paramentos de mampostería calcárea basta y una portada sencilla de medio punto con dovelas toscas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19311','iglesia','Iglesia de San Ildefonso','Exponente señero de la arquitectura negra de la Sierra de Ayllón reedificado en el siglo XIX sobre trazas del siglo XVI empleando lajas de pizarra rústica compacta y madera de roble, dotado de un interior diáfano de una sola nave con artesonado visto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19311','ermita','Ermita de la Virgen de Gracia','Humilde capilla serrana del siglo XVIII construida enteramente en pizarra rústica con cubierta de losas del mismo material, mimetizada cromáticamente con el entorno geológico de la vertiente del pico Ocejón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19314','iglesia','Iglesia de San Juan Bautista','Fábrica de filiación románica modificada en el siglo XVI en cantería arenisca, que conserva de su origen el ábside semicircular con saeteras abocinadas y canes lisos bajo la cornisa del alero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19317','iglesia','Iglesia Parroquial de San Miguel Arcángel','Monumental templo columnario del siglo XVI de líneas renacentistas sencillas construido en sillería granítica berroqueña de Los Pedroches que exhibe tres naves de colosales proporciones de gran luz espacial separadas por robustos pilares de piedra toscana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19317','monumento','Audiencia Municipal / Antiguo Pósito','Espectacular edificio civil renacentista del siglo XVI de estilo institucional que presenta una fachada palaciega con portalón de cantería dovelado flanqueada por blasones heráldicos imperiales de noble linaje.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19318','iglesia','Iglesia de San Blas','Edificación del siglo XVI construida en mampostería caliza calavera con sillares de refuerzo angulares, rematada por una espadaña de dos cuerpos decrecientes con frontón triangular dispuesto sobre el imafronte.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19319','iglesia','Iglesia de San Juan Bautista','Templo renacentista del siglo XVI ejecutado en aparejo toledano de ladrillo macizo y cajones de mampostería, notable por su cabecera poligonal y una gran portada plateresca cobijada bajo un pórtico renacentista sobre columnas de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19321','iglesia','Iglesia de Santa Natividad','Obra rural de la Sierra Norte del siglo XVI edificada con muros de mampostería de pizarra rústica y cuarcita, caracterizada por su espadaña exenta en la fachada occidental provista de dos troneras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19323','iglesia','Iglesia de Nuestra Señora de la Asunción','Templo de finales del siglo XVI construido en mampostería caliza y sillería, que destaca por su portada clasicista flanqueada por pilastras cajeadas y un interior barroco con bóvedas de cañón con lunetos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19322','iglesia','Iglesia de San Blas','Fábrica del siglo XVI levantada en aparejo de sillarejo calizo con esquinas de sillería bien labrada, dotada de una torre-campanario de planta cuadrangular adosada al hastial occidental.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19324','monumento','Castillo de los Funes','Espectacular fortaleza roquera bajomedieval del siglo XV levantada en sillería de piedra arenisca roja sobre una abrupta cresta caliza, de la que sobresalen su imponente torre del homenaje almenada y los lienzos de muralla almenados con saeteras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19324','iglesia','Iglesia de la Asunción','Templo tardogótico-renacentista del siglo XVI construido en regular cantería arenisca, notable por su ábside poligonal con bóveda de crucería estrellada y su gran portada plateresca con fina decoración de grutescos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19325','iglesia','Iglesia de Nuestra Señora de la Asunción','Edificio del siglo XVI levantado en aparejo mixto de piedra caliza y ladrillo, singular por su espadaña de tres vanos en el hastial occidental y una portada purista de arco de medio punto moldurado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19326','iglesia','Iglesia de San Bartolomé','Fábrica renacentista del siglo XVI ejecutada en mampostería caliza calavera con refuerzo de sillares en las esquinas, notable por su portada meridional de líneas clasicistas bajo arco de medio punto y su severa torre campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19327','iglesia','Iglesia de San Andrés Apóstol','Templo monumental del siglo XVI edificado en regular sillería calcárea, cuyo interior consta de tres naves de gran altura separadas por pilares toscanos y cubiertas con bóvedas de crucería de sillar bien labrado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19329','iglesia','Iglesia de la Asunción de Nuestra Señora','Edificación religiosa del siglo XVI levantada en aparejo de sillarejo calizo, caracterizada por su presbiterio de planta rectangular reforzado exteriormente por contrafuertes y una modesta espadaña de dos vanos para las campanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19330','iglesia','Iglesia de la Asunción','Templo de finales del siglo XVI construido en mampostería basta del terreno con esquinas de piedra labrada, dotado de un interior sencillo con viguería de madera de par y nudillo vista y una pila bautismal románica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19331','iglesia','Iglesia de San Pedro Apóstol','Magna construcción de transición del gótico al renacimiento del siglo XVI erigida en sillería y mampostería caliza, que destaca por su ábside poligonal con contrafuertes oblicuos y su esbelta torre campanario de tres cuerpos decrecientes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19332','iglesia','Iglesia de Santa María la Mayor','Fábrica del siglo XVI ejecutada en excelente cantería de piedra arenisca roja (pétreo rodeno), singular por su planta de cruz latina con bóvedas de crucería estrellada y una portada renacentista purista flanqueada por pilastras cajeadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19332','monumento','Torre de los Campillo','Restos de una antigua casafuerte bajomedieval del siglo XV levantada en sillería y mampostería con carácter defensivo, de la que subsiste una robusta estructura cuadrangular desmochada con saeteras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19333','monumento','Núcleos de población de Zaorejas','El término municipal incluye los siguientes núcleos de población: Huertapelayo y Villanueva de las Tres Fuentes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19333','iglesia','Iglesia de la Asunción (Zaorejas)','Templo del siglo XVII plenamente integrado en el Parque Natural del Alto Tajo, edificado con gruesos paramentos de mampostería calcárea y una torre campanario baja que dobla funciones defensivas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19333','iglesia','Iglesia de Santa María Magdalena (Huertapelayo)','Pequeña construcción rural del siglo XVII encajonada en un desfiladero rocoso, levantada en mampostería basta con cubierta a dos aguas de teja árabe y artesonado interior de madera de pino sin decorar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19334','iglesia','Iglesia de la Asunción','Exponente de la arquitectura rural de la Sierra Norte del siglo XVI erigido con lajas de pizarra rústica cementadas con barro, rematado por una espadaña de pizarra de dos vanos y un pórtico protegido por tejaroz sobre pies derechos de madera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19335','monumento','Yacimiento Arqueológico de Recópolis','Excepcional conjunto urbano de fundación visigoda erigido por Leovigildo en el año 578 en sillería caliza, del cual se conservan los potentes restos cimentados de la gran basílica palatina de planta de cruz latina, el palacio real articulado en dos pisos y el complejo sistema de acueductos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19335','monumento','Castillo de Zorita de los Canes','Colosal fortaleza de origen califal del siglo IX reedificada por la Orden de Calatrava en los siglos XII y XIII en sillería caliza regular, que cuenta con una impresionante iglesia románica interior, una torre del homenaje fortificada, la sala capitular con arcos apuntados y un recinto amurallado con barbacana y foso roquero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19335','iglesia','Iglesia de San Juan Bautista','Templo de origen románico del siglo XII modificado en el siglo XVI en cantería bien escuadrada, que mantiene intacta su portada meridional románica provista de arquivoltas de medio punto decoradas con motivos geométricos y capiteles con motivos vegetales esquemáticos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15002','iglesia','Iglesia de San Juan Bautista','Magna fábrica de transición del gótico tardío al renacimiento del siglo XVI construida en sillería caliza compacta, notable por su imponente torre campanario de corte clasicista y un ábside poligonal cubierto con complejas bóvedas de crucería nervada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15002','ermita','Ermita de Nuestra Señora del Camino','Edificación religiosa de carácter rural del siglo XVIII levantada en mampostería regular y sillares de refuerzo en los vanos, caracterizada por su planta de cajón con coro alto y sacristía adosada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51015','iglesia','Iglesia de Santa Eulalia','Templo de origen románico profundamente reformado en el siglo XVIII mediante fábrica de mampostería tosca y sillarejo, del que perviven algunos canecillos lisos en el alero septentrional y una rústica pila bautismal monolítica medieval.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41011','monumento','Núcleos de población de Ágreda','El término municipal incluye los siguientes núcleos de población: Fuentes de Ágreda, Valverde de Ágreda y Yanguas de Soria.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41011','iglesia','Iglesia de San Miguel','Excepcional obra monumental del gótico del siglo XV construida en sillería arenisca, que conserva adosada una espectacular torre-fortaleza románica del siglo XII de planta cuadrangular con arquerías ciegas de influjo mudéjar y un soberbio retablo mayor plateresco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41011','palacio','Palacio de los Castejones','Espléndido palacio renacentista-barroco del siglo XVII edificado en sillería de piedra arenisca roja, dotado de una fachada monumental flanqueada por dos torres herrerianas y un jardín','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41011','monumento','Muralla Árabe y Puerta del Barrio','Conjunto fortificado califal del siglo X ejecutado en tapial y mampostería basta calcárea, del que destaca el arco de herradura califal exento que daba acceso al antiguo barrio morisco de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41011','iglesia','Basílica de Nuestra Señora de los Milagros','Templo monumental de proporciones catedralicias construido en el siglo XVI en sillería caliza regular, provisto de una espaciosa nave única con capillas laterales entre contrafuertes y bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41011','iglesia','Iglesia de la Virgen de la Peña (Fuentes de Ágreda)','Templo del románico rural soriano del siglo XII levantado en cantería, que mantiene su ábside semicircular perfecto con saeteras abocinadas y capiteles de labra tosca con decoración vegetal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90273','monumento','Núcleos de población de Alconaba','El término municipal incluye los siguientes núcleos de población: Cubo de Hogueras, Martialay y Ontalvilla de Valcorba.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90273','iglesia','Iglesia de Nuestra Señora de la Visitación (Alconaba)','Fábrica del siglo XVI ejecutada en mampostería con esquinas reforzadas en cantería, rematada por una espadaña de dos cuerpos decrecientes con frontón clasicista y un interior sobrio de nave única.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90273','monumento','Torre de Cubo de Hogueras','Restos desmochados de una atalaya fortificada bajomedieval del siglo XV construida en sillarejo calizo con saeteras, que formaba parte del sistema de señales fronterizas entre Castilla y Aragón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90274','monumento','Núcleos de población de Alcubilla de Avellaneda','El término municipal incluye los siguientes núcleos de población: Alcoba de la Torre y Zayas de Báscones.','inventario_monumentos_pdf');
