INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90274','monumento','Castillo de Alcoba de la Torre','Ruinas de una fortaleza del siglo XV levantada en sillería y mampostería, de la que subsisten potentes lienzos de muralla y los arranques de una gran torre del homenaje cuadrangular adaptada a la artillería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90274','iglesia','Iglesia de Santo Domingo de Silos','Templo renacentista del siglo XVI construido en sillarejo calizo calavera, provisto de un presbiterio poligonal reforzado por estribos oblicuos y un sotocoro sostenido por un gran arco escarzano.','inventario_monumentos_pdf');
