INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90276','iglesia','Iglesia de Santa María','Estructura de arquitectura popular castellana del siglo XVI levantada en aparejo mixto de canto rodado y sillarejo, rematada por una espadaña de dos vanos en la fachada occidental y un pórtico simple de madera.','inventario_monumentos_pdf');
