INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42033','iglesia','Iglesia de la Asunción','Templo de arquitectura popular castellana del siglo XVI edificado en aparejo mixto de arcilla y sillarejo, rematado por una espadaña de dos vanos en el hastial occidental y una pila bautismal románica troncocónica.','inventario_monumentos_pdf');
