INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42035','monumento','Núcleos de población de Berlanga de Duero','El término municipal incluye los siguientes núcleos de población: Abanco, Brías, Ciruela, Lumías, Morales y Paones.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42035','monumento','Castillo de Berlanga de Duero','Colosal fortaleza de los siglos XV y XVI erigida en sillería caliza compacta, monumental por su imponente torre del homenaje gótica rodeada por una espectacular fortificación renacentista adaptada a la artillería con recios cubos artilleros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42035','iglesia','Colegiata de Santa María del Mercado','Magna obra cumbre del gótico tardío y del renacimiento erigida entre 1526 y 1530 por Juan de Rasines en sillería caliza, señera por su planta de salón con tres naves a igual altura y esbeltas columnas que sostienen bóvedas estrelladas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42035','palacio','Palacio de los Marqueses de Berlanga','Restos de la monumental residencia plateresca del siglo XVI en sillería regular caliza, de la que subsiste la imponente fachada de corte clasicista y un conjunto de patios y torres angulares integradas al pie del castillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42035','iglesia','Iglesia de San Juan Bautista (Brías)','Espectacular templo barroco de finales del siglo XVII proyectado con trazas cortesanas y construido en sillería caliza bien labrada, rematado por una cúpula sobre pechinas ricamente ornamentada con yeserías barrocas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42035','ermita','Ermita de la Virgen de la Calzada (Morales)','Construcción del siglo XII levantada en sillería románica rural, que mantiene un ábside semicircular perfecto con saeteras abocinadas y capiteles interiores decorados con palmetas esquemáticas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42036','iglesia','Iglesia de la Virgen del Cardo','Templo parroquial del siglo XVII ejecutado en mampostería basta y sillarejo de refuerzo en los vanos, con un interior sobrio que alberga un coro alto de madera y un retablo mayor barroco exento de decoración áurea.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42037','iglesia','Iglesia de la Asunción de Nuestra Señora','Fábrica renacentista del siglo XVI construida en aparejo mixto de mampostería caliza y ladrillo, rematada por una espadaña de dos cuerpos decrecientes con vanos de medio punto para voltear las campanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42038','iglesia','Iglesia de San Juan Bautista','Modesta construcción del siglo XVI en mampostería caliza calavera con esquinas de sillería regular, provista de una portada purista de arco de medio punto bajo pórtico protegido y una pila bautismal medieval.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42039','iglesia','Iglesia de la Asunción','Edificio monumental del siglo XVI edificado en regular sillería de piedra arenisca y caliza, con planta de cruz latina y una gran torre','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42042','iglesia','Iglesia de la Asunción','Templo barroco del siglo XVII edificado en mampostería con contrafuertes de cantería, cuya portada principal exhibe un arco sencillo de medio punto moldurado orientado al mediodía bajo tejaroz de teja árabe.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42043','monumento','Núcleos de población de Burgo de Osma-Ciudad de Osma','El término municipal incluye los siguientes núcleos de población: Alcubilla del Marqués, Barcebalejo, Lodares de Osma, Valdegrulla y Torralba de Osma.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42043','catedral','Catedral de la Asunción (El Burgo de Osma)','Magna basílica gótica iniciada en 1232 en sillería caliza calavera sobre el templo románico previo, célebre por su claustro flamígero del siglo XVI, una imponente torre barroca de 72 metros diseñada por Domingo de Ondátegui y el sepulcro románico de San Pedro de Osma.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42043','monumento','Castillo de Osma','Inmensa fortaleza roquera de origen califal de los siglos X y XI reconstruida en sillería y','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42043','monumento','Antiguo Hospital de San Agustín','Espléndido edificio civil barroco edificado entre 1694 y 1699 en sillería caliza regular, que presenta una fachada monumental flanqueada por dos torres herrerianas y una portada con el escudo de armas del obispo fundador.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42043','monumento','Universidad de Santa Catalina','Edificio plateresco del siglo XVI construido por orden del obispo Pedro Álvarez de Acosta en sillería caliza, que destaca por su monumental portada renacentista con pilastras esculpidas y un gran patio central claustral de dos pisos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42043','monumento','Murallas del Burgo de Osma','Recinto fortificado medieval del siglo XV construido en cantería y mampostería compacta por el obispo Pedro de Montoya, del cual se conservan notables lienzos almenados y la monumental Puerta de San Miguel.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42044','iglesia','Iglesia de San Juan Bautista','Fábrica de finales del siglo XVI ejecutada en mampostería caliza con sillares de refuerzo en los ángulos, que cuenta con una espadaña de dos vanos escalonados en el imafronte y un interior de nave única.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42045','iglesia','Iglesia de San Millán','Edificio renacentista del siglo XVI construido en sillería y mampostería caliza, notable por su presbiterio poligonal reforzado por potentes estribos y una torre campanario robusta sujeta por contrafuertes angulares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42045','monumento','Castillo de Cabrejas','Restos de una fortaleza medieval del siglo XIV levantada en mampostería basta sobre una peña calcárea, de la que subsisten lienzos de muralla desmochados y la base de una torre cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42046','monumento','Núcleos de población de Calatañazor','El término municipal incluye los siguientes núcleos de población: Aldehuela de Calatañazor y Monasterio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42046','monumento','Castillo de Calatañazor','Fortaleza medieval de los siglos XIV y XV levantada en sillería y mampostería caliza sobre un espolón rocoso, de la que subsiste la imponente torre del homenaje con saeteras y lienzos de la muralla perimetral con foso natural.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42046','iglesia','Iglesia de Nuestra Señora del Castillo','Templo con orígenes románicos del siglo XII modificado en los siglos XVI y XVIII en cantería bien escuadrada, que mantiene una portada meridional románica de arquivoltas lobuladas y un notable retablo mayor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42046','ermita','Ermita de la Soledad','Construcción románica del siglo XII edificada en sillería caliza calavera a las afueras de la villa, caracterizada por su ábside semicircular perfecto con canecillos decorados con motivos geométricos y zoomorfos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42046','monumento','Entramado Urbano y Casas Con Chimenea Cónica','Conjunto histórico de arquitectura popular medieval construido en mampostería caliza, entramado de madera de sabina y revoco de barro, coronado por colosales chimeneas pinariegas cónicas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42048','monumento','Núcleos de población de Caltojar','El término municipal incluye los siguientes núcleos de población: Bordecorex y Casillas de Berlanga.','inventario_monumentos_pdf');
