INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42048','ermita','Ermita de San Baudelio de Berlanga (Casillas de Berlanga)','Joya excepcional de la arquitectura mozárabe del siglo XI levantada en sillería y sillarejo calizo, universal por su pilar central en forma de palmera del que arrancan ocho arcos de herradura y sus restos de pinturas murales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42048','iglesia','Iglesia de San Miguel (Bordecorex)','Fábrica románica del siglo XII construida en sillería regular, singular por su ábside semicircular con ventanales abocinados y una torre defensiva adosada sobre el presbiterio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42049','monumento','Núcleos de población de Candilichera','El término municipal incluye los siguientes núcleos de población: Carazuelo, Fuentetecha y Fuensaúco.','inventario_monumentos_pdf');
