INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42049','iglesia','Iglesia de Nuestra Señora de los Ángeles (Fuensaúco)','Notable edificio románico rural del siglo XII levantado en cantería basta caliza, que conserva su ábside semicircular original con canecillos lisos y una espadaña de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42050','iglesia','Iglesia de San Juan Bautista','Templo del siglo XVI edificado en mampostería caliza con esquinas de sillería bien labrada, caracterizado por su presbiterio de planta rectangular reforzado por estribos oblicuos y su pila bautismal románica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42051','iglesia','Iglesia de San Martín','Obra barroca del siglo XVII ejecutada en aparejo toledano combinando bandas de ladrillo macizo y cajones de mampostería basta, con un interior sobrio que alberga un coro alto de madera con zapatas talladas.','inventario_monumentos_pdf');
