INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42052','iglesia','Iglesia de Santa María','Templo románico de transición del siglo XII construido en sillería caliza calavera, que mantiene su ábside semicircular con saeteras abocinadas y capiteles interiores decorados con palmetas y motivos geométricos cistercienses.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42053','monumento','Núcleos de población de Carrascosa de Abajo','El término municipal incluye los siguientes núcleos de población: Pozuelo.','inventario_monumentos_pdf');
