INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42054','monumento','Rollo-Picota de Justicia','Monumento exento de estilo plateresco del siglo XVI labrado en piedra caliza, compuesto por una basa moldurada, fuste cilíndrico estriado y un remate decorado con cuatro canes tallados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42055','iglesia','Iglesia de San Ildefonso','Edificio renacentista del siglo XVI ejecutado en regular sillería calcárea con recios contrafuertes exteriores, caracterizado por su interior de nave única cubierta con bóveda de crucería estrellada y nervaduras de sillar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42056','iglesia','Iglesia de la Asunción','Templo fortificado de transición del gótico al renacimiento del siglo XVI en sillería de cantería regular arenisca, notable por sus grandes proporciones, una torre campanario robusta exenta de vanos y potentes contrafuertes.','inventario_monumentos_pdf');
