INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42063','iglesia','Iglesia de la Virgen de la Blanca','Templo del siglo XVI levantado en regular sillería de arenisca, con un presbiterio cubierto por una techumbre de madera de tradición mudéjar y una pila bautismal románica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42064','monumento','Castillo de Ciria','Espectacular fortaleza roquera medieval del siglo XIV levantada en mampostería y sillería caliza sobre un cerro escarpado, caracterizada por sus potentes lienzos de cortina almenados provistos de numerosas saeteras.','inventario_monumentos_pdf');
