INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42065','iglesia','Iglesia de la Virgen del Rosario','Templo parroquial del siglo XVII edificado mediante mampostería de pizarra','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42068','monumento','Núcleos de población de Coscurita','El término municipal incluye los siguientes núcleos de población: Centenera del Campo, Neguillas y Villalba.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42068','iglesia','Iglesia de San Miguel (Coscurita)','Obra barroca del siglo XVII ejecutada en aparejo toledano combinando hiladas de ladrillo macizo y cajones de mampostería basta, con una torre campanario baja y un arco triunfal de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42069','iglesia','Iglesia de San Quirico y Santa Julita','Magna edificación renacentista del siglo XVI construida en excelente sillería arenisca roja por los maestros de la escuela de cantería pinariega, notable por sus grandes proporciones y bóvedas de crucería estrellada.','inventario_monumentos_pdf');
