INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42070','iglesia','Iglesia de San Pedro','Pequeño oratorio de planta rectangular en mampostería vista y sillares de refuerzo','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42071','monumento','Núcleos de población de Cubo de la Solana','El término municipal incluye los siguientes núcleos de población: Almarail, Ituero, Lubia y Rabanera del Campo.','inventario_monumentos_pdf');
