INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42073','iglesia','Iglesia de la Asunción','Templo del siglo XVI levantado en piedra arenisca del Moncayo, caracterizado por sus paramentos de mampostería gruesa y una torrecampanario de planta cuadrangular adosada al presbiterio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42075','iglesia','Iglesia de la Virgen del Patrocinio','Fábrica barroca del siglo XVIII con planta de cruz latina construida en sillarejo calizo, cuya cabecera se cubre con cúpula sobre pechinas decorada con yeserías de la época.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42075','palacio','Palacio de los Condes de Villarrea','Residencia señorial del siglo XVI en piedra de sillería bien escuadrada, que presenta una portada adintelada con alfiz heráldico y ventanas molduradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42076','monumento','Núcleos de población de Deza','El término municipal incluye los siguientes núcleos de población: La Miñosa y Miñana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42076','iglesia','Iglesia de Nuestra Señora de la Asunción','Monumental edificio gótico-renacentista del siglo XVI construido en excelente sillería regular caliza, notable por sus grandes dimensiones, contrafuertes exteriores cilíndricos y amplias bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42076','palacio','Palacio de los Duques de Medinaceli','Residencia señorial del siglo XVI edificada en regular cantería caliza, que exhibe una fachada monumental de estilo renacentista con patio porticado interior de dos pisos sobre columnas toscanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42078','iglesia','Iglesia de San Miguel Arcángel','Templo que conserva vestigios mozárabes del siglo X y reformas góticorenacentistas del siglo XVI en sillería arenisca, célebre por albergar en su entorno una necrópolis altomedieval con tumbas antropomorfas excavadas en roca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42079','monumento','Núcleos de población de Escobosa de Almazán','El término municipal incluye los siguientes núcleos de población: Velilla de los Ajos y Saelices.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42079','iglesia','Iglesia de San Juan Bautista','Edificación renacentista del siglo XVI levantada en aparejo de sillarejo calizo con esquinas reforzadas, destacando su ábside de testero plano y una espadaña de dos cuerpos rematada por frontón clasicista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42080','monumento','Núcleos de población de Espeja de San Marcelino','El término municipal incluye los siguientes núcleos de población: Guijosa, Orillares, Quintanilla de Nuño Pedro y La Hinojosa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42080','iglesia','Iglesia de San Marcelino (Espeja de San Marcelino)','Templo gótico tardío del siglo XVI edificado en regular sillería caliza, notable por su ábside poligonal con contrafuertes y un interior con bóvedas de crucería estrellada de fina labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42080','iglesia','Convento de Jerónimos de Espeja (Guijosa)','Ruinas de un monasterio del siglo XV construido en sillería y mampostería, del que subsisten los potentes paramentos de la iglesia conventual y el arranque de sus arcos fajones apuntados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42081','iglesia','Iglesia de la Asunción','Fábrica de transición renacentista del siglo XVI ejecutada en sillería caliza compacta extraída de las canteras locales de mármol, caracterizada por su presbiterio cuadrangular y una robusta torre campanario sujeta por contrafuertes angulares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42082','iglesia','Iglesia de San Esteban','Modesta construcción rural de origen románico reformada en el siglo XVII en mampostería caliza basta, que mantiene una espadaña exenta en el hastial occidental y una pila bautismal monolítica medieval.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42083','iglesia','Iglesia de la Virgen de la Antigua','Templo parroquial del siglo XVII levantado con aparejo mixto de piedra caliza del terreno y sillarejo, con una planta rectangular de nave única con coro de madera y viguería de pino vista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42084','iglesia','Iglesia de la Virgen de la Asunción','Edificio de filiación románica del siglo XII modificado en el siglo XVI en cantería bien escuadrada, que conserva su ábside semicircular con canecillos lisos y una portada meridional de arquivoltas simples de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42085','monumento','Núcleos de población de Fuentearmegil','El término municipal incluye los siguientes núcleos de población: Fuencaliente del Burgo, Santervás del Burgo y Langa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42085','iglesia','Iglesia de San Andrés (Fuentearmegil)','Fábrica renacentista de grandes dimensiones del siglo XVI construida en sillería caliza regular, provista de un presbiterio poligonal reforzado por estribos y un interior con notables retablos barrocos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42085','iglesia','Monasterio de San Cristóbal (Fuencaliente del Burgo)','Restos del cenobio medieval del siglo XII ejecutado en sillería y mampostería, del que perviven paramentos de la iglesia abacial con ventanas saeteras y contrafuertes oblicuos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42086','monumento','Núcleos de población de Fuentecambrón','El término municipal incluye los siguientes núcleos de población: Cenegro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42086','iglesia','Iglesia de la Asunción','Templo de origen románico rural del siglo XII reformado en el siglo XVIII mediante fábrica de mampostería caliza basta, del que sobresale su portada meridional exenta de decoración con arquivoltas de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42087','iglesia','Iglesia de San Miguel','Estructura de arquitectura popular castellana del siglo XVII levantada en aparejo de canto rodado y sillarejo, rematada por una modesta espadaña de dos vanos y un porche sencillo de acceso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42088','iglesia','Iglesia de Nuestra Señora de la Asunción','Fábrica del siglo XVI edificada en regular sillería arenisca, caracterizada por su presbiterio poligonal reforzado por potentes estribos y una torre campanario robusta sujeta por contrafuertes angulares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42090','monumento','Núcleos de población de Fuentepinilla','El término municipal incluye los siguientes núcleos de población: Osona y Valderrueda.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42090','iglesia','Iglesia de San Juan Bautista (Fuentepinilla)','Templo románico de finales del siglo XII reformado en el siglo XVI en cantería regular caliza, sobresaliente por su magnífica portada meridional románica de arquivoltas profusamente decoradas con motivos geométricos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42090','palacio','Palacio de los Condes de Aguilar','Residencia señorial del siglo XVI edificada en excelente sillería caliza, que presenta una fachada monumental de estilo renacentista con portada adintelada y escudo heráldico moldurado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40088','iglesia','Iglesia de San Bernardo','Modesta fábrica del siglo XVII construida en mampostería calcárea y sillarejo, con tejado a dos aguas y una espadaña exenta en el hastial oriental provista de dos troneras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42092','iglesia','Iglesia de la Inmaculada Concepción','Templo del siglo XVI levantado en aparejo de sillarejo calizo, caracterizado por su presbiterio de planta rectangular y una espadaña de tres vanos en el hastial occidental de tradición serrana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42093','iglesia','Iglesia de San Juan Bautista','Fábrica de finales del siglo XVI ejecutada en mampostería caliza con refuerzo','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42094','monumento','Núcleos de población de Garray','El término municipal incluye los siguientes núcleos de población: Dombellas, Tardesillas, Canredondo de la Sierra y Santervás de la Sierra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42094','monumento','Yacimiento Arqueológico de Numancia','Colosal conjunto arqueológico de la célebre ciudad celtíbera y romana excavado sobre el cerro de la Muela, que conserva tramos de muralla celtibérica de piedra seca, aljibes, plantas de viviendas rectangulares y el trazado de las calles romanas porticadas con los característicos pasos de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42094','ermita','Ermita de los Santos Mártires','Joya del románico soriano del siglo XII erigida en sillería regular caliza, célebre por su equilibrada planta rectangular con ábside semicircular y una espléndida portada meridional de arquivoltas bellamente esculpidas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42094','iglesia','Iglesia de San Juan Bautista (Dombellas)','Templo renacentista del siglo XVI construido en sillería caliza, provisto de un presbiterio poligonal reforzado por estribos oblicuos y una notable pila bautismal románica troncocónica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42095','monumento','Núcleos de población de Golmayo','El término municipal incluye los siguientes núcleos de población: Camparañón, Carbonera de Frentes, Fuentetovar, La Cuenca, Las Casas y Nódalo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42095','iglesia','Iglesia de San Juan Bautista (Golmayo)','Fábrica renacentista del siglo XVI levantada en sillería caliza calavera y mampostería, notable por su ábside poligonal con bóvedas de crucería y una portada meridional plateresca con grutescos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42095','monumento','Conjunto Etnográfico de La Cuenca','Casco urbano de arquitectura popular serrana excelentemente conservado, configurado por viviendas del siglo XVIII edificadas en mampostería caliza calavera, entramado de madera y espectaculares chimeneas cónicas pinariegas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42096','monumento','Núcleos de población de Gómara','El término municipal incluye los siguientes núcleos de población: Abión, Paredesroyas, Tapiela y Torralba de Fuentes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42096','iglesia','Iglesia de San Juan Bautista','Magna edificación del siglo XVI con trazas de estilo gótico tardío y renacentista ejecutada en sillería regular caliza, singular por su esbelta torre-campanario de tres cuerpos decrecientes y un sotocoro sostenido por un gran arco escarzano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42096','palacio','Palacio de los Condes de Gómara','Casona noble señorial del siglo XVI construida en excelente sillería arenisca, mostrando una fachada monumental con escudo heráldico moldurado y balconadas de forja artística sobre repisas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42097','monumento','Fortaleza Califal de Gormaz','La mayor fortaleza medieval de Europa, erigida en el siglo X por Al-Hakam II en excelente sillería caliza regular sobre una cresta rocosa inexpugnable, monumental por su perímetro amurallado de 1.200 metros jalonado por 28 torres califales, la monumental Puerta Califal con arco de herradura alfizdo, el alcázar y una colosal alberca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42097','ermita','Ermita de San Miguel','Joya excepcional del románico inicial del siglo XI construida en sillería y sillarejo calizo, universal por albergar en su interior un valiosísimo','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42098','iglesia','Iglesia de la Asunción de Nuestra Señora','Fábrica del siglo XVI integrada en la comarca de Pinares, armada con gruesos muros de piedra calcárea e hiladas de sillarejo regular, provista de una portada de medio punto y una espadaña de dos vanos en el hastial occidental.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42100','iglesia','Iglesia de Nuestra Señora de la Asunción','Extraordinario templo fortificado que integra dos recias torres de origen bereber del siglo X construidas en mampostería gruesa caliza, enlazadas por muros barrocos del siglo XVIII y un presbiterio con arco triunfal clasicista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42103','monumento','Núcleos de población de Langa de Duero','El término municipal incluye los siguientes núcleos de población: Alcozar, Bocigas de Perales, Valdanzo, Valdanzuelo y Zayas de Torre.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42103','monumento','Torre del Homenaje o del Cubo','Esbelta fortificación bajomedieval del siglo XV levantada en sillería caliza calavera y sillarejo sobre el cerro que domina la villa, estructurada en planta cuadrada con saeteras, ladroneras defensivas y remate almenado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42103','iglesia','Iglesia de San Miguel Arcángel (Langa de Duero)','Fábrica monumental gótico-renacentista del siglo XVI edificada en excelente cantería, notable por su ábside poligonal con contrafuertes oblicuos y un interior cubierto por complejas bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42103','iglesia','Iglesia de San Esteban Protomártir (Alcozar)','Ruinas de un templo románico del siglo XII edificado en sillería, del cual subsiste una galería porticada meridional con arquerías de medio punto tapiadas y capiteles decorados con motivos vegetales esquemáticos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42103','monumento','Puente Medieval sobre el río Duero','Gran estructura de ingeniería civil de origen medieval reformada en los siglos XVII y XVIII en sillería caliza compacta, compuesta por doce ojos con arcos de medio punto y apuntados provistos de potentes tajamares triangulares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42105','monumento','Atalaya de las Tiendas','Torre vigía circular de origen califal del siglo X ejecutada en mampostería basta de piedra caliza trabada con argamasa de cal, conservada íntegra en su alzado con acceso en altura para garantizar su inexpugnabilidad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42105','iglesia','Iglesia de la Invención de la Santa Cruz','Templo renacentista del siglo XVI levantado en aparejo mixto de sillería y sillarejo calcáreo, provisto de una espadaña barroca escalonada y un presbiterio poligonal reforzado exteriormente por estribos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42107','monumento','Núcleos de población de Magaña','El término municipal incluye los siguientes núcleos de población: Pantiñano y Villarraso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42107','monumento','Castillo de Magaña','Espectacular fortaleza bajomedieval del siglo XV mandada erigir por los condes de Miranda en excelente sillería de piedra arenisca y caliza, que destaca por su colosal torre del homenaje de planta cuadrada de origen bereber del siglo X y su doble recinto amurallado jalonado por torres cilíndricas con saeteras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42107','iglesia','Iglesia de San Andrés','Fábrica del gótico tardío del siglo XVI construida en sillarejo calcáreo con refuerzos de sillería en los ángulos, que presenta una nave única rematada por un ábside poligonal con bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42108','iglesia','Iglesia de la Purísima Concepción','Templo rural barroco del siglo XVIII ejecutado en aparejo de mampostería basta del terreno con esquinas de piedra labrada, dotado de un interior sobrio de planta rectangular con artesonado de madera vista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42110','monumento','Núcleos de población de Matalebreras','El término municipal incluye los siguientes núcleos de población: Montenegro de Ágreda.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42110','iglesia','Iglesia de San Pedro Apóstol','Edificio del siglo XVI levantado en sillería arenisca y mampostería regular, caracterizado por su presbiterio poligonal reforzado por contrafuertes y su esbelta torre-campanario de dos cuerpos con vanos de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42111','monumento','Núcleos de población de Matamala de Almazán','El término municipal incluye los siguientes núcleos de población: Matute de Almazán, Santa María de Huerta y Villalba.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42111','iglesia','Iglesia de la Inmaculada Concepción (Matamala)','Fábrica barroca del siglo XVII construida en mampostería caliza, dotada de una torre-campanario exenta de planta cuadrada con vanos moldurados y un interior cubierto por bóveda de lunetos ciegos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42113','monumento','Núcleos de población de Medinaceli','El término municipal incluye los siguientes núcleos de población: Ambrona, Azcamellas, Beltéjar, Benamira, Blocona, Esteras de Medinaceli, Fuencaliente de Medinaceli, Lodares, Salinas de Medinaceli, Torralba del Moral y Ventosa del Ducado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42113','monumento','Arco Romano de Medinaceli','Monumento universal de la ingeniería civil romana del siglo I, único en España por su estructura monumental de triple arcada labrada en gruesos sillares de sillería caliza compacta colocados a hueso, erigido como hito fronterizo e indicador de rango de la ciudad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42113','palacio','Palacio Ducal de Medinaceli','Magna residencia renacentista construida en el siglo XVI según trazas de Juan de Herrera en sillería caliza calavera, provista de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42113','iglesia','Colegiata de Nuestra Señora de la Asunción','Templo de proporciones monumentales del gótico tardío del siglo XVI edificado en excelente cantería, célebre por albergar una espaciosa nave única con bóvedas de crucería nervada, la cripta con el panteón de los duques de Medinaceli y la talla medieval del Cristo de Medinaceli.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42113','monumento','Castillo de Medinaceli','Ruinas de la fortaleza medieval del siglo XIV construida sobre el antiguo alcázar árabe en mampostería basta caliza con esquinas de sillería regular, de la que subsisten tres recios torreones cilíndricos y tramos del recinto amurallado perimetral.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42113','monumento','Plaza Mayor y Alhóndiga','Conjunto urbanístico monumental porticado del siglo XVI constituido por hileras de columnas de cantería y arcos de medio punto de sillería caliza que sostienen el edificio municipal y las viviendas nobiliarias tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42113','monumento','Yacimiento Paleontológico de Ambrona','Estación arqueológica y paleontológica del Pleistoceno Medio que conserva in situ una de las mayores concentraciones mundiales de restos de fauna fósil de elefantes antiguos (Elephas antiquus) asociados a industria lítica achelense.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42115','monumento','Núcleos de población de Miño de Medinaceli','El término municipal incluye los siguientes núcleos de población: Ambrona, Conquezuela, Ventosa del Ducado y Yelo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42115','iglesia','Iglesia de San Miguel (Miño de Medinaceli)','Templo románico del siglo XII levantado en regular cantería caliza, del que destaca su ábside semicircular con saeteras abocinadas y una hermosa portada meridional de tres arquivoltas decoradas con baquetones.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42115','ermita','Ermita de la Santa Cruz (Conquezuela)','Singular santuario rupestre románico del siglo XII emplazado bajo un colosal abrigo rocoso calizo, cuyos muros de mampostería cierran una cueva natural que presenta grabados e inscripciones rupestres de la Edad del Bronce.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42119','monumento','Núcleos de población de Monteagudo de las Vicarías','El término municipal incluye los siguientes núcleos de población: Valtueña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42119','monumento','Castillo de Altamira','Imponente fortaleza-palacio del siglo XV erigida por los Mendoza en excelente sillería caliza calavera, señera por su gran patio de armas central perimetrado por una elegante galería renacentista de tres pisos decorada con arquerías de fina tracería gótico-plateresca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42119','iglesia','Iglesia de Nuestra Señora de la Muela','Templo monumental de transición del gótico al renacimiento del siglo XVI edificado en regular sillería, que destaca por su imponente fachada fortificada, sus bóvedas de crucería estrellada y un valioso retablo mayor pictórico de la escuela aragonesa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42119','monumento','Murallas y Puerta de la Villa','Conjunto amurallado bajomedieval del siglo XIV construido en cantería y sillarejo, del que se conserva intacta la monumental puerta de acceso bajo arco apuntado flanqueada por potentes torreones defensivos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42121','iglesia','Iglesia de San Martín','Fábrica de tradición barroca del siglo XVIII edificada en sillería de piedra arenisca y sillarejo calcáreo, notable por su gran torre-campanario','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42121','ermita','Ermita de San Mamés','Pequeña construcción románica del siglo XII labrada en cantería rústica, caracterizada por albergar en su ábside semicircular restos de pinturas murales medievales de labra popular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42123','monumento','Plaza Mayor de Morón de Almazán','Excepcional conjunto urbanístico renacentista diseñado en el siglo XVI en magnífica sillería caliza, que agrupa armónicamente la iglesia de la Asunción, el Palacio de los Mendoza y el Rollo jurisdiccional en una composición monumental de primer orden nacional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42123','iglesia','Iglesia de Nuestra Señora de la Asunción','Magna edificación renacentista del siglo XVI cuya soberbia torre campanario de estilo plateresco, diseñada por Juan de Rasines, está considerada una de las obras cumbre de la arquitectura renacentista soriana por su profusa ornamentación escultórica de grutescos y relieves.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42123','monumento','Rollo-Picota de Justicia','Monumento exento de estilo plateresco del siglo XVI labrado en piedra caliza calavera, constituido por un graderío circular sobre el que se asienta un fuste estriado rematado por cuatro saledizos en forma de gárgolas zoomorfas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42124','iglesia','Iglesia de San Nicolás','Templo de origen románico modificado en el siglo XVI en cantería caliza, que mantiene su ábside de testero plano y una hermosa pila','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42125','iglesia','Iglesia de la Asunción','Obra rural de la comarca de Pinares del siglo XVI erigida en mampostería tosca de caliza y esquinas de sillería bien labrada, rematada por una espadaña de dos vanos escalonados orientada a poniente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42127','monumento','Núcleos de población de Nafría de Ucero','El término municipal incluye los siguientes núcleos de población: Rejas de Ucero, Valdelubia y Beltejar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42127','iglesia','Iglesia de San Antón','Fábrica de origen románico del siglo XII con sustanciales reformas clasicistas en el siglo XVII ejecutadas en mampostería caliza, de la que pervive su cabecera rectangular original y una pila bautismal monolítica decorada con sogueado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42128','iglesia','Iglesia de San Juan Bautista','Templo del gótico tardío del siglo XVI edificado en regular sillería y mampostería caliza calavera, provisto de una esbelta torre campanario de planta cuadrada y un interior cubierto por bóvedas de crucería de fina labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42129','iglesia','Iglesia de San Esteban Protomártir','Edificio de la comarca pinariega erigido en el siglo XVI y ampliado en el siglo XVIII en excelente sillería de piedra arenisca roja, dotado de un presbiterio con arco triunfal de medio punto y una robusta torre campanario de paramentos ciegos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42132','monumento','Torreón Árabe de Noviercas','Excepcional torrefortaleza de origen islámico del siglo X construida en sillería caliza compacta y mampostería gruesa, universal por su perfecto estado de conservación formal con planta rectangular de veinte metros de alzado y saeteras en altura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42132','iglesia','Iglesia de los Santos Justo y Pastor','Templo monumental de transición renacentista-barroca del siglo XVII edificado en excelente cantería caliza regular, provisto de una amplia nave única con cúpula sobre pechinas en el crucero y portadas clasicistas molduradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41007','monumento','Núcleos de población de Ólvega','El término municipal incluye los siguientes núcleos de población: Muro de Ágreda y Montenegro de Cameros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41007','iglesia','Iglesia de Santa María la Mayor','Magna fábrica del siglo XVI proyectada con trazas renacentistas en excelente sillería de piedra arenisca del Moncayo, notable por sus grandes proporciones, un imponente presbiterio poligonal con contrafuertes y un colosal retablo mayor renacentista de tres cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41007','iglesia','Iglesia de San Pedro Apóstol (Muro de Ágreda)','Edificación del románico rural soriano del siglo XII construida sobre restos de la muralla romana en cantería caliza calavera, que mantiene su ábside semicircular con ventanas abocinadas y capiteles de labra vegetal esquemática.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42135','monumento','Núcleos de población de Oncala','El término municipal incluye los siguientes núcleos de población: San Andrés de San Pedro, El Collado y Navabellida.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42135','iglesia','Iglesia de San Millán','Templo del siglo XVIII erigido bajo el mecenazgo del arzobispo Juan Francisco Ximénez del Río en sillería caliza de estilo neoclásico academicista, universal por albergar en su interior una valiosísima colección de ocho tapices flamencos del siglo XVII sobre cartones de Rubens.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42139','iglesia','Iglesia de la Asunción','Templo de origen románico modificado en el siglo XVI mediante fábrica de mampostería caliza y sillarejo, que mantiene su ábside de testero plano y una severa portada de medio punto con dovelas regulares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42140','iglesia','Iglesia de San Juan Bautista','Estructura rural barroca del siglo XVII ejecutada en aparejo tosco de piedra calcárea, caracterizada por su planta rectangular de nave única con coro de madera y una modesta espadaña de dos vanos en el hastial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42142','iglesia','Iglesia de Santa María la Mayor','Fábrica del gótico tardío y transición renacentista del siglo XVI erigida en sillería caliza, notable por su ábside poligonal con bóvedas nervadas y por conservar empotrado un miliario romano de la vía que unía Astorga con Zaragoza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42144','monumento','Núcleos de población de Quintana Redonda','El término municipal incluye los siguientes núcleos de población: Fuentelárbol, Las Cuevas de Soria, Izana y Monasterio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42144','monumento','Yacimiento de la Villa Romana de Las Cuevas de Soria','Espectacular asentamiento rural bajoimperial de los siglos III y IV de gran envergadura, compuesto por un gran patio porticado y más de treinta habitaciones cubiertas con magníficos pavimentos de mosaico polícromo con motivos geométricos y vegetales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42144','iglesia','Iglesia de la Asunción (Quintana Redonda)','Edificio singular del siglo XVIII construido en cantería caliza con una inusual planta central octogonalizada, rematado por una linterna superior y decoración clasicista en sus paramentos interiores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42145','iglesia','Iglesia de San Lorenzo','Fábrica renacentista del siglo XVI levantada en sillería caliza y sillarejo frente a la vega del Duero, dotada de una torre campanario robusta sujeta por contrafuertes angulares y una portada de líneas clásicas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42148','iglesia','Iglesia de la Virgen de la Asunción','Edificación religiosa del siglo XVII levantada en mampostería tosca de caliza con refuerzo de bloques de cantería en las esquinas, estructurada en una sola nave con presbiterio elevado y arco de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10154','iglesia','Iglesia Parroquial de Santa Catalina','Sencillo edificio rural del siglo XVI levantado en el Valle del Jerte con paramentos encalados de mampostería y piedra rústica que presenta una modesta espadaña de ladrillo visto situada a los pies de la nave única.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42152','monumento','Núcleos de población de Recuerda','El término municipal incluye los siguientes núcleos de población: Galapagares, La Perera, Nograles y Quintanilla de Tres Barrios.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42152','monumento','Atalaya de Quintanilla de Tres Barrios','Excepcional torre vigía circular de origen islámico del siglo X construida en sillería caliza compacta y mampostería regular, que conserva casi intacto su alzado cilíndrico con una puerta de acceso abierta en altura para garantizar su defensa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42154','monumento','Núcleos de población de Renieblas','El término municipal incluye los siguientes núcleos de población: Fuensaúco y Ventosilla de San Juan.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42154','monumento','Campamentos Romanos de Renieblas (Gran Atalaya)','Inmenso conjunto arqueológico militar de época republicana que abarca cinco campamentos romanos superpuestos construidos en aparejo de piedra seca caliza entre los siglos II y I a.C., claves en el asedio a Numancia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42154','iglesia','Iglesia de Nuestra Señora de la Cruz (Renieblas)','Fábrica de origen románico del siglo XII sustancialmente modificada en el siglo XVI en sillería y mampostería, de la que sobrevive su ábside semicircular con saeteras abocinadas y capiteles románicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42155','monumento','Núcleos de población de Retortillo de Soria','El término municipal incluye los siguientes núcleos de población: Cañicera, Madruédano, Modamio, Sauquillo de Paredes, Tarancueña, Torrevicente y Valvenedizo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42155','monumento','Murallas de Retortillo de Soria y Puerta de la Villa','Conjunto fortificado medieval del siglo XIV construido en cantería y sillarejo calizo, del que destaca su monumental puerta de acceso abierta bajo un gran arco apuntado flanqueado por lienzos almenados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42155','iglesia','Iglesia de San Pedro (Retortillo de Soria)','Fábrica monumental de transición del gótico al renacimiento del siglo XVI en regular sillería, notable por su ábside de testero plano reforzado por contrafuertes oblicuos y un interior cubierto con bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42155','iglesia','Iglesia de San Juan Bautista (Madruédano)','Sobresaliente edificio del románico rural soriano del siglo XII edificado en excelente cantería caliza regular, célebre por conservar intacta su galería porticada meridional con arquerías de medio punto sobre columnas pareadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42156','iglesia','Iglesia de la Virgen de la Asunción','Templo de finales del siglo XVI edificado en mampostería caliza con contrafuertes exteriores de cantería, rematado por una torre campanario robusta de planta cuadrangular provista de dos vanos moldurados para voltear las campanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42158','monumento','Yacimiento de la Villa Romana de Los Quintanares','Importante asentamiento agrícola bajoimperial de los siglos III y IV de la que se documentan las trazas de su zona residencial con espléndidos mosaicos polícromos geométricos conservados in situ.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42158','iglesia','Iglesia de San Juan Bautista','Templo del siglo XVI levantado en regular cantería caliza, provisto de un presbiterio poligonal reforzado por estribos angulares y una portada de líneas clasicistas bajo pórtico protegido por tejaroz.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42159','iglesia','Iglesia de San Sebastián','Edificación parroquial del siglo XVI ejecutada en mampostería caliza calavera con esquinas de sillería bien labrada, rematada por una espadaña de dos cuerpos decrecientes dispuesta sobre el muro occidental de los pies.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42160','monumento','Núcleos de población de El Royo','El término municipal incluye los siguientes núcleos de población: Derroñadas, Hinojosa de la Sierra, Langosto y Vilviestre de los Nabos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42160','palacio','Castillo-Palacio de los Hurtado de Mendoza (Hinojosa de la Sierra)','Suntuosa residencia señorial fortificada del siglo XV en excelente sillería arenisca, que destaca por su gran fachada renacentista con escudo heráldico moldurado y ventanas góticas geminadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42160','iglesia','Iglesia de Nuestra Señora de la Asunción (El Royo)','Magna construcción renacentista del siglo XVI levantada en sillería regular caliza por los maestros de la escuela pinariega, singular por sus amplias dimensiones y bóvedas de crucería estrellada de finísima labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42161','iglesia','Iglesia de San Juan Bautista','Fábrica del siglo XVI ejecutada en sillería de piedra arenisca roja pinariega, que destaca por su ábside de traza poligonal reforzado exteriormente por contrafuertes angulares y una portada meridional clasicista de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42162','monumento','Núcleos de población de San Esteban de Gormaz','El término municipal incluye los siguientes núcleos de población: Atauta, Ines, Olmillos, Piquera de San Esteban, Quintanilla de Tres Barrios, Rejas de San Esteban, Soto de San Esteban, Torraño, Torrecilla de San Esteban, Velilla de San Esteban y Villálvaro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42162','iglesia','Iglesia de San Miguel','Obra cumbre de la arquitectura románica peninsular del siglo XI (año 1081) construida en excelente sillería caliza regular, universal por poseer la galería porticada románica más antigua conservada en España con arquerías de medio punto apoyadas sobre capiteles historiados de influencia califal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42162','iglesia','Iglesia de Nuestra Señora del Rivero','Templo románico monumental del siglo XII edificado en excelente cantería caliza sobre un promontorio, célebre por su soberbia galería porticada meridional con arquerías de medio punto, capiteles con ricas representaciones zoomorfas y una nave única cubierta con armadura de madera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42162','monumento','Castillo de San Esteban de Gormaz','Ruinas de la colosal fortaleza fronteriza de origen califal del siglo X (la "Fuerza de San Esteban") levantada en mampostería gruesa y sillería a hueso, de la que subsiste un larguísimo lienzo de muralla desmochada ("el paredón") sobre la cresta rocosa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42162','iglesia','Iglesia de San Martín (Rejas de San Esteban)','Templo del románico rural soriano del siglo XII edificado en sillería caliza calavera, provisto de una magnífica galería porticada que rodea los muros sur y oeste con arcos de medio punto sobre capiteles decorados con motivos vegetales y geométricos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42162','monumento','Puente Medieval sobre el río Duero','Gran estructura de ingeniería civil medieval de origen romano reformada en el siglo XVI en sillería caliza compacta, constituida por dieciséis ojos con arcos de medio punto y apuntados provistos de potentes tajamares triangulares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42163','iglesia','Iglesia de San Pedro Apóstol','Fábrica renacentista del siglo XVI levantada en aparejo de sillarejo calizo con esquinas de sillería de refuerzo, que cuenta con una esbelta torre campanario de planta cuadrangular adosada al hastial de los pies del templo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42164','monumento','Castillo de San Leonardo','Extraordinario ejemplo de fortaleza abaluartada del Renacimiento construida en 1563 por Juan Manrique de Lara en excelente sillería caliza regular, pionera en España por su planta rectangular con cuatro baluartes angulares diseñados específicamente para resistir los ataques del fuego artillero moderno.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42164','iglesia','Iglesia de San Leonardo','Magna edificación de transición renacentista-herreriana de finales del siglo XVI levantada en regular cantería caliza, notable por la severa desnudez decorativa de su fachada simétrica y un espacioso interior cubierto con bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42165','monumento','Núcleos de población de San Pedro Manrique','El término municipal incluye los siguientes núcleos de población: Sarnago, Valdenegrillos, Taniñe y Ventosa de San Pedro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42165','monumento','Castillo de San Pedro Manrique','Ruinas monumentales de una fortaleza bajomedieval del siglo XV erigida en sillería caliza calavera y mampostería regular, caracterizada por su imponente silueta flanqueada por dos espectaculares torres de entrada de planta poligonal con matacanes defensivos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42165','iglesia','Ruinas de la Iglesia de San Miguel','Restos arqueológicos de un gran templo de origen románico del siglo XII modificado en el gótico, del que subsisten los potentes muros perimetrales de mampostería caliza, las arquerías apuntadas del presbiterio y una hermosa pila bautismal monolítica medieval.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42165','ermita','Ermita de la Virgen de la Peña','Edificio barroco del siglo XVIII construido en aparejo mixto de piedra caliza basta y sillarejo, universal por celebrarse en su recinto exterior el ancestral rito del "Paso del Fuego" durante las fiestas de San Juan.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42166','monumento','Núcleos de población de Santa Cruz de Yanguas','El término municipal incluye los siguientes núcleos de población: Villarijo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42166','iglesia','Iglesia de la Trinidad','Fábrica de tradición barroca del siglo XVII plenamente integrada en la arquitectura de la Sierra de Cameros, levantada con gruesos paramentos de lajas de pizarra rústica y sillarejo calcáreo con un interior de nave única de gran sobriedad estructural.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42167','iglesia','Monasterio de Santa María de Huerta','Magna obra cumbre del monacato cisterciense en España fundado en el siglo XII por Alfonso VIII y edificado en magnífica','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42168','iglesia','Iglesia de la Asunción de Nuestra Señora','Edificio parroquial renacentista del siglo XVI construido en sillería y mampostería caliza regular, que presenta una cabecera poligonal reforzada por estribos oblicuos y un interior cubierto por una techumbre de madera de tradición pinariega.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42171','monumento','Castillo de Serón de Nágima','Singular fortaleza de origen mudéjar construida en el siglo XIV de forma atípica mediante la técnica del tapial de arcilla y mampostería basta revestida, de la que subsisten imponentes lienzos desmochados y la estructura cuadrangular de sus torres esquineras con saeteras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42171','iglesia','Iglesia de Nuestra Señora de la Asunción','Templo monumental del siglo XVI edificado en regular sillería caliza y arenisca, provisto de una esbelta torre campanario de tres cuerpos decrecientes y un interior gótico tardío con bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42172','monumento','Núcleos de población de Soliedra','El término municipal incluye los siguientes núcleos de población: Borchicayada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42172','iglesia','Iglesia de la Asunción','Fábrica del siglo XVI reformada en el barroco empleando mampostería caliza, dotada de una torre campanario baja y un presbiterio con arco triunfal de medio punto moldurado que da acceso a una cabecera cuadrada de gran sencillez espacial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42173','monumento','Núcleos de población de Soria','El término municipal incluye los siguientes núcleos de población: Las Casas, Oteruelos, Pedraza y Toledillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42173','iglesia','Monasterio de San Juan de Duero','Joya excepcional del románico universal del siglo XII levantada en sillería caliza por la Orden de los Hospitalarios a orillas del Duero, célebre por su espectacular claustro a cielo abierto cuyos arcos entrelazados, túmidos y apuntados','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42173','catedral','Concatedral de San Pedro','Magna basílica del gótico plateresco iniciada en el siglo XVI en excelente cantería caliza regular, que destaca por su espacioso interior de tres naves a igual altura con bóvedas de crucería estrellada y, de forma sobresaliente, por conservar el monumental claustro románico del siglo XII del antiguo cenobio con arquerías de medio punto profusamente historiadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42173','iglesia','Iglesia de Santo Domingo','Obra cumbre de la escultura románica española de finales del siglo XII construida en sillería caliza, célebre internacionalmente por su fachada monumental cuya portada presenta cuatro arquivoltas profusamente labradas con escenas bíblicas, un gran pantócrator central en el tímpano y un magnífico rosetón calado superior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42173','iglesia','Iglesia de San Juan de Rabanera','Sobresaliente templo del románico tardío de influjo bizantino del siglo XII ejecutado en sillería bien escuadrada, notable por su original ábside semicircular exterior jalonado por pilastras estriadas y una portada meridional románica de arquivoltas lobuladas traída desde la desaparecida iglesia de San Nicolás.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42173','palacio','Palacio de los Condes de Gómara','El edificio civil renacentista más monumental de la ciudad, construido entre 1577 y 1592 en magnífica sillería de cantería caliza regular, célebre por su inmensa fachada asimétrica presidida por una imponente torre cuadrangular, una gran portada heráldica y una elegante galería porticada de dobles arquerías toscanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42173','ermita','Ermita de San Saturio','Pintoresco santuario barroco edificado a finales del siglo XVII en cantería caliza calavera, colgado de forma inverosímil sobre un espolón rocoso calizo del desfiladero del Duero, cuyo interior se asienta sobre una cueva natural eremítica y alberga','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42175','iglesia','Iglesia de El Salvador','Templo del siglo XVI edificado en sillería caliza y mampostería regular, caracterizado por su presbiterio de planta rectangular reforzado por potentes estribos oblicuos y una espadaña de tres vanos en el hastial occidental de tradición serrana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42176','iglesia','Iglesia de Nuestra Señora de la Asunción','Templo que integra una esbelta atalaya defensiva de origen califal del siglo X construida en mampostería gruesa caliza calavera, adosada a una estructura parroquial reformada en el siglo XVI con presbiterio plano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42177','iglesia','Iglesia de San Pedro Apóstol','Fábrica renacentista del siglo XVI edificada en sillarejo calizo con contrafuertes angulares de sillería regular, notable por su portada meridional de líneas clasicistas y una pila bautismal románica decorada con gallones.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42178','monumento','Núcleos de población de Talveila','El término municipal incluye los siguientes núcleos de población: Cantalucía y Fuentearmegil.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42178','iglesia','Iglesia de San Miguel (Talveila)','Edificación de tradición pinariega reconstruida en el siglo XVIII en sillería arenisca y mampostería, dotada de una torre campanario baja y paramentos ciegos de gran robustez estructural.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42181','monumento','Núcleos de población de Tardelcuende','El término municipal incluye los siguientes núcleos de población: Cascajosa y Osonilla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42181','iglesia','Iglesia de San Pedro Apóstol (Tardelcuende)','Templo renacentista del siglo XVI levantado en regular cantería caliza, provisto de una espaciosa nave única con capillas hornacinas entre los contrafuertes y bóvedas de crucería estrellada en la cabecera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42182','iglesia','Iglesia de San Esteban Protomártir','Fábrica del siglo XVI con importantes modificaciones barrocas en el siglo XVIII ejecutada en mampostería y sillería, que destaca por su presbiterio poligonal y un retablo mayor barroco con columnas salomónicas talladas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37319','monumento','Núcleos de población de El Tejado','El término municipal incluye los siguientes núcleos de población: Alparrache, Castillazuelo, Nódalo, Villanueva de Zamajón y Zamajón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37319','monumento','Castillo de Castillazuelo','Ruinas fortificadas de una casa-fuerte bajomedieval del siglo XV levantada en mampostería caliza basta y sillarejo, de la que subsisten potentes lienzos de muralla desmochados y la base de una torre del homenaje cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37319','iglesia','Iglesia de Santa María la Mayor (Tejado)','Templo renacentista del siglo XVI edificado en regular sillería caliza, que cuenta con una robusta torre campanario adosada al imafronte y un interior cubierto por bóvedas de crucería nervada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42184','iglesia','Iglesia de Santiago Apóstol','Fábrica del siglo XVI ejecutada en mampostería de piedra arenisca y caliza local, caracterizada por su presbiterio de planta rectangular reforzado exteriormente por estribos y una modesta espadaña de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42185','iglesia','Iglesia de la Asunción de Nuestra Señora','Modesta construcción rural barroca del siglo XVII levantada con aparejo tosco de piedra caliza, provista de una espadaña exenta en el hastial occidental y un pórtico de acceso protegido por tejaroz.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19285','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo del siglo XVI levantado con el tradicional aparejo de mampostería encintada y contrafuertes de sillería caliza calavera en sus esquinales que alberga una nave única con cubiertas de madera de tradición mudéjar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42188','monumento','Torreón de Trévago','Imponente torre-fortaleza de origen bereber del siglo X construida en sillería caliza regular y mampostería compacta, que destaca por conservar íntegro su alzado cuadrangular de veinte metros con saeteras y acceso en altura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42188','iglesia','Iglesia de Nuestra Señora de la Asunción','Fábrica renacentista del siglo XVI levantada en sillería y mampostería caliza, dotada de un interior de tres naves separadas por pilares cilíndricos y una notable portada renacentista clasicista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42189','monumento','Castillo de Ucero','Imponente fortaleza bajomedieval del siglo XIV erigida en sillería caliza regular sobre un espolón rocoso inexpugnable dominando el río Lobos, célebre por su monumental torre del homenaje que','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42189','ermita','Ermita de San Bartolomé','Joya del románico tardío de principios del siglo XIII vinculada a la Orden del Temple y enclavada en el cañón del río Lobos, construida en cantería caliza calavera con planta de cruz latina, magníficos canecillos historiados y ventanales con rosetones calados de influencia mística.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42190','iglesia','Iglesia de la Natividad de Nuestra Señora','Fábrica renacentista del siglo XVI levantada en excelente sillería de piedra arenisca de la comarca de Pinares, caracterizada por su ábside de planta poligonal con estribos angulares y una portada de líneas clasicistas bajo arco de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42192','iglesia','Iglesia de la Virgen de la Asunción','Edificación religiosa del siglo XVII levantada en mampostería caliza calavera y sillarejo en las esquinas, dotada de una nave','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42193','iglesia','Iglesia de la Magdalena','Templo barroco del siglo XVII ejecutado en aparejo de mampostería basta calcárea con refuerzos de piedra labrada en los vanos, caracterizado por su espadaña escalonada de piedra dispuesta sobre el hastial occidental.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42194','monumento','Núcleos de población de Valdemaluque','El término municipal incluye los siguientes núcleos de población: Sotos del Burgo, Valdelubia y Valero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42194','iglesia','Iglesia de San Miguel (Valdemaluque)','Templo del siglo XVI edificado en sillería y mampostería caliza, provisto de una cabecera poligonal y una hermosa pila bautismal románica troncocónica decorada con sogueado y gallones en su base.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42195','iglesia','Iglesia de la Virgen de la Asunción','Modesta fábrica rural del siglo XVI levantada en aparejo de sillarejo calizo, con portada simple de medio punto protegida por un pequeño soportal sobre postes de madera y una espadaña de dos cuerpos decrecientes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42196','monumento','Núcleos de población de Valdeprado','El término municipal incluye los siguientes núcleos de población: Castillejo de San Pedro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42196','iglesia','Iglesia de San Pedro','Edificio integrado en la arquitectura serrana de las Tierras altas del siglo XVI, construido con gruesos paramentos de lajas de pizarra rústica y argamasa, rematado por una espadaña de pizarra de dos vanos escalonados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42197','iglesia','Iglesia de la Virgen de la Asunción','Templo de filiación románica tardía del siglo XIII profundamente remodelado en el siglo XVI con cantería caliza, del que sobrevive su ábside semicircular con canecillos lisos bajo la cornisa del alero y una pila bautismal medieval.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42198','iglesia','Iglesia Fortificada de Nuestra Señora de la Asunción','Excepcional y único ejemplar de iglesia-fortaleza románica del siglo XII labrada en regular cantería caliza compacta, universal por conservar intacto su remate perimetral defensivo compuesto por almenas falsas, saeteras y una imponente espadaña fortificada de tres vanos dispuesta a modo de torre del homenaje.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42200','monumento','Núcleos de población de Velamazán','El término municipal incluye los siguientes núcleos de población: Rebollo de Duero y Fuentetovar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42200','iglesia','Iglesia de la Santa Cruz (Velamazán)','Templo renacentista del siglo XVI construido en excelente sillería caliza, dotado de un interior de tres naves separadas por','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42200','monumento','Atalaya de Fuentetovar','Torre vigía de planta circular de origen islámico del siglo X ejecutada en mampostería basta de piedra caliza compacta con mortero de cal, que mantiene su fisonomía cilíndrica defensiva dominando la vega.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42201','iglesia','Iglesia de San Juan Bautista','Estructura de arquitectura popular castellana del siglo XVI levantada en aparejo de canto rodado y sillarejo, rematada por una modesta espadaña de dos vanos en la fachada occidental y un pórtico simple de acceso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42202','iglesia','Iglesia de San Pedro Apóstol','Fábrica barroca del siglo XVII construida mediante aparejo de mampostería caliza y sillarejo calavera en los ángulos de refuerzo, que alberga en su presbiterio un arco triunfal clasicista moldurado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42204','iglesia','Iglesia de San Bartolomé','Fábrica renacentista de finales del siglo XVI ejecutada en mampostería caliza con sillares de cantería regular en las esquinas, notable por su ábside de paños con contrafuertes y un interior cubierto por bóvedas de crucería nervada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42205','monumento','Núcleos de población de Villaciervos','El término municipal incluye los siguientes núcleos de población: Villacierbitos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42205','iglesia','Iglesia de San Blas (Villaciervos)','Edificio renacentista del siglo XVI edificado en regular sillería y mampostería caliza, caracterizado por su presbiterio de planta rectangular reforzado por estribos oblicuos y su pila bautismal románica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42206','iglesia','Iglesia de la Virgen de la Asunción','Templo parroquial de finales del siglo XVI ejecutado en mampostería caliza basta calavera frente a la vega del Duero, dotado de una portada simple de medio punto con dovelas regulares y una espadaña de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42207','iglesia','Iglesia de San Juan Bautista','Fábrica del siglo XVI integrada en el entorno serrano, armada con gruesos muros de piedra calcárea del terreno y sillarejo, rematada por una espadaña de dos cuerpos decrecientes dispuesta sobre el muro de los pies.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42208','iglesia','Iglesia de la Virgen del Rosario','Templo rural barroco del siglo XVII que utiliza mampostería basta de arcilla y','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42209','monumento','Núcleos de población de Villar del Río','El término municipal incluye los siguientes núcleos de población: Bretún, La Lago, Diustes, Huérteles, Valdelavilla, Villar de Maya y Villaseca de San Pedro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42209','monumento','Yacimiento de Icnitas de Bretún','Célebre estación paleontológica que conserva espectaculares huellas fosilizadas de dinosaurios y reptiles del Cretácico Inferior sobre estratos de calizas, destacando los rastros de terópodos y ornitópodos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42209','iglesia','Iglesia de la Virgen de la Asunción (Villar del Río)','Fábrica del siglo XVI de proporciones monumentales levantada en regular cantería caliza, notable por su gran torre campanario de planta cuadrangular y un interior de tres naves.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42212','monumento','Núcleos de población de Villasayas','El término municipal incluye los siguientes núcleos de población: Fuentegelmes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42212','iglesia','Iglesia de la Virgen de la Asunción (Villasayas)','Extraordinario templo románico de finales del siglo XII labrado en excelente cantería caliza regular, célebre por conservar intacta su galería porticada meridional con arquerías de medio punto apoyadas sobre columnas pareadas con capiteles decorados con motivos vegetales y zoomorfos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42213','iglesia','Iglesia de San Juan Bautista','Fábrica de finales del siglo XVI ejecutada en mampostería caliza calavera con','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42215','iglesia','Iglesia de Nuestra Señora del Pino','Magna edificación gótico-renacentista del siglo XVI proyectada con trazas monumentales en sillería de piedra arenisca roja por maestros de la escuela de cantería pinariega, célebre por sus amplias proporciones, contrafuertes cilíndricos y espectaculares bóvedas de crucería estrellada de finísima labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42215','palacio','Palacio de los Marqueses de Vilueña','Espléndida casona señorial del siglo XVII construida en regular sillería arenisca, que exhibe una fachada monumental de estilo barroco herreriano con un colosal blasón heráldico moldurado sobre la portada adintelada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42215','monumento','Puente Romano sobre el río Duero','Restos monumentales de una estructura de ingeniería civil romana del siglo I construida en sillería regular colocada a hueso, visible en épocas de estiaje en el lecho del embalse de la Cuerda del Pozo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42218','monumento','Núcleos de población de Yanguas','El término municipal incluye los siguientes núcleos de población: Ligos, Diustes y Vellosillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42218','monumento','Castillo de Yanguas','Fortaleza bajomedieval de los siglos XIV y XV de clara influencia mudéjar construida en lajas de pizarra rústica y mampostería basta unida con argamasa de cal, estructurada con una planta cuadrangular reforzada por cuatro espectaculares torres cuadradas provistas de saeteras defensivas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42218','monumento','Torre de San Miguel','Esbelta atalaya románica exenta del siglo XII labrada en magnífica sillería de piedra arenisca compacta, único vestigio de una desaparecida iglesia medieval, notable por sus tres cuerpos decrecientes decorados con arquillos ciegos lombardos y ventanales geminados abocinados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42218','iglesia','Iglesia de San Lorenzo','Fábrica gótica del siglo XV levantada en sillarejo de pizarra y esquinas de cantería caliza regular, cuyo interior destaca por albergar el valioso e histórico archivo de los arrieros y nobles de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42218','monumento','Continuar con la Provincia de Toledo','Continuar con la Provincia de Toledo (Letra T)','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42218','monumento','Continuar con la Provincia de Valladolid','Continuar con la Provincia de Valladolid (Letra V)','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90283','monumento','Torre Vieja de Ababuj','Atalaya defensiva de origen bajomedieval del siglo XIV levantada en sillería caliza compacta y mampostería regular, que conserva su alzado cuadrangular de paramentos ciegos provistos de saeteras y un acceso original dispuesto en altura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90283','iglesia','Iglesia de Santa Ana','Fábrica del siglo XVI reformada en el período barroco en mampostería basta del terreno, estructurada en una sola nave cubierta por bóveda de crucería estrellada con nervaduras de sillar bien labrado en el presbiterio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90284','iglesia','Iglesia de San Agustín','Templo barroco del siglo XVIII construido en aparejo mixto de sillarejo calizo calavera y mampostería, dotado de una torre campanario adosada de tres cuerpos decrecientes y un interior con bóveda de cañón con lunetos ciegos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90285','iglesia','Iglesia de El Salvador','Edificación parroquial del siglo XVII levantada en mampostería tosca de caliza con','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90286','iglesia','Iglesia de San Lorenzo','Templo monumental barroco del siglo XVII edificado en sillería y mampostería caliza, que destaca por su fachada con portada-retablo churrigueresca moldurada en cantería y una esbelta torre campanario de tres cuerpos con remate octogonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90287','iglesia','Iglesia de la Virgen del Rosario','Fábrica del gótico tardío del siglo XVI construida en sillarejo calcáreo con esquinas de sillería de refuerzo, notable por su ábside poligonal cubierto por complejas bóvedas de crucería estrellada de fina labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14001','iglesia','Iglesia de la Asunción de Nuestra Señora','Edificio barroco del siglo XVIII levantado en aparejo toledano combinando hiladas de ladrillo macizo y cajones de mampostería, rematado por una gran cúpula sobre crucero y una torre campanario adosada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90288','iglesia','Iglesia de la Invención de la Santa Cruz','Templo del siglo XVI edificado en mampostería con esquinas de sillería regular, caracterizado por su presbiterio de planta poligonal con contrafuertes oblicuos exteriores y un retablo mayor clasicista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90289','palacio','Castillo-Palacio Episcopal','Magna fortaleza gótica de los siglos XIII y XIV erigida en sillería caliza compacta por orden de los arzobispos de Zaragoza, célebre por su monumental residencia palatina con ventanales de fina tracería gótica y una torre mudéjar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90289','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI construido en cantería y ladrillo, notable por su gran torre campanario de estilo mudéjar-renacentista decorada con paños de arquerías ciegas y frisos de esquinillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90290','iglesia','Iglesia de Nuestra Señora de los Ángeles','Fábrica monumental del gótico tardío del siglo XVI levantada en sillería regular caliza, provista de un presbiterio poligonal reforzado por potentes estribos y una portada renacentista plateresca moldurada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43002','monumento','Castillo de los Calatravos','Inmensa fortaleza de la Orden de Calatrava de los siglos XII al XIV edificada en excelente sillería caliza regular, célebre por albergar una','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43002','iglesia','Iglesia de Santa María la Mayor','Magna basílica del siglo XVIII proyectada con dimensiones catedralicias en sillería caliza regular, que destaca por su colosal fachada-retablo barroca de tres cuerpos profusamente esculpida y una gran torre campanario gótica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43002','monumento','Lonja Gótica y Casa Consistorial','Espectacular conjunto civil renacentista y gótico de los siglos XV y XVI tallado en piedra de sillería bien escuadrada, singular por sus grandes arquerías apuntadas caladas y una fachada palaciega plateresca con columnillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44014','iglesia','Iglesia de Santa María la Mayor','Templo barroco de grandes proporciones del siglo XVII erigido en sillería caliza regular, célebre por su imponente torre campanario mudéjar de ladrillo vista decorada con paños de rombos y fajas decorativas decrecientes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44022','iglesia','Iglesia de la Concepción','Fábrica renacentista del siglo XVI levantada en aparejo mixto de sillería y ladrillo, caracterizada por su presbiterio poligonal con bóvedas de crucería estrellada y un sotocoro sostenido por un gran arco escarzano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44023','iglesia','Iglesia de San Luis','Modesto oratorio rural del siglo XVII construido en mampostería basta de piedra caliza, con tejado a dos aguas y una espadaña de dos cuerpos decrecientes dispuesta sobre el hastial de los pies del templo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44024','iglesia','Iglesia de San Bartolomé','Templo parroquial barroco del siglo XVII ejecutado en aparejo toco de arcilla y sillarejo calcáreo, que alberga una nave única con coro de madera y viguería de pino serrano vista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44025','iglesia','Iglesia de la Natividad de Nuestra Señora','Edificio renacentista del siglo XVI de grandes dimensiones en sillería caliza regular, notable por su cabecera de paños con contrafuertes oblicuos exteriores y un interior con arcos formeros apuntados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44026','monumento','Salinas de Arcos','Conjunto etnográfico e industrial de origen romano y medieval modificado en el siglo XVIII, compuesto por albercas de evaporación de madera, canales de distribución de salmuera y almacenes monumentales de cantería caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44027','iglesia','Iglesia de la Asunción de Nuestra Señora','Fábrica monumental gótica del siglo XIV en excelente sillería de piedra arenisca regular, dotada de un interior de nave única cubierta por bóvedas de crucería y una portada meridional de arquivoltas apuntadas de fina labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44028','iglesia','Iglesia de la Inmaculada Concepción','Templo renacentista del siglo XVI levantado en aparejo de mampostería con esquinas de sillería bien labrada, rematado por una torre campanario baja y un presbiterio con arco triunfal de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44029','iglesia','Iglesia de El Salvador','Obra barroca del siglo XVIII ejecutada en ladrillo y mampostería caliza calavera, singular por su esbelta torre campanario que combina un primer cuerpo cuadrangular de piedra con cuerpos superiores ochavados de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44031','monumento','Yacimiento del Cabezo de Alcalá','Espectacular conjunto arqueológico de una ciudad celtíbera, ibérica y romana excavado sobre un cerro, que conserva tramos de murallas de piedra seca, una acrópolis fortificada, cisternas monumentales y el trazado de las calles porticadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44032','iglesia','Iglesia de la Asunción','Estructura de arquitectura popular del siglo XVII levantada en aparejo mixto de arcilla y sillarejo, rematada por una modesta espadaña de dos vanos y un pórtico sencillo de madera de pino.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44033','iglesia','Iglesia de la Asunción de Nuestra Señora','Fábrica barroca del siglo XVII cuya imponente torre campanario mudéjar, labrada en ladrillo vista sobre zócalo de piedra, está considerada una obra cumbre por sus relieves geométricos de tradición islámica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44034','iglesia','Iglesia de San Juan Bautista','Templo renacentista del siglo XVI construido en sillarejo calizo con contrafuertes exteriores, provisto de un presbiterio de planta rectangular y una portada de líneas clásicas bajo arco adintelado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44035','iglesia','Iglesia de la Asunción de Nuestra Señora','Edificación barroca del siglo XVII levantada en mampostería caliza, dotada de una torre campanario de tres cuerpos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44036','iglesia','Iglesia de San Bartolomé','Modesta construcción rural del siglo XVII edificada en piedra basta del terreno con esquinas de piedra labrada, caracterizada por su planta rectangular unicelular con tejado a dos aguas de teja árabe.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44037','iglesia','Iglesia de San Bartolomé','Magna fábrica barroca del siglo XVIII ejecutada en excelente cantería caliza regular, notable por su monumental portada-retablo flanqueada por columnas salomónicas profusamente esculpidas y un espacioso interior de tres naves.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44037','monumento','Puente Medieval sobre el río Matarraña','Estructura monumental de ingeniería civil del siglo XII levantada en sillería compacta, constituida por un gran ojo central apuntado de tradición románica tardía y potentes tajamares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44039','iglesia','Iglesia de la Natividad de Nuestra Señora','Templo del siglo XVI edificado en regular sillería de arenisca, con un presbiterio cubierto por una techumbre de madera de tradición mudéjar y una pila bautismal medieval monolítica de labra popular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44038','iglesia','Iglesia de El Salvador','Templo barroco del siglo XVIII construido en excelente sillería caliza regular, que destaca por su fachada clasicista de tres cuerpos moldurados y una colosal torre campanario exenta de paramentos ciegos en su base.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44040','iglesia','Iglesia de San Pedro Apóstol','Fábrica del siglo XVII ejecutada en mampostería caliza con refuerzo de sillares en las esquinas, caracterizada por su presbiterio poligonal reforzado exteriormente por estribos oblicuos de cantería regular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44041','iglesia','Iglesia de la Visitación','Edificación rústica del siglo XVII levantada en sillería de piedra arenisca de rodeno rojo pinariego, provista de una espadaña de dos vanos escalonados en el imafronte occidental y nave única.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44043','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo barroco del siglo XVIII en mampostería y ladrillo, célebre por su gran torre campanario que combina zócalo pétreo','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44044','iglesia','Iglesia de la Virgen de la Carrasca','Fábrica de origen templario del siglo XIV reformada en el gótico tardío en sillería caliza, universal por conservar en sus paramentos interiores un magnífico ciclo completo de pinturas murales góticas y barrocas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44045','iglesia','Iglesia de la Asunción','Templo del siglo XVI edificado en regular sillería arenisca en plena Sierra de Albarracín, dotado de un interior de tres naves separadas por pilares cilíndricos y cubiertas por viguería de madera de pino vista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44046','monumento','Castillo de Bueña','Ruinas fortificadas de una fortaleza medieval del siglo XIV levantada en mampostería caliza basta sobre un cerro, de la que subsisten los potentes lienzos de una robusta torre del homenaje cuadrangular de carácter fronterizo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44047','iglesia','Iglesia de la Asunción','Fábrica barroca del siglo XVIII levantada en sillería y ladrillo vista, notable por su esbelta torre campanario de tres cuerpos decrecientes y un interior con crucero cubierto por gran cúpula sobre pechinas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44050','monumento','Núcleos de población de Calamocha','El término municipal incluye los siguientes núcleos de población: Collados, Cuencabuena, El Poyo del Cid, Langa del Castillo, Luco de Jiloca, Navarrete del Río, Olalla, Pelarda, Valverde y Villarejo de los Olmos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44050','iglesia','Iglesia de Santa María la Mayor (Calamocha)','Magna edificación barroca del siglo XVIII construida en sillería caliza y ladrillo vista, célebre por su esbelta torre campanario de planta cuadrada que evoluciona a cuerpos superiores octogonales decorados con azulejería polícroma mudéjar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44050','monumento','Puente Romano de Luco de Jiloca','Excepcional obra de ingeniería civil del alto imperio romano edificada en colosales sillares de piedra caliza colocados a hueso, conservando tres de sus arcos de medio punto originales y potentes tajamares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44050','iglesia','Iglesia de la Asunción (Luco de Jiloca)','Fábrica mudéjar del siglo XVI levantada en ladrillo sobre zócalo de cantería, cuya espectacular torre campanario exhibe','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44050','monumento','Yacimiento de El Poyo del Cid','Asentamiento fortificado con niveles celtibéricos y medievales vinculados a las campañas de Rodrigo Díaz de Vivar, caracterizado por sus potentes fosos y cimentaciones de piedra seca en la meseta del cerro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44051','iglesia','Templo del Pilar','Monumental edificio barroco edificado entre los siglos XVII y XVIII en sillería y ladrillo vista, dotado de una imponente fachada neoclásica de orden gigante, una gran cúpula central sobre pechinas y un espacioso interior de tres naves.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44051','iglesia','Iglesia de Nuestra Señora de la Esperanza','Fábrica renacentista-barroca del siglo XVII erigida en regular cantería caliza, que destaca por su ábside poligonal de cinco paños y una robusta torre campanario de tres cuerpos decrecientes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44052','iglesia','Iglesia de San Pedro Apóstol','Fábrica rústica de la Sierra de Albarracín del siglo XVII construida en sillería de piedra arenisca roja (pétreo rodeno) y mampostería basta, provista de una nave única con coro alto de madera tallada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44053','ermita','Ermita de la Virgen del Consuelo','Edificio de origen románico modificado en el gótico tardío del siglo XIV levantado en mampostería caliza regular, que destaca por albergar una techumbre de madera mudéjar con tabicas pintadas de gran valor iconográfico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44054','iglesia','Iglesia de San Mateo','Fábrica barroca del siglo XVIII edificada en sillería y sillarejo calcáreo a los pies de la Sierra de Javalambre, notable por su gran torre campanario de tres cuerpos con vanos moldurados y un interior cubierto por bóveda de lunetos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44055','iglesia','Santuario de la Virgen del Campo','Complejo barroco del siglo XVIII en sillería regular caliza, que consta de una monumental iglesia con cúpula gallonada y una espectacular torre campanario exenta de estilo mudéjarbarroco exornada con ladrillo moldurado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44056','monumento','Núcleos de población de Caminreal','El término municipal incluye los siguientes núcleos de población: Villalba de los Morales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44056','monumento','Yacimiento de La Caridad','Espectacular asentamiento urbano de época ibero-romana del siglo II a.C., que destaca por conservar la planta completa de una gran casa de tipo itálico con pavimentos de mosaico polícromo de tipo opus signinum.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44056','iglesia','Iglesia de San Roque','Fábrica barroca del siglo XVIII levantada en sillería y ladrillo, provista de una esbelta','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44059','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo barroco de proporciones catedralicias construido en el siglo XVIII por el arquitecto Antonio Nadal en excelente sillería caliza, célebre por su monumental portada clasicista cobijada bajo pórtico y un interior de tres naves a igual altura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44059','monumento','Conjunto de la Plaza de Cristo Rey','Espectacular espacio urbanístico gótico fortificado perimetrado por la Casa Consistorial del siglo XVI con grandes arquerías apuntadas de sillería y los soportales tradicionales de las casonas nobles de la Orden de San Juan.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44059','monumento','Castillo de Cantavieja','Ruinas de la fortaleza templaria y carlista levantada sobre un espolón rocoso inexpugnable en mampostería basta, de la que subsisten torreones cilíndricos angulares, tramos de murallas almenadas y el primitivo torreón del homenaje.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44060','monumento','Conjunto de la Plaza Mayor y Hospital de Pobres','Complejo arquitectónico civil del siglo XVI en sillería caliza calavera, constituido por la Casa Consistorial de tres arcos de medio punto sobre pilares macizos y el antiguo hospital con ventanales platerescos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44060','iglesia','Iglesia de la Asunción','Ruinas monumentales de un gran templo barroco del siglo XVIII edificado en cantería','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44062','iglesia','Iglesia de la Asunción','Templo renacentista del siglo XVI construido en sillarejo calizo con contrafuertes oblicuos exteriores, dotado de un presbiterio plano y una portada meridional purista de arco de medio punto flanqueada por pilastras planas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44064','iglesia','Iglesia de San Nicolás de Bari','Templo de origen gótico modificado en el siglo XVII levantado en mampostería y sillarejo, que conserva su portada meridional de arquivoltas apuntadas y una nave única con capillas laterales entre contrafuertes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44065','iglesia','Iglesia de la Asunción de Nuestra Señora','Obra barroca del siglo XVII ejecutada en aparejo de mampostería basta calcárea y sillarejo, rematada por una modesta torre campanario adosada al hastial occidental con dos vanos moldurados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44066','iglesia','Iglesia de la Asunción','Edificación religiosa de transición renacentista del siglo XVI levantada en sillarejo con esquinas de cantería regular, que alberga un coro alto a los pies soportado por un gran arco escarzano de cantería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44067','iglesia','Iglesia de la Inmaculada Concepción','Templo del siglo XVII edificado en aparejo mixto de ladrillo macizo y cajones de mampostería basta caliza, dotado de una portada clasicista adintelada flanqueada por pilastras planas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44068','iglesia','Iglesia de la Natividad de Nuestra Señora','Fábrica barroca del siglo XVIII construida en excelente sillería caliza regular, notable por su monumental portadaretablo churrigueresca profusamente esculpida y un espacioso interior cubierto por bóvedas de cañón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44068','monumento','Puente sobre el río Guadalope','Estructura de ingeniería civil de origen medieval reformada en el siglo XVII en cantería caliza compacta, formada por cinco grandes ojos con arcos de medio punto provistos de recios tajamares triangulares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44071','monumento','Núcleos de población de Castellote','El término municipal incluye los siguientes núcleos de población: Abenfigfig, Dos Torres de Mercader, Ladruñán, Las Cuevas de Caartas, Luco de Bordón y Santolea.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44071','monumento','Castillo de Castellote','Colosal fortaleza de la Orden del Temple del siglo XII levantada sobre una abrupta cresta caliza inexpugnable, de la que subsiste la imponente torre del homenaje gótica con muros de sillería de tres metros de espesor y lienzos de muralla jalonados por saeteras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44071','iglesia','Iglesia de San Miguel','Magna edificación gótica del siglo XIV erigida en sillería caliza regular, célebre por su monumental rosetón calado en la fachada occidental, su','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44071','monumento','Torre de los Templarios o del Torrejón','Estructura defensiva exenta de planta cuadrangular bajomedieval construida en cantería caliza compacta, que formaba parte del sistema de acceso fortificado a la villa histórica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44074','monumento','Castillo de Cedrillas','Ruinas de una fortaleza medieval del siglo XIV levantada en mampostería caliza sobre un cerro escarpado, de la que se conserva un larguísimo perímetro amurallado jalonado por torres cuadrangulares y la base de su torre del homenaje.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44074','iglesia','Iglesia de El Salvador','Templo del gótico tardío del siglo XVI edificado en sillería caliza regular, notable por su presbiterio poligonal reforzado por estribos oblicuos exteriores y un interior cubierto con bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44075','iglesia','Iglesia de Santo Domingo de Silos','Fábrica monumental de transición gótico-renacentista del siglo XVI levantada en cantería caliza regular, notable por su ábside de testero plano con contrafuertes y un interior cubierto con complejas bóvedas de crucería de fina labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44076','monumento','Fuente de Cella','Monumental pozo artesiano —el más grande de Europa— modificado en el siglo XII y ornamentado en el siglo XVIII mediante un colosal pretil perimetral de sillería caliza regular diseñado por el ingeniero Domingo de Ondátegui.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44076','iglesia','Iglesia de la Inmaculada Concepción','Templo monumental del gótico tardío del siglo XVI edificado en excelente cantería caliza, provisto de una esbelta torre campanario de tres cuerpos decrecientes y un interior de tres naves con bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44112','iglesia','Iglesia de San Pedro Apóstol','Fábrica renacentista del siglo XVI levantada en sillería caliza y mampostería regular, que destaca por su recia torre campanario adosada que integra elementos fortificados y un interior cubierto con bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44086','iglesia','Iglesia de la Asunción de Nuestra Señora','Fábrica gótico-renacentista del siglo XVI diseñada por las escuelas del Maestrazgo en excelente sillería caliza compacta, notable por su imponente fachada fortificada de corte militar y su nave única con complejas bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44087','iglesia','Iglesia de San Juan Bautista','Templo barroco de finales del siglo XVII erigido en mampostería caliza y ladrillo vista, caracterizado por su portada clasicista moldurada de medio punto y una torre campanario adosada con cuerpos superiores octogonales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44088','iglesia','Iglesia de San Nicolás de Bari','Edificación parroquial de transición renacentista del siglo XVI levantada en sillería y mampostería caliza, provista de una nave única con cabecera de paños protegida por robustos estribos exteriores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44094','iglesia','Iglesia de San Juan Evangelista','Fábrica del siglo XVI reformada en el barroco empleando mampostería caliza','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44100','iglesia','Monasterio del Olivar','Complejo cenobítico de la Orden de la Merced fundado en el siglo XIII y reconstruido en los siglos XVI y XVII en excelente sillería caliza regular, célebre por su iglesia gótico-renacentista con bóvedas de crucería y su sobrio claustro alto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44101','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo parroquial barroco del siglo XVII ejecutada en aparejo de sillarejo calcáreo con refuerzos de piedra labrada en los vanos, rematada por una espadaña de dos cuerpos decrecientes dispuesta sobre los pies.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44102','iglesia','Iglesia de San Miguel','Estructura de arquitectura popular del siglo XVII levantada con aparejo mixto de arcilla y mampostería basta, rematada por una modesta espadaña de dos vanos en la fachada occidental de tradición serrana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44103','monumento','Núcleos de población de Formiche Alto','El término municipal incluye los siguientes núcleos de población: Formiche Bajo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44103','iglesia','Iglesia de la Asunción (Formiche Alto)','Fábrica del siglo XVI con importantes modificaciones barrocas en el siglo XVIII ejecutada en mampostería y sillería, que destaca por su presbiterio poligonal y una robusta torre campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44105','iglesia','Iglesia de la Asunción de Nuestra Señora','Magna edificación gótica del siglo XIV en excelente sillería de piedra arenisca regular, singular por poseer una de las torres campanario barrocas más esbeltas del Matarraña construida sobre los arcos apuntados del porche.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44106','iglesia','Iglesia de la Purificación de Nuestra Señora','Magna obra monumental del barroco del siglo XVIII diseñada en excelente sillería caliza regular, provista de una suntuosa nave única de proporciones academicistas cubiertas por bóvedas de cañón con lunetos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44106','palacio','Palacio de los Duques de San Fernando o Casa de los Daudén','Espléndida residencia señorial renacentista del siglo XVI en excelente sillería, que exhibe una fachada de corte clasicista con alero de madera tallada y una ventana plateresca moldurada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44107','iglesia','Iglesia de San Juan Bautista','Templo renacentista del siglo XVI edificado en regular sillería caliza calavera, caracterizado por su presbiterio de planta rectangular reforzado por estribos oblicuos y su pila bautismal románica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44109','iglesia','Iglesia de la Asunción','Edificación rústica del siglo XVII levantada en sillería de piedra arenisca de rodeno rojo, provista de una nave única con cabecera de paños y una robusta torre campanario de planta cuadrangular adosada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44110','iglesia','Iglesia de San Blas','Fábrica barroca del siglo XVII construida en aparejo de mampostería vasta caliza con esquinas de sillería de refuerzo, que alberga un coro alto de madera tradicional de pino y un arco triunfal moldurado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44113','iglesia','Iglesia de Nuestra Señora de los Ángeles','Templo barroco del siglo XVII levantado en regular cantería caliza, provisto de un presbiterio de planta rectangular reforzado por estribos y una portada renacentista clasicista bajo pórtico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44114','iglesia','Iglesia de El Salvador','Templo gótico del siglo XIV edificado en excelente cantería de piedra arenisca regular, célebre por su magnífico ábside de paños con ventanales apuntados de fina tracería gótica y un grandioso órgano barroco interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44115','iglesia','Iglesia de la Asunción de Nuestra Señora','Fábrica barroca del siglo XVIII construida en mampostería caliza calavera con esquinas de sillería de refuerzo, que destaca por su robusta torre campanario de tres cuerpos decrecientes y sus paramentos exentos de decoración.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44115','monumento','Yacimiento de Icnitas de Las Cerradicas','Estación paleontológica con niveles del Jurásico Superior protegida con estructuras de cantería, que conserva huellas fosilizadas de dinosaurios saurópodos y terópodos impresas sobre estratos de calizas y areniscas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44116','iglesia','Iglesia de Nuestra Señora de la Piedad','Templo barroco de principios del siglo XVIII edificado en mampostería basta y ladrillo vista, caracterizado por su portada de líneas clasicistas y una esbelta torre campanario de cuerpos decrecientes con troneras molduradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44117','monumento','Acueducto Romano de Albarracín-Cella (Tramo de Gea)','Magna obra de ingeniería hidráulica romana del siglo I excavada directamente en la roca caliza de los escarpes del río Guadalaviar, singular por su impresionante sucesión de pozos de ventilación y galerías subterráneas labradas a pico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44117','iglesia','Iglesia de San Bernardo','Edificio conventual barroco del siglo XVII levantado en regular sillería arenisca, provisto de una espaciosa nave única con capillas laterales cubiertas por cúpulas y yeserías mudéjares de gran dinamismo plástico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44119','iglesia','Iglesia de San Pedro','Fábrica rural de la Sierra de Albarracín del siglo XVII edificada con gruesos paramentos de mampostería caliza y piedra arenisca de rodeno rojo, rematada por una modesta espadaña de dos vanos dispuesta sobre el imafronte occidental.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44120','iglesia','Iglesia de Santiago Apóstol','Templo del siglo XVII integrado en la arquitectura serrana del Alto Tajo, edificado con paramentos toscos de piedra calcárea del terreno y viguería de pino, que alberga una pila bautismal monolítica medieval de labra popular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44122','monumento','Núcleos de población de Híjar','El término municipal incluye los siguientes núcleos de población: La Puebla de Híjar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44122','monumento','Castillo de los Duques de Híjar','Restos fortificados de una gran fortaleza medieval y palacio ducal del siglo XV levantada sobre un cabezo en excelente mampostería y ladrillo, de la que subsiste la imponente Torre del Homenaje de planta cuadrada y la silueta desmochada de sus murallas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44122','iglesia','Iglesia de Santa María la Mayor','Magna fábrica mudéjar aragonesa del siglo XIV construida en ladrillo sobre zócalo de sillería caliza, célebre por su espectacular decoración exterior con frisos de esquinillas, rombos y una gran nave única con capillas entre contrafuertes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44122','ermita','Ermita del Santo Sepulcro','Santuario barroco del siglo XVII ejecutado en mampostería y ladrillo que domina el calvario de la villa, singular por su planta de cruz latina y su cúpula sobre pechinas ricamente ornamentada con motivos de la Pasión.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44123','iglesia','Iglesia de San Miguel','Templo renacentista del siglo XVI edificado en regular sillarejo calizo, caracterizado por su presbiterio de planta rectangular reforzado por estribos oblicuos y su portada meridional de arco de medio punto moldurado flanqueada por pilastras lisas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44125','monumento','Castillo de Peñaflor','Espectacular fortaleza roquera de origen musulmán reedificada en el siglo XIV por la Orden de San Juan en excelente sillería caliza, inexpugnable por asentarse sobre un crestón rocoso vertical que conserva lienzos almenados y dos imponentes torres fortificadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44125','iglesia','Iglesia de San Miguel','Templo de transición góticorenacentista del siglo XVI levantado en cantería bien escuadrada, notable por su ábside poligonal con bóvedas de crucería estrellada y su gran torre campanario adosada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44126','iglesia','Iglesia de la Purificación','Monumental templo del gótico tardío del siglo XVI reedificado sobre el primitivo edificio medieval en sillería caliza compacta, notable por su imponente torre fortificada (la Torre de los Nublos) y sus complejas bóvedas interiores de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44126','monumento','Casa Consistorial y Torre del Homenaje','Espléndido conjunto civil fortificado de los siglos XIV y XV erigido en excelente cantería por los caballeros templarios, singular por su gran lonja de arcos apuntados góticos y sus fachadas palaciegas con ventanas triforadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44126','palacio','Palacio de los Matutano-Daudén','Residencia noble señorial del siglo XVIII construida en magnífica sillería regular caliza, señera por su portada monumental barroca, sus rejerías de forja artística y una colosal escalera interior imperial bajo cúpula linterna.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44127','monumento','Núcleos de población de Jabaloyas','El término municipal incluye los siguientes núcleos de población: Arroyofrío.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44127','iglesia','Iglesia de la Asunción de Nuestra Señora','Fábrica del gótico tardío del siglo XVI levantada en sillería de piedra arenisca de rodeno y caliza calavera, notable por su ábside de paños con contrafuertes oblicuos y su portada meridional plateresca con grutescos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44127','monumento','Casa de las Sirenas','Notable ejemplar de arquitectura civil nobiliaria renacentista del siglo XVI edificado en sillería arenisca, caracterizado por sus ventanas molduradas flanqueadas por relieves escultóricos de seres mitológicos y blasones heráldicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44128','iglesia','Iglesia de la Asunción de Nuestra Señora','Fábrica renacentista de finales del siglo XVI ejecutada en mampostería caliza con sillares de refuerzo en los ángulos, que cuenta con una espadaña barroca escalonada de dos vanos dispuesta en el hastial occidental.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44129','iglesia','Iglesia de la Inmaculada Concepción','Templo barroco del siglo XVII edificado en aparejo mixto de ladrillo macizo y cajones de mampostería basta caliza, dotado de un interior sencillo con nave única y coro alto de madera tradicional a los pies.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44130','iglesia','Iglesia de la Asunción','Edificación religiosa del siglo XVI levantada en sillarejo y mampostería calcárea con contrafuertes exteriores, provista de un presbiterio poligonal cubierto por bóveda de crucería estrellada y una portada de líneas clásicas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44135','iglesia','Iglesia de San Juan Bautista','Fábrica de tradición barroca del siglo XVIII ejecutada en mampostería basta y sillarejo calizo, caracterizada por su planta rectangular de nave única con capillas laterales entre los contrafuertes y una sobria torre campanario adosada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44136','iglesia','Iglesia de Santiago Apóstol','Templo del siglo XVI levantado en regular cantería caliza con potentes estribos exteriores, notable por su presbiterio cubierto con bóvedas de crucería estrellada y una portada clasicista bajo arco de medio punto moldurado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44137','iglesia','Iglesia de la Inmaculada Concepción','Monumental obra barroca del siglo XVIII diseñada por el arquitecto Martín de Beltodano en magnífica sillería caliza regular, célebre por su planta de tres naves exenta de columnas gracias a sus potentes muros y por su campanario exento del siglo XIV adaptado de una torre fortificada medieval.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44137','monumento','Castillo y Recinto Amurallado','Restos fortificados de la fortaleza de los obispos de Zaragoza del siglo XIII erigidos en mampostería y sillería caliza compacta, de los que subsisten el Portal de Arriba con arco apuntado y potentes lienzos almenados sobre el cortado rocoso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44141','iglesia','Iglesia de Santiago Apóstol','Fábrica gótica del siglo XIV labrada en excelente cantería de piedra arenisca regular, dotada de un interior de nave única con bóvedas de crucería nervada y una portada meridional de tres arquivoltas apuntadas de fina labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44138','monumento','Núcleos de población de Loscos','El término municipal incluye los siguientes núcleos de población: Mezquita de Loscos, Piedrahíta y El Colladico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44138','iglesia','Iglesia de San Juan Bautista (Loscos)','Templo barroco del siglo XVIII construido en aparejo mixto de sillería y ladrillo vista, rematado por una gran cúpula sobre crucero y una esbelta torre campanario de tres cuerpos decrecientes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44138','iglesia','Iglesia de San Juan Bautista (Mezquita de Loscos)','Fábrica barroca del siglo XVIII notable por su torre de tradición mudéjar tardía erigida en ladrillo sobre base de sillería, decorada con frisos de esquinillas y rombos resaltados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44142','iglesia','Iglesia de San Juan Bautista','Modesta edificación rural barroca del siglo XVII levantada con aparejo tosco de piedra caliza, provista de una espadaña exenta de dos vanos y un porche sencillo de acceso con viguería de madera de pino vista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44143','monumento','Núcleos de población de Manzanera','El término municipal incluye los siguientes núcleos de población: Alcotas, Los Cerezos, Las Alhambras y Paraíso Bajo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44143','monumento','Murallas de Manzanera y Portal de Abajo','Conjunto amurallado bajomedieval del siglo XIV construido en cantería y mampostería compacta, del que destaca su monumental puerta de acceso bajo arco apuntado flanqueada por dos potentes torreones cilíndricos almenados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44143','iglesia','Iglesia de El Salvador','Templo renacentista del siglo XVI levantado en regular sillería caliza calavera, provisto de una gran nave única con capillas hornacinas y un presbiterio poligonal cubierto con bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44144','iglesia','Iglesia de la Asunción de Nuestra Señora','Fábrica renacentista de finales del siglo XVI ejecutada en mampostería caliza y ladrillo vista, caracterizada por su presbiterio poligonal reforzado exteriormente por estribos y una torre campanario adosada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44145','iglesia','Iglesia de San Juan Bautista','Magna edificación barroca del siglo XVIII construida en excelente sillería caliza calavera y ladrillo, universal por poseer una de las torres campanario más altas de la provincia, diseñada con cuerpos decrecientes y una fachada monumental de líneas academicistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44146','iglesia','Iglesia de San Bartolomé','Templo renacentista del siglo XVI edificado en sillería caliza regular, notable por su ábside poligonal con contrafuertes oblicuos y su portada meridional plateresca flanqueada por pilastras molduradas con relieves de grutescos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44147','monumento','Casa Consistorial','Espléndido edificio civil renacentista del siglo XVI edificado en magnífica sillería de piedra arenisca regular, que destaca por su gran lonja porticada de arcos de medio punto sobre pilares macizos y ventanas molduradas heráldicas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44147','iglesia','Iglesia de Santa María la Mayor','Fábrica gótica del siglo XIV construida en cantería bien escuadrada, provista de un ábside poligonal con ventanales de fina tracería gótica y una nave única cubierta con arcos fajones apuntados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44148','iglesia','Iglesia de San Lorenzo','Fábrica barroca del siglo XVII levantada en mampostería tosca de caliza con esquinas de sillería de refuerzo, dotada de una torre campanario baja de planta cuadrangular provista de dos vanos moldurados para las campanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44149','monumento','Recinto Amurallado de Mirambel y Portal de las Monjas','Espectacular perímetro fortificado medieval de la Orden de San Juan construido en sillería caliza compacta en el siglo XV, universal por conservar intactas sus murallas almenadas y el Portal de las Monjas con sus celosías de madera calada de tradición mudéjar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44149','iglesia','Iglesia de Santa Margarita','Fábrica monumental barroca del siglo XVII erigida en excelente cantería caliza calavera, notable por su espacioso interior de tres naves cubiertas con bóvedas de cañón con lunetos ciegos y su esbelta torre campanario adosada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44149','monumento','Casa Consistorial y Lonja Gótica','Espléndido edificio civil del gótico tardío del siglo XV labrado en piedra de sillería bien escuadrada, caracterizado por sus grandes arquerías apuntadas caladas y sus fachadas nobiliarias provistas de aleros de madera tallada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44150','iglesia','Iglesia de Nuestra Señora de las Nieves','Magna edificación renacentista-barroca del siglo XVI levantada en excelente sillería regular caliza, célebre por su portada meridional plateresca cobijada bajo pórtico, sus complejas bóvedas de crucería estrellada y su torre campanario barroca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44150','monumento','Puente Medieval sobre el río Guadalope','Estructura monumental de ingeniería civil del siglo XV levantada en sillería compacta, constituida por dos grandes ojos de perfil apuntado provistos de tajamares triangulares aguas arriba.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44152','monumento','Castillo de Monforte','Ruinas de la fortaleza bajomedieval del siglo XIV levantada en sillería y mampostería caliza compacta sobre una abrupta cresta, de la que subsisten potentes lienzos de la muralla jalonados por cubos desmochados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44152','iglesia','Iglesia de la Asunción','Fábrica renacentista del siglo XVI construida en regular cantería, provista de un','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44153','iglesia','Iglesia de la Natividad de Nuestra Señora','Fábrica monumental barroca del siglo XVIII construida en sillería caliza regular y mampostería, notable por su crucero cubierto con cúpula sobre pechinas y una robusta torre campanario de paramentos ciegos en su base.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44154','iglesia','Iglesia de la Asunción de Nuestra Señora','Magna edificación renacentista del siglo XVI labrada en excelente cantería de piedra arenisca regular, singular por albergar bajo su presbiterio una original cripta medieval y por su torre campanario exenta de paramentos ciegos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44155','monumento','Núcleos de población de Montalbán','El término municipal incluye los siguientes núcleos de población: Peñarroyas y Castel de Cabra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44155','iglesia','Iglesia de Santiago Mayor','Obra cumbre de la arquitectura mudéjar aragonesa (Patrimonio de la Humanidad UNESCO) iniciada en el siglo XIV por la Orden de Santiago en sillería caliza y ladrillo vista, universal por sus colosales proporciones de iglesiafortaleza, su ábside poligonal exornado con frisos de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44156','iglesia','Iglesia de la Virgen de la Peña','Templo del gótico tardío del siglo XVI edificado en regular sillería caliza, notable por su ábside poligonal con contrafuertes oblicuos exteriores y un interior de tres naves cubiertas con bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44159','iglesia','Iglesia de San Pedro','Fábrica rural de la Sierra de Albarracín del siglo XVII construida en sillería de piedra arenisca de rodeno rojo y mampostería, provista de una nave única con cabecera de paños y una robusta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44160','iglesia','Iglesia de la Asunción de Nuestra Señora','Magna fábrica gótico-renacentista ampliada en el siglo XVIII en excelente sillería caliza calavera, notable por su portada gótica del siglo XIV provista de arquivoltas ojivales y un fastuoso interior cubierto con complejas bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44160','monumento','Portal de San Roque y Recinto Amurallado','Conjunto fortificado medieval del siglo XIV construido en excelente cantería, del que se conserva intacta la monumental','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44161','iglesia','Iglesia de la Asunción de Nuestra Señora','Fábrica barroca del siglo XVIII cuya imponente torre campanario de estilo mudéjar, labrada en ladrillo vista sobre base de piedra, está considerada una obra maestra por su planta octogonal profusamente decorada con paños de rombos y relieves geométricos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44163','iglesia','Iglesia de San Miguel','Fábrica de tradición barroca del siglo XVIII integrada en la Sierra de Albarracín, levantada en mampostería basta de piedra arenisca roja (pétreo rodeno) y caliza local, provista de una torre campanario de dos cuerpos con remate piramidal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44164','iglesia','Iglesia de San Juan Bautista','Modesta construcción rural del siglo XVII edificada en aparejo tosco de arcilla y sillarejo, caracterizada por su planta rectangular unicelular con techumbre interior de madera de pino y un sencillo tejado a dos aguas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44168','iglesia','Iglesia de San Bartolomé','Templo del siglo XVI reformada en el barroco levantado en sillería caliza y mampostería regular, caracterizado por su presbiterio de planta rectangular y una portada purista de arco de medio punto flanqueada por pilastras lisas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44169','monumento','Castillo y Recinto Amurallado','Fortaleza bajomedieval del siglo XIV erigida en sillería caliza compacta sobre un cerro, de la que subsisten tres imponentes torres fortificadas de planta cuadrangular unidas por paños de muralla almenada y restos del foso roquero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44169','iglesia','Iglesia de Nuestra Señora del Pilar','Magna fábrica barroca del siglo XVIII construida en excelente cantería caliza regular, notable por su suntuosa fachada-retablo moldurada, su gran crucero cubierto con cúpula sobre pechinas y un interior de tres naves.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44171','iglesia','Iglesia de Santa Catalina','Edificio barroco del siglo XVIII levantado bajo trazas de corte academicista en sillería y mampostería calcárea, que destaca por su fachada simétrica con portada moldurada y una esbelta torre campanario de tres cuerpos decrecientes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44172','monumento','Poblado Ibérico de San Pedro','Espectacular asentamiento fortificado de época ibérica (siglos III-I a.C.) excavado sobre un cabezo escarpado, que conserva una colosal muralla de piedra seca de cuatro metros de alzado reforzada por dos imponentes torres defensivas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44172','iglesia','Iglesia de la Asunción de Nuestra Señora','Fábrica renacentista-barroca del siglo XVII erigida en aparejo mixto de sillería caliza y ladrillo vista, singular por su esbelta torre campanario exornada con relieves geométricos barrocos de tradición mudéjar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44174','iglesia','Iglesia de San Millán de la Cogolla','Templo barroco monumental de proporciones catedralicias edificado entre 1770 y 1776 en sillería de cantería regular caliza y arenisca, célebre por su soberbia fachada neoclásica de orden gigante diseñada por el arquitecto José Martín de Aldehuela y un fastuoso interior barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44174','monumento','Casa Consistorial','Espléndido edificio civil renacentista del siglo XVI edificado en magnífica sillería de piedra arenisca de rodeno rojo, que destaca por su gran','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44175','iglesia','Iglesia de la Asunción','Edificación religiosa del siglo XVI levantada en sillarejo y mampostería calcárea con contrafuertes exteriores, provista de un presbiterio poligonal cubierto por bóveda de crucería y una portada de líneas clásicas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44176','iglesia','Iglesia de San Juan Bautista','Fábrica del gótico tardío del siglo XVI ejecutada en mampostería caliza calavera con refuerzo de sillares en las esquinas, caracterizada por su presbiterio poligonal cubierto por complejas bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44177','monumento','Núcleos de población de Pancrudo','El término municipal incluye los siguientes núcleos de población: Cervera de Pancrudo, Cuevas de Portalrubio y Portalrubio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44177','iglesia','Iglesia de Nuestra Señora de la Asunción (Pancrudo)','Templo renacentista del siglo XVI construido en cantería regular caliza, notable por su ábside poligonal con contrafuertes oblicuos exteriores y un interior de tres naves con bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44177','iglesia','Iglesia de la Asunción (Cervera de Pancrudo)','Fábrica barroca del siglo XVII levantada en mampostería con esquinas de sillería de refuerzo, rematada por una','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44178','monumento','Núcleos de población de Las Parras de Castellote','El término municipal incluye los siguientes núcleos de población: Jaganta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44178','monumento','Almazara de Jaganta','Excepcional conjunto etnográfico industrial de origen medieval modificado en el siglo XVII, universal por conservar intacto un colosal molino de aceite que funciona mediante el sistema tradicional de prensa de viga de palanca de madera de roble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44178','iglesia','Iglesia de San Nicolás de Bari','Templo barroco del siglo XVIII construido en excelente sillería caliza regular, que destaca por su fachada clasicista de tres cuerpos moldurados y una robusta torre campanario de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44179','iglesia','Santuario de la Virgen de la Fuente','Magna joya del gótico mudéjar aragonés del siglo XIV declarada Patrimonio de la Humanidad UNESCO, ejecutada en sillería de piedra arenisca regular, universal por albergar en su iglesia una de las techumbres de madera mudéjares (techumbre de par y nudillo) más complejas y ricamente policromadas de la península.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44179','iglesia','Iglesia de Santa María la Mayor','Templo barroco de grandes proporciones del siglo XVIII erigido en cantería bien escuadrada, notable por su monumental portadaretablo churrigueresca profusamente esculpida y un espacioso interior cubierto por bóvedas de cañón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44180','monumento','Castillo de Peracense','Fortaleza militar roquera excepcional de los siglos XIII y XIV levantada en sillería de piedra arenisca roja (pétreo rodeno) sobre un espolón rocoso vertical inexpugnable, universal por su perfecta simbiosis con la geografía natural del terreno, su triple recinto amurallado con torreones almenados y su torre del homenaje inexpugnable.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44180','iglesia','Iglesia de San Pedro Apóstol','Fábrica renacentista de finales del siglo XVI ejecutada en cantería de rodeno y mampostería, provista de una nave única con cabecera poligonal y una pila bautismal románica de labra popular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44182','iglesia','Iglesia de la Asunción de Nuestra Señora','Fábrica de transición renacentista-barroca del siglo XVII levantada en sillería y mampostería caliza, dotada de una torre campanario de planta cuadrangular adosada al hastial occidental con vanos moldurados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44183','iglesia','Iglesia de la Virgen de la Asunción','Templo barroco del siglo XVIII enclavado en los desfiladeros del Maestrazgo, construido con paramentos de mampostería calcárea basta y contrafuertes angulares, albergando una portada sencilla bajo arco de medio punto moldurado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44185','iglesia','Iglesia de San Bartolomé','Templo del gótico tardío del siglo XVI edificado en regular sillería caliza, notable por su presbiterio de planta poligonal con contrafuertes oblicuos exteriores y un interior cubierto con bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44187','iglesia','Iglesia de San Cosme y San Damián','Fábrica barroca del siglo XVII levantada en cantería de piedra arenisca regular, provista de una portada de líneas clasicistas bajo arco de medio punto moldurado y un interior de tres naves separadas por pilares toscanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44189','iglesia','Iglesia de Santa Catalina','Edificación del siglo XVI levantada en aparejo mixto de piedra arenisca de rodeno y caliza calavera, que destaca por su torre campanario fortificada adosada al hastial occidental provista de vanos de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44190','iglesia','Iglesia de San Miguel','Templo renacentista del siglo XVI construido en sillería caliza calavera, provisto de un presbiterio poligonal reforzado por potentes estribos y una portada meridional purista flanqueada por pilastras cajeadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50219','ermita','Ermita de San Roque','Modesto oratorio rural del siglo XVII construido en aparejo de arcilla y sillarejo calizo, caracterizado por su planta de cajón con techumbre interior de madera de pino y un sencillo tejado a dos aguas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44192','iglesia','Iglesia de Santa Emerenciana','Fábrica monumental de finales del siglo XVI ejecutada en regular cantería caliza, notable por su gran torre campanario adosada de planta cuadrada y un interior barroco de tres naves cubiertas con bóveda de cañón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44193','monumento','Castillo de Puertomingalvo','Espectacular fortaleza militar del siglo XIV erigida en sillería caliza compacta en','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44193','monumento','Casa Consistorial','Espléndido palacio gótico civil del siglo XIV labrado en magnífica sillería regular caliza, universal por sus grandes arquerías apuntadas de la lonja, sus ventanas geminadas caladas de fina tracería gótica y sus estancias con techumbres de madera tallada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44193','iglesia','Iglesia de la Purificación','Templo monumental barroco del siglo XVIII edificado en regular cantería por los maestros del Maestrazgo, provisto de una suntuosa portada-retablo clasicista y un interior de tres naves decorado con yeserías molduradas.','inventario_monumentos_pdf');
