INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44194','monumento','Casa Consistorial y Cárcel','Edificio civil de estilo renacentista del siglo XVI edificado en magnífica cantería, caracterizado por su planta baja porticada con arcos de medio punto sobre pilares macizos y las mazmorras históricas en su subsuelo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44196','iglesia','Iglesia de la Virgen de los Dolores','Edificación barroca del siglo XVIII construida en sillería caliza regular y mampostería, notable por su gran crucero cubierto con cúpula sobre pechinas y una portada de líneas clasicistas.','inventario_monumentos_pdf');
