INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44197','iglesia','Iglesia de Santa Catalina','Magna edificación del siglo XVI diseñada en estilo renacentista purista en excelente sillería de piedra arenisca roja (pétreo rodeno), singular por su nave única de grandes proporciones y sus bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44197','monumento','Aljibe Medieval y Lavadero','Complejo hidráulico monumental excavado directamente en la roca arenisca roja en el siglo XIV, provisto de una bóveda apuntada de sillería que protege el vaso de captación de aguas pluviales.','inventario_monumentos_pdf');
