INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45125','iglesia','Colegiata de Nuestra Señora de la Asunción','Magna iglesia del siglo XVI trazada por Juan de Herrera en sillería granítica que presenta una única nave de monumentales proporciones de estilo clasicista herreriano con bóvedas de cañón y una portada con columnas jónicas.','inventario_monumentos_pdf');
