INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45125','monumento','Hospital de San Juan Bautista','Edificio asistencial del siglo XV de estilo gótico tardío construido en sillería que conserva un patio central con columnas de piedra de fuste liso y una capilla con arcos apuntados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45125','ermita','Ermita de las Peñitas','Santuario rural del siglo XVIII emplazado sobre berrocales graníticos, edificado en aparejo rústico visto con esquinales reforzados mediante sillares labrados que sirve de hito devocional comarcal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45126','iglesia','Iglesia Parroquial de la Inmaculada Concepción','Templo rural del siglo XVI edificado con el tradicional aparejo toledano que resguarda una nave única techada con una armadura de madera de par y nudillo con decoración geométrica modesta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45127','iglesia','Iglesia Parroquial de San Juan Bautista','Fábrica de tradición mudéjar levantada con cajones de mampostería caliza y bandas de ladrillo visto cuya torre campanario presenta un cuerpo superior decorado con vanos de medio punto y cubiertas interiores enfoscadas.','inventario_monumentos_pdf');
