INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45131','iglesia','Iglesia Parroquial de San Andrés Apóstol','Templo renacentista del siglo XVI construido enteramente en sillería y mampostería de granito berroqueño que destaca por su ábside poligonal y una torre campanario rematada con un cuerpo de campanas de cantería vista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45131','monumento','Rollo-Picota Jurisdiccional','Monumento exento de piedra granítica erigido en el siglo XVI sobre gradas cuadradas que presenta un fuste estriado coronado por cuatro elementos salientes esculpidos como símbolo del villazgo.','inventario_monumentos_pdf');
