INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45133','iglesia','Iglesia Parroquial de San Pedro Apóstol','Gran edificio columnario del siglo XVI de transición renacentista levantado en aparejo toledano que acoge en su cabecera un soberbio ábside poligonal cubierto por bóvedas de crucería estrellada.','inventario_monumentos_pdf');
