INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45142','iglesia','Santuario de Nuestra Señora de la Piedad','Templo de factura barroca edificado sobre una antigua ermita mudéjar mediante aparejo toledano que alberga un crucero rematado por una cúpula sobre pechinas ricamente ornamentada con yeserías clasicistas y un retablo mayor dorado de gran envergadura.','inventario_monumentos_pdf');
