INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45143','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo de origen mudéjar con profundas reformas clasicistas edificado en aparejo mixto de ladrillo y mampostería caliza que alberga en su presbiterio un altar mayor de líneas neoclásicas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45143','monumento','Caño Viejo','Estructura hidráulica comunal construida en sillería de piedra con un frontón clasicista de cuyo dintel parten los caños de bronce que vierten en un gran pilón rectangular destinado al ganado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45145','iglesia','Iglesia Parroquial de San Pedro Apóstol','Fábrica del siglo XVI de líneas renacentistas construida en aparejo toledano y piedra de la Sagra que destaca por su robusta torre campanario de tres cuerpos ejecutada enteramente en ladrillo macizo con vanos de medio punto doblados.','inventario_monumentos_pdf');
