INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16061','iglesia','Iglesia Parroquial de la Purísima Concepción','Fábrica clasicista del siglo XVII levantada con cajones de mampostería y esquinales reforzados mediante sillares calizos regulares que resguarda un espacioso interior cubierto por bóveda de cañón con lunetos y un retablo neoclásico.','inventario_monumentos_pdf');
