INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16066','iglesia','Iglesia Parroquial de San Juan Evangelista','Gran fábrica columnaria de transición renacentista construida en el siglo XVI con recios muros de sillería caliza calavera que alberga tres amplias naves de gran altura separadas por pilares ochavados y una techumbre interior de vigas de madera vista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16066','ermita','Ermita de la Concepción','Capilla de planta de cajón erigida en el siglo XVIII mediante cajones de mampostería encintada cuya fachada se remata con una pequeña espadaña de ladrillo visto moldurado de un solo ojo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16067','iglesia','Iglesia Parroquial de la Asunción','Templo de líneas renacentistas edificado en el siglo XVI mediante sillería regular y mampostería de la Alcarria conquense que destaca por su ábside poligonal reforzado por recios contrafuertes y una robusta torre campanario de tres cuerpos escalonados.','inventario_monumentos_pdf');
