INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16112','monumento','Murallas de Huete y Puerta de Almazán','Recinto fortificado bajomedieval edificado con tapial y mampostería trabada con cal que rodea la villa vieja conservando de forma monumental el torreón-puerta de sillería provisto de un arco de medio punto dovelado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16112','iglesia','Convento de Jesús y María','Edificio renacentista del siglo XVI trazado por la escuela de arquitectura herreriana que presenta una fachada clasicista de piedra caliza con una gran portada de líneas geométricas y una iglesia conventual de nave única con bóveda de cañón casetonada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16116','iglesia','Iglesia Parroquial de San Juan Bautista','Modesta fábrica de montaña levantada en piedra rústica y mortero','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16117','iglesia','Iglesia Parroquial de la Asunción','Templo renacentista del siglo XVI edificado en sillería regular y mampostería de la Serranía Baja que aloja tres naves separadas por pilares ochavados y una techumbre interior de vigas de madera de sabina vista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16117','ermita','Ermita de la Virgen de la Fuen María','Oratorio rural del siglo XVIII levantado en aparejo de piedra rústica con esquinales reforzados mediante sillares labrados que sirve de hito devocional comarcal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16119','iglesia','Iglesia Parroquial de la Asunción','Templo del siglo XVI con importantes reformas barrocas edificado en el tradicional aparejo de cajones de mampostería y','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16124','iglesia','Iglesia Parroquial de la Asunción','Fábrica columnaria del siglo XVI de líneas renacentistas construida en aparejo de mampostería manchega y sillería caliza calavera que resguarda tres amplias naves de gran altura separadas por robustas columnas toscanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16903','monumento','Núcleos de población de Las Valeras','El término municipal incluye los siguientes núcleos de población: Valera de Abajo y Valera de Arriba.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16903','monumento','Yacimiento Arqueológico de Valeria','Espectacular e importantísima ciudad romana fundada en el siglo I a.C. sobre un escarpado hoz fluvial que conserva de forma monumental el foro, un colosal ninfeo o fuente monumental de más de cien metros de longitud, calles empedradas, termas y casas colgadas romanas talladas en la roca caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16903','iglesia','Iglesia Parroquial de Nuestra Señora de la Altagracia (Valera de Abajo)','Monumental edificio de culto','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16903','ermita','Ermita de San Cristóbal','Oratorio del siglo XVIII ejecutado en mampostería encintada que presenta una fachada clasicista rematada por un frontón herreriano y una espadaña de dos ojos.','inventario_monumentos_pdf');
