INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16100','iglesia','Iglesia Parroquial de la Asunción (Hinojoso del Marquesado)','Templo gótico-renacentista del siglo XVI levantado en cantería caliza que cuenta con una nave única de gran amplitud cubierta por una armadura de madera mudéjar con tirantes decorados geométricamente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16906','monumento','Núcleos de población de Los Valdecolmenas','El término municipal incluye los siguientes núcleos de población: Valdecolmenas de Abajo y Valdecolmenas de Arriba.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16906','iglesia','Iglesia Parroquial de la Asunción (Valdecolmenas de Abajo)','Edificio del siglo XVI de origen renacentista construido con aparejo mixto de piedra caliza y ladrillo que alberga un presbiterio con bóveda de arista y un coro alto a los pies con balaustrada de madera.','inventario_monumentos_pdf');
