INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16251','iglesia','Iglesia del Carmen','Templo barroco del siglo XVII de la orden de los carmelitas descalzos que destaca por su espaciosa planta de cruz latina y una gran cúpula sobre pechinas ricamente ornamentada con yeserías polícromas.','inventario_monumentos_pdf');
