INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02041','iglesia','Iglesia Parroquial de la Asunción','Monumental fábrica columnaria de transición gótico-renacentista erigida en sillería caliza de primer orden que exhibe una nave única de gran luz espacial cubierta por bóvedas de crucería estrellada complejas y una portada plateresca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02041','iglesia','Santuario de la Virgen de Cubas','Oratorio rupestre del siglo XVIII emplazado junto a la hoz del Júcar cuya peculiar estructura aprovecha las oquedades naturales de la roca caliza calavera combinando las dependencias excavadas con una fachada tradicional encalada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02016','iglesia','Iglesia Parroquial de la Asunción','Joya monumental del gótico tardío y transición plateresca del siglo XVI construida en sillería regular caliza que destaca por su ábside poligonal reforzado por contrafuertes y una bellísima portada decorada con finas tracerías escultóricas de estilo renacentista.','inventario_monumentos_pdf');
