INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02043','iglesia','Iglesia Parroquial de la Asunción','Fábrica columnaria de transición renacentista del siglo XVI levantada en aparejo de cantería y sillería caliza calavera que resguarda tres amplias naves de gran altura separadas','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02044','iglesia','Antiguo Convento de San Juan de la Cruz','Complejo monástico carmelita del siglo XVII emplazado de forma espectacular sobre los acantilados de la hoz del río Mundo que presenta una sobria iglesia barroca con fachadas de ladrillo visto y una inmensa cripta subterránea que conserva momias desecadas de forma natural.','inventario_monumentos_pdf');
