INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02044','iglesia','Iglesia Parroquial de Santiago Apóstol','Monumental fábrica renacentista del siglo XVI erigida en sillería de piedra regular caliza que destaca por su esbelta torre campanario de planta cuadrada con vanos de medio punto y capillas heráldicas nobiliarias interiores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02045','iglesia','Iglesia Parroquial de San Pedro Apóstol','Fábrica de transición renacentista con fachada proyectada en suntuoso estilo barroco dieciochesco y muros de sillería caliza calavera que resguarda una nave de gran envergadura rematada por una cúpula sobre el crucero.','inventario_monumentos_pdf');
