INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02047','iglesia','Iglesia Parroquial de la Inmaculada Concepción','Modesta construcción rural de la Sierra de Alcaraz levantada en mampostería basta con refuerzo de sillares regulares en las esquinas que cuenta con una espadaña exenta de un solo vano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02048','iglesia','Iglesia Parroquial de Santiago Apóstol','Gran templo renacentista del siglo XVI edificado en sillería y mampostería manchega que alberga tres naves sostenidas por robustas columnas toscanas y un magnífico artesonado interior mudéjar de madera policromada.','inventario_monumentos_pdf');
