INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02024','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo renacentista del siglo XVI construido en sillería de piedra regular y mampostería que destaca por su ábside poligonal gótico tardío reforzado por potentes contrafuertes exteriores.','inventario_monumentos_pdf');
