INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02073','iglesia','Iglesia Parroquial de San Bartolomé','Monumental fábrica columnaria del siglo XVI de líneas renacentistas erigida en sillería caliza calavera que destaca por sus tres amplias naves de colosales proporciones sustentadas por robustas columnas dóricas de gran sección.','inventario_monumentos_pdf');
