INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02075','iglesia','Iglesia Parroquial de la Purísima Concepción','Templo de líneas clasicistas de La Manchuela edificado en el siglo XVIII mediante el tradicional aparejo de cajones de mampostería caliza y hiladas de ladrillo visto macizo que aloja una nave única con cubiertas de yesería.','inventario_monumentos_pdf');
