INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02078','iglesia','Iglesia Parroquial de Santa María Magdalena','Edificio de culto renacentista del siglo XVI construido con cajones de mampostería y esquinales de sillería caliza calavera que alberga una nave única cubierta por una bóveda de cañón con lunetos y un coro tradicional.','inventario_monumentos_pdf');
