INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02080','iglesia','Iglesia Parroquial de San Sebastián','Espléndido templo columnario gótico-renacentista del siglo XVI edificado por los condes de Paredes en cantería de la Sierra de Alcaraz que destaca por albergar una techumbre mudéjar de madera con tirantes decorados geométricamente y un interior de tres naves de gran amplitud.','inventario_monumentos_pdf');
