INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02027','monumento','Casa Consistorial (Ayuntamiento)','Obra cumbre de la arquitectura civil renacentista castellana del siglo XVI que presenta una fachada palaciega con una bellísima galería porticada de doble piso de arcos de medio punto sustentada por columnas jónicas de piedra labrada caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02027','iglesia','Convento de San Bernardo (Las Clarisas)','Complejo monacal fundado en el siglo XVII que presenta una sobria y geométrica fachada clasicista de ladrillo toledano','inventario_monumentos_pdf');
