INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02028','iglesia','Iglesia Parroquial de San Ildefonso','Humilde templo de La Manchuela construido en mampostería encintada encalada que presenta una fachada sobria con una pequeña espadaña de ladrillo macizo moldurado y cubiertas interiores enfoscadas.','inventario_monumentos_pdf');
