INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12051','iglesia','Iglesia Parroquial de el Salvador','Templo renacentista del siglo XVI levantado con recios muros de cantería caliza que alberga una nave única techada por una espléndida armadura de madera con tirantes mudéjares y un retablo mayor labrado. [1]','inventario_monumentos_pdf');
