INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12043','monumento','Torre del Molino','Recia atalaya defensiva medieval de planta cilíndrica erigida en mampostería basta que formaba parte del sistema de vigilancia y control territorial de la comarca del Alto Palancia.','inventario_monumentos_pdf');
