INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12046','iglesia','Iglesia Parroquial de San Bernardo','Templo barroco del siglo XVIII levantado con paramentos de mampostería encintada que aloja un presbiterio con bóveda de cañón con lunetos y una torre campanario baja de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12048','iglesia','Iglesia Parroquial de Nuestra Señora de los Ángeles','Monumental templo de proporciones catedralicias edificado en el siglo XVIII en sillería de cantería caliza de montaña que destaca por su espaciosa nave central cubierta por bóvedas de cañón, una gran cúpula sobre el crucero y un retablo gótico universal dedicado a las almas atribuido a la escuela valenciana.','inventario_monumentos_pdf');
