INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12115','iglesia','Iglesia Parroquial de Nuestra Señora de los Ángeles','Fábrica barroco-clasicista del siglo XVII levantada con cajones de piedra caliza de montaña que presenta una espaciosa nave central cubierta por bóveda de cañón con lunetos y una robusta torre campanario de planta cuadrada.','inventario_monumentos_pdf');
