INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12142','monumento','Provincia de Toledo','Completada al 100% (Cerrado tras Yuncos).','inventario_monumentos_pdf');
