INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46129','iglesia','Iglesia Parroquial de Santiago Apóstol','Fábrica de líneas neoclásicas del siglo XVIII levantada con cajones de mampostería de la comarca de Requena-Utiel que resguarda una nave de gran amplitud espacial y una robusta torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46902','iglesia','Iglesia Parroquial de Nuestra Señora de los Ángeles','Templo de tipología barroca rural del Camp de Túria edificado en el siglo XVIII con aparejo rústico visto que alberga una nave única cubierta por bóvedas de cañón con lunetos y una espadaña de dos vanos escalonados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46130','iglesia','Iglesia Parroquial de la Purísima Concepción (Pueblo Viejo)','Ruinas del antiguo templo parroquial del siglo','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46133','monumento','Castillo de Gestalgar / Castillo de los Murviedro','Ruinas espectaculares de una fortaleza militar de origen andalusí dispuesta sobre un peñasco escarpado de la comarca de Los Serranos, de la que restan potentes lienzos de muralla de mampostería basta y los muros enteros de su gran torre del homenaje de planta cuadrada.','inventario_monumentos_pdf');
