INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46134','monumento','Torre de Gilet','Recia estructura defensiva bajomedieval de planta cuadrada construida mediante aparejo de','inventario_monumentos_pdf');
