INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46135','iglesia','Iglesia Parroquial de San Bartolomé Apóstol','Fábrica renacentista de nave única del siglo XVI levantada en aparejo de cantería y sillería caliza calavera que resguarda una techumbre interior de madera de tradición mudéjar y reformas barrocas posteriores.','inventario_monumentos_pdf');
