INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46177','monumento','Punto de arranque inmediato para la nueva sesión','Provincia de Valencia, Letra N (comenzando estrictamente por municipios como Náquera, Navarrés, Novelé / Novetlè, etcétera).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46179','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Monumental fábrica barroca del siglo XVIII de la comarca del Canal de Navarrés que destaca por su espaciosa nave central cubierta por bóvedas de cañón con lunetos y un interior ornado con un magnífico conjunto de yeserías clasicistas molduradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46179','monumento','Castillo de Navarrés','Ruinas consolidadas de una antigua fortaleza militar de origen andalusí levantada en lo alto del cerro de la que subsisten paños fragmentados de murallas de tapial y mampostería basta adaptados al relieve geológico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46180','iglesia','Iglesia Parroquial of Nuestra Señora del Rosario','Fábrica del siglo XVIII de líneas barroco-clasicistas edificada mediante el tradicional aparejo mixto de mampostería de la Costera y hiladas de ladrillo visto macizo que aloja un presbiterio con bóveda de arista y una torre campanario baja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46180','palacio','Palacio de la Señoría / Palacio de Tallada','Casona señorial de origen bajomedieval edificada en sillería de piedra regular y mampostería que conserva una estructura cuadrangular con una portada dovelada y un patio central de gran valor etnológico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46182','monumento','Puntal dels Llops','Extraordinario y monumental oppidum o poblado fortificado de la cultura ibérica del siglo V a.C. emplazada de forma estratégica sobre una elevada estribación de la Sierra Calderona, el cual conserva intacto su potente recinto amurallado de piedra seca con una recia torre defensiva avanzada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46182','palacio','Palacio de los Condes de Olocau (Casa de la Señoría)','Edificio civil señorial de origen bajomedieval construido en sillería de piedra regular y mampostería basta que presenta una estructura cuadrangular con un patio de armas central de gran porte arquitectónico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46185','palacio','Palacio del Marqués de San José','Residencia noble señorial del siglo XVIII de estilo barroco-clasicista que conserva una portada monumental de piedra caliza con molduras herrerianas y un interior de gran valor etnológico estructurado en torno a un patio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46185','iglesia','Iglesia Parroquial de la Inmaculada Concepción','Fábrica barroca del siglo XVIII que presenta una espaciosa nave central cubierta por bóvedas de cañón con lunetos y una robusta torre campanario de planta cuadrada baja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46186','iglesia','Iglesia Parroquial de San Jorge','Templo del siglo XVIII de estilo barroco academicista erigido en la comarca de L''Horta Sud con aparejo mixto de piedra y ladrillo visto que presenta una fachada sobria con una portada adintelada de cantería y un campanario de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46187','iglesia','Iglesia Parroquial de San Miguel Arcángel','Fábrica barroca del siglo XVIII levantada con muros de mampostería basta de la Safor que aloja un presbiterio cubierto por bóveda de cañón con lunetos y una pequeña torre campanario baja de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46188','iglesia','Iglesia Parroquial de la Purísima Concepción','Modesta edificación de culto de la comarca de Safor levantada con cajones de mampostería ordinaria y esquinales de sillería caliza que cuenta con una pequeña torre campanario de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46190','monumento','Torre de Paterna','Recia e histórica torre defensiva de origen andalusí de planta cuadrada en su base y octogonal en su cuerpo superior erigida en sillería caliza','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46190','palacio','Palacio de los Condes de Villapaterna / Ayuntamiento','Edificio civil renacentista del siglo XVI de estilo institucional que presenta una fachada palaciega de sillería de piedra regular rematada por un gran alero de madera tallada y un patio central jónico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46190','monumento','Casas Cueva de Paterna','Conjunto de arquitectura popular y etnológica formado por decenas de viviendas trogloditas excavadas directamente en los terrenos arcillosos de la llanura que configuran un paisaje de fachadas encaladas y chimeneas cónicas exentas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46191','iglesia','Iglesia Parroquial de la Virgen de la Purísima Concepción','Templo del siglo XVIII de líneas barrococlasicistas de la comarca de Los Serranos edificado en mampostería encintada que aloja un presbiterio cubierto por bóveda de cañón con lunetos y una espectacular fachada-retablo de ladrillo visto moldurado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46192','palacio','Castillo de Petrés / Palacio del Barón de Petrés','Residencia noble señorial fortificada del siglo XV erigida en estilo gótico-renacentista con muros de sillería caliza y mampostería, de la que destaca su estructura cuadrangular con torres almenadas y estancias cubiertas por bóvedas de crucería estrellada gótico tardías.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46192','iglesia','Iglesia Parroquial de San Jaime Apóstol','Fábrica barroca del siglo XVIII que presenta una espaciosa nave central cubierta por bóvedas de cañón con lunetos y un campanario de planta cuadrada baja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46195','monumento','Torre Vigía de Piles','Espectacular torre vigía costera del siglo XVI erigida en sillería regular y mampostería sobre','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46195','iglesia','Iglesia Parroquial de Santa Bárbara','Fábrica del siglo XVIII de líneas renacentistas sencillas construida en aparejo de mampostería que alberga una bóveda de cañón rebajada sobre el presbiterio y una torre campanario baja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46196','iglesia','Iglesia Parroquial de los Santos Juanes','Humilde templo de la comarca de la Vall d''Albaida levantado con aparejo de mampostería de piedra tosca y mortero de cal que cuenta con una espadaña baja de dos ojos y un interior enfoscado en yeso blanco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46201','iglesia','Iglesia Parroquial de San Miguel Arcángel','Fábrica del siglo XVII erigida en mampostería basta y esquinales de cantería del Rincón de Ademuz que presenta una nave única con bóveda de cañón y una esbelta torre campanario de planta cuadrada que destaca por sus remates de piedra labrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46102','iglesia','Iglesia Parroquial de la Purísima Concepción','Fábrica barroca del siglo XVIII construida con paramentos de mampostería encintada y ladrillo visto de la comarca de L''Horta Sud que alberga un crucero rematado por una esbelta cúpula sobre pechinas decorada con azulejería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46102','monumento','Cisterna Medieval de Quart de Poblet','Espectacular depósito hidráulico subterráneo del siglo XIV edificado en sillería de piedra regular y arcos fajones de medio punto destinado al abastecimiento público de agua de la villa histórica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46103','iglesia','Iglesia Parroquial de Santa Ana','Edificio de culto del siglo XVIII de líneas barroco-clasicistas levantado con muros de mampostería encintada que alberga una nave única cubierta por bóvedas de cañón con lunetos y una torre campanario baja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46103','monumento','El Molí de Quartell','Complejo harinero y arrocero tradicional del siglo XVIII que conserva sus cárcavos de cantería y la maquinaria hidráulica original alimentada por las acequias de la comarca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46206','monumento','Castillo de Quesa','Ruinas de una fortaleza militar medieval de origen andalusí dispuesta sobre un peñasco escarpado de la comarca de la Canal de Navarrés, de la que restan potentes lienzos de muralla de mampostería basta y la base de su torre defensiva de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46206','iglesia','Iglesia Parroquial de San Antonio de Padua','Fábrica barroca del siglo XVIII que presenta una espaciosa nave central cubierta por bóvedas de cañón con lunetos y un campanario de planta cuadrada baja con remates de piedra tosca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46208','iglesia','Iglesia Parroquial de San Antonio de Padua','Edificio de culto de la comarca de Safor levantado con cajones de mampostería encintada y esquinales de sillería caliza calavera que resguarda un interior modesto con pinturas populares barrocas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46208','monumento','El Trinquet de Rafelcofer','Estructura arquitectónica civil del siglo XIX destinada a la práctica del juego tradicional de la pelota valenciana con gruesos muros portantes de mampostería basta y losas de cantería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46209','iglesia','Iglesia Parroquial de la Natividad de Nuestra Señora','Fábrica del siglo XVIII de líneas renacentistas sencillas construida en aparejo de mampostería de la comarca de la Ribera Alta que alberga una bóveda de cañón rebajada sobre el presbiterio y una torre campanario baja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46210','iglesia','Iglesia Parroquial of Nuestra Señora de los Ángeles','Modesta edificación de culto de la Vall d''Albaida construida en el siglo XVIII mediante el tradicional aparejo mixto de mampostería basta y verdugadas de ladrillo visto que aloja una nave única con cubiertas de yesería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46213','monumento','Núcleos de población de Requena','El término municipal incluye los siguientes núcleos de población: El Azagador, Barrio Arroyo, Calderón, Campo Arcís, Casas de Cuadra, Casas de Eufemia, Casas de Sotos, Casas del Río, Los Duques, El Rebollar, Los Cojos, Los Isidros, Los Ruices, San Antonio, San Juan, El Pontón, Roma, Serrano y Hortunas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46213','iglesia','Iglesia de Santa María','Obra cumbre del gótico flamígero de la provincia construida en el siglo XIV en sillería caliza calavera que destaca por su monumental e intrincada fachada occidental repleta de esculturas, arquivoltas caladas de fina tracería y un interior columnario cubierto por bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46213','iglesia','Iglesia del Salvador','Monumental templo gótico del siglo XIV reformado en el barroco que exhibe una suntuosa portada plateresca bajo arco de triunfo de cantería de primer orden y tres naves monumentales cubiertas por bóvedas de crucería estrellada gótico tardías.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46213','monumento','Torre del Homenaje y Alcazaba','Recia fortaleza medieval de origen andalusí profundamente reconstruida en el siglo XV con muros de sillería granítica y mampostería trabada que domina de forma monumental el barrio histórico de la Villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46213','monumento','Cuevas de Requena (Barrio de la Villa)','Espectacular y colosal red de túneles y silos subterráneos medievales excavados directamente en la muela de toba caliza destinados históricamente al almacenamiento de grano, la tinajería vinícola y como refugio civil.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46213','palacio','Palacio del Cid','Edificio palaciego del siglo XV de arquitectura gótico-civil que presenta una fachada monumental de sillería regular con un portalón dovelado y blasones de noble linaje labrados en piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46214','monumento','Yacimiento de el Pla de Nadal','Espectacular y único palacio fortificado de época visigoda del siglo VII d.C. que conserva de forma monumental pavimentos de hormigón de cal, arranques de arcos de herradura y una riquísima decoración escultórica plástica con relieves geométricos y epigráficos tallados en piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46214','monumento','Castillo de Riba-roja de Túria','Complejo residencial y fortificado bajomedieval erigido en sillería y mampostería caliza que organiza sus dependencias en torno a un patio de armas con adarves y salas abovedadas góticas totalmente musealizadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46214','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Fábrica barroco-clasicista del siglo XVIII que presenta una espaciosa nave central cubierta por bóvedas de cañón con lunetos y una robusta torre campanario del Camp de Túria.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46215','iglesia','Iglesia Parroquial de Santa María','Templo de la Ribera Baixa edificado en el siglo XVIII mediante el tradicional aparejo de cajones de mampostería caliza y hiladas de ladrillo visto macizo que aloja una nave única reformada en el barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46216','iglesia','Iglesia Parroquial de San Sebastián','Edificio del siglo XVIII de líneas barroco-clasicistas levantado con muros de mampostería encintada y contrafuertes calizos de la comarca de L''Horta Nord que alberga una nave única cubierta por bóvedas de cañón con lunetos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46219','iglesia','Iglesia Parroquial de Nuestra Señora de la Gracia','Humilde oratorio de la comarca de la Vall d''Albaida edificado en mampostería tosca encalada que cuenta con una pequeña espadaña de ladrillo visto de un solo vano y cubiertas de madera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45013','monumento','Núcleos de población de Sagunto/Sagunt','El término municipal incluye los siguientes núcleos de población: Puerto de Sagunto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45013','monumento','Teatro Romano de Sagunto','Joya monumental universal del siglo I d.C. declarada Monumento Nacional, labrada de forma espectacular aprovechando la concavidad de la roca viva caliza de la ladera del cerro que conserva de forma monumental su cávea semicircular, la orchestra y restos monumentales del frente escénico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45013','monumento','Castillo de Sagunto','Inmenso e histórico complejo fortificado de casi un kilómetro de longitud que corona la silueta de la montaña en sillería y mampostería basta, el cual conserva los restos de la plaza de armas romana, el foro porticado, murallas andalusíes, torres medievales y defensas de las guerras de la independencia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45013','iglesia','Iglesia de Santa María','Joya del gótico valenciano construida en cantería caliza calavera de primer orden entre los siglos XIV y XVI que exhibe una colosal nave central de gran luz espacial con contrafuertes y las espectaculares portadas góticas abocinadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45013','monumento','Alto Horno Nº 2 (Puerto de Sagunto)','Monumental e histórico vestigio de la arquitectura industrial y tecnológica del siglo XX construido en hierro y acero de gran sección que se erige de forma exenta como hito y museo de la siderurgia valenciana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45013','ermita','Ermita de la Sangre','Templo barroco de grandes proporciones levantado en el siglo XVII con aparejo de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46221','iglesia','Iglesia Parroquial de San Miguel Arcángel','Modesta edificación de culto de la Vall d''Albaida construida en el siglo XVIII mediante aparejo de mampostería de piedra tosca y mortero de cal que cuenta con una espadaña baja de dos ojos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46903','iglesia','Iglesia Parroquial de San Antonio Abad','Templo civil de mediados del siglo XX de líneas funcionales y racionalistas edificado con paramentos encalados simétricos y una torre campanario exenta integrada en el urbanismo de colonización.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46223','iglesia','Iglesia Parroquial of Nuestra Señora del Rosario','Edificio de culto de la comarca de L''Horta Sud levantado en el siglo XVIII con aparejo mixto de piedra y ladrillo que cuenta con una pequeña torre campanario y cubiertas de bóveda de arista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46224','monumento','Castillo de Segart','Ruinas de una pequeña atalaya defensiva de origen andalusí situada sobre una aguja rocosa caliza de la comarca del Camp de Morvedre, de la que restan paños fragmentados de muros de mampostería seca adaptados a la escarpadura geológica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46224','iglesia','Iglesia Parroquial de la Purísima Concepción','Sencillo edificio religioso del siglo XVIII de líneas clasicistas levantado con muros de mampostería ordinaria que cuenta con una pequeña torre campanario baja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46225','iglesia','Iglesia Parroquial de la Purísima Concepción','Fábrica de tradición barroco-renacentista de la comarca de la Ribera Alta levantada con el tradicional aparejo de cajones de mampostería caliza y hiladas de ladrillo visto macizo que resguarda una nave única.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46227','iglesia','Iglesia Parroquial de Santa Ana','Edificio de culto de la comarca de la Ribera Alta construido en el siglo XVIII mediante el tradicional aparejo mixto de mampostería basta y verdugadas de ladrillo visto que aloja una nave única con cubiertas de bóveda de arista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46228','iglesia','Cartuja de Porta Coeli','Monumental complejo monástico eclesial fundado en el siglo XIV emplazado en un valle protegido de la Sierra Calderona, edificado en sillería de la máxima calidad de la que destacan su gran iglesia de cruz latina, capillas góticas caladas y restos de un claustro monumental de primer orden nacional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46228','monumento','Castillo de Serra','Ruinas espectaculares de una inexpugnable e histórica fortaleza militar de origen andalusí del siglo XII que corona el cerro de la que restan potentes lienzos almenados de mampostería basta y los muros enteros de su torre del homenaje.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46228','ermita','Torre de la Ermita y Torre del Señor','Pareja de recias atalayas defensivas islámicas dispuestas en el entorno urbano y periurbano construidas mediante aparejo de mampostería y tapial que servían como alquerías fortificadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46229','iglesia','Iglesia Parroquial de San Juan Bautista','Templo del siglo XVII erigido en mampostería basta y esquinales de cantería de la comarca de la Hoya de Buñol que presenta una nave única con bóveda de cañón y una esbelta torre campanario de planta cuadrada baja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46230','monumento','Torre de Silla','Recia e histórica torre defensiva de origen andalusí de planta cuadrada erigida en sillería caliza regular y mampostería basta en el núcleo del casco histórico que servía como puesto avanzado de control territorial y se encuentra integrada de forma monumental en el palacio consistorial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46230','iglesia','Iglesia Parroquial de Nuestra Señora de los Ángeles','Monumental templo del siglo XVIII de estilo barroco academicista erigido en cantería y ladrillo de L''Horta Sud que destaca por su espaciosa nave central cubierta por bóvedas de cañón, una gran cúpula sobre el crucero y portadas de cantería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46231','iglesia','Real Monasterio de Santa María de la Valldigna','Espectacular y colosal complejo monástico cisterciense fundado en el siglo XIII por Jaime II el Justo en el corazón de la Valldigna, construido en sillería de cantería de primer orden que conserva de forma magistral una','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46231','ermita','Mezquita de la Xara / Ermita de Santa Ana','Joya monumental de la arquitectura islámica rural del siglo XV que conserva sus muros portantes de mampostería basta, los arranques de arcos de herradura y la base del mihrab reconvertida tras la expulsión de los moriscos en ermita.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46232','iglesia','Iglesia Parroquial de Santiago Apóstol','Fábrica renacentista de nave única del siglo XVI levantada en aparejo de cantería caliza calavera y mampostería de la comarca de Requena-Utiel que alberga un presbiterio con bóvedas de crucería estrellada gótico tardías.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46232','ermita','Ermita de San Marcos','Oratorio barroco de planta de cajón erigida en el siglo XVIII mediante el tradicional aparejo encintado que presenta una portada adintelada de piedra moldurada coronada por una pequeña espadaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46233','monumento','Núcleos de población de Sollana','El término municipal incluye los siguientes núcleos de población: El Romaní.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46233','iglesia','Iglesia Parroquial de la Purísima Concepción','Monumental templo del siglo XVIII de estilo barroco academicista erigido en cantería caliza y ladrillo de la Ribera Baixa que destaca por su espaciosa nave central cubierta por bóvedas de cañón, una gran cúpula sobre el crucero y un campanario exento de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46234','monumento','Castillo de Sot de Chera y Torre del Homenaje','Vestigios fortificados medievales situados de forma espectacular junto al río en la comarca de Los Serranos, construidos en mampostería gruesa de los que destaca su recia torre cuadrada totalmente restaurada integrada en el casco histórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46234','iglesia','Iglesia Parroquial de la Inmaculada Concepción','Templo del siglo XVIII de líneas barroco-clasicistas edificado en mampostería encintada que aloja un presbiterio cubierto por bóveda de cañón con lunetos y una torre campanario baja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46235','iglesia','Iglesia Parroquial de San Pedro Apóstol','Monumental fábrica barroca del siglo XVIII de la comarca de la Ribera Baixa que destaca por su espaciosa nave central cubierta por bóvedas de cañón con lunetos, una inmensa cúpula sobre el crucero decorada con azulejería vidriada azul y un interior tapizado de ricas yeserías exentas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46235','iglesia','Real Santuario de Nuestra Señora de Sales','Complejo barroco de proporciones monumentales erigido en cantería que presenta una majestuosa fachada de suntuosa decoración escultórica y un interior que alberga un camarín absidial ricamente decorado con pinturas de la escuela valenciana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46235','monumento','Asilo de Ancianos Desamparados','Magna obra de la arquitectura modernista de principios del siglo XX diseñada con muros de ladrillo visto policromo que exhibe intrincadas filigranas de tracería calada en sus ventanas y azulejería de valor artesanal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46238','iglesia','Iglesia Parroquial de San Pedro Apóstol','Monumental fábrica barroca del siglo XVIII construida con paramentos de mampostería encintada de la Valldigna y esquinales de sillería caliza calavera que resguarda un interior de gran amplitud cubierto por bóveda de cañón con lunetos y una torre campanario robusta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46238','monumento','Torre de Guaita de la Vall','Atalaya defensiva costera del siglo XVI erigida en sillería regular y mampostería sobre la línea de costa para la vigilancia y protección de la comarca contra las incursiones de la piratería berberisca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46239','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Fábrica del siglo XVI de líneas renacentistas y reformas barrocas construida en aparejo de mampostería y contrafuertes calizos del Valle de Ayora que aloja una nave única con una robusta torre campanario de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46240','iglesia','Iglesia Parroquial de San Juan Bautista','Humilde templo de la comarca de la Vall d''Albaida levantado con aparejo de mampostería de piedra tosca y mortero de cal que cuenta con una pequeña espadaña de ladrillo visto de un solo vano y cubiertas de yesería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46241','iglesia','Iglesia Parroquial de el Salvador','Templo renacentista del siglo XVI de la comarca de Los Serranos construido en sillería regular y mampostería que destaca por su ábside poligonal tardogótico reforzado por recios contrafuertes exteriores y una techumbre de madera castellana bien conservada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46241','ermita','Ermita de la Virgen del Remedio','Oratorio barroco de planta de cajón erigido en el siglo XVIII mediante el tradicional aparejo encintado que presenta una portada adintelada de piedra moldurada coronada por una pequeña espadaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46242','iglesia','Iglesia Parroquial de Santa Ana','Edificio de culto del siglo XVIII construido en el Rincón de Ademuz mediante el tradicional aparejo mixto de mampostería basta y verdugadas de ladrillo visto que presenta una fachada neoclásica sobria rematada por una pequeña espadaña de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46243','iglesia','Iglesia Parroquial de la Virgen de los Ángeles','Humilde oratorio de la comarca de la Costera edificado en mampostería tosca encalada que cuenta con una pequeña espadaña de ladrillo visto de un solo vano y cubiertas de madera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46245','monumento','Baños Árabes de Torres Torres','Joya monumental universal de la arquitectura hidráulica andalusí del siglo XII perfectamente conservada en el Camp de Morvedre, constituida por una estructura de planta rectangular de mampostería y ladrillo que alberga las salas fría,','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46245','monumento','Castillo de Torres Torres','Ruinas de una fortaleza militar medieval de origen musulmán emplazada sobre un promontorio escarpado de la que restan potentes lienzos de muralla de mampostería basta y la base de su torre defensiva poligonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46246','iglesia','Iglesia Parroquial de San Miguel Arcángel (Pueblo Nuevo)','Templo edificado a finales del siglo XX para el nuevo emplazamiento del municipio tras el anegamiento del núcleo histórico por la presa, que destaca por albergar la portada barroca de cantería desmontada sillar a sillar de la antigua iglesia desaparecida bajo las aguas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46247','iglesia','Iglesia Parroquial de Nuestra Señora de los Ángeles','Monumental fábrica barroca del siglo XVII de la comarca de Los Serranos declarada Bien de Interés Cultural, construida en cantería caliza calavera que exhibe una fastuosa portada monumental barroca de ricas molduras y un interior tapizado por completo con un soberbio conjunto de yeserías polícromas exentas e iconográficas de valor universal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46247','monumento','Castillo de Tuéjar','Ruinas de una antigua fortaleza militar medieval de origen andalusí levantada en lo alto del cerro de la que subsisten paños fragmentados de murallas de tapial y mampostería basta adaptados al relieve de la montaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46248','iglesia','Iglesia Parroquial de la Natividad de Nuestra Señora','Monumental templo del siglo XVIII de estilo barroco academicista erigido en cantería caliza y ladrillo de la Ribera Alta que destaca por su espaciosa nave central cubierta por bóvedas de cañón, una gran cúpula sobre el crucero y un campanario de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46248','monumento','Castillo de Turís / Castellet de Turís','Ruinas consolidadas de una atalaya militar defensiva de origen andalusí de planta cuadrada erigida en sillería regular y mampostería basta sobre un cerro testigo que domina el entorno agrícola de la comarca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46249','monumento','Núcleos de población de Utiel','El término municipal incluye los siguientes núcleos de población: Los Corrales, Las Casas, Las Cuevas, La Torre, El Remedio, Estenas y El Carraixet.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46249','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Joya monumental del gótico tardío de la provincia construida en el siglo XVI en sillería caliza calavera de primer orden que destaca por su colosal nave única de gran luz espacial cubierta por intrincadas bóvedas de crucería estrellada compleja y capillas hornacinas entre contrafuertes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46249','monumento','Bodegas Subterráneas de Utiel','Espectacular y colosal red de túneles y bodegas históricas medievales excavadas directamente bajo el casco urbano destinadas históricamente a la tinajería vinícola tradicional de la comarca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46249','iglesia','Santuario de Nuestra Señora del Remedio','Complejo religioso barroco del siglo XVIII levantado en un entorno de montaña y matorral que presenta una majestuosa','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46250','monumento','Lonja de la Seda (Llotja de la Seda)','Obra cumbre de la arquitectura gótica civil universal declarada Patrimonio de la Humanidad por la UNESCO construida por Pere Compte en el siglo XV en sillería caliza de la máxima finura técnica, que deslumbra por su colosal Sala de Contratación jalonada por altísimas columnas helicoidales que se abren como palmeras formando bóvedas de crucería estrellada flamígeras y el fastuoso Consulado del Mar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46250','catedral','Santa Iglesia Catedral-Basílica Metropolitana de Santa María','Monumental templo gótico valenciano construido entre los siglos XIII y XV que destaca por su presbiterio renacentista con frescos universales, el monumental cimborrio calado octogonal gótico flamígero, la barroca Puerta de los Hierros y la Capilla del Santo Cáliz que custodia la célebre reliquia universal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46250','monumento','Torre del Micalet (Miguelete)','Espectacular campanario histórico de la catedral exento de planta octogonal erigido enteramente en el siglo XIV en sillería caliza calavera calada en el perfil urbano que exhibe superposición de cuerpos geométricos simétricos de gran impacto plástico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46250','monumento','Torres de Serranos y Torres de Quart','Colosales e inexpugnables puertas militares fortificadas bajomedievales de los siglos XIV y XV erigidas en sillería regular que representan las cumbres de la poliorcética gótica europea con sus recios torreones pentagonales y cilíndricos provistos de almenas, matacanes y troneras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46250','palacio','Palacio del Marqués de Dos Aguas','Joya monumental universal de la arquitectura barroco-rococó civil del siglo','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46250','monumento','Mercado Central (Mercat Central)','Obra cumbre del modernismo valenciano de principios del siglo XX construida con una monumental estructura de hierro calado, cristal y cerámica policromada que exhibe una inmensa cúpula central linterna calada de gran complejidad técnica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46250','iglesia','Monasterio de San Miguel de los Reyes','Espectacular y colosal complejo renacentista del siglo XVI proyectado por orden del Duque de Calabria bajo las trazas del estilo herreriano en sillería que exhibe una fachada monumental de líneas simétricas geométricas puras y un claustro de doble orden porticado de valor nacional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46251','monumento','Castillo de Vallada / Castell de Umbría','Ruinas espectaculares de una importante fortaleza militar de origen andalusí y posterior encomienda de la Orden de Montesa emplazada en la comarca de la Costera sobre un cerro escarpado, de la que subsisten paños de muralla de mampostería, cubos de flanqueo cuadrangulares y el aljibe interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46251','iglesia','Iglesia Parroquial de San Bartolomé Apóstol','Fábrica gótico-renacentista del siglo XVI de nave única levantada en sillería caliza calavera que alberga un presbiterio con bóvedas de crucería estrellada gótico tardías.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46254','monumento','Núcleos de población de Venta del Moro','El término municipal incluye los siguientes núcleos de población: Casas de Pradas, Casas de la Moya, Casas del Rey, Las Monjas, Los Marcos y San Juan.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46254','iglesia','Iglesia Parroquial de Nuestra Señora de Loreto','Fábrica barroca del siglo XVIII levantada con cajones de mampostería de la comarca de Requena-Utiel que destaca por su esbelta torre campanario de tres cuerpos y un interior de gran amplitud espacial cubierto por bóvedas de cañón con lunetos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46258','iglesia','Iglesia Parroquial de Nuestra Señora de la Paz','Monumental fábrica columnaria de transición gótico-','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46258','palacio','Palacio Arzobispal','Edificio civil señorial de origen bajomedieval de los arzobispos de Valencia construido en sillería de piedra regular y mampostería basta que presenta una estructura cuadrangular con un patio de armas central de gran porte arquitectónico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46259','iglesia','Iglesia Parroquial de San Roque','Fábrica de líneas neoclásicas del siglo XVIII levantada con cajones de mampostería en los límites provinciales del río Cabriel que resguarda una nave de gran amplitud espacial y una robusta torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46260','monumento','Fábrica de la Seda / Fàbrica de la Seda','Gran exponente de la arquitectura industrial tradicional del siglo XVIII fundado en la huerta de L''Horta Nord, construido en ladrillo visto policromo y mampostería con ricas molduras geométricas en sus cornisas que servía para el hilado histórico de la seda.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46260','iglesia','Iglesia Parroquial de San Honorato Obispo','Templo barroco del siglo XVIII levantado con muros de mampostería encintada que aloja un presbiterio con bóveda de cañón con lunetos y una torre campanario baja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46261','iglesia','Iglesia Parroquial de los Santos Reyes','Templo del siglo XVII erigido en mampostería basta y esquinales de cantería de la comarca de la Hoya de Buñol que presenta una nave única con bóveda de cañón y una esbelta torre campanario de planta cuadrada baja con remates de cantería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46263','iglesia','Iglesia Parroquial de Santa Ana','Templo del siglo XVI de líneas renacentistas y reformas barrocas del siglo XVIII edificado mediante muros de aparejo de piedra caliza del Valle de Ayora que alberga un presbiterio cubierto por bóveda de cañón con lunetos y una bellísima torre campanario exenta de planta cuadrada ejecutada en ladrillo visto moldurado.','inventario_monumentos_pdf');
